function recordMemoryReview({course,topic,activityType='quiz',accuracy=null,questionsAnswered=0,durationMinutes=0}={}){if(!course||!topic)return;const cleanTopic=normalizeTopicName(topic),record=getMemoryRecord(course,cleanTopic),now=new Date(),todayKey=isoDateOnly(now),lastCheckpoint=record.reviewHistory[record.reviewHistory.length-1],daysSincePreviousReview=lastCheckpoint?calendarDaysBetween(lastCheckpoint.reviewedAt,now):0,weight=reviewWeight(activityType,accuracy,questionsAnswered,durationMinutes);record.reviewActivities=[...(record.reviewActivities||[]),{id:'review-'+Date.now()+'-'+Math.random().toString(36).slice(2,6),course,topic:cleanTopic,reviewedAt:now.toISOString(),activityType,accuracy,questionsAnswered,durationMinutes}].slice(-200);if(lastCheckpoint&&isoDateOnly(lastCheckpoint.reviewedAt)===todayKey){const existingWeight=lastCheckpoint.weight||1;if(accuracy!==null&&accuracy!==undefined){lastCheckpoint.accuracy=lastCheckpoint.accuracy===null?Math.round(Number(accuracy)):Math.round((lastCheckpoint.accuracy*existingWeight+Number(accuracy)*weight)/(existingWeight+weight));lastCheckpoint.weight=existingWeight+weight}lastCheckpoint.questionsAnswered=(lastCheckpoint.questionsAnswered||0)+(Number(questionsAnswered)||0);lastCheckpoint.durationMinutes=(lastCheckpoint.durationMinutes||0)+(Number(durationMinutes)||0);lastCheckpoint.activityTypes=uniqueCourses([...(lastCheckpoint.activityTypes||[]),activityType])}else record.reviewHistory.push({reviewedAt:now.toISOString(),accuracy:accuracy===null||accuracy===undefined?null:Math.round(Number(accuracy)),daysSincePreviousReview,questionsAnswered:Number(questionsAnswered)||0,durationMinutes:Number(durationMinutes)||0,activityTypes:[activityType],weight});record.reviewHistory=record.reviewHistory.slice(-60);updateMemoryPrediction(record);ensureLearningProfile().lastUpdated=new Date().toISOString();return record}
function recordMemoryReviewsFromQuiz(course,questionResults=[],durationMinutes=10){const groups={};questionResults.forEach(result=>{const topic=topicLabelFromQuestion(result.question||{}),key=memoryKey(course,topic);groups[key]=groups[key]||{topic,correct:0,total:0};groups[key].total++;if(result.correct)groups[key].correct++});Object.values(groups).forEach(group=>recordMemoryReview({course,topic:group.topic,activityType:'quiz',accuracy:Math.round(group.correct/group.total*100),questionsAnswered:group.total,durationMinutes:Math.max(1,Math.round((durationMinutes||10)/Object.keys(groups).length))}))}
function memoryRows(){const profile=ensureLearningProfile();Object.values(profile.memoryTracking||{}).forEach(updateMemoryPrediction);return Object.values(profile.memoryTracking||{}).filter(r=>r.reviewHistory?.length)}
function reviewsDue(){const today=isoDateOnly(),rows=memoryRows();return {today:rows.filter(r=>r.predictedReviewDate===today||r.memoryStatus==='Review Recommended'),overdue:rows.filter(r=>r.predictedReviewDate&&r.predictedReviewDate<today),upcoming:rows.filter(r=>r.predictedReviewDate&&r.predictedReviewDate>today).sort((a,b)=>a.predictedReviewDate.localeCompare(b.predictedReviewDate)).slice(0,5)}}
function memoryTopicsForPlan(course,totalDays){const end=addDaysISO(new Date(),Math.max(0,totalDays-1));return memoryRows().filter(r=>(!course||r.course.toLowerCase()===course.toLowerCase())&&r.predictedReviewDate&&r.predictedReviewDate<=end).sort((a,b)=>a.predictedReviewDate.localeCompare(b.predictedReviewDate))}
function memorySummary(){const rows=memoryRows(),due=reviewsDue(),intervals=rows.map(r=>r.reviewHistory.slice(1).map(x=>x.daysSincePreviousReview)).flat().filter(Boolean),avgInterval=intervals.length?Math.round(intervals.reduce((a,b)=>a+b,0)/intervals.length):null,declines=rows.map(r=>{const h=r.reviewHistory.filter(x=>x.accuracy!==null);return {topic:r.topic,course:r.course,drop:h.length>1?h[h.length-2].accuracy-h[h.length-1].accuracy:0}}).sort((a,b)=>b.drop-a.drop);return {well:rows.filter(r=>['Fresh','Stable'].includes(r.memoryStatus)).length,dueToday:due.today.length,overdue:due.overdue.length,avgInterval,fastestDecline:declines[0]?.drop>0?declines[0]:null}}
function examReadinessRules(){return learningRules().examReadiness||FALLBACK_LEARNING_RULES.examReadiness}
function clampScore(value){return Math.max(0,Math.min(100,Math.round(Number(value)||0)))}
function readinessStatus(score){const t=examReadinessRules().statusThresholds||{};if(score>=t.highlyPrepared)return 'Highly Prepared';if(score>=t.onTrack)return 'On Track';if(score>=t.moreReviewNeeded)return 'More Review Needed';return 'Needs Focused Preparation'}
function examRecordFromPlan(plan){migratePlanDays(plan);const topics=uniqueCourses([...(plan.topics||[]),...((plan.days||[]).map(d=>d.mainTopic))]).slice(0,36);return {id:plan.id,title:plan.title||`${plan.course||'Course'} Exam`,course:plan.course||'',testDate:plan.testDate||'',topics,createdAt:plan.createdAt||plan.updatedAt||new Date().toISOString(),planId:plan.id}}
