function topicMatchScore(a='',b=''){const x=normalizeTopicName(a).toLowerCase(),y=normalizeTopicName(b).toLowerCase();if(!x||!y)return 0;if(x===y)return 3;if(x.includes(y)||y.includes(x))return 2;const xs=x.split(/\s+/),ys=y.split(/\s+/),shared=xs.filter(w=>w.length>2&&ys.includes(w)).length;return shared?1:0}
function rowForExamTopic(course,topic){return topicPerformanceRows(course,'','').map(row=>({row,score:topicMatchScore(row.topic,topic)})).filter(x=>x.score).sort((a,b)=>b.score-a.score||((b.row.totalAnswers||0)-(a.row.totalAnswers||0)))[0]?.row||null}
function memoryForExamTopic(course,topic){return memoryRows().map(row=>({row,score:row.course.toLowerCase()===course.toLowerCase()?topicMatchScore(row.topic,topic):0})).filter(x=>x.score).sort((a,b)=>b.score-a.score)[0]?.row||null}
function speedForExamTopic(course,topic){return learningSpeedTopics().map(row=>({row,score:row.course.toLowerCase()===course.toLowerCase()?topicMatchScore(row.topic,topic):0})).filter(x=>x.score).sort((a,b)=>b.score-a.score)[0]?.row||null}
function topicPlanCompletion(plan,topic){const days=(plan?.days||[]).filter(d=>topicMatchScore(d.mainTopic,topic)||((d.subtopics||[]).some(s=>topicMatchScore(s,topic))));if(!days.length)return plannerProgress(plan).percent;return Math.round(days.filter(d=>d.completed).length/days.length*100)}
