function practiceVolumeScore(row,speed){const target=examReadinessRules().practiceVolumeTarget||20,questions=(row?.totalAnswers||0)+(speed?.questionsAnswered||0),quizzes=speed?.quizzesTaken||0;return clampScore((Math.min(target,questions)/target*80)+Math.min(20,quizzes*5))}
