function calculateTopicReadiness(exam,topic,plan){const row=rowForExamTopic(exam.course,topic),memory=memoryForExamTopic(exam.course,topic),speed=speedForExamTopic(exam.course,topic),weights=examReadinessRules().weights||{},accuracy=row?.accuracy??null,recent=topicRecentAccuracy(row)||accuracy,planScore=topicPlanCompletion(plan,topic),memoryScore=memoryReadinessScore(memory),volumeScore=practiceVolumeScore(row,speed),assessed=accuracy!==null&&accuracy!==undefined&&row?.totalAnswers>=topicRules().minimumQuestions;const estimate=clampScore((assessed?accuracy:60)*(weights.topicPerformance||.45)+(recent??60)*(weights.recentPerformance||.2)+planScore*(weights.planCompletion||.15)+memoryScore*(weights.memoryStatus||.1)+volumeScore*(weights.practiceVolume||.1));const score=assessed?estimate:null,status=assessed?readinessStatus(estimate):'Not Assessed';let reason=assessed?`${row.status} topic with ${row.totalAnswers} answered question(s).`:'No topic quiz data yet.';if(memory?.memoryStatus==='Overdue'||memory?.memoryStatus==='Review Recommended')reason+=' Memory review is due.';if(topicTrend(row)==='Declining')reason+=' Recent scores are declining.';return {topic:normalizeTopicName(topic),readiness:score,estimatedReadiness:estimate,status,accuracy,recentAccuracy:recent??null,planCompletion:planScore,memoryStatus:memory?.memoryStatus||'Not Reviewed',lastPracticed:row?.lastPracticed||memory?.lastReviewedAt||null,questionsAnswered:row?.totalAnswers||0,quizzesTaken:speed?.quizzesTaken||0,reason,nextAction:topicNextAction(normalizeTopicName(topic),status),assessed}}
function examEvidence(exam,topics){const courseQuizzes=(user()?.quizzes||[]).filter(q=>(q.subject||'').toLowerCase()===exam.course.toLowerCase()),questions=topics.reduce((sum,t)=>sum+(t.questionsAnswered||0),0),measured=topics.filter(t=>t.assessed).length;return {quizzes:courseQuizzes.length,questions,measuredTopics:measured,totalTopics:topics.length}}
function scorePrediction(readiness,evidence){const mins=examReadinessRules().predictionMinimums||{},coverage=evidence.totalTopics?evidence.measuredTopics/evidence.totalTopics:0,enough=evidence.quizzes>=(mins.quizzes||3)&&evidence.questions>=(mins.questions||15)&&coverage>=(mins.topicCoverage||.5);if(!enough)return {available:false,message:'Not enough information to estimate an exam score yet.'};const margin=examReadinessRules().scoreRangeMargin||3;let confidence='Medium';if(evidence.quizzes>=(mins.quizzes||3)*2&&evidence.questions>=(mins.questions||15)*2&&coverage>=.8)confidence='High';else if(coverage<(mins.topicCoverage||.5)+.2)confidence='Low';return {available:true,low:clampScore(readiness-margin),high:clampScore(readiness+margin),confidence}}
function readinessTrend(history=[]){if(history.length<2)return 'Stable';const last=history[history.length-1],prev=history[history.length-2];if(last.overallReadiness>=prev.overallReadiness+3)return 'Improving';if(last.overallReadiness<=prev.overallReadiness-3)return 'Declining';return 'Stable'}
function recordReadinessSnapshot(profile,exam,result){const list=profile.examReadiness.history[exam.id]||[],todayKey=isoDateOnly(new Date()),last=list[list.length-1];if(!last||last.date!==todayKey||Math.abs((last.overallReadiness||0)-result.overallReadiness)>=1){list.push({date:todayKey,overallReadiness:result.overallReadiness,status:result.status,confidence:result.confidence});if(last&&last.status!==result.status&&profile.profileSettings?.autoUpdate!==false)recordProfileHistory(profile,{type:`examReadiness:${exam.id}`,previousValue:last.status,newValue:result.status,confidence:result.confidence,evidenceCount:result.overallReadiness,reason:`${exam.title} readiness changed to ${result.status} at ${result.overallReadiness}%.`})}profile.examReadiness.history[exam.id]=list.slice(-60);return profile.examReadiness.history[exam.id]}
