function calculateAllExamReadiness({store=true}={}){const profile=ensureLearningProfile();if(!profile)return [];const ids=new Set(),results=examRecords().map(exam=>{ids.add(exam.id);return calculateExamReadiness(exam,{store})});if(store)Object.keys(profile.examReadiness.exams||{}).forEach(id=>{if(!ids.has(id))delete profile.examReadiness.exams[id]});return results}
function nextExamReadiness(course=''){return calculateAllExamReadiness({store:true}).filter(r=>!course||r.course.toLowerCase()===course.toLowerCase()).filter(r=>daysUntilTest(r.testDate)>=0).sort((a,b)=>new Date(a.testDate)-new Date(b.testDate))[0]||null}
function methodRules(){return learningRules().methodTracking||FALLBACK_LEARNING_RULES.methodTracking}
function methodLabel(method='Mixed Method'){const methods=methodRules().methods||FALLBACK_LEARNING_RULES.methodTracking.methods;return methods.find(m=>m.toLowerCase()===String(method).toLowerCase())||'Mixed Method'}
function blankMethodStats(method){return {method,sessions:0,assessments:0,totalScore:0,totalWeight:0,averageScore:null,recentAverage:null,confidence:'Not Enough Data',status:'Not Enough Data',trend:'Stable',links:[],byCourse:{},byTopic:{}}}
function methodConfidence(count){const c=methodRules().confidence||{};if(count>=(c.highMin||10))return 'High';if(count>=(c.mediumMin||6))return 'Medium';if(count>=(c.lowMin||3))return 'Low';return 'Not Enough Data'}
function methodStatus(stats,rank){if(stats.confidence==='Not Enough Data')return 'Not Enough Data';if(rank===0)return 'Most Effective';if(stats.averageScore>=85)return 'Very Effective';if(stats.averageScore>=75)return 'Helpful';return 'Still Learning'}
