function addMethodAggregate(bucket,method,link){bucket[method]=bucket[method]||blankMethodStats(method);const stats=bucket[method],weight=Math.max(1,Number(link.questionsAnswered)||1);stats.assessments++;stats.totalScore+=Number(link.quizAccuracy)*weight;stats.totalWeight+=weight;stats.links=[...(stats.links||[]),link].slice(-40);stats.averageScore=Math.round(stats.totalScore/stats.totalWeight);const recent=stats.links.slice(-(methodRules().recentAssessmentLimit||5)),recentWeight=recent.reduce((sum,l)=>sum+(Number(l.questionsAnswered)||1),0);stats.recentAverage=recentWeight?Math.round(recent.reduce((sum,l)=>sum+Number(l.quizAccuracy)*(Number(l.questionsAnswered)||1),0)/recentWeight):stats.averageScore;stats.confidence=methodConfidence(stats.assessments);stats.trend=methodTrend(stats);return stats}
