function rebuildMethodPerformance(profile=ensureLearningProfile()){const mp=profile.methodPerformance||{},methods={};(methodRules().methods||[]).forEach(m=>methods[m]=blankMethodStats(m));(mp.sessions||[]).forEach(s=>{const method=methodLabel(s.method);methods[method]=methods[method]||blankMethodStats(method);methods[method].sessions++});(mp.links||[]).forEach(link=>{const method=methodLabel(link.method),stats=addMethodAggregate(methods,method,link),courseKey=link.course||'Course',topicKey=`${courseKey}::${normalizeTopicName(link.topic)}`;stats.byCourse[courseKey]=stats.byCourse[courseKey]||blankMethodStats(method);addMethodAggregate(stats.byCourse,courseKey,{...link,method:courseKey});stats.byTopic[topicKey]=stats.byTopic[topicKey]||blankMethodStats(method);addMethodAggregate(stats.byTopic,topicKey,{...link,method:topicKey})});Object.values(methods).sort((a,b)=>(b.averageScore??-1)-(a.averageScore??-1)).forEach((stats,rank)=>stats.status=methodStatus(stats,rank));profile.methodPerformance.methods=methods;const effective=effectiveMethodNames(methods);if(effective.length&&profile.profileSettings?.autoUpdate!==false){const label=effective.join(', ');setProfileInsight(profile,'effectiveMethods',label,{confidence:effective.length>1?'Medium':'High',evidenceCount:(mp.links||[]).length,reason:`Recent linked quiz results show ${label} as your strongest method${effective.length===1?'':'s'}.`});profile.methodPerformance.effectiveMethods=effective}return methods}
function recordStudyMethodSession({course='',topic='',method='Mixed Method',durationMinutes=0,completed=true,startedAt=null}={}){const profile=ensureLearningProfile(),mp=profile.methodPerformance;if(!profile||!mp||mp.enabled===false||!completed||!course||!topic)return null;const session={id:'study-session-'+Date.now()+'-'+Math.random().toString(36).slice(2,6),course,topic:normalizeTopicName(topic),method:methodLabel(method),startedAt:startedAt||new Date(Date.now()-Math.max(1,Number(durationMinutes)||1)*60000).toISOString(),endedAt:new Date().toISOString(),durationMinutes:Number(durationMinutes)||0,completed:true};mp.sessions=[session,...(mp.sessions||[])].slice(0,250);rebuildMethodPerformance(profile);profile.lastUpdated=new Date().toISOString();return session}
