function methodRows(scope={}){const profile=ensureLearningProfile(),methods=rebuildMethodPerformance(profile),rows=Object.values(methods);return rows.map(row=>{let links=row.links||[];if(scope.course)links=links.filter(l=>l.course.toLowerCase()===scope.course.toLowerCase());if(scope.topic)links=links.filter(l=>normalizeTopicName(l.topic).toLowerCase()===normalizeTopicName(scope.topic).toLowerCase());if(!scope.course&&!scope.topic)return row;const scoped=blankMethodStats(row.method);scoped.sessions=(profile.methodPerformance.sessions||[]).filter(s=>s.method===row.method&&(!scope.course||s.course.toLowerCase()===scope.course.toLowerCase())&&(!scope.topic||s.topic.toLowerCase()===normalizeTopicName(scope.topic).toLowerCase())).length;links.forEach(link=>addMethodAggregate({[row.method]:scoped},row.method,link));scoped.status=methodStatus(scoped,0);return scoped}).sort((a,b)=>(b.averageScore??-1)-(a.averageScore??-1))}
function bestMethod(scope={}){return methodRows(scope).filter(r=>r.confidence!=='Not Enough Data'&&r.averageScore!==null).sort((a,b)=>b.averageScore-a.averageScore)[0]||null}
function mostUsedMethod(){return methodRows().slice().sort((a,b)=>b.sessions-a.sessions)[0]||null}
function setMethodFeedback(method,mode){const profile=ensureLearningProfile(),mp=profile.methodPerformance;mp.feedback[method]={mode,updatedAt:new Date().toISOString()};if(mode==='reset'){mp.links=(mp.links||[]).filter(l=>l.method!==method);mp.sessions=(mp.sessions||[]).filter(s=>s.method!==method)}rebuildMethodPerformance(profile);saveDB();renderLearningProfile();toast(mode==='reset'?'Method data reset.':'Thanks. Your feedback was saved.')}
function learningRules(){return appData.learningRules||FALLBACK_LEARNING_RULES}
function learningStyleLabel(style){const rules=learningRules(),value=normalizeStyleEvidence(style);if(value.manual)return value.manual;if(value.evidenceCount<(rules.minimumEvidence||3)||value.confidence<(rules.minimumConfidence||40))return 'Unknown';if(value.score<40)return 'Low';if(value.score<70)return 'Medium';return 'High'}
function confidenceLabel(value=0){if(value>=70)return 'High confidence';if(value>=40)return 'Medium confidence';if(value>0)return 'Low confidence';return 'Not enough evidence'}
function timeOfDayLabel(date=new Date()){const h=date.getHours();if(h>=5&&h<12)return 'Morning';if(h>=12&&h<17)return 'Afternoon';if(h>=17&&h<22)return 'Evening';return 'Night'}
function median(values=[]){const nums=values.map(Number).filter(n=>Number.isFinite(n)&&n>0).sort((a,b)=>a-b);if(!nums.length)return null;const mid=Math.floor(nums.length/2);return nums.length%2?nums[mid]:Math.round((nums[mid-1]+nums[mid])/2)}
function insightFeedback(id){return ensureLearningProfile()?.behavior?.insightFeedback?.[id]||{}}
function adjustedConfidence(id,value){const fb=insightFeedback(id);let next=Number(value)||0;if(fb.disagree)next=Math.max(0,next-70);if(fb.accurate)next=Math.min(100,next+10);if(fb.reset)return 0;return next}
function profileUpdateRules(){return learningRules().profileUpdates||FALLBACK_LEARNING_RULES.profileUpdates}
function confidenceTier(value=0){if(value>=70)return 'High';if(value>=40)return 'Medium';if(value>0)return 'Low';return 'Not Enough Data'}
function profileUpdateCategory(type=''){if(type.includes('method'))return 'Effective methods';if(type.includes('topic'))return 'Topic performance';if(type.includes('memory'))return 'Memory';if(type.includes('speed'))return 'Learning speed';if(type.includes('exam'))return 'Exam readiness';return 'Study habits'}
function recencyWeight(timestamp){const rules=profileUpdateRules(),days=Math.max(0,(Date.now()-new Date(timestamp||Date.now()).getTime())/86400000);if(days<=rules.recentDays)return rules.recentWeight;if(days<=rules.mediumDays)return rules.mediumWeight;return rules.olderWeight}
function historyCountSince(profile,type,date){if(!date)return Infinity;return (profile.behavior?.history||[]).filter(e=>new Date(e.timestamp)>new Date(date)&&(!type||String(e.type||'').includes(type))).length}
function profileCooldownPassed(previous,confidence){if(!previous?.lastUpdated)return true;const rules=profileUpdateRules(),days=(Date.now()-new Date(previous.lastUpdated).getTime())/86400000;return days>=rules.cooldownDays||confidence==='High'}
function recordProfileHistory(profile,{type,previousValue=null,newValue=null,confidence='Low',reason='',evidenceCount=0,source='automatic'}={}){if(!profile||previousValue===newValue)return null;const entry={id:'profile-change-'+Date.now()+'-'+Math.random().toString(36).slice(2,6),date:new Date().toISOString(),type,category:profileUpdateCategory(type),previousValue,newValue,confidence,evidenceCount,reason,source,status:'accepted'};profile.profileHistory=[entry,...(profile.profileHistory||[])].slice(0,profileUpdateRules().historyLimit||120);profile.lastUpdated=entry.date;return entry}
function setProfileInsight(profile,type,value,{confidence='Low',evidenceCount=0,reason='',source='automatic'}={}){profile.profileInsights=profile.profileInsights||{};const previous=profile.profileInsights[type]||{},prevValue=previous.value??null;if(source==='automatic'&&previous.source==='user-selected')return null;if(prevValue===value){profile.profileInsights[type]={...previous,value,confidence,evidenceCount,reason,lastUpdated:previous.lastUpdated||new Date().toISOString(),source:previous.source||source};return null}if(source==='automatic'&&!profileCooldownPassed(previous,confidence)&&historyCountSince(profile,'',previous.lastUpdated)<(profileUpdateRules().minimumNewEvents||5))return null;profile.profileInsights[type]={value,source,confidence,evidenceCount,lastUpdated:new Date().toISOString(),reason};return recordProfileHistory(profile,{type,previousValue:prevValue,newValue:value,confidence,evidenceCount,reason,source})}
