function notifyProfileUpdates(profile){const entry=(profile.pendingProfileUpdates||[]).find(e=>!e.notified);if(!entry)return;entry.notified=true;toast(`Your learning profile has been updated: ${entry.type.replace(/([A-Z])/g,' $1').toLowerCase()} changed to ${entry.newValue}.`)}
