function offerSetStudyingPresence(course=''){const current=user();if(!current)return;const currentPresence=getRawPresenceForUser(current.id);if(currentPresence?.status==='offline')return;confirmDialog({title:'Set status to Studying?',message:course?`Set your status to Studying ${course}?`:'Set your status to Studying?',okText:'Set to Studying',cancelText:'Keep Current Status'}).then(ok=>{if(!ok)return;const result=presenceService.updateCurrentUser({status:'studying',studyCourse:course||selectedCourses()[0]||''});if(result.success){showNotification({type:'success',message:'Status updated.'});renderPresenceSurfaces()}})}function startStudySession(course='',topic='',type='study_session_started'){activeStudySession={startedAt:Date.now(),course,topic,type};recordBehaviorEvent(type,{course,topic,metadata:{timeOfDay:timeOfDayLabel(new Date())}});offerSetStudyingPresence(course||topic)}
function endStudySession(type='study_session_ended'){if(!activeStudySession)return;const duration=Math.max(1,Math.round((Date.now()-activeStudySession.startedAt)/60000));recordBehaviorEvent(type,{course:activeStudySession.course,topic:activeStudySession.topic,durationMinutes:duration});activeStudySession=null}
function recalculateBehaviorProfile(profile=ensureLearningProfile()){if(!profile||profile.profileSettings?.autoUpdate===false)return;const rules=learningRules(),updateRules=profileUpdateRules(),history=profile.behavior?.history||[],totals={visual:0,reading:0,practice:0,audio:0},counts={visual:0,reading:0,practice:0,audio:0};history.forEach(event=>{const weights=rules.behaviorWeights?.[event.type]||{},rWeight=recencyWeight(event.timestamp);Object.entries(weights).forEach(([style,weight])=>{if(totals[style]!==undefined){totals[style]+=(Number(weight)||0)*rWeight;counts[style]++}})});Object.keys(totals).forEach(style=>{const existing=normalizeStyleEvidence(profile.learningStyles[style]);const evidence=totals[style],score=Math.min(100,Math.round(evidence*12)),confidence=adjustedConfidence(`style:${style}`,Math.min(100,Math.round(evidence*18)));profile.learningStyles[style]={...existing,score,confidence,evidenceCount:counts[style],lastUpdated:new Date().toISOString(),source:existing.manual?'user-selected':'automatic'};const label=learningStyleLabel(profile.learningStyles[style]);if(label!=='Unknown'&&!existing.manual)setProfileInsight(profile,`style:${style}`,label,{confidence:confidenceTier(confidence),evidenceCount:counts[style],reason:`Recent weighted activity suggests ${style} learning is ${label.toLowerCase()}.`})});const sessionTypes=['study_session_started','study_session_ended','flashcards_used','quiz_completed','notes_opened','study_plan_session_started'],sessions=history.filter(e=>sessionTypes.includes(e.type)).slice(0,updateRules.rollingSessionLimit||20);if(sessions.length>=(updateRules.minimumRecentSessions||5)&&profile.studyHabits.preferredStudyTimeSource!=='user-selected'){const buckets=sessions.reduce((acc,e)=>{const label=timeOfDayLabel(new Date(e.timestamp));acc[label]=(acc[label]||0)+recencyWeight(e.timestamp);return acc},{}),ranked=Object.entries(buckets).sort((a,b)=>b[1]-a[1]),top=ranked[0],second=ranked[1]||['',0],diff=top[1]-second[1],confidence=top[1]>=12&&diff>=updateRules.strongEvidenceDifference?'High':diff>=updateRules.minimumDifference?'Medium':'Low';if(top&&diff>=updateRules.minimumDifference){const reason=`Most recent study sessions happened in the ${top[0].toLowerCase()}, with stronger evidence than ${second[0]||'other times'}.`;applyHabitInsight(profile,'preferredStudyTime',top[0],confidence,sessions.length,reason)}}const durations=history.filter(e=>e.durationMinutes).slice(0,updateRules.rollingSessionLimit||20).map(e=>e.durationMinutes);if(durations.length>=(updateRules.minimumRecentSessions||5)&&profile.studyHabits.averageSessionSource!=='user-selected')applyHabitInsight(profile,'averageSessionMinutes',median(durations),confidenceTier(Math.min(100,durations.length*10)),durations.length,`Recent timed sessions average about ${median(durations)} minutes.`);const breakDurations=history.filter(e=>e.type==='break_taken'&&e.durationMinutes).slice(0,updateRules.rollingSessionLimit||20).map(e=>e.durationMinutes);if(breakDurations.length>=(updateRules.minimumRecentSessions||5)&&profile.studyHabits.breakFrequencySource!=='user-selected')applyHabitInsight(profile,'breakFrequencyMinutes',median(breakDurations),confidenceTier(Math.min(100,breakDurations.length*10)),breakDurations.length,`Recent break patterns suggest a break about every ${median(breakDurations)} minutes.`)}
function learningInsightReason(id){const profile=ensureLearningProfile(),history=profile?.behavior?.history||[],styles=profile?.learningStyles||{},habits=profile?.studyHabits||{};if(id.startsWith('style:')){const key=id.split(':')[1],style=normalizeStyleEvidence(styles[key]),events=history.filter(e=>learningRules().behaviorWeights?.[e.type]?.[key]);return `Based on ${style.evidenceCount} useful action(s), including ${events.slice(0,3).map(e=>e.type.replaceAll('_',' ')).join(', ')||'recent study activity'}.`}if(id==='habit:preferredStudyTime')return `Based on ${history.filter(e=>['study_session_started','study_session_ended','flashcards_used','quiz_completed','notes_opened','study_plan_session_started'].includes(e.type)).length} recent study session signal(s).`;if(id==='habit:averageSessionMinutes')return `Based on the median duration from ${history.filter(e=>e.durationMinutes).length} timed activity signal(s).`;if(id.startsWith('topic:')){const topic=id.slice(6),row=Object.values(profile.topicPerformance||{}).find(r=>r.topic===topic),stats=profile.performance.topicStats?.[topic];if(row)return `Quiz accuracy: ${row.accuracy}% across ${row.totalAnswers} answered question(s). Recent trend: ${topicTrend(row)}.`;return stats?`Quiz accuracy: ${Math.round(stats.correct/stats.total*100)}% across ${stats.total} answered question(s).`:'Not enough topic evidence yet.'}return 'StudySpark uses repeated activity inside this browser to calculate this insight.'}
function speedKey(course,topic){return `${normalizeCourseName(course||'Course').toLowerCase()}::${normalizeCourseName(topic||'general review').toLowerCase()}`}
function blankLearningSpeedTopic(course,topic){return {course,topic,firstPracticedAt:null,masteredAt:null,originalMasteredAt:null,quizzesTaken:0,questionsAnswered:0,correctAnswers:0,totalStudyMinutes:0,masteryStatus:'Not Started',currentStatus:'Not Started',attemptsToMastery:null,daysToMastery:null,quizAttempts:[],recentAccuracy:null,currentAccuracy:0}}
function learningSpeedTopic(course,topic){const profile=ensureLearningProfile(),key=speedKey(course,topic),topics=profile.learningSpeed.topics;topics[key]=topics[key]||blankLearningSpeedTopic(course,topic);return topics[key]}
