function formatStudyMinutes(minutes=0){const value=Math.round(Number(minutes)||0);if(value<60)return `${value} minute${value===1?'':'s'}`;const h=Math.floor(value/60),m=value%60;return `${h} hour${h===1?'':'s'}${m?` ${m} minutes`:''}`}
function masteryRules(){return learningRules().mastery||FALLBACK_LEARNING_RULES.mastery}
function topicAccuracy(topic){return topic.questionsAnswered?Math.round(topic.correctAnswers/topic.questionsAnswered*100):0}
function recentQuizAccuracy(topic,count=2){const recent=(topic.quizAttempts||[]).slice(-count),total=recent.reduce((sum,q)=>sum+q.total,0),correct=recent.reduce((sum,q)=>sum+q.correct,0);return total?Math.round(correct/total*100):null}
function successfulRecentQuizCount(topic){const rules=masteryRules();return (topic.quizAttempts||[]).slice(-(rules.requiredRecentSuccessfulQuizzes||2)).filter(q=>q.accuracy>=rules.accuracyThreshold).length}
function updateLearningSpeedStatus(topic){const rules=masteryRules(),accuracy=topicAccuracy(topic),recentAccuracy=recentQuizAccuracy(topic,Math.max(1,rules.requiredRecentSuccessfulQuizzes||2)),previousStatus=topic.currentStatus;topic.currentAccuracy=accuracy;topic.recentAccuracy=recentAccuracy;const recentSuccess=successfulRecentQuizCount(topic)>=(rules.requiredRecentSuccessfulQuizzes||2),enough=topic.quizzesTaken>=(rules.minimumQuizzes||3)&&topic.questionsAnswered>=(rules.minimumQuestions||5);let status='Learning';if(!topic.questionsAnswered&&!topic.quizzesTaken)status='Not Started';else if(topic.quizzesTaken>=(rules.needsSupportQuizzes||5)&&accuracy<(rules.needsSupportAccuracy||60))status='Needs More Support';else if(enough&&accuracy>=rules.accuracyThreshold&&recentSuccess)status='Mastered';else if(enough)status='Developing';if(topic.masteredAt&&recentAccuracy!==null&&recentAccuracy<(rules.reviewNeededRecentAccuracy||70)&&topic.quizAttempts.slice(-(rules.requiredRecentSuccessfulQuizzes||2)).reduce((sum,q)=>sum+q.total,0)>=(rules.minimumQuestions||5))status='Review Needed';if(status==='Mastered'&&!topic.masteredAt){topic.masteredAt=new Date().toISOString();topic.originalMasteredAt=topic.originalMasteredAt||topic.masteredAt;topic.attemptsToMastery=topic.quizzesTaken;topic.daysToMastery=daysBetween(topic.firstPracticedAt,topic.masteredAt)}topic.masteryStatus=status;topic.currentStatus=status;if(previousStatus&&previousStatus!==status&&status!=='Not Started'&&ensureLearningProfile()?.profileSettings?.autoUpdate!==false)recordProfileHistory(ensureLearningProfile(),{type:`learningSpeed:${topic.course}:${topic.topic}`,previousValue:previousStatus,newValue:status,confidence:confidenceTier(Math.min(100,(topic.quizzesTaken||0)*18)),evidenceCount:topic.quizzesTaken||0,reason:`${topic.topic} moved to ${status} after ${topic.quizzesTaken} quiz attempt(s).`})}
function learningSpeedCategory(topic){const rules=learningRules().learningSpeedCategories||FALLBACK_LEARNING_RULES.learningSpeedCategories;if(topic.currentStatus==='Review Needed')return 'Review Needed';if(topic.currentStatus==='Needs More Support'||topic.masteryStatus==='Needs More Support')return 'Needs More Support';if(!topic.masteredAt)return topic.masteryStatus==='Developing'?'Developing':'Learning';if(topic.attemptsToMastery<=rules.fastProgressMaxQuizzes)return 'Fast Progress';if(topic.attemptsToMastery<=rules.steadyProgressMaxQuizzes)return 'Steady Progress';return 'Extra Practice Needed'}
function updateLearningSpeedFromQuiz(course,questionResults=[],studyMinutes=0){const groups={};questionResults.forEach(result=>{const topic=topicLabelFromQuestion(result.question||{}),key=speedKey(course,topic);groups[key]=groups[key]||{topic,correct:0,total:0,difficulty:result.question?.difficulty||''};groups[key].total++;if(result.correct)groups[key].correct++});const groupList=Object.values(groups),minutesPerTopic=groupList.length&&studyMinutes?Math.max(1,Math.round(studyMinutes/groupList.length)):0;groupList.forEach(group=>{const topic=learningSpeedTopic(course,group.topic);topic.firstPracticedAt=topic.firstPracticedAt||new Date().toISOString();topic.quizzesTaken+=1;topic.questionsAnswered+=group.total;topic.correctAnswers+=group.correct;topic.totalStudyMinutes=Math.round((topic.totalStudyMinutes||0)+minutesPerTopic);topic.quizAttempts.push({date:new Date().toISOString(),correct:group.correct,total:group.total,accuracy:Math.round(group.correct/group.total*100),difficulty:group.difficulty});updateLearningSpeedStatus(topic)})}
function addLearningSpeedMinutes(course,topic,minutes){if(!course||!topic||!minutes)return;const item=learningSpeedTopic(course,topic);item.totalStudyMinutes=Math.max(0,Math.round((item.totalStudyMinutes||0)+Number(minutes)));if(item.questionsAnswered||item.quizzesTaken)item.masteryStatus=item.masteryStatus==='Not Started'?'Learning':item.masteryStatus;updateLearningSpeedStatus(item)}
function learningSpeedTopics(){return Object.values(ensureLearningProfile()?.learningSpeed?.topics||{}).filter(t=>t.questionsAnswered||t.quizzesTaken||t.totalStudyMinutes)}
