function repairEncoding(value=''){
  let text = String(value ?? '');
  const multiply = String.fromCharCode(215), check = String.fromCharCode(10003), square = String.fromCharCode(9633);
  const repairs = [
    [/\u00c3\u0097/g, multiply],
    [/\u00ef\u00bf\u00bd/g, ''],
    [/\u00c2\u00b7|\u00c2/g, ''],
    [/\u00e2\u0080\u00a2/g, '-'],
    [/\u00e2\u0153\u201c/g, check],
    [/\u00e2\u0080\u0098|\u00e2\u0080\u0099|\u00e2\u20ac\u2122/g, "'"],
    [/\u00e2\u0080\u009c|\u00e2\u0080\u009d|\u00e2\u20ac\u0153|\u00e2\u20ac\u009d/g, '"'],
    [/\u00e2\u0080\u0093|\u00e2\u0080\u0094|\u00e2\u20ac\u201c|\u00e2\u20ac\u201d/g, '-'],
    [/\u00e2\u0086\u0092/g, '->'],
    [/\u00e2\u008b\u00ae/g, '...'],
    [/\u00e2\u0096\u00a1/g, square],
    [/This is an estimate based on recorded performance, not a guaranteed exam result\./g, PREDICTION_DISCLAIMER],
    [/This is an estimate based on recorded activity, not a guaranteed exam result\./g, PREDICTION_DISCLAIMER],
    [/This is an estimate based on stored StudySpark activity, not a guaranteed exam result\./g, PREDICTION_DISCLAIMER],
    [/This is an estimate based on recorded activity and performance\. It is not guaranteed\./g, PREDICTION_DISCLAIMER],
    [/not a certain result/g, 'not a guaranteed result']
  ];
  repairs.forEach(([pattern,replacement])=>{text=text.replace(pattern,replacement)});
  return text;
}
