function performShowView(view){saveSidebarScrollPosition();ensurePredictionDashboardShell();ensureWellBeingHelpSafetyShell();$$('.app-view').forEach(v=>v.classList.remove('active'));$(`#${view}View`).classList.add('active');$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view&&b.closest('#appNav')));$('#breadcrumb').textContent=repairEncoding(viewNames[view][0]);$('#viewTitle').textContent=repairEncoding(viewNames[view][1]);closeMobileSidebar();if(view==='progress')renderProgress();if(view==='wellBeing')renderStudyWellBeingPage();if(view==='wellBeingDashboard')renderWellBeingDashboardPage();if(view==='wellBeingHelpSafety')renderWellBeingHelpSafetyPage();if(view==='wellBeingReminderSettings')renderWellBeingReminderSettingsPage();if(view==='learningProfile')renderLearningProfile();if(view==='examReadiness')renderExamReadinessPage();if(view==='futureSuccess')renderFutureSuccessPage();if(view==='predictionDashboard')renderPredictionDashboardPage();if(view==='dashboard')renderDashboard();if(view==='settings')renderSettings();if(view==='notifications')renderNotificationsPage();if(view==='folders')renderFoldersPage();if(view==='folderDetail')renderFolderDetail();if(view==='noteDetail')renderNoteDetail();if(view==='planner')renderPlannerPage();if(view==='planDetail')renderPlanDetail();if(view==='friendsList')renderFriendsListPage();if(view==='friendProfile')renderFriendProfilePage();if(view==='friends')renderFriendsPage();if(view==='friendRequests')renderFriendRequestsPage();if(view==='studyMatch')renderStudyMatchPage();if(view==='studyPartnerResults')renderStudyPartnerResultsPage();if(view==='studyPartnerProfile')renderStudyPartnerProfilePage();if(view==='studyRequests')renderStudyRequestsPage();if(view==='studyGroups')renderStudyGroupsPage();if(view==='studyGroupCreate')renderStudyGroupCreatePage();if(view==='studyGroupDetail')renderStudyGroupDetailPage();if(view==='safetyPrivacy')renderSafetyPrivacyPage();if(view==='instructions')ensureChapterWeightsInstructions();repairRenderedEncoding($(`#${view}View`));restoreSidebarScrollPosition();keepActiveSidebarLinkVisible();if(view==='studyPartnerResults'){const savedScroll=Number(sessionStorage.getItem('studyPartnerResultsScroll')||0);window.scrollTo(0,savedScroll)}else window.scrollTo(0,0)}
async function unsavedPlanDialog(){return new Promise(resolve=>{const modal=$('#confirmModal'),ok=$('#confirmOk'),cancel=$('#confirmCancel'),actions=cancel.parentElement,leave=document.createElement('button');$('#confirmTitle').textContent='Unsaved Study Plan';$('#confirmMessage').textContent="You haven't saved this study plan yet.";ok.textContent='Save Study Plan';cancel.textContent='Cancel';ok.className='btn btn-primary';leave.className='btn btn-secondary';leave.type='button';leave.textContent='Leave Without Saving';actions.insertBefore(leave,cancel);modal.classList.add('open');modal.setAttribute('aria-hidden','false');const done=value=>{modal.classList.remove('open');modal.setAttribute('aria-hidden','true');ok.onclick=cancel.onclick=leave.onclick=null;leave.remove();resolve(value)};ok.onclick=()=>done('save');leave.onclick=()=>done('leave');cancel.onclick=()=>done('cancel')})}
