async function showView(view,options={}){if((chapterWeightEditorDirty||assessmentWeightEditorDirty)&&view!=='futureSuccess'&&!options.force){const leave=await confirmDialog({title:'Unsaved Prediction Weights',message:chapterWeightEditorDirty?'You have unsaved chapter-weight changes.':'You have unsaved assessment-weight changes.',okText:'Leave Without Saving',cancelText:'Stay',danger:true});if(!leave)return;chapterWeightEditorDirty=false;assessmentWeightEditorDirty=false;sessionStorage.removeItem('chapterWeightEditorOpen');sessionStorage.removeItem('assessmentWeightEditorOpen')}if(pendingPlan&&!pendingPlanSaved&&view!=='planner'&&!options.force){const choice=await unsavedPlanDialog();if(choice==='cancel')return;if(choice==='save')savePendingPlan();if(choice==='leave'){pendingPlan=null;pendingPlanSaved=false;renderPlanPreview()}}performShowView(view);if(view==='planner'&&options.target)scrollPlannerTarget(options.target)}
