function bindSettingsShortcuts(){$$('[data-view="settings"]').forEach(btn=>btn.onclick=()=>showView('settings'))}
function renderReminderSettingsShortcut(){const layout=$('#settingsView .settings-layout');if(!layout)return;let card=$('#reminderSettingsShortcut');if(!card){layout.insertAdjacentHTML('beforeend','<article class="card settings-card" id="reminderSettingsShortcut"><div><h3>Reminder & Well-Being Settings</h3><p>Customize break reminders, late-night warnings, quiet mode, sounds, vibration, and notification levels.</p></div><div class="profile-fact-grid" id="settingsReminderSummary"></div><p class="readiness-note">These settings change reminders only. Your recorded study data and study-pattern analysis are unchanged.</p><button class="btn btn-primary" id="openReminderSettingsFromAccount" type="button">Open Reminder Settings</button></article>');card=$('#reminderSettingsShortcut')}const summary=$('#settingsReminderSummary');if(summary)summary.innerHTML=reminderSettingsSummaryHTML(loadReminderSettings()).replace(/^<div class="profile-fact-grid">|<\/div>$/g,'');$('#openReminderSettingsFromAccount')?.addEventListener('click',()=>showView('wellBeingReminderSettings'))}
function bindNotificationPreviewActions(root=document){$$('[data-notification-preview]',root).forEach(btn=>btn.onclick=()=>{const type=normalizeNotificationType(btn.dataset.notificationPreview)||'information';showNotification({type,category:'system',title:NOTIFICATION_TITLES[type],message:fallbackNotificationMessage(type),preview:true,actions:[{id:'continue',label:'Dismiss'}]})})}
function renderNotificationSettingsCard(){const layout=$('#settingsView .settings-layout');if(!layout)return;let card=$('#notificationSettingsCard');const settings=loadReminderSettings(),validation=validateNotificationRules(studyWellBeingRules()),permission='Notification' in window?Notification.permission:'unsupported';if(!card){layout.insertAdjacentHTML('beforeend','<article class="card settings-card notification-settings-card" id="notificationSettingsCard"></article>');card=$('#notificationSettingsCard')}card.innerHTML=`<div><h3>Notifications</h3><p>Control StudySpark reminder popups and optional browser notifications.</p></div>${validation.valid?'':`<div class="timer-config-error" role="alert">${escapeHTML(validation.errors[0]||'Notification settings need review.')}</div>`}<label class="privacy-toggle"><span>Enable Browser Notifications</span><input id="browserNotificationsEnabledSetting" type="checkbox" ${settings.browserNotificationsEnabled?'checked':''}></label><label class="privacy-toggle"><span>Show Detailed Browser Notification Text</span><input id="detailedBrowserNotificationTextSetting" type="checkbox" ${settings.detailedBrowserNotificationText?'checked':''}></label><p class="readiness-note">Browser permission: ${escapeHTML(permission)}. If permission is denied, in-app notifications still work.</p><div class="study-session-actions"><button class="btn btn-secondary" id="requestBrowserNotificationPermission" type="button">Request Permission</button><button class="btn btn-primary" id="saveNotificationSettingsBtn" type="button">Save Notification Settings</button></div><div class="study-session-actions notification-preview-actions"><button class="btn btn-secondary" data-notification-preview="success" type="button">Preview Success</button><button class="btn btn-secondary" data-notification-preview="information" type="button">Preview Information</button><button class="btn btn-secondary" data-notification-preview="warning" type="button">Preview Warning</button><button class="btn btn-secondary" data-notification-preview="error" type="button">Preview Error</button></div>`;$('#saveNotificationSettingsBtn',card)?.addEventListener('click',()=>{const result=saveReminderSettings({...settings,browserNotificationsEnabled:$('#browserNotificationsEnabledSetting',card)?.checked===true,detailedBrowserNotificationText:$('#detailedBrowserNotificationTextSetting',card)?.checked===true});showNotification({type:result.success?'success':'warning',message:result.success?'Notification settings saved.':result.errors[0]})});$('#requestBrowserNotificationPermission',card)?.addEventListener('click',async()=>{if(!('Notification' in window))return showNotification({type:'information',message:'Browser notifications are not supported here.'});const result=await Notification.requestPermission();showNotification({type:result==='granted'?'success':'information',message:result==='granted'?'Browser notifications are enabled.':'Browser notifications were not enabled.'});renderNotificationSettingsCard()});bindNotificationPreviewActions(card)}
function renderDailyCheckInSettingsCard(){const layout=$('#settingsView .settings-layout');if(!layout)return;let card=$('#dailyCheckInSettingsCard');if(!card){layout.insertAdjacentHTML('beforeend','<article class="card settings-card" id="dailyCheckInSettingsCard"><div><h3>Daily Check-In</h3><p>Control whether StudySpark automatically offers the optional daily check-in before study sessions.</p></div><label>Daily Check-In<select id="dailyCheckInEnabledSetting"><option value="on">Enabled</option><option value="off">Disabled</option></select></label><p class="readiness-note">'+escapeHTML(DAILY_CHECK_IN_NOTICE)+'</p><button class="btn btn-primary" id="saveDailyCheckInSettingBtn" type="button">Save Daily Check-In Setting</button></article>');card=$('#dailyCheckInSettingsCard')}$('#dailyCheckInEnabledSetting').value=getStudyWellBeingSettings().dailyCheckInEnabled===false?'off':'on';$('#saveDailyCheckInSettingBtn')?.addEventListener('click',()=>{saveStudyWellBeingSettings({dailyCheckInEnabled:$('#dailyCheckInEnabledSetting')?.value!=='off'});renderSettings();showNotification({type:'success',message:'Daily Check-In setting saved.'})})}
function connectionIdentityHTML(){return '<section class="connection-identity-card card settings-card" aria-labelledby="connection-identity-title"><h2 id="connection-identity-title">Connection Identity</h2><div class="student-identity-row"><div><span class="field-label">Name</span><p id="profile-student-name">Student</p></div></div><div class="student-identity-row"><div><span class="field-label">Student ID</span><p id="profile-student-id" class="student-id-value">Not available</p></div><button class="btn btn-primary" id="copy-student-id" type="button">Copy ID</button></div><p class="privacy-note">Your Student ID can be used to find your StudySpark profile. Share it only with people you want to connect with.</p><p class="privacy-note">Your email address is not shown to other students.</p><button class="btn btn-secondary" id="learnAboutConnectionsBtn" type="button">Learn About Connections</button></section>'}
function renderConnectionIdentityCard(){const layout=$('#settingsView .settings-layout');if(!layout)return;let card=$('#connectionIdentityCard');if(!card){layout.insertAdjacentHTML('afterbegin',connectionIdentityHTML().replace('<section class="connection-identity-card card settings-card"','<section id="connectionIdentityCard" class="connection-identity-card card settings-card"'));card=$('#connectionIdentityCard')}renderStudentIdentity(user());if($('#copy-student-id')&&!isGuestMode())$('#copy-student-id').onclick=()=>copyStudentId(user()?.studentId);if($('#learnAboutConnectionsBtn'))$('#learnAboutConnectionsBtn').onclick=()=>{showView('instructions');setTimeout(()=>$('#studentIdInstructions')?.scrollIntoView({behavior:'smooth',block:'center'}),50)}}
function renderSettingsStudentIdField(){const form=$('#profileForm');if(!form)return;let wrap=$('#settingsStudentIdWrap');if(!wrap){const gradeLabel=$('#settingsGrade')?.closest('label');gradeLabel?.insertAdjacentHTML('afterend','<label id="settingsStudentIdWrap">Student ID<input id="settings-student-id" type="text" readonly aria-describedby="student-id-help"><p id="student-id-help" class="privacy-note">Your Student ID is permanent and cannot be changed.</p></label>');wrap=$('#settingsStudentIdWrap')}const guest=isGuestMode(),input=$('#settings-student-id');if(input)input.value=guest?'Create an account to receive a Student ID.':normalizeStudentId(user()?.studentId);wrap.classList.toggle('guest-student-id',guest)}
function renderStudentIdentity(u){const nameElement=$('#profile-student-name'),idElement=$('#profile-student-id'),copyButton=$('#copy-student-id');if(!nameElement||!idElement||!copyButton)return;if(isGuestMode()){nameElement.textContent=u?.name||'Guest Student';idElement.textContent='Create an account to receive a Student ID.';idElement.removeAttribute('aria-label');copyButton.disabled=false;copyButton.textContent='Create Account';copyButton.onclick=()=>openAuth('signup');return}if(!u||!isValidStudentId(u.studentId)){nameElement.textContent=u?.name||'Student';idElement.textContent='Not available';idElement.removeAttribute('aria-label');copyButton.disabled=true;copyButton.textContent='Copy ID';copyButton.onclick=null;return}nameElement.textContent=u.name||'Student';idElement.textContent=normalizeStudentId(u.studentId);idElement.setAttribute('aria-label',`Student ID, ${normalizeStudentId(u.studentId).replace(/-/g,', ').split('').join(' ')}`);copyButton.disabled=false;copyButton.textContent='Copy ID'}
