function presenceStatusOptionsHTML(selected='online'){return PRESENCE_STATUSES.map(status=>`<option value="${status}" ${selected===status?'selected':''}>${escapeHTML({online:'Online',studying:'Studying',busy:'Busy',offline:'Offline'}[status])}</option>`).join('')}
function presenceCourseOptionsHTML(value=''){const courses=selectedCourses(),custom=String(value||'').trim(),options=courses.map(course=>`<option value="${escapeHTML(course)}"></option>`).join('');return `<datalist id="presenceCourseOptions">${options}${custom&&!courses.some(c=>c.toLowerCase()===custom.toLowerCase())?`<option value="${escapeHTML(custom)}"></option>`:''}</datalist>`}
function presenceSettingsCardHTML({compact=false}={}){const current=user(),presence=getPresenceForUser(current?.id),settings=ensurePrivacySettings(),status=isValidPresenceStatus(presence.status)?presence.status:'offline';return `<section class="presence-settings-card card ${compact?'presence-settings-compact':''}" aria-labelledby="presence-settings-title"><div class="card-head"><div><h2 id="presence-settings-title">Your Status</h2><p>Presence is simulated in this front-end prototype and may not reflect activity in another browser or device.</p></div>${presenceBadgeHTML(presence)}</div><label for="presence-status">Status<select id="presence-status">${presenceStatusOptionsHTML(status)}</select></label><div id="studying-course-field" ${status==='studying'?'':'hidden'}><label for="presence-study-course">Studying Course<input id="presence-study-course" type="text" maxlength="60" list="presenceCourseOptions" placeholder="Biology" value="${escapeHTML(presence.studyCourse||'')}"></label>${presenceCourseOptionsHTML(presence.studyCourse)}</div><label for="presence-custom-message">Custom Message<input id="presence-custom-message" type="text" maxlength="80" placeholder="Optional short status note" value="${escapeHTML(presence.customMessage||'')}"></label><label for="presence-visibility">Who can see my status?<select id="presence-visibility"><option value="friends" ${settings.presenceVisibility==='friends'?'selected':''}>Friends</option><option value="nobody" ${settings.presenceVisibility==='nobody'?'selected':''}>Nobody</option></select></label><div class="presence-actions"><button class="btn btn-primary" id="save-presence" type="button">Save Status</button><span id="presence-save-status" aria-live="polite"></span></div><p class="prototype-notice">For a real multi-user website, presence requires a backend and live database.</p></section>`}
function mountPresenceSettings(root){if(!root||!user())return;root.innerHTML=presenceSettingsCardHTML();bindPresenceSettings(root)}
function bindPresenceSettings(root=document){const status=$('#presence-status',root),courseField=$('#studying-course-field',root),save=$('#save-presence',root),live=$('#presence-save-status',root);if(!status||!save)return;status.onchange=()=>{const studying=status.value==='studying';if(courseField){courseField.hidden=!studying;$$('input,select,textarea,button',courseField).forEach(el=>el.disabled=!studying)}};status.onchange();save.onclick=()=>{const result=presenceService.updateCurrentUser({status:status.value,studyCourse:$('#presence-study-course',root)?.value||'',customMessage:$('#presence-custom-message',root)?.value||''});if(!result.success){const message=result.error&&result.error.includes('private contact')?'Do not include private contact or location information in your status.':result.error&&result.error.includes('60')?'Enter a valid study course.':'Your status could not be saved.';if(live)live.textContent=message;showNotification({type:'warning',message});return}const settings=ensurePrivacySettings();settings.presenceVisibility=$('#presence-visibility',root)?.value==='nobody'?'nobody':'friends';saveDB();if(live)live.textContent='Status updated.';showNotification({type:'success',message:'Status updated.'});renderPresenceSurfaces();if(settings.presenceVisibility==='nobody')showNotification({type:'success',message:'Status privacy updated.'})}}
function renderPresenceSurfaces(){renderFriendsListPage();renderFriendProfilePage();renderStudyMatchPage();renderSettings()}
