function isBasicStudyMatch(userProfile,partner,rules=matchingRules().matching){return evaluateBasicMatch(userProfile,partner,rules).eligible}
function sortStudyMatches(matches){return [...matches].sort((a,b)=>{const aEvaluation=a.evaluation,bEvaluation=b.evaluation;if(aEvaluation.topicMatch.isTwoWayMatch!==bEvaluation.topicMatch.isTwoWayMatch)return Number(bEvaluation.topicMatch.isTwoWayMatch)-Number(aEvaluation.topicMatch.isTwoWayMatch);if(aEvaluation.totalMatchScore!==bEvaluation.totalMatchScore)return bEvaluation.totalMatchScore-aEvaluation.totalMatchScore;if(aEvaluation.topicMatch.score!==bEvaluation.topicMatch.score)return bEvaluation.topicMatch.score-aEvaluation.topicMatch.score;if(aEvaluation.timeMatch.score!==bEvaluation.timeMatch.score)return bEvaluation.timeMatch.score-aEvaluation.timeMatch.score;if(aEvaluation.preferenceMatch.score!==bEvaluation.preferenceMatch.score)return bEvaluation.preferenceMatch.score-aEvaluation.preferenceMatch.score;const aDays=aEvaluation.examDateDifferenceDays??Infinity,bDays=bEvaluation.examDateDifferenceDays??Infinity;if(aDays!==bDays)return aDays-bDays;if(aEvaluation.courseCompatibility!==bEvaluation.courseCompatibility)return aEvaluation.courseCompatibility==='exact'?-1:1;return a.partner.name.localeCompare(b.partner.name)})}
function findEligibleStudyPartners(userProfile,partners=studyPartners,rules=matchingRules().matching){return sortStudyMatches(partners.map(partner=>({partner,evaluation:evaluateBasicMatch(userProfile,partner,rules)})).filter(result=>result.evaluation.eligible))}
function studyMatchMinimumScore(){const saved=Number(user()?.studyMatchMinimumScore),fallback=matchingRules().finalScore.minimumDisplayedScore??60;return [50,60,70,80].includes(saved)?saved:fallback}
function setStudyMatchMinimumScore(value){const next=Math.max(50,Number(value)||60);user().studyMatchMinimumScore=[50,60,70,80].includes(next)?next:60;saveDB();renderStudyPartnerCards();renderStudyPartnerResultsPage()}
function sessionLengthTieValue(result){const match=result.evaluation.preferenceMatch?.sessionLengthMatch;if(match?.exact)return 2;if(match?.compatible)return 1;return 0}
function exactTimeTieValue(result){return result.evaluation.timeMatch?.exactMatches?.length?1:0}
