function getFirstName(name=''){return partnerText(name).split(/\s+/)[0]||'This partner'}
function explanationId(type,text){return `${type}-${normalizeText(text).replace(/\s+/g,'-').slice(0,60)}`}
function formatTopicList(topics){const cleanTopics=Array.isArray(topics)?topics.map(topic=>topic?.displayTopic||topic?.topic||topic).map(partnerText).filter(Boolean):[];if(cleanTopics.length===0)return '';if(cleanTopics.length===1)return cleanTopics[0];if(cleanTopics.length===2)return `${cleanTopics[0]} and ${cleanTopics[1]}`;const more=cleanTopics.length-2;return `${cleanTopics[0]}, ${cleanTopics[1]}, and ${more} more ${more===1?'topic':'topics'}`}
function createCourseExplanation(userProfile,partner,evaluation){if(evaluation.courseCompatibility==='exact')return {id:'same-course',type:'course',priority:4,text:`You are both studying ${partner.course}.`,points:evaluation.finalScoreBreakdown?.course,positive:true};if(evaluation.courseCompatibility==='related')return {id:'related-course',type:'course',priority:5,text:'Your courses are closely related.',points:evaluation.finalScoreBreakdown?.course,positive:true};return null}
function friendlyStudyTime(value){const map={'weekday morning':'weekday mornings','weekday afternoon':'weekday afternoons','weekday evening':'weekday evenings','weekend morning':'weekend mornings','weekend afternoon':'weekend afternoons','weekend evening':'weekend evenings'};return map[normalizeTimeCategory(value)]||timeCategoryLabel(value).toLowerCase()}
function createSharedTimeExplanation(times=[]){const labels=times.map(friendlyStudyTime).filter(Boolean);if(!labels.length)return '';if(labels.length===1)return `You are both available on ${labels[0]}.`;if(labels.length===2)return `You share ${labels[0]} and ${labels[1]} availability.`;return `You share ${labels[0]}, ${labels[1]}, and ${labels.length-2} more study times.`}
function createMeetingTypeExplanation(value){const type=normalizeMeetingType(value);if(type==='online')return 'You both prefer online study sessions.';if(type==='in person')return 'You both prefer in-person study sessions.';if(type==='either')return 'You are both flexible about meeting online or in person.';return ''}
function createGroupSizeExplanation(value){const size=groupSizeLabel(value);if(size==='2')return 'You both prefer studying with one partner.';if(size==='No Preference')return 'You are both flexible about group size.';if(size!=='Not provided')return `You both prefer studying in groups of ${size}.`;return ''}
function createStudyMethodExplanation(methods=[]){const labels=(methods||[]).map(studyMethodLabel).filter(Boolean).map(x=>x.toLowerCase());if(!labels.length)return '';if(labels.length===1)return `You both prefer ${labels[0]}.`;if(labels.length===2)return `You both prefer ${labels[0]} and ${labels[1]}.`;return `You share ${labels[0]}, ${labels[1]}, and ${labels.length-2} more study methods.`}
function addMatchExplanation(list,item){if(!item||!item.text)return;const clean={positive:true,points:0,...item,text:partnerText(item.text)};clean.id=clean.id||explanationId(clean.type,clean.text);if(!list.some(existing=>existing.text===clean.text))list.push(clean)}
function generateMatchExplanations(userProfile,partner,evaluation,finalScore={}){const explanations=[],firstName=getFirstName(partner.name),breakdown=finalScore.breakdown||{};evaluation={...evaluation,finalScoreBreakdown:breakdown};if(evaluation.topicMatch?.isTwoWayMatch)addMatchExplanation(explanations,{id:'mutual-topic-help',type:'topic',priority:1,text:'Your strengths complement each other.',positive:true});const partnerHelpTopics=evaluation.topicMatch?.partnerCanHelpUser||[],partnerTopicText=formatTopicList(partnerHelpTopics);if(partnerTopicText)addMatchExplanation(explanations,{id:'partner-can-help',type:'topic',priority:2,text:`${firstName} can help you with ${partnerTopicText}.`,positive:true});const userHelpTopics=evaluation.topicMatch?.userCanHelpPartner||[],userTopicText=formatTopicList(userHelpTopics);if(userTopicText)addMatchExplanation(explanations,{id:'user-can-help',type:'topic',priority:3,text:`You can help ${firstName} with ${userTopicText}.`,positive:true});addMatchExplanation(explanations,createCourseExplanation(userProfile,partner,evaluation));if(evaluation.examCompatible)addMatchExplanation(explanations,{id:'same-exam',type:'exam',priority:6,text:`You are both preparing for the ${partner.examName}.`,points:breakdown.exam,positive:true});const dateDifference=evaluation.examDateDifferenceDays;if(Number.isFinite(dateDifference))addMatchExplanation(explanations,{id:'exam-date',type:'exam-date',priority:7,text:dateDifference===0?'Your exams are on the same day.':`Your exams are ${dateDifference} ${dateDifference===1?'day':'days'} apart.`,points:breakdown.examDate,positive:true});const exactTimes=evaluation.timeMatch?.exactMatches||[];if(exactTimes.length)addMatchExplanation(explanations,{id:'shared-time',type:'time',priority:8,text:createSharedTimeExplanation(exactTimes),points:breakdown.studyTime,positive:true});else if(evaluation.timeMatch?.relatedMatches?.length)addMatchExplanation(explanations,{id:'related-time',type:'time',priority:9,text:'Your preferred study times are close.',points:breakdown.studyTime,positive:true});const meetingMatch=evaluation.preferenceMatch?.meetingTypeMatch;if(meetingMatch?.exact)addMatchExplanation(explanations,{id:'meeting-type',type:'preference',priority:10,text:createMeetingTypeExplanation(partner.meetingType),points:breakdown.meetingType,positive:true});else if(meetingMatch?.compatible)addMatchExplanation(explanations,{id:'meeting-compatible',type:'preference',priority:11,text:'Your meeting preferences are compatible.',points:breakdown.meetingType,positive:true});const groupMatch=evaluation.preferenceMatch?.groupSizeMatch;if(groupMatch?.exact)addMatchExplanation(explanations,{id:'group-size',type:'preference',priority:12,text:createGroupSizeExplanation(partner.groupSize),positive:true});else if(groupMatch?.compatible)addMatchExplanation(explanations,{id:'group-size-compatible',type:'preference',priority:13,text:'Your preferred group sizes are similar.',positive:true});const methodMatch=evaluation.preferenceMatch?.studyMethodMatch;if(methodMatch?.exactMatches?.length)addMatchExplanation(explanations,{id:'study-method',type:'preference',priority:14,text:createStudyMethodExplanation(methodMatch.exactMatches),positive:true});else if(methodMatch?.hasMixedCompatibility)addMatchExplanation(explanations,{id:'mixed-method',type:'preference',priority:15,text:'One of you prefers a flexible mix of study methods.',positive:true});const sessionMatch=evaluation.preferenceMatch?.sessionLengthMatch;if(sessionMatch?.exact)addMatchExplanation(explanations,{id:'session-length',type:'preference',priority:16,text:`You both prefer ${partner.sessionLength} study sessions.`,positive:true});else if(sessionMatch?.compatible)addMatchExplanation(explanations,{id:'session-length-compatible',type:'preference',priority:17,text:'Your preferred session lengths are similar.',positive:true});return explanations.filter(explanation=>explanation&&explanation.text).sort((a,b)=>a.priority-b.priority)}
function generateStudyMatches(userProfile,partners=getActiveStudyPartners(),rules=matchingRules()){const minimumScore=studyMatchMinimumScore();return partners.filter(partner=>partner.matchingEnabled===true&&!isStudentBlocked(partner.id)).map(partner=>{const evaluation=evaluateBasicMatch(userProfile,partner,rules.matching),scoreResult=calculateFinalMatchScore(evaluation,rules.finalScore),finalScore={...scoreResult,label:getOverallMatchLabel(scoreResult.score)},explanations=generateMatchExplanations(userProfile,partner,evaluation,finalScore);return {partner,evaluation,finalScore,explanations}}).filter(result=>passesMinimumMatchScore(result.finalScore,minimumScore)).sort(sortFinalStudyMatches)}
function matchLevelLabel(level){return {exact:'Exact match',compatible:'Compatible',different:'Different preferences',unknown:'Not provided'}[level]||'Not provided'}
function preferenceReasonList(userProfile,partner,preference){const items=[];if(preference.meetingTypeMatch.exact)items.push(`You both prefer ${meetingTypeLabel(userProfile?.meetingType).toLowerCase()} sessions.`);else if(preference.meetingTypeMatch.compatible)items.push('One of you is flexible about meeting format.');else if(preference.meetingTypeMatch.level==='different')items.push('You prefer different meeting formats.');if(preference.groupSizeMatch.exact)items.push(`You both prefer groups of ${groupSizeLabel(userProfile?.groupSize)}.`);else if(preference.groupSizeMatch.compatible)items.push('Your group-size preferences are close.');if(preference.studyMethodMatch.exactMatches.length)items.push(`You both use ${preference.studyMethodMatch.exactMatches.map(studyMethodLabel).join(', ')}.`);else if(preference.studyMethodMatch.hasMixedCompatibility)items.push('One of you selected Mixed, so study methods are flexible.');if(preference.sessionLengthMatch.exact)items.push(`You both prefer ${sessionLengthLabel(userProfile?.sessionLength)} sessions.`);else if(preference.sessionLengthMatch.compatible)items.push('You prefer similar session lengths.');return items.length?items:['Different study preferences do not remove this match.']}
function matchExplanation(userProfile,partner,evaluation){const days=evaluation.examDateDifferenceDays,topic=evaluation.topicMatch,time=evaluation.timeMatch,items=[evaluation.courseCompatibility==='exact'?'Same course':`Related ${partner.subject} course`,sameText(normalizeExamName(userProfile.examName),normalizeExamName(partner.examName))?`Same ${partner.examName}`:'Same exam',days===0?'Exam dates are on the same day':`Exam dates are ${days} day${days===1?'':'s'} apart`];if(topic.isTwoWayMatch)items.push('You can help each other with different topics');else if(topic.totalComplementaryTopics>0)items.push('One of you can directly help with a review topic');else items.push('No direct strength-and-need topic matches were found');if(time.exactMatches.length)items.push(`You are both available during ${time.exactMatches.map(timeCategoryLabel).join(', ')}.`);else if(time.relatedMatches.length)items.push('Your preferred times are close, but you may need to adjust the exact meeting time.');else if(!getUniqueTimeCategories(userProfile?.preferredTimes).length||!getUniqueTimeCategories(partner?.preferredTimes).length)items.push('Study-time preference not provided.');else items.push('Your preferred study times are different.');return [...items,...preferenceReasonList(userProfile,partner,evaluation.preferenceMatch)]}
function createTopMatchReasons(partner,evaluation,finalScore){return generateMatchExplanations(studyMatchProfile(),partner,evaluation,finalScore).slice(0,4).map(reason=>reason.text)}
function safePartnerLocation(partner){return ['In Person','Either'].includes(partner.meetingType)&&partner.generalLocation?partner.generalLocation:''}
function topicMatchList(items,empty){return items.length?`<ul>${items.map(item=>`<li>${escapeHTML(item.displayTopic)}</li>`).join('')}</ul>`:`<p>${escapeHTML(empty)}</p>`}
function timeMatchList(time){if(time.exactMatches.length)return `<ul>${time.exactMatches.map(t=>`<li>${escapeHTML(timeCategoryLabel(t))}</li>`).join('')}</ul>`;if(time.relatedMatches.length)return `<ul>${time.relatedMatches.map(t=>`<li>${escapeHTML(timeCategoryLabel(t.userCategory))} and ${escapeHTML(timeCategoryLabel(t.partnerCategory))}</li>`).join('')}</ul>`;return `<p>${time.missing?'Study-time preference not provided.':'Your preferred study times are different.'}</p>`}
function preferenceSummaryHTML(partner,preference){const methodNote=preference.studyMethodMatch.exactMatches.length?'Shared method':(preference.studyMethodMatch.hasMixedCompatibility?'Flexible method':'No shared method');return '<div class="study-match-preview-block"><b>Study Preferences</b>'+'<p>Meeting: '+escapeHTML(partner.meetingType)+' - '+escapeHTML(matchLevelLabel(preference.meetingTypeMatch.level))+'</p>'+'<p>Group size: '+escapeHTML(partner.groupSize)+' - '+escapeHTML(matchLevelLabel(preference.groupSizeMatch.level))+'</p>'+'<p>Study methods: '+escapeHTML(partner.studyMethods.join(', ')||'Not provided')+' - '+methodNote+'</p>'+'<p>Session length: '+escapeHTML(partner.sessionLength)+' - '+escapeHTML(matchLevelLabel(preference.sessionLengthMatch.level))+'</p>'+'<p><b>'+escapeHTML(preference.label)+'</b></p></div>'}
function clampPercent(value){return Math.min(100,Math.max(0,Number(value)||0))}
function matchScoreProgress(score){const pct=clampPercent(score);return '<div class="match-score-progress" role="progressbar" aria-label="Study partner match score" aria-valuemin="0" aria-valuemax="100" aria-valuenow="'+pct+'"><div class="match-score-progress-fill" style="width:'+pct+'%;"></div></div>'}
function scoreBreakdownHTML(finalScore){const b=finalScore.breakdown||{},rows=[['Course match',b.course,25],['Exam match',b.exam,20],['Exam-date match',b.examDate,10],['Complementary strengths',b.complementaryTopics,25],['Study time',b.studyTime,10],['Meeting preference',b.meetingType,5],['Group size and study method',b.groupAndMethod,5]];return '<div class="match-breakdown"><h4>Match Score Breakdown</h4>'+rows.map(([label,value,max])=>'<div><span>'+escapeHTML(label)+'</span><b>'+Number(value||0)+' / '+max+'</b></div>').join('')+'<div class="match-breakdown-total"><span>Total</span><b>'+finalScore.score+' / 100</b></div></div>'}
