function formatMatchDate(value){const d=new Date(`${value}T00:00:00`);return Number.isNaN(d.getTime())?'Date not provided':d.toLocaleDateString(undefined,{month:'long',day:'numeric'})}
function dateLevelLabel(level){return {'very-close':'Very Close',close:'Close',acceptable:'Acceptable',past:'Past exam',unknown:'Unknown'}[level]||'Incompatible'}
function ensureMatchScoreControls(){const section=$('.sample-classmate-section .card-head');if(!section||$('#minimumMatchScore'))return;section.insertAdjacentHTML('beforeend','<label class="privacy-toggle match-score-setting"><span>Minimum Match Score</span><select id="minimumMatchScore"><option value="50">50%</option><option value="60">60%</option><option value="70">70%</option><option value="80">80%</option></select></label>');$('#minimumMatchScore').value=String(studyMatchMinimumScore());$('#minimumMatchScore').onchange=e=>setStudyMatchMinimumScore(e.target.value)}
function bindMatchCardActions(){const u=user();$$('[data-save-match]').forEach(btn=>{btn.onclick=()=>{const id=btn.dataset.saveMatch,match=generateStudyMatches(studyMatchProfile(),studyPartners,matchingRules()).find(row=>row.partner.id===id);if(!match)return toast('That match is no longer available.');u.savedStudyMatches=u.savedStudyMatches||[];const saved={partnerId:id,partnerName:partnerDisplayName(match.partner),course:match.partner.course,examName:match.partner.examName,score:match.finalScore.score,label:match.finalScore.label,savedAt:new Date().toISOString()};u.savedStudyMatches=[saved,...u.savedStudyMatches.filter(item=>item.partnerId!==id)].slice(0,20);saveDB();toast('Study match saved.')}})}
function renderStudyPartnerCards(){if(!$('#studyPartnerList')||!$('#studyPartnerCount'))return;ensureMatchScoreControls();const profile=studyMatchProfile(),rules=matchingRules(),rows=profile?generateStudyMatches(profile,studyPartners,rules):[],minimum=studyMatchMinimumScore();if($('#minimumMatchScore'))$('#minimumMatchScore').value=String(minimum);$('#studyPartnerCount').textContent=studyPartnerLoadFailed?'Study partner data could not be loaded.':`${rows.length} match${rows.length===1?'':'es'} above ${minimum}%`;if(studyPartnerLoadFailed){$('#studyPartnerList').innerHTML='<div class="empty-mini">Study partner data could not be loaded.</div>';return}if(!studyPartners.length){$('#studyPartnerList').innerHTML='<div class="empty-mini">No sample classmates are available.</div>';return}if(!profile){$('#studyPartnerList').innerHTML='<div class="empty-mini">Create and save a Study Match Profile to see possible matches.</div>';return}if(!profile.course||!profile.examName||!profile.examDate){$('#studyPartnerList').innerHTML='<div class="empty-mini">Complete your Study Match Profile with course, exam, and exam date information.</div>';return}if(rules.matching.excludePastExams!==false&&!isFutureOrCurrentDate(profile.examDate)){$('#studyPartnerList').innerHTML='<div class="empty-mini">Exam date required for matching. Choose a future or current exam date.</div>';return}if(!rows.length){$('#studyPartnerList').innerHTML='<div class="empty-state no-match-state"><h2>No study partners currently meet your '+minimum+'% match requirement.</h2><p>Add more strong topics and topics you want to review. Select more preferred study times. Check your course and exam information, or adjust the minimum match score.</p></div>';return}$('#studyPartnerList').innerHTML=rows.slice(0,12).map(studyPartnerCard).join('');bindMatchCardActions()}
function formatCategoryLabel(value){return String(value||'').split(' ').filter(Boolean).map(word=>word.charAt(0).toUpperCase()+word.slice(1)).join(' ')}
function studyPartnerFilterState(){const defaults={minimum:String(studyMatchMinimumScore()),meeting:'All',time:'All',method:'All'};try{return {...defaults,...JSON.parse(sessionStorage.getItem('studyPartnerFilters')||'{}')}}catch{return defaults}}
function saveStudyPartnerFilterState(filters){sessionStorage.setItem('studyPartnerFilters',JSON.stringify(filters))}
function isStudyMatchProfileComplete(profile){return !!profile&&!validateStudyMatchProfile(profile)&&profile.matchingEnabled!==false}
function getAllGeneratedStudyMatches(profile=studyMatchProfile()){if(!profile)return [];return getActiveStudyPartners().map(partner=>{const evaluation=evaluateBasicMatch(profile,partner,matchingRules().matching),scoreResult=calculateFinalMatchScore(evaluation,matchingRules().finalScore),finalScore={...scoreResult,label:getOverallMatchLabel(scoreResult.score)},explanations=generateMatchExplanations(profile,partner,evaluation,finalScore);return {partner,evaluation,finalScore,explanations}}).filter(result=>passesMinimumMatchScore(result.finalScore,studyMatchMinimumScore())).sort(sortFinalStudyMatches)}
function getPrimaryMatchReason(match){const evaluation=match.evaluation;if(evaluation.topicMatch?.isTwoWayMatch)return 'You can help each other with different topics.';if(evaluation.timeMatch?.exactMatches?.length>0)return 'You share the same course, exam, and study time.';return 'You are preparing for the same course and exam.'}
function topicDisplayList(items){return (items||[]).map(item=>item.displayTopic||item.topic||item).filter(Boolean)}
function simpleListHTML(items,emptyText){const values=(items||[]).filter(Boolean);return values.length?'<ul>'+values.map(item=>'<li>'+escapeHTML(item)+'</li>').join('')+'</ul>':'<p>'+escapeHTML(emptyText)+'</p>'}
function availabilitySummaryHTML(timeMatch){if(timeMatch.exactMatches?.length)return simpleListHTML(timeMatch.exactMatches.map(timeCategoryLabel),'Different preferred times');if(timeMatch.relatedMatches?.length){const first=timeMatch.relatedMatches[0];return '<p><b>Similar availability</b></p><p>Your preference: '+escapeHTML(timeCategoryLabel(first.userCategory))+'</p><p>Partner preference: '+escapeHTML(timeCategoryLabel(first.partnerCategory))+'</p><p>Your preferred times are close.</p>'}return '<p>Different preferred times</p>'}
function studyPreferenceSummary(partner,preference){let method='Different study methods';if(preference.studyMethodMatch?.exactMatches?.length)method=preference.studyMethodMatch.exactMatches.slice(0,2).map(studyMethodLabel).join(', ');else if(preference.studyMethodMatch?.hasMixedCompatibility)method='Flexible study methods';const parts=[partner.meetingType,method];if(partner.groupSize&&partner.groupSize!=='Not provided'&&partner.groupSize!=='No Preference')parts.push('Group of '+partner.groupSize);return parts.filter(Boolean).join(' - ')}
function currentStudyRequestUserId(){return isGuestMode()?'guest':(user()?.email||currentUser||'current-user')}
function studyRequestStorageKey(){return isGuestMode()?'guestStudyPartnerRequests':'studyPartnerRequests'}
function normalizeStudyRequest(request){if(!request||typeof request!=='object')return null;const toUserId=partnerText(request.toUserId||request.partnerId),fromUserId=partnerText(request.fromUserId||currentStudyRequestUserId());if(!toUserId||!fromUserId)return null;const status=['Pending','Accepted','Declined'].includes(request.status)?request.status:String(request.status||'').toLowerCase()==='accepted'?'Accepted':String(request.status||'').toLowerCase()==='declined'?'Declined':'Pending';return {id:partnerText(request.id)||'request-'+Date.now(),fromUserId,toUserId,status,message:partnerText(request.message).slice(0,250),sentAt:request.sentAt||request.createdAt||new Date().toISOString(),prototypeOnly:request.prototypeOnly!==false,acceptedAt:request.acceptedAt||null,declinedAt:request.declinedAt||null,conversationId:request.conversationId||null,read:Boolean(request.read)}}
function getStudyRequests(){const key=studyRequestStorageKey();let stored=[];try{const data=localStorage.getItem(key);stored=data?JSON.parse(data):[]}catch{stored=[]}const normalized=Array.isArray(stored)?stored.map(normalizeStudyRequest).filter(Boolean):[];const legacy=(user()?.studyPartnerRequests||[]).map(normalizeStudyRequest).filter(Boolean),seen=new Set(normalized.map(r=>r.id));let changed=false;for(const request of legacy){if(!seen.has(request.id)){normalized.push(request);seen.add(request.id);changed=true}}if(legacy.length&&user()){user().studyPartnerRequests=[];saveDB()}if(changed)saveStudyRequests(normalized);return normalized}
function saveStudyRequests(requests){localStorage.setItem(studyRequestStorageKey(),JSON.stringify(Array.isArray(requests)?requests.map(normalizeStudyRequest).filter(Boolean):[]))}
function createDemoStudyRequests(){const currentUserId=getCurrentUserId(),now=Date.now();return [{id:'demo-request-1',fromUserId:currentUserId,toUserId:'student-1',status:'Pending',message:'Would you like to review Biology together?',sentAt:new Date(now).toISOString(),prototypeOnly:true},{id:'demo-request-2',fromUserId:currentUserId,toUserId:'student-2',status:'Accepted',message:'Would you like to study Genetics together?',sentAt:new Date(now-3600000).toISOString(),acceptedAt:new Date(now-3000000).toISOString(),prototypeOnly:true},{id:'demo-request-3',fromUserId:currentUserId,toUserId:'student-3',status:'Declined',message:'Would you like to review Biology?',sentAt:new Date(now-7200000).toISOString(),declinedAt:new Date(now-6600000).toISOString(),prototypeOnly:true}]}
function resetCollaborativeDemoData(){saveStudyRequests([]);saveStudyGroups([]);saveBlockedStudents([]);saveLocalSafetyList('reports',[]);saveNotifications([]);pendingGroupRecommendations={};sessionStorage.removeItem('selectedStudyGroupId');sessionStorage.removeItem('selectedStudyPartnerId');refreshStudyRequestUI();renderSafetyPrivacyPage();renderNotificationsPage();updateNotificationBadge()}
async function confirmResetCollaborativeDemoData(){const ok=await confirmDialog({title:'Reset Collaborative Demo Data?',message:'This will remove study requests, groups, recommendations, blocks, and reports created during testing.',okText:'Reset Demo Data',cancelText:'Cancel',danger:true});if(!ok)return;resetCollaborativeDemoData();showNotification({type:'success',message:'Collaborative demo data reset successfully.',important:true})}
function createDemoScenario(){if(!user())return;const requests=createDemoStudyRequests();saveStudyRequests(requests);const profile=studyMatchProfile()||normalizeStudyMatchProfile({subject:'Biology',course:'Grade 10 Biology',examName:'Biology Final Exam',examDate:'2026-07-27',strongTopics:['Genetics'],helpTopics:['Cellular Respiration'],preferredTimes:['Weekday Evening','Weekend Afternoon'],studyMethods:['Practice Questions','Explaining Concepts'],groupSize:'2-4',meetingType:'Online',sessionLength:'45-60 minutes',matchingEnabled:true});const currentName=firstName(user().name||'Cally'),alex=studyPartners.find(p=>p.id==='student-1'),maya=studyPartners.find(p=>p.id==='student-2');const group=normalizeStudyGroup({id:'demo-group-1',name:'Biology Demo Study Group',course:'Grade 10 Biology',examName:'Biology Final Exam',examDate:'2026-07-27',members:[{userId:getCurrentUserId(),displayName:currentName,role:'Organizer',status:'Active'},{userId:'student-1',displayName:partnerDisplayName(alex),role:'Member',status:'Active'},{userId:'student-2',displayName:partnerDisplayName(maya),role:'Member',status:'Active'}],meeting:{date:'2026-07-23',time:'17:00',type:'Online',link:'Demo online study room',generalLocation:''},topics:['Cellular Respiration','Genetics','Practice Questions','Mistake Review'],goal:'Explain Cellular Respiration, teach Genetics, complete group practice, review incorrect answers, and finish with a short quiz.',createdBy:getCurrentUserId(),createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),status:'Active',prototypeOnly:true});const recommendation=generateGroupRecommendation(group,[{userId:getCurrentUserId(),displayName:currentName,strongTopics:getUniqueTopics(profile.strongTopics||['Genetics']),topicsNeedingHelp:getUniqueTopics(profile.helpTopics||['Cellular Respiration']),studyMethods:getUniqueStudyMethods(profile.studyMethods||['Practice Questions']),preferredTimes:profile.preferredTimes||['Weekday Evening'],sessionLength:profile.sessionLength||'45-60 minutes'},{userId:'student-1',displayName:partnerDisplayName(alex),strongTopics:getUniqueTopics(alex?.strongTopics||[]),topicsNeedingHelp:getUniqueTopics(alex?.weakTopics||[]),studyMethods:getUniqueStudyMethods(alex?.studyMethods||[]),preferredTimes:alex?.preferredTimes||[],sessionLength:alex?.sessionLength||''},{userId:'student-2',displayName:partnerDisplayName(maya),strongTopics:getUniqueTopics(maya?.strongTopics||[]),topicsNeedingHelp:getUniqueTopics(maya?.weakTopics||[]),studyMethods:getUniqueStudyMethods(maya?.studyMethods||[]),preferredTimes:maya?.preferredTimes||[],sessionLength:maya?.sessionLength||''}],groupRecommendationRules());group.recommendation=normalizeGroupRecommendation({...recommendation,status:'Saved',basedOnGroupUpdatedAt:group.updatedAt},group.updatedAt);saveStudyGroups([group,...getStudyGroups().filter(item=>item.id!==group.id)]);sessionStorage.setItem('selectedStudyGroupId',group.id);refreshStudyGroupUI();renderSafetyPrivacyPage();showNotification({type:'success',message:'Demo scenario created successfully.',actionLabel:'View Group',linkPage:'study-group-detail',relatedId:group.id,important:true})}
function findStudyRequest(fromUserId,toUserId){return getStudyRequests().find(request=>request.fromUserId===fromUserId&&request.toUserId===toUserId)}
function hasPendingStudyRequest(fromUserId,toUserId){if(toUserId===undefined){toUserId=fromUserId;fromUserId=currentStudyRequestUserId()}return getStudyRequests().some(request=>request.fromUserId===fromUserId&&request.toUserId===toUserId&&request.status==='Pending')}
function createStudyRequest({fromUserId,toUserId,message}){const requests=getStudyRequests(),request={id:'request-'+Date.now(),fromUserId,toUserId,status:'Pending',message:String(message||'').trim(),sentAt:new Date().toISOString(),prototypeOnly:true,acceptedAt:null,declinedAt:null,conversationId:null,read:false};requests.push(request);saveStudyRequests(requests);return request}
function updateStudyRequestStatus(requestId,status){const requests=getStudyRequests(),request=requests.find(item=>item.id===requestId);if(!request||!['Pending','Accepted','Declined'].includes(status))return false;request.status=status;if(status==='Accepted')request.acceptedAt=new Date().toISOString();if(status==='Declined')request.declinedAt=new Date().toISOString();saveStudyRequests(requests);refreshStudyRequestUI();showNotification({type:status==='Accepted'?'success':'information',message:status==='Accepted'?'Study request accepted.':'Study request declined.',important:status==='Accepted',linkPage:'my-study-requests'});return true}
function deleteStudyRequest(requestId){saveStudyRequests(getStudyRequests().filter(request=>request.id!==requestId));refreshStudyRequestUI();showNotification({type:'information',message:'Study request deleted.',linkPage:'my-study-requests'})}
function simulateAcceptRequest(requestId){return updateStudyRequestStatus(requestId,'Accepted')}
function simulateDeclineRequest(requestId){return updateStudyRequestStatus(requestId,'Declined')}
function refreshStudyRequestUI(){renderStudyPartnerResultsPage();renderStudyPartnerProfilePage();renderStudyRequestsPage();renderStudyGroupsPage()}
function requestBetweenUsers(firstUserId,secondUserId){return getStudyRequests().find(request=>((request.fromUserId===firstUserId&&request.toUserId===secondUserId)||(request.fromUserId===secondUserId&&request.toUserId===firstUserId)))}
function hasAcceptedRequestBetweenUsers(firstUserId,secondUserId){return getStudyRequests().some(request=>{const connectsUsers=(request.fromUserId===firstUserId&&request.toUserId===secondUserId)||(request.fromUserId===secondUserId&&request.toUserId===firstUserId);return connectsUsers&&request.status==='Accepted'})}
function hasAcceptedStudyRequest(currentUserId,partnerId){return hasAcceptedRequestBetweenUsers(currentUserId,partnerId)}
function partnerRequestButtonHTML(partnerId){const request=requestBetweenUsers(currentStudyRequestUserId(),partnerId);if(request?.status==='Accepted')return '<button class="btn btn-primary" data-create-study-group="'+escapeHTML(partnerId)+'" type="button">Create Study Group</button>';if(request?.status==='Declined')return '<button class="btn btn-secondary pending-request-button" type="button" disabled><span class="status-badge status-declined">Declined</span> Request Declined</button>';if(request?.status==='Pending')return '<button class="btn btn-secondary pending-request-button" type="button" disabled><span class="status-badge status-pending">Pending</span> Waiting for Response</button>';return '<button class="btn btn-primary" data-send-study-request="'+escapeHTML(partnerId)+'" type="button">Send Study Request</button>'}
function explanationIcon(type){return {course:'Book',exam:'Book','exam-date':'Date',topic:'Arrows',time:'Clock',preference:'People'}[type]||'Info'}
function renderMatchExplanations(explanations=[],options={}){const limit=options.limit??4,items=(Array.isArray(explanations)?explanations:[]).slice(0,limit),fallback='This match meets your course, exam, and score requirements.';if(!items.length)return '<div class="match-explanations"><h3>Why This Match?</h3><p>'+escapeHTML(fallback)+'</p></div>';return '<div class="match-explanations"><h3>Why This Match?</h3><ul>'+items.map(item=>'<li><span class="reason-icon">'+escapeHTML(options.showIcons===false?'':explanationIcon(item.type))+'</span><span>'+escapeHTML(item.text)+'</span></li>').join('')+'</ul>'+(explanations.length>items.length?'<p class="match-transparency">View profile for more match details.</p>':'')+'<p class="match-transparency">Suggested using the information in your Study Match Profile.</p></div>'}
function scoreGroupTotals(finalScore){const b=finalScore.breakdown||{};return {academic:{value:Number(b.course||0)+Number(b.exam||0)+Number(b.examDate||0),max:55},topic:{value:Number(b.complementaryTopics||0),max:25},time:{value:Number(b.studyTime||0),max:10},preference:{value:Number(b.meetingType||0)+Number(b.groupAndMethod||0),max:10}}}
function scoreGroupLabel(key,finalScore){const totals=scoreGroupTotals(finalScore)[key];return totals?`${totals.value} / ${totals.max}`:''}
function groupedMatchExplanations(match){const groups=[['topic','Complementary Strengths',['topic']],['academic','Academic Match',['course','exam','exam-date']],['time','Availability',['time']],['preference','Study Preferences',['preference']]],items=match.explanations||[];return '<div class="profile-explanation-grid">'+groups.map(([key,title,types])=>{const groupItems=items.filter(item=>types.includes(item.type));if(!groupItems.length)return '';return '<section class="study-match-preview-block profile-explanation-group"><div class="explanation-group-head"><b>'+escapeHTML(title)+'</b><span>'+escapeHTML(scoreGroupLabel(key,match.finalScore))+'</span></div>'+renderMatchExplanations(groupItems,{limit:99,showIcons:true}).replace('<div class="match-explanations"><h3>Why This Match?</h3>','<div class="match-explanations">').replace('<p class="match-transparency">Suggested using the information in your Study Match Profile.</p>','')+'</section>'}).join('')+'</div><p class="match-transparency profile-note">Match explanations are generated from the profile information selected by both students.</p>'}
function renderStudyPartnerCard(match){const partner=match.partner,evaluation=match.evaluation,score=clampPercent(match.finalScore.percentage??match.finalScore.score),display=partnerDisplayName(partner),canHelp=topicDisplayList(evaluation.topicMatch?.partnerCanHelpUser),userHelps=topicDisplayList(evaluation.topicMatch?.userCanHelpPartner),label=demoProfileLabel(partner);return '<article class="study-partner-card study-partner-result-card '+(evaluation.topicMatch?.isTwoWayMatch?'mutual-match':'')+'"><div class="study-result-card-head"><div><h2>'+escapeHTML(display)+'</h2><small><span class="demo-profile-badge">'+escapeHTML(label)+'</span> Fictional study profile</small></div><div class="study-result-score"><strong>'+score+'% Match</strong><span class="match-level-badge">'+escapeHTML(match.finalScore.label)+'</span></div></div>'+matchScoreProgress(score)+'<p class="match-reason">'+escapeHTML(getPrimaryMatchReason(match))+'</p>'+renderMatchExplanations(match.explanations,{limit:4,showIcons:true})+'<div class="study-result-sections"><section><h3>Course</h3><p>'+escapeHTML(partner.course)+'</p></section><section><h3>Exam</h3><p>'+escapeHTML(partner.examName+' - '+formatMatchDate(partner.examDate))+'</p></section><section><h3>Can Help You With</h3>'+simpleListHTML(canHelp,'No direct topic match yet.')+'</section><section><h3>You Can Help '+escapeHTML(display)+' With</h3>'+simpleListHTML(userHelps,'No direct topic match yet.')+'</section><section><h3>Available</h3>'+availabilitySummaryHTML(evaluation.timeMatch)+'</section><section><h3>Study Preference</h3><p>'+escapeHTML(studyPreferenceSummary(partner,evaluation.preferenceMatch))+'</p></section></div><p class="safety-note">Use StudySpark only for school-safe study coordination. Do not share phone numbers, addresses, passwords, or private contact details.</p><div class="study-result-actions"><button class="btn btn-secondary" data-view-study-partner="'+escapeHTML(partner.id)+'" type="button">View Profile</button>'+partnerRequestButtonHTML(partner.id)+'<button class="btn btn-secondary" data-report-student="'+escapeHTML(partner.id)+'" type="button">Report</button><button class="btn btn-danger" data-block-student="'+escapeHTML(partner.id)+'" type="button">Block</button></div></article>'}
function applyStudyPartnerFilters(matches,filters){return matches.filter(match=>{const partner=match.partner;if(filters.meeting&&filters.meeting!=='All'){const selected=normalizeMeetingType(filters.meeting),partnerType=normalizeMeetingType(partner.meetingType);if(!(partnerType===selected||partnerType==='either'))return false}if(filters.time&&filters.time!=='All'&&!getUniqueTimeCategories(partner.preferredTimes).includes(normalizeTimeCategory(filters.time)))return false;if(filters.method&&filters.method!=='All'&&!getUniqueStudyMethods(partner.studyMethods).includes(normalizeStudyMethod(filters.method)))return false;return true})}
function studyPartnerFilterControlsHTML(filters){const timeOptions=['All',...STUDY_TIME_CATEGORIES],methodOptions=['All',...STUDY_MATCH_METHODS],meetingOptions=['All','Online','In Person','Either'];const option=(value,current)=>'<option value="'+escapeHTML(value)+'" '+(value===current?'selected':'')+'>'+escapeHTML(value)+'</option>';return '<div class="study-partner-controls card"><label>Minimum Match Score<select id="partnerMinimumScore">'+[50,60,70,80].map(v=>option(String(v),String(filters.minimum))).join('')+'</select></label><label>Meeting Type<select id="partnerMeetingFilter">'+meetingOptions.map(v=>option(v,filters.meeting)).join('')+'</select></label><label>Preferred Study Time<select id="partnerTimeFilter">'+timeOptions.map(v=>option(v,filters.time)).join('')+'</select></label><label>Study Method<select id="partnerMethodFilter">'+methodOptions.map(v=>option(v,filters.method)).join('')+'</select></label><button class="btn btn-secondary" id="clearStudyPartnerFilters" type="button">Clear Filters</button></div>'}
function renderStudyPartnerLoadingState(){const root=$('#studyPartnerResultsContent');if(root)root.innerHTML='<div class="empty-state card"><h2>Finding study partners...</h2><p>Loading your profile, matching rules, and sample classmates.</p></div>'}
function renderStudyPartnerErrorState(){const root=$('#studyPartnerResultsContent');if(root)root.innerHTML='<div class="empty-state card"><h2>Study partner data could not be loaded.</h2><p>Try loading the sample classmate file again.</p><button class="btn btn-primary" id="retryStudyPartnerLoad" type="button">Try Again</button></div>';$('#retryStudyPartnerLoad')?.addEventListener('click',loadStudyPartners)}
function renderStudyPartnerEmptyState(message='No study partners currently meet your match requirements.',filtered=false){return '<div class="empty-state card no-match-state"><h2>'+escapeHTML(message)+'</h2><p>Add more topic information. Select more preferred study times. Check your course and exam information. Lower the minimum match score.</p>'+(filtered?'<button class="btn btn-primary" id="filteredClearStudyPartners" type="button">Clear Filters</button>':'')+'</div>'}
function renderStudyPartnerResults(matches){const root=$('#studyPartnerResultsContent');if(!root)return;const filters=studyPartnerFilterState(),filtered=applyStudyPartnerFilters(matches,filters),countText=`${filtered.length} study partner${filtered.length===1?'':'s'} found`;root.innerHTML=studyPartnerFilterControlsHTML(filters)+'<div class="study-results-summary"><div id="study-partner-results-count" aria-live="polite">'+escapeHTML(countText)+'</div><span>Minimum match score: '+escapeHTML(String(filters.minimum))+'%</span></div>'+(filtered.length?'<div class="study-partner-grid study-results-grid">'+filtered.map(renderStudyPartnerCard).join('')+'</div>':renderStudyPartnerEmptyState('No study partners match your selected filters.',matches.length>0));bindStudyPartnerResultsActions()}
function maybeNotifyMatchCount(count){if(forceMatchCountNotification||lastNotifiedMatchCount===null||Math.abs(Number(count)-Number(lastNotifiedMatchCount))>0){showNotification({type:'information',message:createMatchCountMessage(count),actionLabel:count>0?'View Matches':'',linkPage:'find-study-partners'});lastNotifiedMatchCount=Number(count)||0;forceMatchCountNotification=false}}
function renderStudyPartnerResultsPage(){const root=$('#studyPartnerResultsContent');if(!root||!user())return;if(studyPartnerLoadFailed)return renderStudyPartnerErrorState();if(!appData.matchingRules||!studyPartners.length)return renderStudyPartnerLoadingState();const profile=studyMatchProfile();if(!profile){root.innerHTML='<div class="empty-state card"><h2>Create your Study Match Profile before searching for study partners.</h2><button class="btn btn-primary" data-view="studyMatch" type="button">Create Study Match Profile</button></div>';showNotification({type:'warning',message:'Complete your Study Match Profile before searching.',persistent:true,actionLabel:'Complete Profile',linkPage:'study-match'});bindStudyPartnerResultsActions();return}if(validateStudyMatchProfile(profile)){root.innerHTML='<div class="empty-state card"><h2>Create your Study Match Profile before searching for study partners.</h2><p>Complete every required field before searching.</p><button class="btn btn-primary" data-view="studyMatch" type="button">Create Study Match Profile</button></div>';showNotification({type:'warning',message:'Complete your Study Match Profile before searching.',persistent:true,actionLabel:'Complete Profile',linkPage:'study-match'});bindStudyPartnerResultsActions();return}if(profile.matchingEnabled===false){root.innerHTML='<div class="empty-state card"><h2>Your Study Match Profile is currently paused.</h2><button class="btn btn-primary" id="enableStudyMatchingBtn" type="button">Enable Matching</button></div>';showNotification({type:'warning',message:'Enable Study Matching before searching for partners.',persistent:true,actionLabel:'Complete Profile',linkPage:'study-match'});bindStudyPartnerResultsActions();return}const filters=studyPartnerFilterState();user().studyMatchMinimumScore=Number(filters.minimum)||studyMatchMinimumScore();const matches=getAllGeneratedStudyMatches(profile);maybeNotifyMatchCount(matches.length);if(!matches.length){root.innerHTML=studyPartnerFilterControlsHTML(filters)+'<div class="study-results-summary"><div id="study-partner-results-count" aria-live="polite">0 study partners found</div><span>Minimum match score: '+escapeHTML(String(filters.minimum))+'%</span></div>'+renderStudyPartnerEmptyState();bindStudyPartnerResultsActions();return}renderStudyPartnerResults(matches)}
function bindStudyPartnerResultsActions(){const root=$('#studyPartnerResultsContent');$$('[data-view="studyMatch"]',root).forEach(btn=>btn.onclick=()=>showView('studyMatch'));$('#enableStudyMatchingBtn')?.addEventListener('click',()=>{const p=studyMatchProfile(),settings=ensurePrivacySettings();if(!p)return;if(!settings.matchingConsent)return showNotification({type:'warning',message:'Enable Study Matching to appear in partner results.',persistent:true,actionLabel:'Complete Profile',linkPage:'study-match'});p.matchingEnabled=true;settings.enableStudyMatching=true;p.updatedAt=new Date().toISOString();user().studyMatchProfile=p;saveDB();forceMatchCountNotification=true;renderStudyPartnerResultsPage();renderStudyMatchPage();showNotification({type:'success',message:'Study Matching is now enabled.'})});['partnerMinimumScore','partnerMeetingFilter','partnerTimeFilter','partnerMethodFilter'].forEach(id=>{$('#'+id)?.addEventListener('change',()=>{const filters={minimum:$('#partnerMinimumScore')?.value||'60',meeting:$('#partnerMeetingFilter')?.value||'All',time:$('#partnerTimeFilter')?.value||'All',method:$('#partnerMethodFilter')?.value||'All'};saveStudyPartnerFilterState(filters);if(id==='partnerMinimumScore')showNotification({type:'warning',message:'Lowering the minimum score may show more matches.'});setStudyMatchMinimumScore(filters.minimum);renderStudyPartnerResultsPage()})});$('#clearStudyPartnerFilters')?.addEventListener('click',clearStudyPartnerFilters);$('#filteredClearStudyPartners')?.addEventListener('click',clearStudyPartnerFilters);$$('[data-view-study-partner]',root).forEach(btn=>btn.onclick=()=>openStudyPartnerProfile(btn.dataset.viewStudyPartner));$$('[data-send-study-request]',root).forEach(btn=>btn.onclick=()=>openStudyRequestModal(btn.dataset.sendStudyRequest));$$('[data-create-study-group]',root).forEach(btn=>btn.onclick=()=>openCreateStudyGroup(btn.dataset.createStudyGroup));$$('[data-block-student]',root).forEach(btn=>btn.onclick=()=>blockStudentFlow(btn.dataset.blockStudent));$$('[data-report-student]',root).forEach(btn=>btn.onclick=()=>openReportStudentModal(btn.dataset.reportStudent))}
function clearStudyPartnerFilters(){const filters={minimum:String(matchingRules().finalScore.minimumDisplayedScore??60),meeting:'All',time:'All',method:'All'};saveStudyPartnerFilterState(filters);setStudyMatchMinimumScore(filters.minimum);renderStudyPartnerResultsPage()}
function openStudyPartnerProfile(partnerId){sessionStorage.setItem('studyPartnerResultsScroll',String(window.scrollY||0));sessionStorage.setItem('selectedStudyPartnerId',partnerId);showView('studyPartnerProfile')}
function currentStudyPartnerMatch(partnerId){return getAllGeneratedStudyMatches(studyMatchProfile()).find(match=>match.partner.id===partnerId)||null}
function renderMatchBreakdown(match){return scoreBreakdownHTML(match.finalScore)+'<div class="study-match-preview-block">'+renderMatchExplanations(match.explanations,{limit:99,showIcons:true})+'</div>'}
function renderStudyPartnerProfilePage(){const root=$('#studyPartnerProfileContent');if(!root||!user())return;const partnerId=sessionStorage.getItem('selectedStudyPartnerId'),match=partnerId?currentStudyPartnerMatch(partnerId):null;if(!match||isStudentBlocked(partnerId)){root.innerHTML='<div class="empty-state card"><h2>Study partner profile could not be found.</h2><button class="btn btn-primary" id="profileBackToPartners" type="button">Back to Study Partners</button></div>';$('#profileBackToPartners')?.addEventListener('click',()=>showView('studyPartnerResults'));return}const p=match.partner,score=clampPercent(match.finalScore.score),saved=(user().savedStudyMatches||[]).some(item=>item.partnerId===p.id),display=partnerDisplayName(p),label=demoProfileLabel(p);root.innerHTML='<article class="card study-partner-profile-card"><div class="study-profile-hero"><div><span class="demo-profile-badge">'+escapeHTML(label)+'</span><h2>'+escapeHTML(display)+'</h2><p>Fictional demo student profile. Only first names and study information are shown.</p><span class="match-level-badge">'+escapeHTML(match.finalScore.label)+'</span></div><strong>'+score+'% Match</strong></div>'+matchScoreProgress(score)+'<div class="profile-fact-grid">'+studyMatchFact('Course',p.course)+studyMatchFact('Exam',p.examName)+studyMatchFact('Exam date',formatMatchDate(p.examDate))+studyMatchFact('Meeting type',p.meetingType)+studyMatchFact('Group size',p.groupSize)+studyMatchFact('Session length',p.sessionLength)+'</div>'+groupedMatchExplanations(match)+'<div class="study-profile-grid"><section class="study-match-preview-block"><b>Strong topics</b>'+simpleListHTML(p.strongTopics,'No strong topics listed.')+'</section><section class="study-match-preview-block"><b>Topics currently reviewing</b>'+simpleListHTML(p.weakTopics,'No review topics listed.')+'</section><section class="study-match-preview-block"><b>Preferred study times</b>'+simpleListHTML(p.preferredTimes,'No preferred times listed.')+'</section><section class="study-match-preview-block"><b>Study methods</b>'+simpleListHTML(p.studyMethods,'No study methods listed.')+'</section></div><p class="safety-note">Meet online when possible. If an in-person study session is approved by your school or guardian, use a public school-safe place and never share a home address.</p>'+renderMatchBreakdown(match)+'<div class="study-result-actions profile-actions"><button class="btn btn-secondary" id="saveMatchFromProfile" type="button">'+(saved?'Match Saved':'Save Match')+'</button>'+partnerRequestButtonHTML(p.id)+'<button class="btn btn-secondary" data-report-student="'+escapeHTML(p.id)+'" type="button">Report</button><button class="btn btn-danger" data-block-student="'+escapeHTML(p.id)+'" type="button">Block</button></div></article>';$('#saveMatchFromProfile')?.addEventListener('click',()=>saveStudyMatchFromProfile(match));$$('[data-send-study-request]',root).forEach(btn=>btn.onclick=()=>openStudyRequestModal(btn.dataset.sendStudyRequest));$$('[data-create-study-group]',root).forEach(btn=>btn.onclick=()=>openCreateStudyGroup(btn.dataset.createStudyGroup));$$('[data-block-student]',root).forEach(btn=>btn.onclick=()=>blockStudentFlow(btn.dataset.blockStudent));$$('[data-report-student]',root).forEach(btn=>btn.onclick=()=>openReportStudentModal(btn.dataset.reportStudent))}
function saveStudyMatchFromProfile(match){const u=user();u.savedStudyMatches=u.savedStudyMatches||[];u.savedStudyMatches=[{partnerId:match.partner.id,partnerName:partnerDisplayName(match.partner),course:match.partner.course,examName:match.partner.examName,score:match.finalScore.score,label:match.finalScore.label,savedAt:new Date().toISOString()},...u.savedStudyMatches.filter(item=>item.partnerId!==match.partner.id)].slice(0,20);saveDB();renderStudyPartnerProfilePage();toast('Study match saved.')}
function openStudyRequestModal(partnerId){const partner=studyPartners.find(p=>p.id===partnerId),fromUserId=currentStudyRequestUserId(),settings=ensurePrivacySettings();if(!partner||isStudentBlocked(partnerId))return showNotification({type:'error',message:'The selected profile could not be found.'});if(settings.allowRequests===false)return showNotification({type:'warning',message:'Study requests are turned off in Safety & Privacy settings.',persistent:true,actionLabel:'Open Settings',linkPage:'safety-privacy'});if(hasPendingStudyRequest(fromUserId,partnerId)){showNotification({type:'warning',message:'You already sent a study request to this partner.'});refreshStudyRequestUI();return}const modal=$('#studyRequestModal'),message=$('#studyRequestText'),name=partnerDisplayName(partner);$('#studyRequestPartnerId').value=partnerId;$('#studyRequestMessage').textContent=`Send a study request to ${name}?`;message.value='';message.placeholder=`Hi ${name}! Would you like to study ${partner.subject} together?`;updateStudyRequestCounter();modal.classList.add('open');modal.setAttribute('aria-hidden','false');setTimeout(()=>message.focus(),0)}
function closeStudyRequestModal(){$('#studyRequestModal')?.classList.remove('open');$('#studyRequestModal')?.setAttribute('aria-hidden','true')}
function updateStudyRequestCounter(){const text=$('#studyRequestText')?.value||'';$('#studyRequestCounter').textContent=`${text.length} / 250`}
function sendPrototypeStudyRequest(){const toUserId=$('#studyRequestPartnerId')?.value,partner=studyPartners.find(p=>p.id===toUserId),fromUserId=currentStudyRequestUserId();if(!partner||isStudentBlocked(toUserId)){showNotification({type:'error',message:'The study request could not be sent.'});return closeStudyRequestModal()}if(hasPendingStudyRequest(fromUserId,toUserId)){showNotification({type:'warning',message:'You already sent a study request to this partner.'});closeStudyRequestModal();refreshStudyRequestUI();return}const raw=$('#studyRequestText').value,message=raw.trim();if(raw&&message.length===0)return showNotification({type:'warning',message:'Please enter a valid request message.'});if(message.length>250)return showNotification({type:'warning',message:'Please enter a valid request message.'});if(containsRestrictedPersonalInfo(message))return showNotification({type:'warning',message:'Please remove personal contact information before continuing.',persistent:true});const request=safelyRunCollaborativeAction(()=>createStudyRequest({fromUserId,toUserId,message}),'The study request could not be sent.');if(!request)return;closeStudyRequestModal();refreshStudyRequestUI();showNotification({type:'success',message:'Study request sent successfully.',actionLabel:'View Requests',linkPage:'my-study-requests',important:true});showNotification({type:'information',message:'Prototype mode: The request is stored only on this device.'})}
function studyRequestPartner(request){return studyPartners.find(partner=>partner.id===request.toUserId)}
function formatRequestDate(value){const date=new Date(value);return Number.isNaN(date.getTime())?'Date not provided':date.toLocaleDateString(undefined,{month:'long',day:'numeric',year:'numeric'})}
function statusBadgeHTML(status){const safe=['Pending','Accepted','Declined','Active','Completed','Cancelled','Preview','Saved','Outdated'].includes(status)?status:'Pending';return '<span class="status-badge status-'+safe.toLowerCase()+'">'+escapeHTML(safe)+'</span>'}
function currentUserStudyRequests(){const id=currentStudyRequestUserId();return getStudyRequests().filter(request=>request.fromUserId===id).sort((a,b)=>String(b.sentAt).localeCompare(String(a.sentAt)))}
function requestMatchesFilters(request,query,status){const partner=studyRequestPartner(request),haystack=[partnerDisplayName(partner),partner?.course,partner?.subject,request.status].join(' ').toLowerCase();return (!query||haystack.includes(query))&&(status==='All'||request.status===status)}
function renderStudyRequestSummary(requests){const counts={Pending:0,Accepted:0,Declined:0};requests.forEach(r=>{if(counts[r.status]!==undefined)counts[r.status]++});return '<div class="request-summary-grid"><article><span>Pending</span><b>'+counts.Pending+'</b></article><article><span>Accepted</span><b>'+counts.Accepted+'</b></article><article><span>Declined</span><b>'+counts.Declined+'</b></article></div>'}
function requestGroupActionHTML(request){if(request.status==='Accepted')return '<button class="btn btn-primary" data-request-create-group="'+escapeHTML(request.toUserId)+'" type="button">Create Study Group</button>';if(request.status==='Declined')return '<button class="btn btn-secondary" type="button" disabled>Request Declined</button>';return '<button class="btn btn-secondary" type="button" disabled>Waiting for Response</button>'}
function studyRequestCardHTML(request){const partner=studyRequestPartner(request),name=partner?partnerDisplayName(partner):request.toUserId,course=partner?.course||'Sample study partner',message=request.message||'No message added.',dev=DEVELOPMENT_MODE?'<button class="btn btn-secondary" data-dev-accept-request="'+escapeHTML(request.id)+'" type="button">Dev Accept</button><button class="btn btn-secondary" data-dev-decline-request="'+escapeHTML(request.id)+'" type="button">Dev Decline</button>':'';return '<article class="request-card"><div class="request-card-head"><div><h3>'+escapeHTML(name)+'</h3><p>'+escapeHTML(course)+'</p></div>'+statusBadgeHTML(request.status)+'</div><div class="request-detail-grid"><div><span>Sent</span><b>'+escapeHTML(formatRequestDate(request.sentAt))+'</b></div><div><span>Status</span><b>'+escapeHTML(request.status)+'</b></div></div><div class="request-message"><span>Message</span><p>'+escapeHTML(message)+'</p></div><div class="request-card-actions"><button class="btn btn-secondary" data-request-view-partner="'+escapeHTML(request.toUserId)+'" type="button">View Partner</button>'+requestGroupActionHTML(request)+dev+'<button class="btn btn-secondary" data-report-student="'+escapeHTML(request.toUserId)+'" type="button">Report</button><button class="btn btn-danger" data-block-student="'+escapeHTML(request.toUserId)+'" type="button">Block Student</button><button class="btn btn-danger" data-request-delete="'+escapeHTML(request.id)+'" type="button">Delete Request</button></div></article>'}
function renderStudyRequestsPage(){const root=$('#studyRequestsContent');if(!root||!user())return;const requests=currentUserStudyRequests(),query=($('#requestSearch')?.value||'').trim().toLowerCase(),status=$('#requestStatusFilter')?.value||'All',filtered=requests.filter(request=>requestMatchesFilters(request,query,status));root.innerHTML='<div class="prototype-banner card"><span class="pill blue-pill">Prototype Feature</span><h2>Study requests do not notify real students.</h2><p>A future version would require user accounts, authentication, a backend database, notifications, messaging, consent, and moderation.</p></div>'+renderStudyRequestSummary(requests)+'<div class="request-tools card"><label>Search requests<input id="requestSearch" value="'+escapeHTML($('#requestSearch')?.value||'')+'" placeholder="Search by partner, course, or status"></label><label>Status<select id="requestStatusFilter"><option>All</option><option>Pending</option><option>Accepted</option><option>Declined</option></select></label></div><p class="prototype-notice">Study requests in this prototype are stored only on this device.</p>'+(requests.length?'<div class="request-list">'+(filtered.length?filtered.map(studyRequestCardHTML).join(''):'<div class="empty-state card"><h2>No requests match your filters.</h2><button class="btn btn-primary" id="clearRequestFilters" type="button">Clear Filters</button></div>')+'</div>':'<div class="empty-state card"><h2>You have not sent any study requests yet.</h2><button class="btn btn-primary" data-view="studyPartnerResults" type="button">Find Study Partners</button></div>');if($('#requestStatusFilter'))$('#requestStatusFilter').value=status;bindStudyRequestActions()}
function bindStudyRequestActions(){const root=$('#studyRequestsContent');$('#requestSearch')?.addEventListener('input',renderStudyRequestsPage);$('#requestStatusFilter')?.addEventListener('change',renderStudyRequestsPage);$('#clearRequestFilters')?.addEventListener('click',()=>{if($('#requestSearch'))$('#requestSearch').value='';if($('#requestStatusFilter'))$('#requestStatusFilter').value='All';renderStudyRequestsPage()});$$('[data-view="studyPartnerResults"]',root).forEach(btn=>btn.onclick=()=>showView('studyPartnerResults'));$$('[data-request-view-partner]',root).forEach(btn=>btn.onclick=()=>openStudyPartnerProfile(btn.dataset.requestViewPartner));$$('[data-request-create-group]',root).forEach(btn=>btn.onclick=()=>openCreateStudyGroup(btn.dataset.requestCreateGroup));$$('[data-request-delete]',root).forEach(btn=>btn.onclick=()=>confirmDeleteStudyRequest(btn.dataset.requestDelete));$$('[data-block-student]',root).forEach(btn=>btn.onclick=()=>blockStudentFlow(btn.dataset.blockStudent));$$('[data-report-student]',root).forEach(btn=>btn.onclick=()=>openReportStudentModal(btn.dataset.reportStudent));$$('[data-dev-accept-request]',root).forEach(btn=>btn.onclick=()=>simulateAcceptRequest(btn.dataset.devAcceptRequest));$$('[data-dev-decline-request]',root).forEach(btn=>btn.onclick=()=>simulateDeclineRequest(btn.dataset.devDeclineRequest))}
async function confirmDeleteStudyRequest(requestId){const ok=await confirmDialog({title:'Delete Study Request?',message:'Are you sure you want to delete this study request?',okText:'Delete',cancelText:'Cancel',danger:true});if(!ok)return;deleteStudyRequest(requestId)}
function studyGroupStorageKey(){return isGuestMode()?'guestStudyGroups':'studyGroups'}
function currentUserDisplayName(){return repairEncoding(user()?.name||'Guest Student').trim()||'Student'}
function firstName(value){return repairEncoding(value||'Student').trim().split(/\s+/)[0]||'Student'}
function isCurrentOrFutureDate(dateString){return isFutureOrCurrentDate(dateString)}
function getStudyGroups(){const key=studyGroupStorageKey();try{const stored=localStorage.getItem(key),parsed=stored?JSON.parse(stored):[];return Array.isArray(parsed)?parsed.map(normalizeStudyGroup).filter(Boolean):[]}catch{return []}}
function saveStudyGroups(groups){localStorage.setItem(studyGroupStorageKey(),JSON.stringify(Array.isArray(groups)?groups.map(normalizeStudyGroup).filter(Boolean):[]))}
function normalizeGroupRecommendation(recommendation,groupUpdatedAt=''){if(!recommendation||typeof recommendation!=='object')return null;const steps=Array.isArray(recommendation.steps)?recommendation.steps.map((step,index)=>({order:Number(step.order)||index+1,type:String(step.type||'activity'),title:String(step.title||'').trim(),description:String(step.description||'').trim(),durationMinutes:Math.max(1,Number(step.durationMinutes)||1),leaderId:step.leaderId||'',leaderName:step.leaderName?firstName(step.leaderName):'',topic:String(step.topic||'').trim(),reason:String(step.reason||'').trim()})).filter(step=>step.description):[];const status=['Preview','Saved','Outdated'].includes(recommendation.status)?recommendation.status:'Saved',outdated=status==='Saved'&&recommendation.basedOnGroupUpdatedAt&&groupUpdatedAt&&recommendation.basedOnGroupUpdatedAt!==groupUpdatedAt;return {id:String(recommendation.id||'recommendation-'+Date.now()),sessionMinutes:Math.min(120,Math.max(30,Number(recommendation.sessionMinutes)||60)),generatedAt:recommendation.generatedAt||new Date().toISOString(),basedOnGroupUpdatedAt:recommendation.basedOnGroupUpdatedAt||groupUpdatedAt,goalType:recommendation.goalType||'general-review',steps,topicAssignments:Array.isArray(recommendation.topicAssignments)?recommendation.topicAssignments:[],sessionRoles:Array.isArray(recommendation.sessionRoles)?recommendation.sessionRoles:[],totalMinutes:calculateRecommendationDuration(steps),status:outdated?'Outdated':status,prototypeOnly:recommendation.prototypeOnly!==false}}
function normalizeStudyGroup(group){if(!group||typeof group!=='object')return null;const members=Array.isArray(group.members)?group.members.filter(m=>m&&m.userId).map(m=>({userId:String(m.userId),displayName:firstName(m.displayName||m.name||m.userId),role:m.role==='Organizer'?'Organizer':'Member',status:m.status||'Active'})):[];const status=['Active','Completed','Cancelled'].includes(group.status)?group.status:'Active',updatedAt=group.updatedAt||group.createdAt||new Date().toISOString(),recommendation=normalizeGroupRecommendation(group.recommendation,updatedAt);return {id:String(group.id||'group-'+Date.now()),name:String(group.name||'Study Group').trim(),course:String(group.course||'').trim(),examName:String(group.examName||'').trim(),examDate:group.examDate||'',members,meeting:{date:group.meeting?.date||'',time:group.meeting?.time||'',type:['Online','In Person','Hybrid'].includes(group.meeting?.type)?group.meeting.type:'Online',link:String(group.meeting?.link||'').trim(),generalLocation:String(group.meeting?.generalLocation||'').trim()},topics:normalizeStudyTopics(group.topics||[]),goal:String(group.goal||'').trim(),createdBy:group.createdBy||members.find(m=>m.role==='Organizer')?.userId||currentStudyRequestUserId(),createdAt:group.createdAt||new Date().toISOString(),updatedAt,status,prototypeOnly:group.prototypeOnly!==false,...(recommendation?{recommendation}: {})}}
function findStudyGroupById(groupId){return getStudyGroups().find(group=>group.id===groupId)||null}
function updateStudyGroup(groupId,updates){const groups=getStudyGroups(),index=groups.findIndex(group=>group.id===groupId);if(index<0)return null;const oldGroup=groups[index],detailKeys=['course','examName','examDate','members','meeting','topics','goal'],detailsChanged=detailKeys.some(key=>Object.prototype.hasOwnProperty.call(updates,key));let recommendation=updates.recommendation!==undefined?updates.recommendation:oldGroup.recommendation;if(recommendation&&detailsChanged&&!Object.prototype.hasOwnProperty.call(updates,'recommendation')){recommendation={...recommendation,status:'Outdated'};showNotification({type:'warning',message:'This recommendation may be outdated because the group details changed.',actionLabel:'Regenerate',linkPage:'study-group-detail',relatedId:groupId})}groups[index]=normalizeStudyGroup({...oldGroup,...updates,recommendation,updatedAt:new Date().toISOString()});saveStudyGroups(groups);refreshStudyGroupUI();return groups[index]}
function updateStudyGroupStatus(groupId,status){if(!['Active','Completed','Cancelled'].includes(status))return null;return updateStudyGroup(groupId,{status})}
function deleteStudyGroup(groupId){saveStudyGroups(getStudyGroups().filter(group=>group.id!==groupId));refreshStudyGroupUI()}
function buildGroupMember(userId,displayName,role='Member'){return {userId,displayName:firstName(displayName),role,status:'Active'}}
function createStudyGroup(groupData){const groups=getStudyGroups(),now=new Date().toISOString(),group=normalizeStudyGroup({id:`group-${Date.now()}`,name:String(groupData.name||'').trim(),course:String(groupData.course||'').trim(),examName:String(groupData.examName||'').trim(),examDate:groupData.examDate||'',members:groupData.members,meeting:{date:groupData.meeting.date,time:groupData.meeting.time,type:groupData.meeting.type,link:String(groupData.meeting.link||'').trim(),generalLocation:String(groupData.meeting.generalLocation||'').trim()},topics:groupData.topics,goal:String(groupData.goal||'').trim(),createdBy:groupData.createdBy,createdAt:now,updatedAt:now,status:'Active',prototypeOnly:true});groups.push(group);saveStudyGroups(groups);return group}
function visibleStudyGroups(){const id=currentStudyRequestUserId();return getStudyGroups().filter(group=>group.members.some(member=>member.userId===id))}
function acceptedStudyPartnerMatches(){const id=currentStudyRequestUserId();return getStudyRequests().filter(r=>r.status==='Accepted'&&(r.fromUserId===id||r.toUserId===id)).map(request=>{const partnerId=request.fromUserId===id?request.toUserId:request.fromUserId,partner=studyPartners.find(p=>p.id===partnerId),match=partner?currentStudyPartnerMatch(partnerId):null;return partner&&!isStudentBlocked(partnerId)?{request,partner,match}:null}).filter(Boolean)}
function relatedGroupCandidate(candidate,base){if(!base)return true;return normalizeText(candidate.partner.course)===normalizeText(base.partner.course)||normalizeText(candidate.partner.subject)===normalizeText(base.partner.subject)||normalizeText(candidate.partner.examName)===normalizeText(base.partner.examName)}
function suggestedGroupTopics(match){const topics=[...(match?.evaluation?.topicMatch?.partnerCanHelpUser||[]),...(match?.evaluation?.topicMatch?.userCanHelpPartner||[]),...(match?.partner?.weakTopics||[]),...(match?.partner?.strongTopics||[]),...(studyMatchProfile()?.helpTopics||[])];return normalizeStudyTopics(topics).slice(0,8)}
function selectedGroupContext(){const editId=sessionStorage.getItem('editingStudyGroupId'),partnerId=sessionStorage.getItem('studyGroupPartnerId');if(editId)return {mode:'edit',group:findStudyGroupById(editId)};const accepted=acceptedStudyPartnerMatches(),initial=accepted.find(row=>row.partner.id===partnerId)||accepted[0]||null;return {mode:'create',accepted,initial}}
function openCreateStudyGroup(partnerId=''){const accepted=acceptedStudyPartnerMatches(),initial=accepted.find(row=>row.partner.id===partnerId)||accepted[0];if(!initial){sessionStorage.removeItem('editingStudyGroupId');sessionStorage.removeItem('studyGroupPartnerId');studyGroupDraftTopics=[];studyGroupDraftMemberIds=[];showView('studyGroupCreate');return}sessionStorage.removeItem('editingStudyGroupId');sessionStorage.setItem('studyGroupPartnerId',initial.partner.id);studyGroupDraftTopics=suggestedGroupTopics(initial.match);studyGroupDraftMemberIds=[initial.partner.id];showView('studyGroupCreate')}
function openEditStudyGroup(groupId){const group=findStudyGroupById(groupId);if(!group)return openStudyGroup(groupId);sessionStorage.setItem('editingStudyGroupId',groupId);sessionStorage.removeItem('studyGroupPartnerId');studyGroupDraftTopics=[...(group.topics||[])];studyGroupDraftMemberIds=group.members.filter(m=>m.userId!==group.createdBy).map(m=>m.userId);showView('studyGroupCreate')}
function openStudyGroup(groupId){sessionStorage.setItem('selectedStudyGroupId',groupId);showView('studyGroupDetail')}
function hasSimilarActiveGroup(proposedGroup){const proposedMemberIds=proposedGroup.members.map(member=>member.userId).sort().join('|');return getStudyGroups().some(group=>{const groupMemberIds=group.members.map(member=>member.userId).sort().join('|');return group.status==='Active'&&normalizeText(group.course)===normalizeText(proposedGroup.course)&&normalizeText(group.examName)===normalizeText(proposedGroup.examName)&&groupMemberIds===proposedMemberIds&&group.meeting?.date===proposedGroup.meeting?.date})}
function validateStudyGroupForm(data){const errors={},name=String(data.name||'').trim(),goal=String(data.goal||'').trim(),link=String(data.meeting?.link||'').trim(),location=String(data.meeting?.generalLocation||'').trim();if(name.length<3||name.length>60)errors.name='Please enter a group name between 3 and 60 characters.';if(!String(data.course||'').trim())errors.course='Please select a course.';if(String(data.course||'').trim().length>80)errors.course='Please keep the course under 80 characters.';if(!String(data.examName||'').trim())errors.examName='Please enter an exam.';if(String(data.examName||'').trim().length>80)errors.examName='Please keep the exam under 80 characters.';if(!Array.isArray(data.members)||data.members.length<2)errors.members='A study group needs at least 2 members.';else if(data.members.length>6)errors.members='A study group can have a maximum of 6 members.';if(!isCurrentOrFutureDate(data.meeting?.date))errors.meetingDate='Please choose a current or future meeting date.';if(!data.meeting?.time)errors.meetingTime='Please choose a meeting time.';if(!['Online','In Person','Hybrid'].includes(data.meeting?.type))errors.meetingType='Please select a meeting type.';if(link&&!/^https?:\/\//i.test(link))errors.meetingLink='Meeting links must begin with http:// or https://.';if(['In Person','Hybrid'].includes(data.meeting?.type)&&location&&!validateGeneralLocation(location))errors.meetingLink='Use only a general public location, not an address or private contact detail.';if(!Array.isArray(data.topics)||data.topics.length===0)errors.topics='Add at least one topic to review.';if(!goal||goal.length>200)errors.goal='Please enter a shared study goal.';return {valid:Object.keys(errors).length===0,errors}}
function formatStudyGroupMeeting(dateString,timeString){if(!dateString||!timeString)return 'Meeting not scheduled';const date=new Date(`${dateString}T${timeString}`);if(Number.isNaN(date.getTime()))return 'Meeting not scheduled';return date.toLocaleString(undefined,{weekday:'long',month:'long',day:'numeric',hour:'numeric',minute:'2-digit'})}
function formatStudyGroupTime(timeString){if(!timeString)return '';const date=new Date(`2026-01-01T${timeString}`);return Number.isNaN(date.getTime())?timeString:date.toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit'})}
function formatStudyGroupDate(value){const date=new Date(value);return Number.isNaN(date.getTime())?'Not provided':date.toLocaleDateString(undefined,{month:'long',day:'numeric',year:'numeric'})}
function studyGroupCourseOptions(current=''){const courses=uniqueCourses([...(selectedCourses()||[]),current].filter(Boolean));return courses.map(course=>'<option value="'+escapeHTML(course)+'" '+(course===current?'selected':'')+'>'+escapeHTML(course)+'</option>').join('')+'<option value="__custom__">Custom course...</option>'}
function studyGroupTopicChipsHTML(){return studyGroupDraftTopics.length?studyGroupDraftTopics.map(topic=>'<span class="study-topic-chip">'+escapeHTML(topic)+'<button data-remove-group-topic="'+escapeHTML(topic)+'" type="button" aria-label="Remove '+escapeHTML(topic)+'">x</button></span>').join(''):'<span class="empty-chip">Add at least one topic.</span>'}
function acceptedMemberOptionsHTML(base,group=null){const candidates=acceptedStudyPartnerMatches().filter(row=>relatedGroupCandidate(row,base)),required=base?.partner?.id||'';return candidates.filter(row=>row.partner.id!==required).map(row=>{const checked=studyGroupDraftMemberIds.includes(row.partner.id),disabled=!hasAcceptedRequestBetweenUsers(currentStudyRequestUserId(),row.partner.id);return '<label><input type="checkbox" name="studyGroupMembers" value="'+escapeHTML(row.partner.id)+'" '+(checked?'checked':'')+' '+(disabled?'disabled':'')+'> '+escapeHTML(firstName(row.partner.name))+' <small>'+escapeHTML(row.partner.course)+'</small></label>'}).join('')||'<p class="empty-mini">No other accepted partners match this course or exam yet.</p>'}
function renderStudyGroupCreatePage(){const root=$('#studyGroupCreateContent');if(!root||!user())return;const ctx=selectedGroupContext(),editing=ctx.mode==='edit',group=ctx.group;if(editing&&!group){root.innerHTML='<div class="empty-state card"><h2>Study group could not be found.</h2><button class="btn btn-primary" data-view="studyGroups" type="button">Back to Study Groups</button></div>';return bindStudyGroupFormActions()}const base=editing?null:ctx.initial;if(!editing&&!base){root.innerHTML='<div class="empty-state card"><h2>You need an accepted study request before creating a study group.</h2><p>Study groups can only be created with partners whose request status is Accepted.</p><button class="btn btn-primary" data-view="studyRequests" type="button">View Study Requests</button></div>';return bindStudyGroupFormActions()}const organizer=buildGroupMember(currentStudyRequestUserId(),currentUserDisplayName(),'Organizer'),partner=base?buildGroupMember(base.partner.id,base.partner.name,'Member'):null,members=editing?group.members:[organizer,partner].filter(Boolean),course=editing?group.course:base.partner.course,examName=editing?group.examName:base.partner.examName,examDate=editing?group.examDate:base.partner.examDate,meeting=editing?group.meeting:{date:'',time:'',type:base.partner.meetingType==='In person'?'In Person':base.partner.meetingType==='Hybrid'?'Hybrid':'Online',link:'',generalLocation:''};$('#studyGroupFormTitle').textContent=editing?'Edit Study Group':'Create Study Group';root.innerHTML='<form id="studyGroupForm" class="card study-group-form" novalidate><div id="studyGroupFormMessage" class="form-status" aria-live="polite"></div><p class="privacy-notice">Do not include home addresses, passwords, phone numbers, or other private information. For in-person meetings, use a general location such as a school library or public library.</p><div class="form-row"><label>Group Name<input id="studyGroupName" maxlength="60" required placeholder="Biology Final Prep" value="'+escapeHTML(editing?group.name:'')+'"><small data-error-for="name"></small></label><label>Course<select id="studyGroupCourse">'+studyGroupCourseOptions(course)+'</select><input id="studyGroupCourseCustom" class="hidden" maxlength="80" placeholder="Custom course name"><small data-error-for="course"></small></label></div><div class="form-row"><label>Exam<input id="studyGroupExam" maxlength="80" required value="'+escapeHTML(examName||'Final Exam')+'"><small data-error-for="examName"></small></label><label>Exam date<input id="studyGroupExamDate" type="date" value="'+escapeHTML(examDate||'')+'"></label></div><section class="match-form-section"><h4>Members</h4><div class="member-pill-list">'+members.map(m=>'<span class="member-pill">'+escapeHTML(m.displayName)+' <small>'+escapeHTML(m.role)+'</small></span>').join('')+'</div><div class="accepted-member-list"><b>Add Members</b>'+acceptedMemberOptionsHTML(base,group)+'</div><small data-error-for="members"></small></section><section class="match-form-section"><h4>Meeting</h4><div class="form-row"><label>Meeting Date<input id="studyGroupMeetingDate" type="date" required value="'+escapeHTML(meeting.date||'')+'"><small data-error-for="meetingDate"></small></label><label>Meeting Time<input id="studyGroupMeetingTime" type="time" required value="'+escapeHTML(meeting.time||'')+'"><small data-error-for="meetingTime"></small></label></div><label>Meeting Type<select id="studyGroupMeetingType"><option '+(meeting.type==='Online'?'selected':'')+'>Online</option><option '+(meeting.type==='In Person'?'selected':'')+'>In Person</option><option '+(meeting.type==='Hybrid'?'selected':'')+'>Hybrid</option></select><small data-error-for="meetingType"></small></label><div class="form-row" id="studyGroupMeetingExtras"><label data-meeting-extra="link">Meeting Link<input id="studyGroupMeetingLink" placeholder="https://..." value="'+escapeHTML(meeting.link||'')+'"><small data-error-for="meetingLink"></small></label><label data-meeting-extra="location">General Meeting Location<input id="studyGroupLocation" maxlength="100" placeholder="School library" value="'+escapeHTML(meeting.generalLocation||'')+'"></label></div></section><section class="match-form-section"><h4>Topics to Review</h4><div class="study-topic-chip-list" id="studyGroupTopicChips">'+studyGroupTopicChipsHTML()+'</div><div class="topic-add-row"><input id="studyGroupTopicInput" maxlength="50" placeholder="Add a topic"><button class="btn btn-secondary" id="addStudyGroupTopicBtn" type="button">Add Topic</button></div><small data-error-for="topics"></small></section><label>Shared Study Goal<textarea id="studyGroupGoal" maxlength="200" rows="3" required placeholder="Complete 30 practice questions">'+escapeHTML(editing?group.goal:'')+'</textarea><small data-error-for="goal"></small></label><div class="study-group-form-actions"><button class="btn btn-secondary" id="cancelStudyGroupForm" type="button">Cancel</button><button class="btn btn-primary" type="submit">'+(editing?'Save Group':'Create Group')+'</button></div></form>';bindStudyGroupFormActions();updateStudyGroupMeetingExtras()}
function bindStudyGroupFormActions(){const root=$('#studyGroupCreateContent');$$('[data-view]',root).forEach(btn=>btn.onclick=()=>showView(btn.dataset.view));$('#cancelStudyGroupCreateTop')?.addEventListener('click',()=>showView('studyGroups'));$('#cancelStudyGroupForm')?.addEventListener('click',()=>showView('studyGroups'));$('#studyGroupMeetingType')?.addEventListener('change',updateStudyGroupMeetingExtras);$('#studyGroupCourse')?.addEventListener('change',()=>$('#studyGroupCourseCustom')?.classList.toggle('hidden',$('#studyGroupCourse').value!=='__custom__'));$('#addStudyGroupTopicBtn')?.addEventListener('click',addStudyGroupTopicFromInput);$('#studyGroupTopicInput')?.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();addStudyGroupTopicFromInput()}});$$('[data-remove-group-topic]',root).forEach(btn=>btn.onclick=()=>{studyGroupDraftTopics=studyGroupDraftTopics.filter(topic=>topic!==btn.dataset.removeGroupTopic);renderStudyGroupCreatePage()});$$('[name="studyGroupMembers"]',root).forEach(box=>box.onchange=()=>{const id=box.value;if(box.checked&&!studyGroupDraftMemberIds.includes(id)){if(studyGroupDraftMemberIds.length>=5){box.checked=false;toast('A study group can have a maximum of 6 members.');return}studyGroupDraftMemberIds.push(id)}else if(!box.checked)studyGroupDraftMemberIds=studyGroupDraftMemberIds.filter(x=>x!==id)});$('#studyGroupForm')?.addEventListener('submit',saveStudyGroupForm)}
function updateStudyGroupMeetingExtras(){const type=$('#studyGroupMeetingType')?.value||'Online';$$('[data-meeting-extra]').forEach(label=>{const key=label.dataset.meetingExtra;label.classList.toggle('hidden',(key==='link'&&type==='In Person')||(key==='location'&&type==='Online'))})}
function addStudyGroupTopicFromInput(){const input=$('#studyGroupTopicInput'),topic=normalizeCourseName(input?.value||'').slice(0,50);if(!topic)return;if(studyGroupDraftTopics.length>=12)return toast('Add up to 12 topics.');if(!studyGroupDraftTopics.some(t=>normalizeText(t)===normalizeText(topic)))studyGroupDraftTopics.push(topic);if(input)input.value='';renderStudyGroupCreatePage()}
function collectStudyGroupForm(){const editingId=sessionStorage.getItem('editingStudyGroupId'),existing=editingId?findStudyGroupById(editingId):null,ctx=selectedGroupContext(),base=ctx.initial,organizer=existing?.members.find(m=>m.role==='Organizer')||buildGroupMember(currentStudyRequestUserId(),currentUserDisplayName(),'Organizer'),requiredPartner=existing?null:buildGroupMember(base.partner.id,base.partner.name,'Member'),extraIds=[...new Set(studyGroupDraftMemberIds)].filter(id=>id!==organizer.userId&&id!==requiredPartner?.userId),extraMembers=extraIds.map(id=>{const p=studyPartners.find(partner=>partner.id===id);return p&&hasAcceptedRequestBetweenUsers(currentStudyRequestUserId(),id)?buildGroupMember(id,p.name,'Member'):null}).filter(Boolean),members=[organizer,...(requiredPartner?[requiredPartner]:[]),...extraMembers],courseSelect=$('#studyGroupCourse')?.value,course=courseSelect==='__custom__'?$('#studyGroupCourseCustom')?.value:courseSelect;return {id:editingId||'',name:$('#studyGroupName')?.value||'',course,examName:$('#studyGroupExam')?.value||'',examDate:$('#studyGroupExamDate')?.value||'',members,meeting:{date:$('#studyGroupMeetingDate')?.value||'',time:$('#studyGroupMeetingTime')?.value||'',type:$('#studyGroupMeetingType')?.value||'',link:$('#studyGroupMeetingLink')?.value||'',generalLocation:$('#studyGroupLocation')?.value||''},topics:normalizeStudyTopics(studyGroupDraftTopics),goal:$('#studyGroupGoal')?.value||'',createdBy:organizer.userId}}
function showStudyGroupErrors(errors){$$('[data-error-for]').forEach(el=>{el.textContent=errors[el.dataset.errorFor]||''});const msg=Object.values(errors)[0]||'';if($('#studyGroupFormMessage'))$('#studyGroupFormMessage').textContent=msg}
function saveStudyGroupForm(e){e.preventDefault();const data=collectStudyGroupForm(),validation=validateStudyGroupForm(data);showStudyGroupErrors(validation.errors);if(!validation.valid){showNotification({type:'warning',message:'Review the highlighted fields before creating the group.',persistent:true});return}const editingId=sessionStorage.getItem('editingStudyGroupId');if(!editingId&&hasSimilarActiveGroup(data)){showStudyGroupErrors({name:'A similar active study group already exists.'});showNotification({type:'warning',message:'Review the highlighted fields before creating the group.'});return}const group=safelyRunCollaborativeAction(()=>editingId?updateStudyGroup(editingId,data):createStudyGroup(data),editingId?'The study group could not be saved.':'The study group could not be created.');if(!group)return;sessionStorage.removeItem('editingStudyGroupId');sessionStorage.removeItem('studyGroupPartnerId');studyGroupDraftTopics=[];studyGroupDraftMemberIds=[];openStudyGroup(group.id);showNotification({type:'success',message:editingId?'Study group updated successfully.':'Study group created successfully.',actionLabel:'View Group',linkPage:'study-group-detail',relatedId:group.id,important:true})}
function sortedStudyGroups(groups){return [...groups].sort((a,b)=>{if(a.status==='Active'&&b.status==='Active'){const ad=a.meeting?.date?new Date(`${a.meeting.date}T${a.meeting.time||'23:59'}`).getTime():Infinity,bd=b.meeting?.date?new Date(`${b.meeting.date}T${b.meeting.time||'23:59'}`).getTime():Infinity;return ad-bd}return String(b.updatedAt).localeCompare(String(a.updatedAt))})}
function studyGroupMatchesFilters(group,query,status,type){const haystack=[group.name,group.course,group.examName,...group.topics,...group.members.map(m=>m.displayName)].join(' ').toLowerCase();return (!query||haystack.includes(query))&&(status==='All'||group.status===status)&&(type==='All'||group.meeting?.type===type)}
function studyGroupCardHTML(group){const ready=group.recommendation&&group.recommendation.status!=='Preview',recHTML=ready?'<div class="request-message recommendation-mini"><span>Study Plan Ready</span><p>'+escapeHTML(group.recommendation.status==='Outdated'?'Saved plan may be outdated.':'Recommended plan saved.')+'</p></div>':'<div class="request-message recommendation-mini"><span>No study plan generated</span><p>Create a suggested session plan from group topics and member profiles.</p></div>';return '<article class="study-group-card card"><div class="request-card-head"><div><h3>'+escapeHTML(group.name)+'</h3><p>'+escapeHTML(group.course)+'</p></div>'+statusBadgeHTML(group.status)+'</div><div class="study-group-facts"><div><span>Exam</span><b>'+escapeHTML(group.examName)+'</b></div><div><span>Members</span><b>'+escapeHTML(group.members.map(m=>m.displayName).join(', '))+'</b></div><div><span>Meeting</span><b>'+escapeHTML(formatStudyGroupMeeting(group.meeting?.date,group.meeting?.time))+'</b></div><div><span>Meeting Type</span><b>'+escapeHTML(group.meeting?.type||'Online')+'</b></div></div><div class="request-message"><span>Topics</span><p>'+escapeHTML(group.topics.join(', ')||'No topics added.')+'</p></div><div class="request-message"><span>Goal</span><p>'+escapeHTML(group.goal)+'</p></div>'+recHTML+'<div class="request-card-actions"><button class="btn btn-primary" data-group-view="'+escapeHTML(group.id)+'" type="button">'+(ready?'View Recommended Plan':'View Group')+'</button><button class="btn btn-secondary" data-group-edit="'+escapeHTML(group.id)+'" type="button">Edit Group</button><button class="btn btn-secondary" data-card-generate-recommendation="'+escapeHTML(group.id)+'" type="button">'+(ready?'Regenerate Plan':'Generate Study Plan')+'</button>'+(group.status==='Active'?'<button class="btn btn-secondary" data-group-complete="'+escapeHTML(group.id)+'" type="button">Mark Complete</button>':'')+'</div></article>'}
function renderStudyGroupsPage(){const root=$('#studyGroupsContent');if(!root||!user())return;const groups=visibleStudyGroups(),query=($('#studyGroupSearch')?.value||'').trim().toLowerCase(),status=$('#studyGroupStatusFilter')?.value||'Active',type=$('#studyGroupTypeFilter')?.value||'All',counts={Active:0,Completed:0,Cancelled:0};groups.forEach(group=>counts[group.status]++);const filtered=sortedStudyGroups(groups).filter(group=>studyGroupMatchesFilters(group,query,status,type));root.innerHTML='<div class="prototype-banner card"><span class="pill blue-pill">Prototype Mode</span><h2>Study groups and changes are stored only on this device.</h2><p>Other students are not notified. A real version would need secure accounts, a shared backend, invitations, notifications, messaging, moderation, and privacy controls.</p></div><div class="request-summary-grid"><article><span>Active</span><b>'+counts.Active+'</b></article><article><span>Completed</span><b>'+counts.Completed+'</b></article><article><span>Cancelled</span><b>'+counts.Cancelled+'</b></article></div><div class="request-tools study-group-tools card"><label>Search groups<input id="studyGroupSearch" value="'+escapeHTML($('#studyGroupSearch')?.value||'')+'" placeholder="Search name, course, exam, member, or topic"></label><label>Status<select id="studyGroupStatusFilter"><option>All</option><option>Active</option><option>Completed</option><option>Cancelled</option></select></label><label>Meeting Type<select id="studyGroupTypeFilter"><option>All</option><option>Online</option><option>In Person</option><option>Hybrid</option></select></label></div>'+(groups.length?'<div class="study-group-grid">'+(filtered.length?filtered.map(studyGroupCardHTML).join(''):'<div class="empty-state card"><h2>No study groups match your filters.</h2></div>')+'</div>':'<div class="empty-state card"><h2>No study groups have been created yet.</h2><p>Create a group from an accepted study request.</p><button class="btn btn-primary" data-view="studyRequests" type="button">View Accepted Requests</button></div>');if($('#studyGroupStatusFilter'))$('#studyGroupStatusFilter').value=status;if($('#studyGroupTypeFilter'))$('#studyGroupTypeFilter').value=type;bindStudyGroupListActions()}
function bindStudyGroupListActions(){const root=$('#studyGroupsContent');$('#newStudyGroupBtn')?.addEventListener('click',()=>openCreateStudyGroup());$('#studyGroupSearch')?.addEventListener('input',renderStudyGroupsPage);$('#studyGroupStatusFilter')?.addEventListener('change',renderStudyGroupsPage);$('#studyGroupTypeFilter')?.addEventListener('change',renderStudyGroupsPage);$$('[data-view]',root).forEach(btn=>btn.onclick=()=>showView(btn.dataset.view));$$('[data-group-view]',root).forEach(btn=>btn.onclick=()=>openStudyGroup(btn.dataset.groupView));$$('[data-group-edit]',root).forEach(btn=>btn.onclick=()=>openEditStudyGroup(btn.dataset.groupEdit));$$('[data-group-complete]',root).forEach(btn=>btn.onclick=()=>markStudyGroupComplete(btn.dataset.groupComplete));$$('[data-card-generate-recommendation]',root).forEach(btn=>btn.onclick=()=>{openStudyGroup(btn.dataset.cardGenerateRecommendation);setTimeout(()=>generateRecommendationForGroup(btn.dataset.cardGenerateRecommendation),0)})}
function renderRecommendationSteps(recommendation){return '<ol class="recommendation-steps">'+recommendation.steps.map(step=>'<li><div><b>'+escapeHTML(step.description)+'</b>'+(step.topic?'<small>Topic: '+escapeHTML(step.topic)+'</small>':'')+(step.leaderName?'<small>Member: '+escapeHTML(step.leaderName)+'</small>':'')+(step.reason?'<details><summary>Why this step?</summary><p>'+escapeHTML(step.reason)+'</p></details>':'')+'</div><span>'+escapeHTML(String(step.durationMinutes))+' min</span></li>').join('')+'</ol>'}
function renderRecommendationRoles(recommendation){return recommendation.sessionRoles?.length?'<div class="study-match-preview-block"><b>Assigned member roles</b><ul>'+recommendation.sessionRoles.map(role=>'<li>'+escapeHTML(role.displayName+' - '+role.role+': '+role.details)+'</li>').join('')+'</ul></div>':''}
function renderRecommendationEditForm(group,recommendation){const draft=recommendationEditDrafts[group.id]||cloneData(recommendation);recommendationEditDrafts[group.id]=draft;return '<section class="card group-recommendation-panel"><div class="card-head"><div><span class="pill blue-pill">EDIT RECOMMENDATION</span><h3>Edit Recommended Study Plan</h3><p>Update steps, durations, assigned members, and topics.</p></div></div><div id="recommendationEditMessage" class="form-status" aria-live="polite"></div><div class="recommendation-edit-list">'+draft.steps.map((step,index)=>'<article class="recommendation-edit-row" data-edit-step="'+index+'"><div class="form-row"><label>Step description<input data-edit-field="description" value="'+escapeHTML(step.description)+'"></label><label>Duration<input data-edit-field="durationMinutes" type="number" min="1" max="120" value="'+escapeHTML(String(step.durationMinutes))+'"></label></div><div class="form-row"><label>Assigned member<select data-edit-field="leaderId"><option value="">No assigned member</option>'+group.members.map(member=>'<option value="'+escapeHTML(member.userId)+'" '+(member.userId===step.leaderId?'selected':'')+'>'+escapeHTML(member.displayName)+'</option>').join('')+'</select></label><label>Topic<input data-edit-field="topic" value="'+escapeHTML(step.topic||'')+'"></label></div><div class="request-card-actions"><button class="btn btn-secondary" data-move-rec-step="'+index+'" data-direction="up" type="button">Move Up</button><button class="btn btn-secondary" data-move-rec-step="'+index+'" data-direction="down" type="button">Move Down</button><button class="btn btn-danger" data-delete-rec-step="'+index+'" type="button">Delete Step</button></div></article>').join('')+'</div><div class="request-card-actions"><button class="btn btn-secondary" data-add-rec-step="'+escapeHTML(group.id)+'" type="button">Add Step</button><button class="btn btn-primary" data-save-edited-rec="'+escapeHTML(group.id)+'" type="button">Save Changes</button><button class="btn btn-secondary" data-cancel-rec-edit="'+escapeHTML(group.id)+'" type="button">Cancel</button></div></section>'}
function renderGroupRecommendationSection(group,isOrganizer){const editing=Boolean(recommendationEditDrafts[group.id]),recommendation=groupRecommendationForDisplay(group),isPreview=recommendation?.status==='Preview',outdated=recommendation?.status==='Outdated'||(recommendation?.basedOnGroupUpdatedAt&&recommendation.basedOnGroupUpdatedAt!==group.updatedAt&&recommendation.status!=='Preview');if(editing&&recommendation)return renderRecommendationEditForm(group,recommendation);if(!recommendation){return '<section class="card group-recommendation-panel"><div class="card-head"><div><span class="pill blue-pill">AI GROUP RECOMMENDATION</span><h3>AI Group Recommendation</h3><p>This recommendation is generated from the group selected topics, goals, and member profiles. Review and edit the plan before using it.</p></div></div><div class="empty-mini">No recommended study plan has been generated yet.</div><div class="request-card-actions">'+(isOrganizer?'<button class="btn btn-primary" data-generate-recommendation="'+escapeHTML(group.id)+'" type="button">Generate Study Plan</button>':'')+'</div></section>'}return '<section class="card group-recommendation-panel"><div class="card-head"><div><span class="pill blue-pill">AI GROUP RECOMMENDATION</span><h3>AI Group Recommendation</h3><p>This recommendation is generated from the group selected topics, goals, and member profiles. Review and edit the plan before using it.</p></div>'+statusBadgeHTML(isPreview?'Preview':outdated?'Outdated':'Saved')+'</div>'+(outdated?'<div class="prototype-notice">This recommendation may be outdated because the group details changed.</div>':'')+'<div class="profile-fact-grid">'+studyMatchFact('Recommended Session',recommendation.sessionMinutes+' minutes')+studyMatchFact('Total',recommendation.totalMinutes+' minutes')+studyMatchFact('Goal connection',recommendation.goalType.replace(/-/g,' '))+studyMatchFact('Topics covered',(recommendation.topicAssignments||[]).map(a=>a.topic).join(', ')||'Group topics')+'</div><h3 class="recommendation-heading">Recommended Study Plan</h3>'+renderRecommendationSteps(recommendation)+renderRecommendationRoles(recommendation)+'<div class="request-card-actions">'+(isOrganizer?'<button class="btn btn-secondary" data-regenerate-recommendation="'+escapeHTML(group.id)+'" type="button">Regenerate Recommendation</button>':'')+(isPreview&&isOrganizer?'<button class="btn btn-primary" data-save-recommendation="'+escapeHTML(group.id)+'" type="button">Save Recommendation</button>':'')+(outdated&&isOrganizer?'<button class="btn btn-secondary" data-keep-recommendation="'+escapeHTML(group.id)+'" type="button">Keep Current Plan</button>':'')+(recommendation.status==='Saved'&&isOrganizer?'<button class="btn btn-secondary" data-edit-recommendation="'+escapeHTML(group.id)+'" type="button">Edit Recommendation</button>':'')+'<button class="btn btn-secondary" data-copy-recommendation="'+escapeHTML(group.id)+'" type="button">Copy Study Plan</button><button class="btn btn-secondary" data-print-recommendation type="button">Print Study Plan</button></div></section>'}
function renderStudyGroupDetailPage(){const root=$('#studyGroupDetailContent');if(!root||!user())return;const id=sessionStorage.getItem('selectedStudyGroupId'),group=id?findStudyGroupById(id):null;if(!group){root.innerHTML='<div class="empty-state card"><h2>Study group could not be found.</h2><button class="btn btn-primary" data-view="studyGroups" type="button">Back to Study Groups</button></div>';return bindStudyGroupDetailActions()}const organizer=group.members.find(m=>m.role==='Organizer'),isOrganizer=organizer?.userId===currentStudyRequestUserId(),location=group.meeting?.type==='Online'?group.meeting.link:group.meeting?.type==='In Person'?group.meeting.generalLocation:[group.meeting?.link,group.meeting?.generalLocation].filter(Boolean).join(' | '),memberHTML='<div class="group-member-safety-list">'+group.members.map(m=>'<div><span>'+escapeHTML(m.displayName+' - '+m.role)+'</span>'+(m.userId!==currentStudyRequestUserId()?'<span><button class="btn btn-secondary" data-report-student="'+escapeHTML(m.userId)+'" type="button">Report</button><button class="btn btn-danger" data-block-student="'+escapeHTML(m.userId)+'" type="button">Block</button></span>':'')+'</div>').join('')+'</div>';root.innerHTML='<article class="card study-group-detail"><div class="study-profile-hero"><div><h2>'+escapeHTML(group.name)+'</h2><p>'+escapeHTML(group.course)+'</p>'+statusBadgeHTML(group.status)+'</div></div><p class="safety-note">This prototype group is visible only on this device. A real version would need authenticated member access, moderation, reporting, and school or guardian safety rules.</p><div class="profile-fact-grid">'+studyMatchFact('Course',group.course)+studyMatchFact('Exam',group.examName)+studyMatchFact('Exam date',formatStudyGroupDate(group.examDate))+studyMatchFact('Organizer',organizer?.displayName||'Organizer')+studyMatchFact('Meeting date',formatStudyGroupDate(group.meeting?.date))+studyMatchFact('Meeting time',formatStudyGroupTime(group.meeting?.time))+studyMatchFact('Meeting type',group.meeting?.type||'Online')+studyMatchFact('Location or link',location||'Not provided')+studyMatchFact('Created',formatStudyGroupDate(group.createdAt))+studyMatchFact('Last updated',formatStudyGroupDate(group.updatedAt))+'</div><section class="study-match-preview-block"><b>Members</b>'+memberHTML+'</section><section class="study-match-preview-block"><b>Topics</b>'+simpleListHTML(group.topics,'No topics saved.')+'</section><section class="study-match-preview-block"><b>Shared goal</b><p>'+escapeHTML(group.goal)+'</p></section><div class="request-card-actions"><button class="btn btn-secondary" data-view="studyGroups" type="button">Back to Study Groups</button><button class="btn btn-primary" data-detail-edit-group="'+escapeHTML(group.id)+'" type="button">Edit Group</button>'+(group.status==='Active'?'<button class="btn btn-secondary" data-detail-complete-group="'+escapeHTML(group.id)+'" type="button">Mark Complete</button><button class="btn btn-secondary" data-detail-cancel-group="'+escapeHTML(group.id)+'" type="button">Cancel Group</button>':'')+'<button class="btn btn-secondary" data-detail-copy-group="'+escapeHTML(group.id)+'" type="button">Copy Meeting Details</button>'+(isOrganizer?'<button class="btn btn-danger" data-detail-delete-group="'+escapeHTML(group.id)+'" type="button">Delete Group</button>':'')+'</div></article>'+renderGroupRecommendationSection(group,isOrganizer);bindStudyGroupDetailActions()}
function bindStudyGroupDetailActions(){const root=$('#studyGroupDetailContent');$('#backToStudyGroupsBtn')?.addEventListener('click',()=>showView('studyGroups'));$$('[data-view]',root).forEach(btn=>btn.onclick=()=>showView(btn.dataset.view));$$('[data-detail-edit-group]',root).forEach(btn=>btn.onclick=()=>openEditStudyGroup(btn.dataset.detailEditGroup));$$('[data-detail-complete-group]',root).forEach(btn=>btn.onclick=()=>markStudyGroupComplete(btn.dataset.detailCompleteGroup));$$('[data-detail-cancel-group]',root).forEach(btn=>btn.onclick=()=>cancelStudyGroup(btn.dataset.detailCancelGroup));$$('[data-detail-delete-group]',root).forEach(btn=>btn.onclick=()=>confirmDeleteStudyGroup(btn.dataset.detailDeleteGroup));$$('[data-detail-copy-group]',root).forEach(btn=>btn.onclick=()=>copyStudyGroupDetails(btn.dataset.detailCopyGroup));$$('[data-block-student]',root).forEach(btn=>btn.onclick=()=>blockStudentFlow(btn.dataset.blockStudent));$$('[data-report-student]',root).forEach(btn=>btn.onclick=()=>openReportStudentModal(btn.dataset.reportStudent));$$('[data-generate-recommendation]',root).forEach(btn=>btn.onclick=()=>generateRecommendationForGroup(btn.dataset.generateRecommendation));$$('[data-regenerate-recommendation]',root).forEach(btn=>btn.onclick=()=>generateRecommendationForGroup(btn.dataset.regenerateRecommendation));$$('[data-save-recommendation]',root).forEach(btn=>btn.onclick=()=>saveRecommendationFromPreview(btn.dataset.saveRecommendation));$$('[data-keep-recommendation]',root).forEach(btn=>btn.onclick=()=>keepOutdatedRecommendation(btn.dataset.keepRecommendation));$$('[data-copy-recommendation]',root).forEach(btn=>btn.onclick=()=>copyGroupRecommendation(btn.dataset.copyRecommendation));$$('[data-print-recommendation]',root).forEach(btn=>btn.onclick=()=>window.print());$$('[data-edit-recommendation]',root).forEach(btn=>btn.onclick=()=>openRecommendationEditor(btn.dataset.editRecommendation));$$('[data-cancel-rec-edit]',root).forEach(btn=>btn.onclick=()=>{delete recommendationEditDrafts[btn.dataset.cancelRecEdit];renderStudyGroupDetailPage()});$$('[data-add-rec-step]',root).forEach(btn=>btn.onclick=()=>addRecommendationEditStep(btn.dataset.addRecStep));$$('[data-move-rec-step]',root).forEach(btn=>btn.onclick=()=>moveRecommendationEditStep(btn.dataset.moveRecStep,btn.dataset.direction));$$('[data-delete-rec-step]',root).forEach(btn=>btn.onclick=()=>deleteRecommendationEditStep(btn.dataset.deleteRecStep));$$('[data-save-edited-rec]',root).forEach(btn=>btn.onclick=()=>saveEditedRecommendation(btn.dataset.saveEditedRec))}
function generateRecommendationForGroup(groupId){const group=findStudyGroupById(groupId);if(!group)return showNotification({type:'error',message:'The recommendation could not be generated.'});const panel=$('.group-recommendation-panel');if(panel)panel.insertAdjacentHTML('afterbegin','<div class="prototype-notice">Creating a study recommendation...</div>');const result=safelyRunCollaborativeAction(()=>buildGroupRecommendation(group),'The study recommendation could not be generated.');if(!result)return;if(result.error){showNotification({type:'warning',message:result.error.includes('topics')?'Add topics before generating a study recommendation.':result.error,persistent:true});renderStudyGroupDetailPage();return}pendingGroupRecommendations[groupId]=result.recommendation;delete recommendationEditDrafts[groupId];renderStudyGroupDetailPage();showNotification({type:'success',message:'Study recommendation generated.'});showNotification({type:'information',message:'Your recommendation is based on the latest group information.'})}
function saveRecommendationFromPreview(groupId){const recommendation=pendingGroupRecommendations[groupId];if(!recommendation)return showNotification({type:'warning',message:'Add topics before generating a study recommendation.'});if(saveGroupRecommendation(groupId,recommendation)){renderStudyGroupsPage();renderStudyGroupDetailPage();showNotification({type:'success',message:'Study recommendation saved successfully.',important:true})}else showNotification({type:'error',message:'The recommendation could not be generated.'})}
function keepOutdatedRecommendation(groupId){const group=findStudyGroupById(groupId);if(!group?.recommendation)return;saveGroupRecommendation(groupId,{...group.recommendation,status:'Saved'});renderStudyGroupDetailPage();showNotification({type:'information',message:'Your recommendation is based on the latest group information.'})}
function copyGroupRecommendation(groupId){const group=findStudyGroupById(groupId),recommendation=group?groupRecommendationForDisplay(group):null;if(!group||!recommendation)return toast('No recommendation to copy.');navigator.clipboard?.writeText(plainRecommendationText(group,recommendation)).then(()=>toast('Study plan copied.')).catch(()=>toast('Copy is not available in this browser.'))}
function openRecommendationEditor(groupId){const group=findStudyGroupById(groupId);if(!group?.recommendation)return;recommendationEditDrafts[groupId]=cloneData(group.recommendation);renderStudyGroupDetailPage()}
function collectRecommendationEditDraft(groupId){const group=findStudyGroupById(groupId),draft=recommendationEditDrafts[groupId];if(!group||!draft)return null;const rows=$$('[data-edit-step]');draft.steps=rows.map((row,index)=>{const leaderId=row.querySelector('[data-edit-field="leaderId"]')?.value||'',member=group.members.find(m=>m.userId===leaderId);return {...(draft.steps[index]||{}),order:index+1,description:row.querySelector('[data-edit-field="description"]')?.value.trim()||'',durationMinutes:Number(row.querySelector('[data-edit-field="durationMinutes"]')?.value)||0,leaderId,leaderName:member?.displayName||'',topic:row.querySelector('[data-edit-field="topic"]')?.value.trim()||''}});draft.totalMinutes=calculateRecommendationDuration(draft.steps);return draft}
function addRecommendationEditStep(groupId){const draft=collectRecommendationEditDraft(groupId)||recommendationEditDrafts[groupId];if(!draft)return;draft.steps.push({order:draft.steps.length+1,type:'custom',title:'Custom step',description:'Add a study activity.',durationMinutes:5,reason:'Added by the organizer.'});renderStudyGroupDetailPage()}
function moveRecommendationEditStep(indexValue,direction){const groupId=sessionStorage.getItem('selectedStudyGroupId'),draft=collectRecommendationEditDraft(groupId)||recommendationEditDrafts[groupId],index=Number(indexValue);if(!draft||!Number.isFinite(index))return;const target=direction==='up'?index-1:index+1;if(target<0||target>=draft.steps.length)return;[draft.steps[index],draft.steps[target]]=[draft.steps[target],draft.steps[index]];renderStudyGroupDetailPage()}
function deleteRecommendationEditStep(indexValue){const groupId=sessionStorage.getItem('selectedStudyGroupId'),draft=collectRecommendationEditDraft(groupId)||recommendationEditDrafts[groupId],index=Number(indexValue);if(!draft||!Number.isFinite(index))return;draft.steps.splice(index,1);renderStudyGroupDetailPage()}
async function saveEditedRecommendation(groupId){const group=findStudyGroupById(groupId),draft=collectRecommendationEditDraft(groupId);if(!group||!draft)return;const errors=[];if(!draft.steps.length)errors.push('At least one step is required.');draft.steps.forEach((step,index)=>{if(!step.description)errors.push(`Step ${index+1} needs a description.`);if(!Number.isFinite(step.durationMinutes)||step.durationMinutes<=0)errors.push(`Step ${index+1} needs a positive duration.`)});draft.totalMinutes=calculateRecommendationDuration(draft.steps);if(draft.totalMinutes>120)errors.push('Total duration must be 120 minutes or less.');if(errors.length){$('#recommendationEditMessage').textContent=errors[0];showNotification({type:'warning',message:'Review the highlighted fields before saving the recommendation.'});return}if(draft.totalMinutes>draft.sessionMinutes){const ok=await confirmDialog({title:'Longer Than Recommended',message:'This plan is longer than the recommended session length.',okText:'Save Anyway',cancelText:'Keep Editing'});if(!ok)return}draft.steps=draft.steps.map((step,index)=>({...step,order:index+1}));saveGroupRecommendation(groupId,draft);delete recommendationEditDrafts[groupId];renderStudyGroupDetailPage();showNotification({type:'success',message:'Study recommendation saved successfully.',important:true})}
async function markStudyGroupComplete(groupId){const ok=await confirmDialog({title:'Mark Complete',message:'Mark this study group as completed?',okText:'Mark Complete',cancelText:'Cancel'});if(!ok)return;updateStudyGroupStatus(groupId,'Completed');showNotification({type:'success',message:'Study group marked as completed.'})}
async function cancelStudyGroup(groupId){const ok=await confirmDialog({title:'Cancel Study Group',message:'Cancel this study group?',okText:'Cancel Group',cancelText:'Keep Active',danger:true});if(!ok)return;updateStudyGroupStatus(groupId,'Cancelled');showNotification({type:'information',message:'Study group cancelled.'})}
async function confirmDeleteStudyGroup(groupId){const ok=await confirmDialog({title:'Delete Study Group',message:'Permanently delete this study group from this device?',okText:'Delete Group',cancelText:'Cancel',danger:true});if(!ok)return;deleteStudyGroup(groupId);showView('studyGroups');showNotification({type:'information',message:'Study group deleted.'})}
function copyStudyGroupDetails(groupId){const group=findStudyGroupById(groupId);if(!group)return;const text=[group.name,formatStudyGroupMeeting(group.meeting?.date,group.meeting?.time),group.meeting?.type||'Online','Topics: '+group.topics.join(', '),'Goal: '+group.goal].join('\n');navigator.clipboard?.writeText(text).then(()=>toast('Meeting details copied.')).catch(()=>toast('Copy is not available in this browser.'))}
function nextActiveStudyGroup(){return sortedStudyGroups(visibleStudyGroups().filter(group=>group.status==='Active'&&group.meeting?.date)).find(Boolean)||null}
function renderStudyGroupDashboardCard(){const root=$('#dashboardStudyGroup');if(!root)return;const group=nextActiveStudyGroup();if(!group){root.innerHTML='<div class="empty-mini">No upcoming study groups.</div><button class="btn btn-secondary btn-full" data-view="studyGroups" type="button">Open Study Groups</button>';$$('[data-view]',root).forEach(btn=>btn.onclick=()=>showView(btn.dataset.view));return}root.innerHTML='<div class="dashboard-readiness-row"><div><b>'+escapeHTML(group.name)+'</b><small>'+escapeHTML(formatStudyGroupMeeting(group.meeting?.date,group.meeting?.time))+'</small></div><span>'+group.members.length+'</span></div><p><b>Goal:</b> '+escapeHTML(group.goal)+'</p><button class="btn btn-primary btn-full" data-dashboard-group="'+escapeHTML(group.id)+'" type="button">View Group</button>';$$('[data-dashboard-group]',root).forEach(btn=>btn.onclick=()=>openStudyGroup(btn.dataset.dashboardGroup))}
function refreshStudyGroupUI(){renderStudyGroupsPage();renderStudyRequestsPage();renderStudyPartnerProfilePage();renderStudyGroupDetailPage();renderStudyGroupDashboardCard()}
function getCurrentUserId(){return currentStudyRequestUserId()}
function groupRecommendationRules(){return appData.groupRecommendationRules||FALLBACK_GROUP_RECOMMENDATION_RULES}
function getUniqueTopics(list=[]){return normalizeStudyTopics(list)}
function buildGroupMemberLearningProfile(member,currentUserProfile=studyMatchProfile(),partners=studyPartners){const isCurrentUser=member.userId===getCurrentUserId();if(isCurrentUser)return {userId:member.userId,displayName:member.displayName,strongTopics:getUniqueTopics(currentUserProfile?.strongTopics||[]),topicsNeedingHelp:getUniqueTopics(currentUserProfile?.helpTopics||[]),studyMethods:getUniqueStudyMethods(currentUserProfile?.studyMethods||[]),preferredTimes:currentUserProfile?.preferredTimes||[],sessionLength:currentUserProfile?.sessionLength||''};const partner=partners.find(item=>item.id===member.userId);return {userId:member.userId,displayName:member.displayName||firstName(partner?.name)||'Member',strongTopics:getUniqueTopics(partner?.strongTopics||[]),topicsNeedingHelp:getUniqueTopics(partner?.weakTopics||[]),studyMethods:getUniqueStudyMethods(partner?.studyMethods||[]),preferredTimes:partner?.preferredTimes||[],sessionLength:partner?.sessionLength||''}}
function findBalancedTopicLeader(topic,memberProfiles,assignmentCounts,previousLeaderId=''){const normalizedTopic=normalizeTopic(topic),eligible=memberProfiles.filter(member=>member.strongTopics.some(strongTopic=>normalizeTopic(strongTopic)===normalizedTopic));if(!eligible.length)return null;return eligible.sort((a,b)=>(assignmentCounts.get(a.userId)||0)-(assignmentCounts.get(b.userId)||0)||(a.userId===previousLeaderId?1:0)-(b.userId===previousLeaderId?1:0)||memberProfiles.indexOf(a)-memberProfiles.indexOf(b))[0]}
function findBestTopicLeader(topic,memberProfiles){const counts=new Map(memberProfiles.map(member=>[member.userId,0]));return findBalancedTopicLeader(topic,memberProfiles,counts,'')}
function createTopicAssignments(groupTopics,memberProfiles){const assignments=[],assignmentCounts=new Map(memberProfiles.map(member=>[member.userId,0]));let previousLeaderId='';for(const topic of groupTopics){const leader=findBalancedTopicLeader(topic,memberProfiles,assignmentCounts,previousLeaderId),normalized=normalizeTopic(topic),learners=memberProfiles.filter(member=>member.topicsNeedingHelp.some(helpTopic=>normalizeTopic(helpTopic)===normalized));assignments.push({topic,leaderId:leader?.userId||null,leaderName:leader?.displayName||'',learnerIds:learners.map(member=>member.userId),learnerNames:learners.map(member=>member.displayName),type:leader?'member-led':'group-review'});if(leader){assignmentCounts.set(leader.userId,(assignmentCounts.get(leader.userId)||0)+1);previousLeaderId=leader.userId}}return assignments.sort((a,b)=>{const ap=(a.leaderId&&a.learnerIds.length?0:a.leaderId?1:a.learnerIds.length>1?2:3),bp=(b.leaderId&&b.learnerIds.length?0:b.leaderId?1:b.learnerIds.length>1?2:3);return ap-bp})}
function determineRecommendedSessionLength(memberProfiles,rules){const lengthMap={'20-30 minutes':30,'30-45 minutes':45,'45-60 minutes':60,'60-90 minutes':75,'no preference':rules.defaultSessionMinutes??60},preferredLengths=memberProfiles.map(member=>lengthMap[sessionLengthLabel(member.sessionLength)]||lengthMap[normalizeSessionLength(member.sessionLength)]).filter(Number.isFinite);if(!preferredLengths.length)return rules.defaultSessionMinutes??60;const average=preferredLengths.reduce((sum,value)=>sum+value,0)/preferredLengths.length,rounded=Math.round(average/15)*15;return Math.min(Math.max(rounded,rules.minimumSessionMinutes??30),rules.maximumSessionMinutes??120)}
function pickCountForMinutes(sessionMinutes,counts={},fallback=10){const entries=Object.entries(counts).map(([minutes,count])=>({minutes:Number(minutes),count:Number(count)})).filter(entry=>Number.isFinite(entry.minutes)&&Number.isFinite(entry.count)).sort((a,b)=>a.minutes-b.minutes);let selected=fallback;for(const entry of entries)if(sessionMinutes>=entry.minutes)selected=entry.count;return selected}
function getPracticeQuestionCount(sessionMinutes,rules){return pickCountForMinutes(sessionMinutes,rules.practiceQuestionCounts,10)}
function getFinalQuizQuestionCount(sessionMinutes,rules){return pickCountForMinutes(sessionMinutes,rules.finalQuizQuestionCounts,5)}
function detectStudyGoalType(goal){const normalized=normalizeText(goal);if(normalized.includes('practice exam')||normalized.includes('mock exam'))return 'practice-exam';if(normalized.includes('practice question'))return 'practice-questions';if(normalized.includes('flashcard'))return 'flashcards';if(normalized.includes('note')||normalized.includes('summary'))return 'notes';if(normalized.includes('explain')||normalized.includes('teach'))return 'explanation';return 'general-review'}
function sharedStudyMethod(memberProfiles,goalType){if(goalType==='practice-questions'||goalType==='practice-exam')return 'practice questions';if(goalType==='flashcards')return 'flashcards';if(goalType==='notes')return 'reading notes';if(goalType==='explanation')return 'explaining concepts';const counts=new Map();memberProfiles.forEach(member=>member.studyMethods.forEach(method=>counts.set(method,(counts.get(method)||0)+1)));const priority=['practice questions','flashcards','explaining concepts','group discussion','reading notes','videos','mixed'];return priority.find(method=>(counts.get(method)||0)>1)||priority.find(method=>counts.has(method))||'practice questions'}
function roleAssignments(memberProfiles,topicAssignments){const roles=['Timekeeper','Question Reader','Answer Checker','Note Summarizer','Quiz Leader'],result=[],counts=new Map(memberProfiles.map(member=>[member.userId,0]));topicAssignments.filter(a=>a.leaderId).slice(0,3).forEach(a=>{result.push({userId:a.leaderId,displayName:a.leaderName,role:'Topic Leader',details:`Lead the ${a.topic} review.`});counts.set(a.leaderId,(counts.get(a.leaderId)||0)+1)});roles.forEach(role=>{const member=memberProfiles.slice().sort((a,b)=>(counts.get(a.userId)||0)-(counts.get(b.userId)||0))[0];if(!member)return;const details={Timekeeper:'Keep the group on schedule.',QuestionReader:'Read practice questions aloud.',AnswerChecker:'Lead answer checking after practice.',NoteSummarizer:'Write the final key points.',QuizLeader:'Read the final quiz questions.'}[role];result.push({userId:member.userId,displayName:member.displayName,role,details});counts.set(member.userId,(counts.get(member.userId)||0)+1)});return result}
function practiceStepForMethod(method,group,sessionMinutes,rules,goalType){const count=getPracticeQuestionCount(sessionMinutes,rules),minutes=goalType==='practice-exam'?Math.max(20,rules.practiceQuestionMinutes):rules.practiceQuestionMinutes;if(method==='flashcards')return {type:'practice',title:'Flashcard practice',description:'Members quiz each other using flashcards.',durationMinutes:Math.min(15,minutes),reason:'Flashcards match the group goal or shared study method.'};if(method==='explaining concepts')return {type:'practice',title:'Teach-back round',description:'Each member explains one topic without using notes.',durationMinutes:Math.min(15,minutes),reason:'Explaining concepts helps members check understanding.'};if(method==='group discussion')return {type:'practice',title:'Exam question discussion',description:'Discuss two exam-style questions and compare answers.',durationMinutes:minutes,reason:'Group discussion matches a shared study method.'};if(method==='reading notes')return {type:'practice',title:'Note summary',description:'Review key notes and create a one-page summary.',durationMinutes:minutes,reason:'This supports a notes or summary-based goal.'};if(method==='videos')return {type:'practice',title:'Short video review',description:'Watch one short review video and write three key points.',durationMinutes:Math.min(12,minutes),reason:'Videos match a selected study method.'};if(method==='mixed')return {type:'practice',title:'Mixed practice',description:`Complete ${Math.max(8,Math.round(count*.7))} practice questions, then explain one answer aloud.`,durationMinutes:minutes,reason:'Mixed practice combines questions and explanation.'};return {type:'practice',title:'Practice questions',description:`The group completes ${count} practice questions.`,durationMinutes:minutes,reason:goalType==='practice-questions'?'This directly supports the shared practice-question goal.':'Practice Questions is a strong shared study method.'}}
function buildGroupRecommendationSteps({group,memberProfiles,topicAssignments,sessionMinutes,rules}){const goalType=detectStudyGoalType(group.goal),method=sharedStudyMethod(memberProfiles,goalType),steps=[];steps.push({type:'opening',title:'Goal review',description:group.goal?`Review the goal: ${group.goal}. Decide what success looks like for this session.`:'Review the group goal and decide what success looks like for this session.',durationMinutes:rules.openingMinutes,reason:'The group should agree on the session target before studying.'});const maxLed=rules.maximumMemberLedTopics??4,led=topicAssignments.filter(a=>a.leaderId).slice(0,maxLed);led.forEach(a=>{const learners=a.learnerNames.filter(name=>name&&name!==a.leaderName),learnerText=learners.length?' to '+learners.join(' and '):'';steps.push({type:'topic-explanation',title:`${a.topic} explanation`,description:`${a.leaderName} explains ${a.topic}${learnerText}.`,durationMinutes:rules.topicExplanationMinutes,leaderId:a.leaderId,leaderName:a.leaderName,topic:a.topic,reason:`${a.leaderName} listed ${a.topic} as a strength.`})});const groupReview=topicAssignments.filter(a=>!a.leaderId).slice(0,3);groupReview.forEach(a=>steps.push({type:'group-review',title:`${a.topic} group review`,description:`Review ${a.topic} together using notes or a textbook.`,durationMinutes:rules.groupReviewMinutes,topic:a.topic,reason:'No group member listed this topic as a strength, so it should be reviewed together.'}));const remaining=topicAssignments.slice(maxLed+groupReview.length);if(remaining.length)steps.push({type:'group-review',title:'Remaining topics review',description:`Briefly review the remaining topics together: ${remaining.map(a=>a.topic).join(', ')}.`,durationMinutes:10,reason:'The group has more topics than can fit as individual explanations.'});const practice=practiceStepForMethod(method,group,sessionMinutes,rules,goalType);steps.push(practice);if(['practice','quiz'].includes(practice.type)||/question|quiz|exam/i.test(practice.description))steps.push({type:'mistake-review',title:'Mistake review',description:'Review incorrect answers together and explain why each answer was incorrect.',durationMinutes:rules.mistakeReviewMinutes,reason:'Error review helps turn practice into learning.'});steps.push({type:'final-quiz',title:'Final quiz',description:`End with a ${getFinalQuizQuestionCount(sessionMinutes,rules)}-question quiz covering ${group.topics.slice(0,3).join(', ')||group.course}.`,durationMinutes:rules.finalQuizMinutes,reason:'A short quiz checks what the group remembers at the end.'});steps.push({type:'closing',title:'Goal check',description:'Check the shared goal, choose one next action, and save any topics that still need review.',durationMinutes:rules.closingMinutes,reason:'The group should leave with a clear next step.'});return steps}
function calculateRecommendationDuration(steps){return (steps||[]).reduce((total,step)=>total+(Number(step.durationMinutes)||0),0)}
function fitRecommendationToSession(steps,sessionMinutes){const minByType={opening:2,'topic-explanation':5,'final-quiz':3,closing:2,'group-review':5,practice:8,'mistake-review':5},priority=['group-review','topic-explanation','practice','mistake-review'];let total=calculateRecommendationDuration(steps);for(const type of priority){for(const step of steps){if(total<=sessionMinutes)break;if(step.type!==type)continue;const min=minByType[type]||3,canReduce=Math.max(0,(Number(step.durationMinutes)||0)-min),reduce=Math.min(canReduce,total-sessionMinutes);step.durationMinutes-=reduce;total-=reduce}if(total<=sessionMinutes)break}while(total>sessionMinutes&&steps.length>1){const removable=steps.findIndex(step=>!['opening','final-quiz','closing'].includes(step.type));if(removable<0)break;total-=steps[removable].durationMinutes;steps.splice(removable,1)}let remaining=sessionMinutes-calculateRecommendationDuration(steps);if(remaining>10){const topics=steps.filter(s=>s.topic).map(s=>s.topic),topic=topics[0]||'the hardest topic';steps.splice(Math.max(steps.length-1,1),0,{type:'extra-practice',title:'Extra practice',description:`Use the extra time for more practice questions or peer explanation on ${topic}.`,durationMinutes:remaining,reason:'This fills unused time with focused practice instead of leaving the session short.'})}return steps}
