function buildGroupRecommendation(group){const activeMembers=(group.members||[]).filter(m=>m.status!=='Removed'&&(!isStudentBlocked(m.userId)||m.userId===currentStudyRequestUserId()));if(activeMembers.length<2)return {error:'At least two active unblocked members are required to create a group study recommendation.'};if(!group.topics?.length)return {error:'Add topics to the study group before generating a recommendation.'};const safeGroup={...group,members:activeMembers};const profiles=activeMembers.map(member=>buildGroupMemberLearningProfile(member,studyMatchProfile(),studyPartners));return {recommendation:generateGroupRecommendation(safeGroup,profiles,groupRecommendationRules())}}
