function blankStudyMatchProfile(){return {id:'match'+Date.now(),subject:'',course:'',examName:'',examDate:'',strongTopics:[],helpTopics:[],preferredTimes:[],meetingType:'Online',groupSize:'No Preference',studyMethods:[],sessionLength:'',location:'',matchingEnabled:false,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()}}
function normalizeStudyTopics(list=[]){const seen=new Set();return (Array.isArray(list)?list:[]).map(x=>normalizeCourseName(String(x||'')).slice(0,50)).filter(Boolean).filter(topic=>{const key=topic.toLowerCase();if(seen.has(key))return false;seen.add(key);return true})}
