function validateStudyMatchProfile(profile){if(!profile.subject)return 'Please choose a subject.';if(!profile.course)return 'Please enter the full course name.';if(!profile.examName)return 'Please enter an exam name.';if(!profile.examDate)return 'Please choose an exam date.';if(!profile.strongTopics.length)return 'Add at least one strong topic.';if(!profile.helpTopics.length)return 'Add at least one topic needing help.';if(!profile.preferredTimes.length)return 'Please select at least one preferred study time.';if(!profile.studyMethods.length)return 'Choose at least one preferred study method.';if(!STUDY_SESSION_LENGTHS.map(normalizeSessionLength).includes(normalizeSessionLength(profile.sessionLength)))return 'Please select a preferred session length.';if(['in person','either'].includes(normalizeMeetingType(profile.meetingType))&&(!profile.location||!validateGeneralLocation(profile.location)))return 'Add a general meeting area only, not a full address or private contact detail.';return ''}
