async function deleteStudyMatchProfile(){const ok=await confirmDialog({title:'Delete Study Match Profile',message:'Are you sure you want to delete your Study Match Profile?',okText:'Delete Profile',cancelText:'Cancel',danger:true});if(!ok)return;user().studyMatchProfile=null;saveDB();renderStudyMatchPage();toast('Study Match Profile deleted.')}
function toggleStudyMatchPause(){const p=studyMatchProfile(),settings=ensurePrivacySettings();if(!p)return;if(p.matchingEnabled===false&&!settings.matchingConsent)return showNotification({type:'warning',message:'Enable Study Matching to appear in partner results.',persistent:true,actionLabel:'Complete Profile',linkPage:'study-match'});p.matchingEnabled=!p.matchingEnabled;settings.enableStudyMatching=p.matchingEnabled;settings.matchingConsent=settings.matchingConsent||p.matchingEnabled;p.updatedAt=new Date().toISOString();user().studyMatchProfile=p;saveDB();forceMatchCountNotification=p.matchingEnabled;renderStudyMatchPage();renderStudyPartnerResultsPage();renderSafetyPrivacyPage();showNotification({type:p.matchingEnabled?'success':'information',message:p.matchingEnabled?'Study Matching is now enabled.':'Study Matching is paused.'})}
$('#studyMatchForm')?.addEventListener('submit',saveStudyMatchProfile);
$('#editStudyMatchBtn')?.addEventListener('click',()=>setStudyMatchEditing(true));
$('#pauseStudyMatchBtn')?.addEventListener('click',toggleStudyMatchPause);
$('#deleteStudyMatchBtn')?.addEventListener('click',deleteStudyMatchProfile);
$('#refreshStudyPartnersBtn')?.addEventListener('click',()=>{forceMatchCountNotification=true;renderStudyPartnerResultsPage()});
$('#backToStudyPartnersBtn')?.addEventListener('click',()=>showView('studyPartnerResults'));
$('#studyRequestText')?.addEventListener('input',updateStudyRequestCounter);
$('#studyRequestClose')?.addEventListener('click',closeStudyRequestModal);
$('#studyRequestCancel')?.addEventListener('click',closeStudyRequestModal);
$('#studyRequestSend')?.addEventListener('click',sendPrototypeStudyRequest);
$('#studyRequestModal')?.addEventListener('keydown',e=>{if(e.key==='Escape')closeStudyRequestModal();if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendPrototypeStudyRequest()}if(e.key==='Tab'){const focusables=$$('#studyRequestModal button,#studyRequestModal textarea').filter(el=>!el.disabled),first=focusables[0],last=focusables[focusables.length-1];if(!first||!last)return;if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
$('#reportStudentClose')?.addEventListener('click',closeReportStudentModal);
$('#reportStudentCancel')?.addEventListener('click',closeReportStudentModal);
$('#reportStudentSubmit')?.addEventListener('click',submitReportStudent);
$('#reportStudentModal')?.addEventListener('keydown',e=>{if(e.key==='Escape')closeReportStudentModal()});
$('#studyMatchSubject')?.addEventListener('change',()=>{$('#studyMatchCourse').value=$('#studyMatchSubject').value});
$('#studyMatchMeetingPreference')?.addEventListener('change',syncStudyMatchLocationVisibility);
bindStudyMatchTopicInput('#strongTopicInput','strongTopics');
bindStudyMatchTopicInput('#helpTopicInput','helpTopics');

/* Folder organization. Every study item stores a folderId in localStorage. */
function folderById(id){return user().folders.find(f=>f.id===id)}
function uncategorized(){return folderById(SYSTEM_FOLDER_ID)}
function visibleFolders(){return user().folders.filter(f=>!f.protected)}
function normalizeFolderId(id){return folderById(id)&&!folderById(id).protected?id:SYSTEM_FOLDER_ID}
function folderOptions(){const options=visibleFolders().map(f=>`<option value="${f.id}">${escapeHTML(f.name)}</option>`).join('');return '<option value="">No folder</option>'+options}
function displayFolderName(id){const f=folderById(id);return f&&!f.protected?f.name:'No folder'}
function touchFolder(id){const f=folderById(id);if(f)f.updated=today()}
function folderParentOptions(editId=''){const blocked=editId?folderDescendants(editId):[];return '<option value="">Top level</option>'+visibleFolders().filter(f=>f.id!==editId&&!blocked.includes(f.id)).map(f=>`<option value="${f.id}">${escapeHTML(f.name)}</option>`).join('')}
function openFolderModal(id=''){const f=folderById(id);if(f?.protected)return toast('That system folder cannot be renamed.');$('#folderEditId').value=id;$('#folderName').value=f?.name||'';$('#folderColor').value=f?.color||'#5867e8';$('#folderParent').innerHTML=folderParentOptions(id);$('#folderParent').value=f?.parentId||'';$('#folderModalTitle').textContent=f?'Rename folder':'Create a folder';$('#folderModal').classList.add('open');$('#folderName').focus()}
function closeFolderModal(){$('#folderModal').classList.remove('open')}
function folderDescendants(id){const found=[];const walk=parent=>user().folders.filter(f=>f.parentId===parent).forEach(f=>{found.push(f.id);walk(f.id)});walk(id);return found}
function openDeleteFolder(id){const f=folderById(id);if(!f||f.protected)return toast('That system folder cannot be deleted.');$('#deleteFolderId').value=id;$('input[name="deleteMode"][value="folder"]').checked=true;$('#deleteFolderModal').classList.add('open')}
function closeDeleteFolder(){$('#deleteFolderModal').classList.remove('open')}
function deleteFolder(){const id=$('#deleteFolderId').value,f=folderById(id),mode=$('input[name="deleteMode"]:checked').value;if(!f||f.protected)return;const ids=[id,...folderDescendants(id)],keys=['notes','flashcards','quizzes','plans','files'];if(mode==='all')keys.forEach(k=>user()[k]=user()[k].filter(x=>!ids.includes(x.folderId)));else keys.forEach(k=>user()[k].forEach(x=>{if(ids.includes(x.folderId))x.folderId=SYSTEM_FOLDER_ID}));user().folders=user().folders.filter(x=>!ids.includes(x.id));if(mode==='folder')touchFolder(SYSTEM_FOLDER_ID);if(ids.includes(activeFolderId))activeFolderId=null;saveDB();closeDeleteFolder();renderAll();showView('folders');toast(mode==='all'?'Folder and all contents permanently deleted.':'Folder deleted; contents moved to Uncategorized.')}
function moveFolder(id,parentId){const f=folderById(id);if(!f||f.protected||id===parentId||folderDescendants(id).includes(parentId))return toast('That folder cannot be moved there.');if(folderNameExists(f.name,parentId,id))return toast('A folder with that name already exists there.');f.parentId=parentId;touchFolder(id);saveDB();renderAll();toast(parentId?'Folder moved.':'Folder moved to the top level.')}
function changeFolderColor(id,color){const f=folderById(id);if(!f)return;f.color=color;touchFolder(id);saveDB();renderAll()}
function folderNameExists(name,parentId='',ignoreId=''){return visibleFolders().some(f=>f.id!==ignoreId&&(f.parentId||'')===(parentId||'')&&f.name.trim().toLowerCase()===name.trim().toLowerCase())}
$('#sidebarCreateFolderBtn')?.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();openFolderModal()});$('#dashboardNewFolder').onclick=()=>openFolderModal();$('#createFolderPageBtn').onclick=()=>openFolderModal();$('#folderModalClose').onclick=closeFolderModal;$('#cancelDeleteFolder').onclick=closeDeleteFolder;$('#confirmDeleteFolder').onclick=deleteFolder;$('#folderForm').onsubmit=e=>{e.preventDefault();const name=normalizeCourseName($('#folderName').value),id=$('#folderEditId').value,color=$('#folderColor').value||'#5867e8',parentId=$('#folderParent').value||'';if(!name)return toast('Enter a folder name.');if(name.length>40)return toast('Folder names must be 40 characters or less.');if(folderNameExists(name,parentId,id))return toast('A folder with that name already exists there.');if(id){const f=folderById(id);if(!f||f.protected)return toast('That system folder cannot be renamed.');if(parentId===id||folderDescendants(id).includes(parentId))return toast('That folder cannot be moved there.');Object.assign(f,{name,color,parentId,updated:today()})}else user().folders.unshift({id:'f'+Date.now(),name,updated:today(),createdAt:new Date().toISOString(),color,parentId});saveDB();closeFolderModal();renderAll();if(id&&activeFolderId===id)renderFolderDetail();toast(id?'Folder updated.':'Folder created.')};
function folderStats(id){const u=user();const stats={notes:u.notes.filter(x=>x.folderId===id).length,cards:u.flashcards.filter(x=>x.folderId===id).length,quizzes:u.quizzes.filter(x=>x.folderId===id).length,plans:u.plans.filter(x=>x.folderId===id).length,files:u.files.filter(x=>x.folderId===id).length};stats.total=stats.notes+stats.cards+stats.quizzes+stats.plans+stats.files;return stats}
function folderUpdatedLabel(f){if(!f?.updated)return 'Unknown';return f.updated===today()?'Today':f.updated}
function folderMenuHTML(f,menuId,parentChoices){return `<div class="folder-menu" data-folder-dropdown="${menuId}"><button type="button" data-folder-open-menu="${f.id}">Open Folder</button><button type="button" data-folder-edit="${f.id}">Rename Folder</button><div class="menu-section"><span>Change Folder Color</span><div class="color-options">${['#5867e8','#8b6ddd','#40a77e','#dd8b51','#d65e72','#4b9bc2'].map(c=>`<button type="button" data-folder-color="${f.id}" data-color="${c}" style="--swatch:${c}" aria-label="Use color ${c}"></button>`).join('')}</div></div><label class="move-folder-label">Move Folder<select data-folder-move="${f.id}">${parentChoices(f.id)}</select></label><button type="button" class="danger-menu-item" data-folder-delete="${f.id}">Delete Folder</button></div>`}
function folderCardHTML(f,menuId){const s=folderStats(f.id);return `<article class="folder-card folder-page-card" data-folder-card="${f.id}" style="--folder-color:${f.color||'#5867e8'}"><div class="folder-card-top"><span class="folder-symbol">F</span><div><b>${escapeHTML(f.name)}</b><small>${s.total} ${s.total===1?'Item':'Items'}</small></div><button type="button" class="folder-menu-button" data-folder-menu="${menuId}" aria-label="Manage ${escapeHTML(f.name)}" title="Manage folder">...</button></div><div class="folder-counts folder-page-counts"><span><b>${s.notes}</b> Notes</span><span><b>${s.files}</b> Files</span><span><b>${s.cards}</b> Flashcards</span><span><b>${s.quizzes}</b> Quizzes</span><span><b>${s.plans}</b> Study Plans</span></div><small class="folder-updated">Updated ${escapeHTML(folderUpdatedLabel(f))}</small>${folderMenuHTML(f,menuId,folderParentOptions)}</article>`}
function sortFolders(list){const sort=$('#folderSortSelect')?.value||'updated';return [...list].sort((a,b)=>{if(sort==='name')return a.name.localeCompare(b.name);if(sort==='items')return folderStats(b.id).total-folderStats(a.id).total;if(sort==='newest')return String(b.createdAt||b.updated||'').localeCompare(String(a.createdAt||a.updated||''));return String(b.updated||'').localeCompare(String(a.updated||''))})}
function renderFoldersPage(){if(!user()||!$('#foldersPageGrid'))return;const query=normalizeCourseName($('#folderSearchInput')?.value||'').toLowerCase();let folders=visibleFolders().filter(f=>!query||f.name.toLowerCase().includes(query));folders=sortFolders(folders);$('#foldersPageGrid').innerHTML=folders.length?folders.map(f=>folderCardHTML(f,`page-${f.id}`)).join(''):`<div class="empty-state card folder-empty-state"><h2>No folders yet</h2><p>Create your first folder to organize your study materials.</p><button class="btn btn-primary" id="emptyCreateFolderBtn" type="button">+ Create Your First Folder</button></div>`;$('#emptyCreateFolderBtn')?.addEventListener('click',()=>openFolderModal());bindFolderMenus($('#foldersView'))}
function openFolderDetail(id){activeFolderId=id;activeFolderDetailFilter='all';showView('folderDetail')}
function folderItems(id){const u=user();return {notes:u.notes.filter(x=>x.folderId===id),files:(u.files||[]).filter(x=>x.folderId===id),flashcards:u.flashcards.filter(x=>x.folderId===id),quizzes:u.quizzes.filter(x=>x.folderId===id),plans:u.plans.filter(x=>x.folderId===id)}}
function folderItemCard(kind,item,index){if(kind==='notes')return `<article class="folder-item-card" data-open-note="${item.id}"><b>${escapeHTML(item.title||'Untitled note')}</b><span>${escapeHTML(item.subject||'Course')} - ${escapeHTML(item.created||'Saved note')}</span></article>`;if(kind==='files')return `<article class="folder-item-card"><b>${escapeHTML(item.title||item.fileName||'Uploaded file')}</b><span>${escapeHTML(item.fileType||fileTypeLabel(item))} - ${escapeHTML(formatFileSize(item.fileSize||0))}</span></article>`;if(kind==='flashcards')return `<article class="folder-item-card"><b>${escapeHTML(item.question||'Flashcard')}</b><span>${escapeHTML(item.subject||'Course')}</span></article>`;if(kind==='quizzes')return `<article class="folder-item-card"><b>${escapeHTML(item.subject||'Quiz')}</b><span>${item.score??0}% - ${escapeHTML(item.date||'Recent')}</span></article>`;return `<article class="folder-item-card" data-folder-plan="${item.id}"><b>${escapeHTML(item.title||'Study Plan')}</b><span>${escapeHTML(item.course||'Course')} - Test ${escapeHTML(item.testDate||'Not set')}</span></article>`}
function folderSectionHTML(kind,title,items){return `<section class="card folder-detail-section" data-folder-section="${kind}"><div class="card-head"><div><h3>${title}</h3><p>${items.length} item(s)</p></div></div><div class="folder-item-grid">${items.length?items.map((item,i)=>folderItemCard(kind,item,i)).join(''):'<div class="empty-mini">No items in this section.</div>'}</div></section>`}
function renderFolderDetail(){const f=folderById(activeFolderId),missing=!f||f.protected;$('#folderDetailMissing')?.classList.toggle('hidden',!missing);$('#folderDetailPanel')?.classList.toggle('hidden',missing);if(missing)return;const stats=folderStats(f.id),items=folderItems(f.id);$('#folderDetailTitle').textContent=f.name;$('#folderDetailHero').style.setProperty('--folder-color',f.color||'#5867e8');$('#folderDetailHero').innerHTML=`<div class="folder-detail-summary"><span class="folder-symbol">F</span><div><h2>${escapeHTML(f.name)}</h2><p>${stats.total} total item(s) - Updated ${escapeHTML(folderUpdatedLabel(f))}</p></div></div><div class="folder-detail-actions"><button class="btn btn-secondary" id="folderDetailRenameBtn" type="button">Rename</button><button class="btn btn-danger" id="folderDetailDeleteBtn" type="button">Delete</button></div><div class="folder-counts folder-page-counts"><span><b>${stats.notes}</b> Notes</span><span><b>${stats.files}</b> Files</span><span><b>${stats.cards}</b> Flashcards</span><span><b>${stats.quizzes}</b> Quizzes</span><span><b>${stats.plans}</b> Study Plans</span></div>`;$('#folderDetailRenameBtn').onclick=()=>openFolderModal(f.id);$('#folderDetailDeleteBtn').onclick=()=>openDeleteFolder(f.id);$$('[data-folder-detail-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.folderDetailFilter===activeFolderDetailFilter);b.onclick=()=>{activeFolderDetailFilter=b.dataset.folderDetailFilter;renderFolderDetail()}});const sections=[['notes','Notes',items.notes],['files','Uploaded Files',items.files],['flashcards','Flashcards',items.flashcards],['quizzes','Quizzes',items.quizzes],['plans','Study Plans',items.plans]].filter(([kind])=>activeFolderDetailFilter==='all'||activeFolderDetailFilter===kind);$('#folderDetailSections').innerHTML=sections.map(([kind,title,list])=>folderSectionHTML(kind,title,list)).join('');$$('[data-open-note]',$('#folderDetailSections')).forEach(card=>card.onclick=()=>openNoteDetail(card.dataset.openNote));$$('[data-folder-plan]',$('#folderDetailSections')).forEach(card=>card.onclick=()=>openPlanDetail(card.dataset.folderPlan))}
function bindFolderMenus(root=document){$$('[data-folder-menu]',root).forEach(b=>b.onclick=e=>{e.preventDefault();e.stopPropagation();const menu=$(`[data-folder-dropdown="${b.dataset.folderMenu}"]`);$$('.folder-menu').forEach(m=>{if(m!==menu)m.classList.remove('open')});menu?.classList.toggle('open')});$$('.folder-menu',root).forEach(menu=>menu.onclick=e=>e.stopPropagation());$$('[data-folder-card]',root).forEach(c=>{c.onclick=()=>openFolderDetail(c.dataset.folderCard);c.oncontextmenu=e=>{e.preventDefault();e.stopPropagation();$(`[data-folder-dropdown="${c.dataset.folderCard}"],[data-folder-dropdown="page-${c.dataset.folderCard}"]`)?.classList.add('open')}});$$('[data-folder-open-menu]',root).forEach(b=>b.onclick=e=>{e.stopPropagation();openFolderDetail(b.dataset.folderOpenMenu)});$$('[data-folder-edit]',root).forEach(b=>b.onclick=e=>{e.stopPropagation();openFolderModal(b.dataset.folderEdit)});$$('[data-folder-delete]',root).forEach(b=>b.onclick=e=>{e.stopPropagation();openDeleteFolder(b.dataset.folderDelete)});$$('[data-folder-color]',root).forEach(b=>b.onclick=e=>{e.stopPropagation();changeFolderColor(b.dataset.folderColor,b.dataset.color)});$$('[data-folder-move]',root).forEach(s=>{s.value=folderById(s.dataset.folderMove)?.parentId||'';s.onclick=e=>e.stopPropagation();s.onchange=e=>{e.stopPropagation();moveFolder(s.dataset.folderMove,s.value)}});$$('[data-folder-open]',root).forEach(b=>b.onclick=()=>openFolderDetail(b.dataset.folderOpen))}
function renderOrganization(){
  const u=user(),folderFilter=$('#dashboardFolderFilter').value,courseFilter=$('#dashboardCourseFilter').value;
  const userFolders=visibleFolders(),safeFolderFilter=userFolders.some(f=>f.id===folderFilter)?folderFilter:'';
  $('#dashboardFolderFilter').innerHTML='<option value="">All folders</option>'+userFolders.map(f=>`<option value="${f.id}" ${f.id===safeFolderFilter?'selected':''}>${escapeHTML(f.name)}</option>`).join('');
  const courses=selectedCourses();
  $('#dashboardCourseFilter').innerHTML='<option value="">All courses</option>'+courses.map(s=>`<option ${s===courseFilter?'selected':''}>${escapeHTML(s)}</option>`).join('');
  $('#courseCards').innerHTML=courses.length?courses.filter(s=>!courseFilter||s===courseFilter).map((s,i)=>{const notes=u.notes.filter(n=>n.subject===s&&(!safeFolderFilter||n.folderId===safeFolderFilter)).length,quizzes=u.quizzes.filter(q=>q.subject===s&&(!safeFolderFilter||q.folderId===safeFolderFilter)).length;return `<article class="course-card"><span class="q-icon ${['blue','lavender','mint','peach'][i%4]}">${escapeHTML(s[0])}</span><div><b>${escapeHTML(s)}</b><small>${notes} notes &middot; ${quizzes} quizzes</small></div><strong>${subjectScore(s)}%</strong></article>`}).join('')||'<div class="empty-mini">No courses match these filters.</div>':courseEmptyMessage();
  $('#dashboardFolders').innerHTML=userFolders.length?userFolders.map(f=>folderCardHTML(f,f.id)).join(''):'<div class="empty-mini">You don&rsquo;t have any folders yet. Create your first folder to organize your study materials.</div>';
  bindFolderMenus($('#dashboardFolders'));
}
function openFolder(id){openFolderDetail(id)}
$('#dashboardFolderFilter').onchange=renderOrganization;$('#dashboardCourseFilter').onchange=renderOrganization;
$('#folderSearchInput')?.addEventListener('input',renderFoldersPage);$('#folderSortSelect')?.addEventListener('change',renderFoldersPage);$('#backToFoldersBtn')?.addEventListener('click',()=>showView('folders'));$('#missingBackToFolders')?.addEventListener('click',()=>showView('folders'));
document.addEventListener('click',e=>{if(!e.target.closest('.folder-menu')&&!e.target.closest('[data-folder-menu]'))$$('.folder-menu').forEach(m=>m.classList.remove('open'))});
document.addEventListener('click',e=>{if(!e.target.closest('.note-card-menu')&&!e.target.closest('[data-note-menu]'))$$('.note-card-menu').forEach(m=>m.classList.remove('open'))});
function renderResourceMoves(){const u=user(),rows=[...u.flashcards.map((x,i)=>({kind:'flashcards',i,label:`Flashcard - ${x.subject}: ${x.question.slice(0,38)}`})),...u.quizzes.map((x,i)=>({kind:'quizzes',i,label:`Quiz - ${x.subject} (${x.score}%)`})),...u.plans.map((x,i)=>({kind:'plans',i,label:`Plan - ${x.title||x.course||x.subject||'Study plan'}`}))];$('#resourceMoveList').innerHTML=rows.length?rows.slice(-15).map(r=>{const item=u[r.kind][r.i];return `<div class="resource-move-row"><span class="pill blue-pill">${r.kind==='flashcards'?'CARD':r.kind==='quizzes'?'QUIZ':'PLAN'}</span><b>${escapeHTML(r.label)}</b><select data-move-kind="${r.kind}" data-move-index="${r.i}">${folderOptions()}</select></div>`}).join(''):'<div class="empty-mini">Generate cards, quizzes, or plans to organize them here.</div>';$$('[data-move-kind]').forEach(s=>{const item=u[s.dataset.moveKind][Number(s.dataset.moveIndex)];s.value=folderById(item.folderId)&&!folderById(item.folderId).protected?item.folderId:'';s.onchange=()=>{item.folderId=normalizeFolderId(s.value);touchFolder(item.folderId);saveDB();renderOrganization();toast('Study resource moved.')}})}

function privacyToggleHTML(key,label,description,checked){return '<label class="safety-toggle"><span><b>'+escapeHTML(label)+'</b><small>'+escapeHTML(description)+'</small></span><input type="checkbox" data-privacy-setting="'+escapeHTML(key)+'" '+(checked?'checked':'')+'></label>'}
function renderSafetyPrivacyPage(){const root=$('#safetyPrivacyContent');if(!root||!user())return;const settings=ensurePrivacySettings(),blocked=getBlockedStudents(),reports=safetyReportList();root.innerHTML='<div class="safety-grid"><article class="card safety-card"><span class="pill blue-pill">Privacy First</span><h3>Only study information is shown.</h3><p>StudySpark displays safe first names, courses, exams, topics, broad availability, and study preferences. It does not show email, phone numbers, addresses, passwords, or full account details.</p></article><article class="card safety-card"><span class="pill purple-pill">Student Safety</span><h3>Use school-safe study coordination.</h3><p>Study online when possible. For any in-person plan, use a public school-approved place and involve a parent, guardian, or trusted adult when needed.</p></article><article class="card safety-card"><span class="pill peach-pill">Prototype Notice</span><h3>Collaborative learning is local-only.</h3><p>Sample classmates are fictional. Requests, groups, blocks, reports, and privacy settings are saved only in this browser.</p></article></div><article class="card safety-settings-card"><div class="card-head"><div><h3>Privacy Settings</h3><p>Defaults are privacy-protective. Matching stays off until you choose to enable it.</p></div></div><div class="privacy-settings-list">'+privacyToggleHTML('privateAccount','Private account','Keep profile details private by default.',settings.privateAccount)+privacyToggleHTML('enableStudyMatching','Study Matching','Allow StudySpark to show possible fictional matches.',settings.enableStudyMatching)+privacyToggleHTML('allowRequests','Allow Requests','Allow sending prototype study requests.',settings.allowRequests)+privacyToggleHTML('showGeneralLocation','Show General Location','Only show a broad public area when needed for in-person studying.',settings.showGeneralLocation)+privacyToggleHTML('allowGroupInvitations','Allow Group Invitations','Allow accepted partners to be used for prototype study groups.',settings.allowGroupInvitations)+'</div><p class="safety-note">Production would require verified student accounts, parent or school consent where required, secure server-side rules, moderation queues, audit logs, reporting review, and data retention controls.</p></article><div class="safety-columns"><article class="card"><div class="card-head"><div><h3>Blocked Students</h3><p>Blocked students are hidden from matches, search, recommendations, and suggested groups. Existing groups are not changed.</p></div></div><div class="blocked-list">'+(blocked.length?blocked.map(row=>'<div><span><b>'+escapeHTML(row.name||row.studentId)+'</b><small>Blocked '+escapeHTML(formatRequestDate(row.blockedAt))+'</small></span><button class="btn btn-secondary" data-unblock-student="'+escapeHTML(row.studentId)+'" type="button">Unblock</button></div>').join(''):'<div class="empty-mini">No blocked students.</div>')+'</div></article><article class="card"><div class="card-head"><div><h3>Reports</h3><p>Reports are saved locally in this prototype.</p></div></div><div class="report-list">'+(reports.length?reports.slice(0,8).map(row=>'<div><b>'+escapeHTML(row.studentName||row.studentId)+'</b><small>'+escapeHTML(row.reason||'Safety concern')+' - '+escapeHTML(formatRequestDate(row.createdAt))+'</small></div>').join(''):'<div class="empty-mini">No reports saved.</div>')+'</div></article></div><article class="card safety-card"><h3>Data Retention</h3><p>Local collaborative-learning safety data stays in this browser until browser data is cleared or the app adds a clear/delete action. Guest safety data is stored separately from registered account safety data.</p><p>Parent or guardian note: students should follow their school and family rules before meeting with anyone in person.</p></article><article class="card demo-data-controls"><div class="card-head"><div><h3>Demo Data Controls</h3><p>Reset or seed fictional collaborative-learning data for testing. This does not delete account information, notes, flashcards, quizzes, files, or study plans.</p></div></div><div class="request-card-actions"><button class="btn btn-secondary" id="createDemoScenarioBtn" type="button">Create Demo Scenario</button><button class="btn btn-danger" id="resetDemoDataBtn" type="button">Reset Collaborative Demo Data</button></div></article>';bindSafetyPrivacyActions()}
function bindSafetyPrivacyActions(){const root=$('#safetyPrivacyContent');$$('[data-privacy-setting]',root).forEach(input=>input.onchange=()=>{const key=input.dataset.privacySetting,ok=safelyRunCollaborativeAction(()=>{const settings=ensurePrivacySettings();settings[key]=input.checked;if(key==='enableStudyMatching'){settings.matchingConsent=input.checked;const profile=studyMatchProfile();if(profile){profile.matchingEnabled=input.checked;profile.updatedAt=new Date().toISOString();user().studyMatchProfile=profile}}saveDB();return true},'Privacy settings could not be saved.');if(!ok){input.checked=!input.checked;return}forceMatchCountNotification=key==='enableStudyMatching'&&input.checked;renderStudyMatchPage();renderStudyPartnerResultsPage();showNotification({type:key==='enableStudyMatching'?(input.checked?'success':'information'):'success',message:key==='enableStudyMatching'?(input.checked?'Study Matching is now enabled.':'Study Matching is paused.'):'Privacy settings updated.'})});$$('[data-unblock-student]',root).forEach(btn=>btn.onclick=()=>unblockStudent(btn.dataset.unblockStudent));$('#resetDemoDataBtn')?.addEventListener('click',confirmResetCollaborativeDemoData);$('#createDemoScenarioBtn')?.addEventListener('click',createDemoScenario)}
function notificationDate(value){const date=new Date(value);return Number.isNaN(date.getTime())?'Date not available':date.toLocaleString(undefined,{month:'long',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit'})}
function notificationFilterValue(){return $('#notificationFilter')?.value||'All'}
function notificationMatchesFilter(notification,filter){if(notification.isArchived)return false;if(filter==='Unread')return !notification.isRead;if(filter==='All')return true;return notification.type===filter.toLowerCase()}
function notificationCardHTML(notification){const actions=(notification.actions||[]).length?notification.actions:[{id:'open',label:notification.actionLabel||notification.linkPage||notification.actionUrl||notification.sourceRecordId?'Open Related Page':'Open'}],buttons=actions.map(action=>`<button class="btn btn-secondary" data-notification-action="${escapeHTML(notification.id)}" data-notification-action-id="${escapeHTML(action.id)}" type="button">${escapeHTML(action.label)}</button>`).join('');return `<article class="notification-card notification-card-${escapeHTML(notification.type)} ${!notification.isRead?'unread':''}"><div><span class="notification-type-label notification-type-${escapeHTML(notification.type)}">${escapeHTML(NOTIFICATION_TITLES[notification.type]||notification.title)}</span><h3>${escapeHTML(notification.title)}</h3><p>${escapeHTML(notification.message)}</p><small>${escapeHTML(notificationDate(notification.createdAt))}${notification.source?` - ${escapeHTML(notification.source)}`:''}</small></div><div class="notification-card-actions">${buttons}${!notification.isRead?`<button class="btn btn-secondary" data-notification-read="${escapeHTML(notification.id)}" type="button">Mark as Read</button>`:''}<button class="btn btn-secondary" data-notification-archive="${escapeHTML(notification.id)}" type="button">Archive</button><button class="btn btn-danger" data-notification-delete="${escapeHTML(notification.id)}" type="button">Delete</button></div></article>`}
function renderNotificationsPage(){const root=$('#notificationsContent');if(!root)return;const filter=notificationFilterValue(),rows=getNotifications().filter(row=>notificationMatchesFilter(row,filter)).sort(sortNotificationsForDisplay),demoBanner=isWellBeingDemoActive()?`<section class="card demo-data-banner">${demoWellBeingBadgeHTML()}<h3>Demo Well-Being Data</h3><p>${escapeHTML('You are viewing fictional Well-Being data.')}</p><p>${escapeHTML(DEMO_WELL_BEING_NOTICE)}</p></section>`:'';root.innerHTML=demoBanner+'<div class="request-tools notification-tools card"><label>Filter<select id="notificationFilter"><option>All</option><option>Unread</option><option>Success</option><option>Information</option><option>Warning</option><option>Error</option></select></label><div class="notification-page-actions"><button class="btn btn-secondary" id="markAllNotificationsRead" type="button">Mark All as Read</button><button class="btn btn-secondary" id="clearReadNotificationsBtn" type="button">Clear Read</button><button class="btn btn-secondary" id="notificationSettingsShortcut" type="button">Notification Settings</button><button class="btn btn-danger" id="clearNotificationsBtn" type="button">Clear Notifications</button></div></div><div class="notification-history-list">'+(rows.length?rows.map(notificationCardHTML).join(''):'<div class="empty-state card"><h2>No notifications yet</h2><p>Study reminders and important updates from StudySpark will appear here.</p></div>')+'</div>';$('#notificationFilter').value=filter;$('#notificationFilter').onchange=renderNotificationsPage;$('#markAllNotificationsRead').onclick=markAllNotificationsRead;$('#clearReadNotificationsBtn').onclick=clearReadNotifications;$('#notificationSettingsShortcut').onclick=()=>showView('settings');$('#clearNotificationsBtn').onclick=clearNotifications;$$('[data-notification-read]',root).forEach(btn=>btn.onclick=()=>markNotificationRead(btn.dataset.notificationRead));$$('[data-notification-archive]',root).forEach(btn=>btn.onclick=()=>archiveNotification(btn.dataset.notificationArchive));$$('[data-notification-delete]',root).forEach(btn=>btn.onclick=()=>deleteNotification(btn.dataset.notificationDelete));$$('[data-notification-action]',root).forEach(btn=>btn.onclick=()=>{const notification=getNotifications().find(row=>row.id===btn.dataset.notificationAction);if(notification){markNotificationRead(notification.id);handleNotificationAction({notification,actionId:btn.dataset.notificationActionId||'open'})}});updateNotificationBadge()}
function ensureStudyTimeInstructions(){const grid=$('#instructionsView .instruction-grid');if(!grid)return;if(!$('#studyTimeMatchingInstructions'))grid.insertAdjacentHTML('beforeend','<article class="folder-instructions" id="studyTimeMatchingInstructions"><span>23</span><div><h3>How Study-Time Matching Works</h3><p>Students select broad times when they are usually available. Exact category matches receive the most points, while nearby time categories receive fewer points. Different schedules do not automatically remove a match. Students can change their preferred times at any time.</p></div></article>');if(!$('#studyPreferenceMatchingInstructions'))grid.insertAdjacentHTML('beforeend','<article class="folder-instructions" id="studyPreferenceMatchingInstructions"><span>24</span><div><h3>How Study Preference Matching Works</h3><p>StudySpark compares meeting format, group size, study methods, and session length. Shared preferences increase the match score, but they matter less than course, exam, and complementary strengths. Different preferences do not automatically remove a match, and students can update their preferences at any time.</p></div></article>');if(!$('#studyMatchScoreInstructions'))grid.insertAdjacentHTML('beforeend','<article class="folder-instructions" id="studyMatchScoreInstructions"><span>25</span><div><h3>How the Match Score Works</h3><p>Every eligible study partner receives a score out of 100. Course and exam information has the greatest effect on eligibility, complementary strengths strongly affect ranking, and study times plus preferences add smaller bonus points. Only partners above the selected minimum score are shown. A high score estimates study compatibility, but it does not guarantee that students will work well together.</p></div></article>');if(!$('#findStudyPartnersInstructions'))grid.insertAdjacentHTML('beforeend','<article class="folder-instructions" id="findStudyPartnersInstructions"><span>26</span><div><h3>How to Find Study Partners</h3><p>Create and enable your Study Match Profile, then open Find Study Partners. Review classmates sorted by match score, check who can help you and who you can help, select View Profile for full details, and use Send Study Request to save a prototype request. Filters can narrow results. Classmates are fictional in this prototype, and requests are stored only on this device. A future version would need secure accounts, a backend, moderation, consent, and messaging controls.</p></div></article>');if(!$('#matchExplanationInstructions'))grid.insertAdjacentHTML('beforeend','<article class="folder-instructions" id="matchExplanationInstructions"><span>27</span><div><h3>How Match Explanations Work</h3><p>StudySpark shows the reasons behind each suggested match. Explanations are based on course, exam, topics, study times, and preferences. Strong academic reasons appear before smaller preference reasons, and they update whenever profile information changes. Match explanations estimate compatibility and do not guarantee that two students will work well together.</p></div></article>');if(!$('#studyRequestInstructions'))grid.insertAdjacentHTML('beforeend','<article class="folder-instructions" id="studyRequestInstructions"><span>28</span><div><h3>How Study Requests Work</h3><p>Open Find Study Partners, select Send Study Request, optionally include a short message, and submit the request. The request is saved as Pending and can be viewed in My Study Requests. This prototype stores requests only on your device. A future version would support real requests, notifications, messaging, and responses.</p></div></article>');if(!$('#studyGroupInstructions'))grid.insertAdjacentHTML('beforeend','<article class="folder-instructions" id="studyGroupInstructions"><span>29</span><div><h3>How to Create a Study Group</h3><p>Send a study request to a matched partner, wait until the request is accepted, then open My Study Requests and select Create Study Group. Enter the group name, meeting details, topics, and shared goal, then add other accepted partners if needed. Groups can contain 2-6 members and are stored only on this device in prototype mode. Other fictional students are not actually notified. A real version would require secure accounts, a shared backend, invitations, notifications, moderation, reporting, privacy controls, and safety review.</p></div></article>');if(!$('#groupRecommendationInstructions'))grid.insertAdjacentHTML('beforeend','<article class="folder-instructions" id="groupRecommendationInstructions"><span>30</span><div><h3>How AI Group Recommendations Work</h3><p>Open a study group, add members, topics, and a shared goal, then select Generate Study Plan. StudySpark compares group topics with each member selected strengths and review needs, then suggests explanations, practice questions, mistake review, and a final quiz. Recommendations use front-end rules and JSON templates, not a real AI service. They do not guarantee academic improvement, so members should review, edit, save, or regenerate the plan based on their needs.</p></div></article>');if(!$('#safetyPrivacyInstructions'))grid.insertAdjacentHTML('beforeend','<article class="folder-instructions" id="safetyPrivacyInstructions"><span>31</span><div><h3>Safety and Privacy</h3><p>Open Safety & Privacy from the Collaborate section to review privacy defaults, turn matching on or off, unblock students, and view local prototype reports. Do not share phone numbers, addresses, private contact details, passwords, or sensitive personal information. Use online study sessions when possible, and follow school, parent, or guardian rules for any in-person plan.</p></div></article>');if(!$('#notificationInstructions'))grid.insertAdjacentHTML('beforeend','<article class="folder-instructions" id="notificationInstructions"><span>32</span><div><h3>How Notifications Work</h3><p>Success notifications confirm completed actions, information notifications provide updates, warning notifications identify conditions that need attention, and error notifications explain failed actions. Notifications may appear as toast messages, in the Notifications page, or as optional browser notifications when enabled. Camera, microphone and screen-sharing warnings remain visible while those features are active. In this front-end prototype, notifications are stored locally and do not synchronize across devices. The production version requires authenticated backend events, real-time synchronization and a secure push-notification service.</p></div></article>');if(!$('#demoDataInstructions'))grid.insertAdjacentHTML('beforeend','<article class="folder-instructions" id="demoDataInstructions"><span>33</span><div><h3>Using Demo Data</h3><p>StudySpark includes fictional student profiles for testing. Demo profiles use first names only, and their courses, topics, exam dates, locations, and preferences are made up. Demo profiles do not represent real students. Sending a request does not contact anyone, and study groups plus recommendations remain only in this browser. Demo data can be reset from Safety & Privacy.</p></div></article>');if(!$('#futureSuccessInstructions'))grid.insertAdjacentHTML('beforeend','<article class="folder-instructions" id="futureSuccessInstructions"><span>34</span><div><h3>Future Success Predictor</h3><p>Open Future Success Predictor, enter your course, exam name, exam date, current grade, and target grade, then add every chapter included on the exam. Estimate each chapter importance and save the Prediction Profile. Future prediction features will use this profile to estimate exam readiness and recommend where to focus your study time.</p></div></article>');if(!$('#performanceDataInstructions'))grid.insertAdjacentHTML('beforeend','<article class="folder-instructions" id="performanceDataInstructions"><span>35</span><div><h3>Collecting Performance Data</h3><p>Open a saved Prediction Profile, select Add Performance Entry, choose the activity type and exam chapter, then enter the score, study time, attempts, and activity date. Continue recording quizzes, practice work, assignments, and study tasks, then open Data Readiness to see whether enough information has been collected. The predictor needs several results recorded across different dates and chapters. One score is not enough to estimate future success responsibly.</p></div></article>')}
function renderDashboardNotificationSummary(){const anchor=$('#recentPlansList')?.closest('.card')||$('#dashboardActiveStudySession')||$('#dashboardView .dashboard-grid');if(!anchor)return;let card=$('#dashboardNotificationSummary');if(!card){anchor.insertAdjacentHTML('afterend','<article class="card dashboard-notification-summary" id="dashboardNotificationSummary"></article>');card=$('#dashboardNotificationSummary')}const rows=getNotifications().filter(row=>!row.isArchived).sort(sortNotificationsForDisplay),unread=rows.filter(row=>!row.isRead).length,recent=rows.slice(0,3);card.innerHTML=`<div class="card-head"><div><span class="pill blue-pill">${unread} UNREAD</span><h3>Notification Center</h3><p>Recent study reminders and important updates.</p></div><button class="btn btn-secondary" data-view="notifications" type="button">Open Center</button></div>${recent.length?`<div class="notification-summary-list">${recent.map(row=>`<button type="button" data-dashboard-notification="${escapeHTML(row.id)}"><b>${escapeHTML(row.title)}</b><span>${escapeHTML(row.message)}</span><small>${escapeHTML(notificationDate(row.createdAt))}</small></button>`).join('')}</div>`:'<div class="empty-mini">No recent notifications.</div>'}`;$$('[data-dashboard-notification]',card).forEach(btn=>btn.onclick=()=>{const row=getNotifications().find(item=>item.id===btn.dataset.dashboardNotification);if(row){markNotificationRead(row.id);handleNotificationAction({notification:row,actionId:'open'})}});$('[data-view="notifications"]',card)?.addEventListener('click',()=>showView('notifications'))}
function renderAll(){const u=user();if(!u)return;ensurePrivacySettings();ensureLearningProfile(u);continuousProfileRefresh({force:true});const first=repairEncoding(u.name).split(' ')[0],initial=isGuestMode()?'G':repairEncoding(u.name)[0].toUpperCase();$('#sideName').textContent=repairEncoding(u.name);$('#sideGrade').textContent=repairEncoding(u.grade);$('#sideAvatar').textContent=$('#topAvatar').textContent=initial;$('#logoutBtn').textContent=isGuestMode()?'Exit Guest Mode':'Log out';$('#logoutBtn').title=isGuestMode()?'Exit Guest Mode':'Log out';$('#welcomeName').textContent=first;$('#todayDate').textContent=new Date().toLocaleDateString(undefined,{weekday:'long',month:'short',day:'numeric'});$('#guestBanner')?.classList.toggle('hidden',!isGuestMode());$$('.registered-only-nav').forEach(btn=>btn.classList.toggle('hidden',isGuestMode()));if(!isGuestMode())ensureFriendStorage();ensurePredictionDashboardShell();ensureWellBeingHelpSafetyShell();ensureStudyTimeInstructions();ensureChapterWeightsInstructions();ensurePredictionConfidenceInstructions();ensurePredictionDashboardInstructions();ensureAutomaticPredictionUpdateInstructions();ensurePredictionSafetyInstructions();ensureStudyWellBeingInstructions();ensureBreakPatternInstructions();ensureStudyLoadLevelInstructions();ensureWellBeingDashboardInstructions();ensureStudyRecommendationInstructions();ensureActiveStudyTimerInstructions();ensureReminderSettingsInstructions();ensureDailyCheckInInstructions();ensureEvidenceExplanationInstructions();ensureSupportiveLanguageInstructions();ensureHelpSafetyInstructions();ensureNotificationManagerInstructions();ensurePdfNoteViewerInstructions();ensureStudentIdInstructions();ensureFriendsInstructions();ensureFriendRequestInstructions();ensureMyFriendsInstructions();ensureUserPresenceInstructions();setupPdfNoteViewer();refreshStudyTaskCompletionIfDueDatesChanged();refreshStudyTimePatternsIfChanged();refreshSessionLengthPatternsIfChanged();updateSubjectSelects();updateNotificationBadge();updateFriendRequestBadges();renderDashboard();renderNotes();renderUploadedFiles();renderQuizHistory();renderOrganization();renderFoldersPage();renderFolderDetail();renderResourceMoves();renderProgress();renderStudyWellBeingPage();renderWellBeingDashboardPage();renderWellBeingHelpSafetyPage();renderWellBeingReminderSettingsPage();renderLearningProfile();renderExamReadinessPage();renderFutureSuccessPage();renderPlannerPage();renderFriendsListPage();renderFriendProfilePage();renderFriendsPage();renderFriendRequestsPage();renderStudyMatchPage();renderStudyPartnerResultsPage();renderStudyPartnerProfilePage();renderStudyRequestsPage();renderStudyGroupsPage();renderStudyGroupDetailPage();renderSafetyPrivacyPage();renderNotificationsPage();if(!isGuestMode())deliverConnectionNotifications();setMinDate();initializeActiveStudyTimer();initializeNotificationManager();repairRenderedEncoding(document.body)}
function renderDashboard(){const u=user();if(!u)return;const p=u.progress,goal=Math.min(100,Math.round(p.minutes/45*100));$('#goalPercent').textContent=goal+'%';$('#goalBar').style.width=goal+'%';$('#goalRing').style.background=`conic-gradient(var(--blue) ${goal}%,#edf0f7 0)`;$('#timeStudied').textContent=`${Math.min(p.minutes,45)} of 45 min`;$('#streakCount').textContent=p.streak;const days=['M','T','W','T','F','S','S'],jsDay=new Date().getDay(),todayIndex=jsDay===0?6:jsDay-1;$('#weekRow').innerHTML=days.map((d,i)=>`<div class="day ${i<=todayIndex?'done':''} ${i===todayIndex?'today':''}"><i>${i<=todayIndex?'&#10003;':i+1}</i><span>${d}</span></div>`).join('');renderDashboardActiveStudySession();let dashboardCheckIn=$('#dashboardDailyCheckIn');if(!dashboardCheckIn){$('#dashboardActiveStudySession')?.insertAdjacentHTML('afterend','<div id="dashboardDailyCheckIn"></div>');dashboardCheckIn=$('#dashboardDailyCheckIn')}if(dashboardCheckIn){dashboardCheckIn.innerHTML=dailyStudyCheckInHTML({context:'dashboard'});bindDailyStudyCheckInActions(dashboardCheckIn)}const subjects=getSubjects();$('#subjectList').innerHTML=subjects.length?subjects.slice(0,4).map((s,i)=>`<div class="subject-row"><span class="subject-dot" style="background:${['#5867e8','#8b6ddd','#40a77e','#dd8b51'][i%4]}"></span><div><b>${escapeHTML(s)}</b><small>${u.notes.filter(n=>n.subject===s).length} saved note(s)</small></div><span>${subjectScore(s)}%</span></div>`).join(''):courseEmptyMessage();$('#activityList').innerHTML=u.activity.slice(0,4).map(a=>`<div class="activity-row"><span class="q-icon ${a.type==='quiz'?'mint':a.type==='card'?'lavender':'blue'}">${a.type[0].toUpperCase()}</span><div><b>${escapeHTML(a.text)}</b><small>${a.type==='quiz'?'Quiz result':a.type==='card'?'Flashcard review':'Study library'}</small></div><span class="activity-time">${a.time}</span></div>`).join('');renderRecentPlans();renderDashboardNotificationSummary();renderDashboardReviews();renderDashboardExamReadiness();renderStudyGroupDashboardCard()}
function renderDashboardActiveStudySession(){const root=$('#dashboardActiveStudySession');if(!root)return;const session=getActiveStudySession();root.classList.toggle('hidden',!session);if(!session)return;const metrics=activeStudyTimerMetrics(session,new Date());root.innerHTML=`<div class="card-head"><div><span class="pill blue-pill">ACTIVE STUDY SESSION</span><h3>${escapeHTML(session.subject||session.course||'Current Session')}</h3><p>${escapeHTML(session.topic||'General study')}</p></div><button class="text-button" data-active-session-open type="button">Open Timer</button></div><div class="profile-fact-grid">${profileFact('Current Session',session.subject||session.course||'Study')}${profileFact('Time Since Last Break',formatCompactTimer(metrics.sinceBreak))}${profileFact('Status',String(session.status||'active').replace(/-/g,' '))}${profileFact('Active Study Time',formatTimerDuration(metrics.activeStudy))}${profileFact("Today's Check-In",dailyCheckInStatusText())}</div><div class="study-session-actions"><button class="btn btn-primary" data-active-session-open type="button">Open</button><button class="btn btn-secondary" data-active-session-open type="button">Continue</button></div>`;$$('[data-active-session-open]',root).forEach(btn=>btn.onclick=openActiveStudySessionDetails)}
function renderRecentPlans(){const plans=(user()?.plans||[]).map(migratePlanDays).slice(0,3);$('#recentPlansList').innerHTML=plans.length?plans.map(plan=>{const p=plannerProgress(plan);return `<div class="recent-plan-row"><div><b>${escapeHTML(plan.title||'Study Plan')}</b><small>${escapeHTML(plan.course||'Course')} - Test ${escapeHTML(plan.testDate||'Not set')} - ${p.percent}% complete</small></div><button class="btn btn-secondary" data-recent-plan="${plan.id}" type="button">Open</button><button class="btn btn-primary" data-recent-plan="${plan.id}" type="button">Continue</button></div>`}).join(''):'<div class="empty-mini">Saved study plans will appear here.</div>';$$('[data-recent-plan]').forEach(btn=>btn.onclick=()=>openPlanDetail(btn.dataset.recentPlan))}
function getSubjects(){return [...new Set([...selectedCourses(),...user().notes.map(n=>n.subject)])].filter(Boolean)}
function subjectScore(subject){const notes=user().notes.filter(n=>n.subject===subject).length,q=user().quizzes.filter(x=>x.subject===subject);return Math.min(100,Math.round(notes*12+(q.length?q.reduce((a,b)=>a+b.score,0)/q.length*.5:10)))}

/* Notes and simulated analysis */
$('#newNoteBtn').addEventListener('click',()=>{$('#noteComposer').classList.remove('hidden');$('#noteTitle').focus()});$('#closeComposer').addEventListener('click',()=>$('#noteComposer').classList.add('hidden'));$('#noteText').addEventListener('input',e=>$('#wordCount').textContent=(e.target.value.trim().split(/\s+/).filter(Boolean).length)+' words');
function displayDate(){return new Date().toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'})}
function fileOwnerKey(){return isGuestMode()?GUEST_SESSION:(currentUser||'local')}
function fileExtension(name=''){return name.split('.').pop().toLowerCase()}
function fileTypeLabel(file){const ext=fileExtension(file.fileName||file.name||'');return (ext||file.fileType||file.type||'file').split('/').pop().toUpperCase()}
function formatFileSize(bytes=0){return bytes<1024?bytes+' B':bytes<1048576?(bytes/1024).toFixed(1)+' KB':(bytes/1048576).toFixed(1)+' MB'}
function validateStudyFile(file){if(!file)return 'Choose a file first.';const ext=fileExtension(file.name);if(!SUPPORTED_EXTENSIONS.includes(ext))return 'Unsupported file type.';if(file.size>MAX_FILE_SIZE)return 'File is too large. Maximum file size: 10 MB.';return ''}
function openFileDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open(FILE_DB_NAME,1);req.onupgradeneeded=()=>req.result.createObjectStore(FILE_STORE,{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function putStoredFile(record){const dbi=await openFileDB();return new Promise((resolve,reject)=>{const tx=dbi.transaction(FILE_STORE,'readwrite');tx.objectStore(FILE_STORE).put(record);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)})}
async function getStoredFile(id){const dbi=await openFileDB();return new Promise((resolve,reject)=>{const tx=dbi.transaction(FILE_STORE,'readonly'),req=tx.objectStore(FILE_STORE).get(id);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function getOwnedStoredFile(id){const stored=await getStoredFile(id);return stored?.owner===fileOwnerKey()?stored:null}
async function deleteStoredFile(id){const dbi=await openFileDB();return new Promise((resolve,reject)=>{const tx=dbi.transaction(FILE_STORE,'readwrite');tx.objectStore(FILE_STORE).delete(id);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)})}
async function extractPDFText(file){if(!window.pdfjsLib)throw new Error('PDF.js is not available in this browser build.');const data=await file.arrayBuffer();pdfjsLib.GlobalWorkerOptions.workerSrc=pdfjsLib.GlobalWorkerOptions.workerSrc||'https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/build/pdf.worker.min.js';const pdf=await pdfjsLib.getDocument({data}).promise,pages=[];for(let i=1;i<=pdf.numPages;i++){const page=await pdf.getPage(i),content=await page.getTextContent();pages.push(content.items.map(item=>item.str).join(' '))}return pages.join('\n')}
async function extractFileText(file){const ext=fileExtension(file.name);if(ext==='txt')return await file.text();if(ext==='pdf')return await extractPDFText(file);if(ext==='docx'){if(!window.mammoth)throw new Error('Mammoth.js is not available in this browser build.');const result=await mammoth.extractRawText({arrayBuffer:await file.arrayBuffer()});return result.value||''}if(ext==='pptx')throw new Error('PowerPoint text extraction is not available in this browser-only build yet.');if(['png','jpg','jpeg'].includes(ext))return '';return ''}
async function readStudyFile(file){try{const text=(await extractFileText(file)).trim();const ext=fileExtension(file.name);if(!text&&ext==='txt')return {text:'',message:'No readable text was found.'};if(!text&&['png','jpg','jpeg'].includes(ext))return {text:'',message:'Image saved. OCR or AI image reading can be connected later.'};if(!text&&['pdf','docx','pptx'].includes(ext))return {text:'',message:'No readable text was found.'};return {text,message:text?'Readable text was extracted.':'File saved.'}}catch(error){return {text:'',message:error.message||'File could not be read.'}}}
function fileById(id){return (user().files||[]).find(f=>f.id===id)}
function fileCard(file){return `<article class="card file-card"><span class="note-subject">${escapeHTML((file.course||'COURSE').toUpperCase())}</span><span class="note-folder-name">${escapeHTML(displayFolderName(file.folderId))}</span><h3>${escapeHTML(file.title||file.fileName)}</h3><p>${escapeHTML(file.fileName)}<br>${escapeHTML(fileTypeLabel(file))} - ${formatFileSize(file.fileSize)}<br>Uploaded ${escapeHTML(file.uploadedAt||'Unknown')}</p><div class="file-actions"><button type="button" data-file-open="${file.id}">Open</button><button type="button" data-file-rename="${file.id}">Rename</button><button type="button" data-file-move="${file.id}">Move</button><button type="button" data-file-delete="${file.id}">Delete</button><button type="button" data-file-analyze="${file.id}">Analyze</button><button type="button" data-file-cards="${file.id}">Generate Flashcards</button><button type="button" data-file-quiz="${file.id}">Generate Quiz</button></div></article>`}
function noteFromForm(){const title=$('#noteTitle').value.trim(),text=$('#noteText').value.trim(),subject=$('#noteSubject').value,folderId=normalizeFolderId($('#noteFolder').value);if(!subject)return toast('Choose a course before saving notes.'),null;if(!title||!text){toast('Add a title and some notes first.');return null}touchFolder(folderId);const created=displayDate();return {id:'n'+Date.now(),subject,folderId,title,text,created,lastEdited:created}}
function saveNote(analyze=false){const note=noteFromForm();if(!note)return;user().notes.unshift(note);recordActivity('note',`Saved ${note.subject} notes`);if(analyze)recordBehaviorEvent('explanation_viewed',{course:note.subject,topic:note.title,metadata:{noteId:note.id}});clearNoteForm();renderAll();if(analyze)showAnalysis(note);toast(analyze?'Notes saved and analyzed.':'Notes saved.')}
$('#saveNoteBtn').addEventListener('click',()=>saveNote(false));$('#analyzeNoteBtn').addEventListener('click',()=>saveNote(true));
function clearNoteForm(){$('#noteTitle').value='';$('#noteText').value='';$('#wordCount').textContent='0 words'}
const stopWords=new Set('the a an and or but is are was were be been being in on at to for from of with by as it this that these those they their them we you your can has have had into through also what which when where how'.split(' '));
function keywords(text){const counts={};(text.toLowerCase().match(/[a-z]{4,}/g)||[]).forEach(w=>{if(!stopWords.has(w))counts[w]=(counts[w]||0)+1});return Object.entries(counts).sort((a,b)=>b[1]-a[1]).slice(0,7).map(x=>x[0])}
function summarize(text){const sentences=text.match(/[^.!?]+[.!?]+|[^.!?]+$/g)||[text];return sentences.slice(0,2).join(' ').trim()}
function showAnalysis(note){const keys=keywords(note.text);$('#analysisResult').innerHTML=`<span class="pill purple-pill">NOTES ANALYSIS</span><h3>${escapeHTML(note.title)}</h3><p><b>Quick summary:</b> ${escapeHTML(summarize(note.text))}</p><div class="keyword-list">${keys.map(k=>`<span class="keyword">${escapeHTML(k)}</span>`).join('')}</div>`;$('#analysisResult').classList.remove('hidden')}
function noteById(id){return user().notes.find(n=>n.id===id)}
function backToNotes(){activeNoteId=null;showView('notes');renderNotes()}
function fillNoteDetail(note){$('#editNoteId').value=note.id;$('#noteDetailTitle').textContent=note.title;$('#noteDetailMeta').textContent=`${note.subject} - ${displayFolderName(note.folderId)} - Created ${note.created||'Unknown'} - Last edited ${note.lastEdited||note.created||'Never'}`;$('#editNoteTitle').value=note.title;$('#editNoteSubject').innerHTML=courseOptionsHTML(getSubjects());$('#editNoteSubject').value=note.subject;$('#editNoteFolder').innerHTML=folderOptions();$('#editNoteFolder').value=folderById(note.folderId)&&!folderById(note.folderId).protected?note.folderId:'';$('#editNoteText').value=note.text}
function renderNoteDetail(){const note=noteById(activeNoteId);const missing=!note;$('#noteDetailMissing').classList.toggle('hidden',!missing);$('#noteEditorForm').classList.toggle('hidden',missing);if(missing)return;fillNoteDetail(note)}
function openNoteDetail(id,focusFolder=false){activeNoteId=id;const note=noteById(id);if(note){const previous=ensureLearningProfile()?.behavior?.history?.find(e=>e.type==='notes_opened'&&e.metadata?.noteId===id);recordBehaviorEvent(previous?'notes_reread':'notes_opened',{course:note.subject,topic:note.title,metadata:{noteId:id}});startStudySession(note.subject,note.title)}showView('noteDetail');renderNoteDetail();if(focusFolder&&note)$('#editNoteFolder').focus()}
function saveNoteChanges(){const note=noteById($('#editNoteId').value);if(!note)return renderNoteDetail();const title=$('#editNoteTitle').value.trim(),text=$('#editNoteText').value.trim(),subject=$('#editNoteSubject').value,folderId=normalizeFolderId($('#editNoteFolder').value);if(!title||!text)return toast('Add a title and note text.');note.title=title;note.text=text;note.subject=subject;note.folderId=folderId;note.lastEdited=displayDate();touchFolder(folderId);recordStudyMethodSession({course:subject,topic:title,method:'Reading Notes',durationMinutes:10,completed:true});recordActivity('note',`Updated ${note.subject} note`);renderAll();activeNoteId=note.id;renderNoteDetail();toast('Note updated.')}
async function deleteNote(id=activeNoteId){const note=noteById(id);if(!note)return;const ok=await confirmDialog({title:'Delete Note',message:'Are you sure you want to delete this note?',okText:'Delete Note',cancelText:'Cancel',danger:true});if(!ok)return;user().notes=user().notes.filter(n=>n.id!==note.id);saveDB();activeNoteId=null;renderAll();showView('notes');toast('Note deleted.')}
function renderNotes(){const u=user();if(!u)return;const filter=$('#noteFilter').value,folderFilter=$('#noteFolderFilter').value,userFolders=visibleFolders(),safeFolderFilter=userFolders.some(f=>f.id===folderFilter)?folderFilter:'';let notes=u.notes.filter(n=>(!filter||filter==='All subjects'||n.subject===filter)&&(!safeFolderFilter||n.folderId===safeFolderFilter));$('#noteCountLabel').textContent=`${notes.length} of ${u.notes.length} notes`;$('#notesGrid').innerHTML=notes.map(n=>`<article class="card note-card" data-open-note="${n.id}" tabindex="0" role="button" aria-label="Open ${escapeHTML(n.title)}"><button class="note-menu-button" data-note-menu="${n.id}" type="button" aria-label="Note actions">...</button><div class="note-card-menu" data-note-menu-panel="${n.id}"><button type="button" data-open-note-action="${n.id}">Open</button><button type="button" data-note-move="${n.id}">Move</button><button type="button" data-delete="${n.id}">Delete</button></div><span class="note-subject">${escapeHTML(n.subject.toUpperCase())}</span><span class="note-folder-name">${escapeHTML(displayFolderName(n.folderId))}</span><h3>${escapeHTML(n.title)}</h3><p>${escapeHTML(n.text)}</p><div class="note-card-dates"><span>Created ${escapeHTML(n.created||'Unknown')}</span><span>Edited ${escapeHTML(n.lastEdited||n.created||'Never')}</span></div></article>`).join('')||'<div class="empty-state card"><h2>No notes here yet</h2><p>Add your first set of class notes above.</p></div>';const subjects=getSubjects();$('#noteFilter').innerHTML='<option>All subjects</option>'+subjects.map(s=>`<option ${s===filter?'selected':''}>${escapeHTML(s)}</option>`).join('');$('#noteFolderFilter').innerHTML='<option value="">All folders</option>'+userFolders.map(f=>`<option value="${f.id}" ${f.id===safeFolderFilter?'selected':''}>${escapeHTML(f.name)}</option>`).join('');$$('[data-open-note]').forEach(card=>{card.onclick=e=>{if(e.target.closest('button,.note-card-menu'))return;openNoteDetail(card.dataset.openNote)};card.onkeydown=e=>{if(e.key==='Enter'||e.key===' ')openNoteDetail(card.dataset.openNote)}});$$('[data-note-menu]').forEach(btn=>btn.onclick=e=>{e.stopPropagation();const panel=$(`[data-note-menu-panel="${btn.dataset.noteMenu}"]`);$$('.note-card-menu').forEach(p=>{if(p!==panel)p.classList.remove('open')});panel?.classList.toggle('open')});$$('.note-card-menu').forEach(menu=>menu.onclick=e=>e.stopPropagation());$$('[data-open-note-action]').forEach(b=>b.onclick=e=>{e.stopPropagation();openNoteDetail(b.dataset.openNoteAction)});$$('[data-note-move]').forEach(b=>b.onclick=e=>{e.stopPropagation();openNoteDetail(b.dataset.noteMove,true)});$$('[data-delete]').forEach(b=>b.onclick=e=>{e.stopPropagation();deleteNote(b.dataset.delete)})}
function switchNotesTab(tab){$$('[data-notes-tab]').forEach(b=>b.classList.toggle('active',b.dataset.notesTab===tab));$$('[data-notes-panel]').forEach(p=>p.classList.toggle('hidden',p.dataset.notesPanel!==tab));if(tab==='files')renderUploadedFiles()}
$$('[data-notes-tab]').forEach(b=>b.addEventListener('click',()=>switchNotesTab(b.dataset.notesTab)));
function setUploadFile(kind,file){if(kind==='note'){noteUploadFile=file;$('#noteSelectedFile').textContent=file?`${file.name} - ${formatFileSize(file.size)}`:'No file selected'}else{quizUploadFile=file;$('#quizSelectedFile').textContent=file?`${file.name} - ${formatFileSize(file.size)}`:'No file selected'}}
function setupDropZone(zoneId,inputId,kind){const zone=$(`#${zoneId}`),input=$(`#${inputId}`);zone?.addEventListener('click',e=>{if(e.target.tagName!=='BUTTON')return});input?.addEventListener('change',()=>setUploadFile(kind,input.files[0]||null));zone?.addEventListener('dragover',e=>{e.preventDefault();zone.classList.add('dragging')});zone?.addEventListener('dragleave',()=>zone.classList.remove('dragging'));zone?.addEventListener('drop',e=>{e.preventDefault();zone.classList.remove('dragging');setUploadFile(kind,e.dataTransfer.files[0]||null)})}
let noteUploadFile=null,quizUploadFile=null;
setupDropZone('noteDropZone','noteFileInput','note');setupDropZone('quizDropZone','quizFileInput','quiz');
$('#noteBrowseBtn')?.addEventListener('click',()=>$('#noteFileInput').click());$('#quizBrowseBtn')?.addEventListener('click',()=>$('#quizFileInput').click());
async function saveStudyFile(file,{course,folderId,title,sourceType}){const error=validateStudyFile(file);if(error)return toast(error),null;if(!course)return toast('Please choose a course.'),null;if(!folderId)return toast('Please choose a folder.'),null;const read=await readStudyFile(file),id='file'+Date.now(),meta={id,fileName:file.name,fileType:file.type||fileExtension(file.name),fileSize:file.size,course,subject:course,folderId,uploadedAt:displayDate(),sourceType,title:title||file.name,readStatus:read.message};await putStoredFile({id,owner:fileOwnerKey(),blob:file,text:read.text});user().files.unshift(meta);touchFolder(folderId);recordActivity('note',`Uploaded ${file.name}`);recordBehaviorEvent('file_or_diagram_viewed',{course,topic:title||file.name,metadata:{fileType:meta.fileType,sourceType}});saveDB();renderAll();toast(read.message||'File uploaded.');return meta}
$('#noteUploadForm')?.addEventListener('submit',async e=>{e.preventDefault();const meta=await saveStudyFile(noteUploadFile,{course:$('#uploadSubject').value,folderId:normalizeFolderId($('#uploadFolder').value),title:$('#uploadTitle').value.trim(),sourceType:'notes'});if(meta){e.target.reset();setUploadFile('note',null);switchNotesTab('files')}});
function renderUploadedFiles(){const files=user().files||[];$('#fileCountLabel').textContent=`${files.length} uploaded file${files.length===1?'':'s'}`;$('#uploadedFilesGrid').innerHTML=files.length?files.map(fileCard).join(''):'<div class="empty-state card"><h2>No uploaded files yet</h2><p>Use Upload File to save PDFs, documents, slides, text files, or images.</p></div>';bindFileActions()}
let currentPdfObjectUrl=null,currentPdfViewerFile=null,currentPdfViewerFocus=null,currentPdfViewerState=null,currentPdfViewerZoom=100,currentPdfViewerPage=1,currentPdfViewerTotalPages=1,pdfViewerBound=false;
function isValidPdfNote(note){const type=String(note?.fileType||'').toLowerCase(),name=String(note?.fileName||'').toLowerCase();return type==='application/pdf'&&name.endsWith('.pdf')}
function base64ToBlob(base64,mimeType='application/pdf'){const clean=String(base64||'').replace(/^data:[^;]+;base64,/,'');const binary=atob(clean),bytes=new Uint8Array(binary.length);for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);return new Blob([bytes],{type:mimeType})}
async function pdfBlobFromNote(note){if(!note)return null;if(note.blob instanceof Blob)return note.blob;if(typeof File!=='undefined'&&note.file instanceof File)return note.file;if(note.file instanceof Blob)return note.file;if(note.base64)return base64ToBlob(note.base64,'application/pdf');if(note.fileData)return base64ToBlob(note.fileData,'application/pdf');const stored=await getOwnedStoredFile(note.indexedDbFileId||note.fileId||note.id);return stored?.blob instanceof Blob?stored.blob:stored?.file instanceof Blob?stored.file:null}
async function createPdfObjectUrl(note){const blob=await pdfBlobFromNote(note);if(!blob)throw new Error('The PDF could not be opened.');return URL.createObjectURL(blob)}
function revokeCurrentPdfObjectUrl(){if(currentPdfObjectUrl){URL.revokeObjectURL(currentPdfObjectUrl);currentPdfObjectUrl=null}}
function captureNotesPageState(){return {scrollPosition:window.scrollY||0,selectedFolderId:$('#noteFolderFilter')?.value||'',subjectFilter:$('#noteFilter')?.value||'',searchQuery:$('#notesSearch')?.value||'',sortOption:$('#notesSort')?.value||'',activeTab:($$('[data-notes-tab]').find(b=>b.classList.contains('active'))?.dataset.notesTab)||'files'}}
function restoreNotesPageState(state){if(!state)return;switchNotesTab(state.activeTab||'files');if($('#noteFolderFilter'))$('#noteFolderFilter').value=state.selectedFolderId||'';if($('#noteFilter'))$('#noteFilter').value=state.subjectFilter||'All subjects';if($('#notesSearch'))$('#notesSearch').value=state.searchQuery||'';if($('#notesSort'))$('#notesSort').value=state.sortOption||'';renderNotes();requestAnimationFrame(()=>window.scrollTo(0,Number(state.scrollPosition)||0))}
function setPdfViewerLoading(message='Loading PDF...'){const status=$('#pdf-viewer-status'),error=$('#pdf-viewer-error');if(status){status.textContent=message;status.classList.remove('hidden')}error?.classList.add('hidden');$('#pdf-note-frame')?.classList.remove('hidden');$('#pdf-note-object')?.classList.add('hidden')}
function setPdfViewerError(){const status=$('#pdf-viewer-status'),error=$('#pdf-viewer-error');if(status)status.classList.add('hidden');error?.classList.remove('hidden');$('#pdf-note-frame')?.classList.add('hidden');$('#pdf-note-object')?.classList.add('hidden')}
function updatePdfPageStatus(){const label=$('#pdf-page-status');if(label)label.textContent=`Page ${currentPdfViewerPage} of ${currentPdfViewerTotalPages}`;const prev=$('#pdf-prev-page'),next=$('#pdf-next-page');if(prev)prev.disabled=currentPdfViewerPage<=1;if(next)next.disabled=currentPdfViewerPage>=currentPdfViewerTotalPages}
function setPdfFrameSrc(){const frame=$('#pdf-note-frame'),object=$('#pdf-note-object');if(!frame||!object||!currentPdfObjectUrl)return;const src=`${currentPdfObjectUrl}#toolbar=1&navpanes=0&page=${currentPdfViewerPage}&zoom=${currentPdfViewerZoom}`;frame.src=src;object.data=src;updatePdfPageStatus()}
async function countPdfPages(note){try{if(!window.pdfjsLib)return 1;const blob=await pdfBlobFromNote(note);if(!blob?.arrayBuffer)return 1;pdfjsLib.GlobalWorkerOptions.workerSrc=pdfjsLib.GlobalWorkerOptions.workerSrc||'https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/build/pdf.worker.min.js';const pdf=await pdfjsLib.getDocument({data:await blob.arrayBuffer()}).promise;return pdf.numPages||1}catch{return 1}}
function focusablePdfControls(){const viewer=$('#pdf-note-viewer');return $$('button,[href],iframe,object',viewer).filter(el=>!el.disabled&&!el.classList.contains('hidden'))}
function trapPdfViewerFocus(e){const controls=focusablePdfControls();if(!controls.length)return;const first=controls[0],last=controls[controls.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}
function handlePdfViewerKeydown(e){const viewer=$('#pdf-note-viewer');if(!viewer||viewer.classList.contains('hidden'))return;if(e.key==='Escape')closePdfNoteViewer();if(e.key==='Tab')trapPdfViewerFocus(e)}
function showPdfFallbackObject(){const frame=$('#pdf-note-frame'),object=$('#pdf-note-object'),status=$('#pdf-viewer-status');if(frame)frame.classList.add('hidden');if(object)object.classList.remove('hidden');if(status)status.textContent='Showing PDF with the browser fallback viewer.'}
function downloadPdfNote(note=currentPdfViewerFile,pdfUrl=currentPdfObjectUrl){if(!note||!pdfUrl)return toast('The PDF could not be opened.');const link=document.createElement('a');link.href=pdfUrl;link.download=note.fileName||'StudySpark-note.pdf';document.body.appendChild(link);link.click();link.remove();toast('PDF download started.')}
async function openPdfViewerFullscreen(){const viewer=$('#pdf-note-viewer .pdf-viewer-shell');try{if(viewer?.requestFullscreen)await viewer.requestFullscreen()}catch{toast('Full screen could not be opened.')}}
async function openPdfNoteViewer(note,trigger=null){if(!isValidPdfNote(note))return toast('The PDF could not be opened.');const viewer=$('#pdf-note-viewer');if(!viewer)return toast('The PDF could not be opened.');currentPdfViewerState=currentPdfViewerState||captureNotesPageState();currentPdfViewerFocus=trigger||document.activeElement;currentPdfViewerFile=note;currentPdfViewerZoom=100;currentPdfViewerPage=1;currentPdfViewerTotalPages=1;showView('notes',{force:true});switchNotesTab('files');setPdfViewerLoading();$('#pdf-viewer-title').textContent=note.title||note.fileName||'PDF Note Viewer';$('#pdf-viewer-filename').textContent=note.fileName||'Uploaded PDF';$('#pdf-viewer-upload-date').textContent=`Uploaded ${note.uploadedAt||'Unknown date'}`;viewer.classList.remove('hidden');document.body.classList.add('pdf-viewer-open');try{revokeCurrentPdfObjectUrl();currentPdfObjectUrl=await createPdfObjectUrl(note);currentPdfViewerTotalPages=await countPdfPages(note);setPdfFrameSrc();sessionStorage.setItem('activePdfNoteId',note.id);if(location.hash!==`#notes/pdf/${encodeURIComponent(note.id)}`)history.pushState({pdfViewer:true,noteId:note.id},'',`#notes/pdf/${encodeURIComponent(note.id)}`);recordBehaviorEvent('file_or_diagram_viewed',{course:note.course||'',topic:note.title||note.fileName||'',metadata:{fileId:note.id,fileType:'pdf',viewer:'in-app'}});setTimeout(()=>{$('#pdf-viewer-status')?.classList.add('hidden')},800);$('#close-pdf-viewer')?.focus()}catch{setPdfViewerError();toast('The PDF could not be opened.')}}
function closePdfNoteViewer({fromPopState=false,silent=false}={}){const viewer=$('#pdf-note-viewer');if(!viewer)return;const wasOpen=!viewer.classList.contains('hidden');viewer.classList.add('hidden');document.body.classList.remove('pdf-viewer-open');const frame=$('#pdf-note-frame'),object=$('#pdf-note-object');if(frame)frame.removeAttribute('src');if(object)object.removeAttribute('data');revokeCurrentPdfObjectUrl();currentPdfViewerFile=null;sessionStorage.removeItem('activePdfNoteId');if(wasOpen&&!fromPopState&&location.hash.startsWith('#notes/pdf/'))history.replaceState(history.state,'','#notes');if(wasOpen&&!silent){restoreNotesPageState(currentPdfViewerState);currentPdfViewerFocus?.focus?.()}currentPdfViewerState=null;currentPdfViewerFocus=null}
async function retryPdfNoteViewer(){const note=currentPdfViewerFile;if(note)await openPdfNoteViewer(note,currentPdfViewerFocus)}
function setupPdfNoteViewer(){if(pdfViewerBound)return;pdfViewerBound=true;$('#close-pdf-viewer')?.addEventListener('click',()=>closePdfNoteViewer());$('#close-pdf-viewer-error')?.addEventListener('click',()=>closePdfNoteViewer());$('#download-pdf-note')?.addEventListener('click',()=>downloadPdfNote());$('#download-pdf-note-error')?.addEventListener('click',()=>downloadPdfNote());$('#fullscreen-pdf-note')?.addEventListener('click',openPdfViewerFullscreen);$('#retry-pdf-note')?.addEventListener('click',retryPdfNoteViewer);$('#pdf-prev-page')?.addEventListener('click',()=>{if(currentPdfViewerPage>1){currentPdfViewerPage--;setPdfFrameSrc()}});$('#pdf-next-page')?.addEventListener('click',()=>{if(currentPdfViewerPage<currentPdfViewerTotalPages){currentPdfViewerPage++;setPdfFrameSrc()}});$('#pdf-zoom-out')?.addEventListener('click',()=>{currentPdfViewerZoom=Math.max(50,currentPdfViewerZoom-25);setPdfFrameSrc()});$('#pdf-zoom-in')?.addEventListener('click',()=>{currentPdfViewerZoom=Math.min(200,currentPdfViewerZoom+25);setPdfFrameSrc()});$('#pdf-zoom-reset')?.addEventListener('click',()=>{currentPdfViewerZoom=100;setPdfFrameSrc()});$('#pdf-note-frame')?.addEventListener('load',()=>$('#pdf-viewer-status')?.classList.add('hidden'));$('#pdf-note-frame')?.addEventListener('error',showPdfFallbackObject);$('#pdf-note-viewer')?.addEventListener('click',e=>{if(e.target===$('#pdf-note-viewer'))closePdfNoteViewer()});document.addEventListener('keydown',handlePdfViewerKeydown);window.addEventListener('popstate',()=>{const viewer=$('#pdf-note-viewer');if(viewer&&!viewer.classList.contains('hidden'))closePdfNoteViewer({fromPopState:true})})}
function restorePdfViewerFromRoute(){const hash=location.hash||'',id=hash.startsWith('#notes/pdf/')?decodeURIComponent(hash.replace('#notes/pdf/','')):sessionStorage.getItem('activePdfNoteId');if(!id||!user())return;const note=fileById(id);if(note&&isValidPdfNote(note))openPdfNoteViewer(note)}
async function openUploadedFile(id,trigger=null){const file=fileById(id);if(!file)return toast('File could not be opened.');if(isValidPdfNote(file))return openPdfNoteViewer(file,trigger);const stored=await getOwnedStoredFile(id);if(!stored?.blob)return toast('File could not be opened.');recordBehaviorEvent((file?.fileType||file?.fileName||'').toLowerCase().match(/png|jpe?g/)?.length?'diagram_viewed':'file_or_diagram_viewed',{course:file?.course||'',topic:file?.title||file?.fileName||'',metadata:{fileId:id}});const url=URL.createObjectURL(stored.blob),link=document.createElement('a');link.href=url;link.download=file.fileName||'studyspark-file';document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('File download started.')}
async function renameUploadedFile(id){const file=fileById(id);if(!file)return;const next=prompt('Rename uploaded file',file.title||file.fileName);if(!next?.trim())return;file.title=next.trim();saveDB();renderUploadedFiles();renderOrganization();toast('File renamed.')}
async function moveUploadedFile(id){const file=fileById(id);if(!file)return;const names=visibleFolders().map(f=>f.name).join(', '),next=prompt(`Move to folder (${names})`,displayFolderName(file.folderId));if(!next)return;const folder=visibleFolders().find(f=>f.name.toLowerCase()===next.trim().toLowerCase());if(!folder)return toast('Please choose a folder.');file.folderId=folder.id;touchFolder(folder.id);saveDB();renderUploadedFiles();renderOrganization();toast('File moved.')}
async function deleteUploadedFile(id){const file=fileById(id);if(!file)return;const ok=await confirmDialog({title:'Delete File',message:'Delete this uploaded file from this browser?',okText:'Delete File',cancelText:'Cancel',danger:true});if(!ok)return;user().files=user().files.filter(f=>f.id!==id);await deleteStoredFile(id);saveDB();renderAll();toast('File deleted.')}
async function fileTextOrMessage(id){const file=fileById(id),stored=await getOwnedStoredFile(id),text=(stored?.text||'').trim();if(text)return {file,text};toast(file?.readStatus||'No readable text was found.');return {file,text:''}}
async function analyzeUploadedFile(id){const {file,text}=await fileTextOrMessage(id);if(!file)return;if(!text)return;recordBehaviorEvent('explanation_viewed',{course:file.course,topic:file.title||file.fileName,metadata:{fileId:id}});showAnalysis({title:file.title||file.fileName,text});switchNotesTab('saved')}
async function generateCardsFromFile(id){const {file,text}=await fileTextOrMessage(id);if(!file||!text)return;generateCardsFromNote({id,fileName:file.fileName,title:file.title||file.fileName,subject:file.course,folderId:file.folderId,text})}
async function generateQuizFromFileId(id){const {file,text}=await fileTextOrMessage(id);if(!file||!text)return;renderQuiz(buildQuizFromText(text,file.course,5,'Multiple Choice','Medium'),file.course,file.folderId);showView('quiz');toast('Quiz generated from uploaded file.')}
function bindFileActions(){$$('[data-file-open]').forEach(b=>b.onclick=()=>openUploadedFile(b.dataset.fileOpen,b));$$('[data-file-rename]').forEach(b=>b.onclick=()=>renameUploadedFile(b.dataset.fileRename));$$('[data-file-move]').forEach(b=>b.onclick=()=>moveUploadedFile(b.dataset.fileMove));$$('[data-file-delete]').forEach(b=>b.onclick=()=>deleteUploadedFile(b.dataset.fileDelete));$$('[data-file-analyze]').forEach(b=>b.onclick=()=>analyzeUploadedFile(b.dataset.fileAnalyze));$$('[data-file-cards]').forEach(b=>b.onclick=()=>generateCardsFromFile(b.dataset.fileCards));$$('[data-file-quiz]').forEach(b=>b.onclick=()=>generateQuizFromFileId(b.dataset.fileQuiz))}
$('#noteFilter').addEventListener('change',renderNotes);$('#noteFolderFilter').addEventListener('change',renderNotes);
$('#backToNotesBtn').addEventListener('click',backToNotes);$('#missingBackToNotes').addEventListener('click',backToNotes);$('#noteEditorForm').addEventListener('submit',e=>{e.preventDefault();saveNoteChanges()});$('#deleteNoteBtn').addEventListener('click',()=>deleteNote());$('#analyzeNoteAgainBtn').addEventListener('click',()=>{const note=noteById(activeNoteId);if(note){recordBehaviorEvent('explanation_viewed',{course:note.subject,topic:note.title,metadata:{noteId:note.id}});showAnalysis(note);showView('notes');toast('Note analyzed again.')}});function statementsFromText(text){return (text.match(/[^.!?]+[.!?]+|[^.!?]+$/g)||[text]).map(s=>s.trim()).filter(s=>s.split(' ').length>4)}
function generateCardsFromNote(note){const folderId=normalizeFolderId(note.folderId),sentences=statementsFromText(note.text),keys=keywords(note.text);currentCards=sentences.slice(0,5).map((s,i)=>{const key=keys.find(k=>s.toLowerCase().includes(k))||keys[i]||'this concept';return {id:'c'+Date.now()+i,subject:note.subject,folderId,question:`What should you remember about ${key}?`,answer:s,topic:key}});while(currentCards.length<5)currentCards.push({id:'c'+Date.now()+currentCards.length,subject:note.subject,folderId,question:`What is a key idea from ${note.title}?`,answer:summarize(note.text),topic:keys[currentCards.length]||note.subject});user().flashcards.push(...currentCards);touchFolder(folderId);cardIndex=0;currentCardKnown=0;recordBehaviorEvent('flashcards_used',{course:note.subject,topic:note.title,result:{cards:currentCards.length}});startStudySession(note.subject,note.title);saveDB();activeNoteId=null;showView('flashcards');$('#flashEmpty').classList.add('hidden');$('#flashStudy').classList.remove('hidden');showCard();recordActivity('card',`Generated 5 flashcards from ${note.title}`)}
