function mockCoachReply(q){const lower=q.toLowerCase(),course=selectedCourses().find(c=>lower.includes(c.toLowerCase()))||'',topicRows=Object.values(ensureLearningProfile()?.topicPerformance||{}).filter(r=>(!course||r.course.toLowerCase()===course.toLowerCase())&&r.totalAnswers>=topicRules().minimumQuestions),lowest=topicRows.slice().sort((a,b)=>(a.accuracy??100)-(b.accuracy??100))[0],mentioned=topicRows.find(r=>lower.includes(r.topic.toLowerCase())),personalized=learningPreferenceSuggestions(course).filter(t=>!t.includes('Complete a quiz')).slice(0,2),speed=learningSpeedTopics().filter(t=>(!course||t.course.toLowerCase()===course.toLowerCase())&&lower.includes(t.topic.toLowerCase())).sort((a,b)=>(b.quizzesTaken||0)-(a.quizzesTaken||0))[0];let base;if(mentioned)base=`Your ${mentioned.course} topic ${mentioned.topic} is at ${mentioned.accuracy}% across ${mentioned.totalAnswers} questions, with a ${topicTrend(mentioned).toLowerCase()} trend. Review the related notes, complete a focused quiz, and correct every missed question.`;else if(lowest)base=`Your lowest ${lowest.course} topic is ${lowest.topic} at ${lowest.accuracy}% across ${lowest.totalAnswers} questions. I recommend reviewing the prerequisite ideas first, then completing a focused ${lowest.topic} quiz.`;else if(lower.includes('biology'))base='Use active recall: sketch the process or structure from memory, label it, then compare it with your notes. Follow with five flashcards and a short quiz. Spend extra time explaining why, not only naming parts.';else if(lower.includes('before')||lower.includes('test'))base='Start with a quick brain dump of everything you remember. Check it against your notes, mark the gaps, then review those weak areas with flashcards. Finish with a timed quiz and explain every missed answer aloud.';else if(lower.includes('procrast'))base='Make the first step tiny: set a 10-minute timer and open one note. Put your phone out of reach, choose one specific outcome, and stop after 10 minutes if you want. Starting is the real assignment.';else if(lower.includes('math'))base='For math, spend less time rereading and more time solving. Work one example with notes, one without notes, then one mixed problem. Keep an error log that names exactly where each mistake happened.';else base='Try a three-part session: 10 minutes recalling what you know, 20 minutes practicing the hardest idea, and 5 minutes writing what to review next. Active recall will give you more useful feedback than rereading.';const memory=memoryRows().filter(r=>(!course||r.course.toLowerCase()===course.toLowerCase())&&lower.includes(r.topic.toLowerCase())).sort((a,b)=>String(a.predictedReviewDate||'9999').localeCompare(String(b.predictedReviewDate||'9999')))[0];if(memory){const h=(memory.reviewHistory||[]).filter(x=>x.accuracy!==null),prev=h[h.length-2],last=h[h.length-1];base+=prev&&last?` Your ${memory.topic} score changed from ${prev.accuracy}% to ${last.accuracy}%, and its review date is ${reviewDateLabel(memory.predictedReviewDate).toLowerCase()}. A short focused review is recommended.`:` ${memory.topic} is ${memory.memoryStatus.toLowerCase()}; ${memorySupportText(memory).toLowerCase()}`}
const readiness=nextExamReadiness(course);if(readiness){const top=readiness.recommendations.slice(0,2).map(r=>r.topic).join(' and ');base+=` Your ${readiness.course} exam readiness is ${readiness.overallReadiness}%. ${top?top+' currently '+(readiness.recommendations.length===1?'is':'are')+' the highest-impact review area.':'Use the Exam Readiness page to choose your next review.'}`}if(speed){const category=learningSpeedCategory(speed);base+=` Your learning-speed data shows ${sentenceCase(speed.topic)} is ${category.toLowerCase()} after ${speed.quizzesTaken} quiz${speed.quizzesTaken===1?'':'zes'}, so use ${['Needs More Support','Extra Practice Needed','Review Needed'].includes(category)?'smaller steps and spaced practice':'short review blocks and maintenance practice'}.`}const methodTip=bestMethod({course})||bestMethod();if(methodTip)base+=' '+methodTip.method+' currently has the strongest linked results, averaging '+methodTip.averageScore+'% across '+methodTip.assessments+' assessment'+(methodTip.assessments===1?'':'s')+'.';return personalized.length?`${base} Based on your Learning Profile: ${personalized.join(' ')}`:base}
