function generateCards(){const subject=$('#flashSubject').value,folderId=normalizeFolderId($('#flashFolder').value),notes=subjectNotes(subject);if(!notes.length)return toast('Save notes for this course first.');const sentences=statementsFor(subject),keys=keywords(notes.map(n=>n.text).join(' '));currentCards=sentences.slice(0,5).map((s,i)=>{const key=keys.find(k=>s.toLowerCase().includes(k))||keys[i]||'this concept';return {id:'c'+Date.now()+i,subject,folderId,question:`What should you remember about ${key}?`,answer:s,topic:key}});while(currentCards.length<5)currentCards.push({id:'c'+Date.now()+currentCards.length,subject,folderId,question:`What is a key idea from ${notes[0].title}?`,answer:summarize(notes[0].text),topic:keys[currentCards.length]||subject});user().flashcards.push(...currentCards);touchFolder(folderId);cardIndex=0;currentCardKnown=0;recordBehaviorEvent('flashcards_used',{course:subject,topic:keys[0]||subject,result:{cards:currentCards.length}});startStudySession(subject,keys[0]||subject);saveDB();$('#flashEmpty').classList.add('hidden');$('#flashStudy').classList.remove('hidden');showCard();recordActivity('card',`Generated 5 ${subject} flashcards`)}
function showCard(){if(cardIndex>=currentCards.length){const first=currentCards[0];if(first&&!currentCards._memoryRecorded){const accuracy=currentCards.length?Math.round(currentCardKnown/currentCards.length*100):null,duration=Math.max(1,currentCards.length*2);recordStudyMethodSession({course:first.subject,topic:first.topic||first.subject,method:'Flashcards',durationMinutes:duration,completed:true});recordMemoryReview({course:first.subject,topic:first.topic||first.subject,activityType:'flashcards',accuracy,questionsAnswered:currentCards.length,durationMinutes:duration});currentCards._memoryRecorded=true;saveDB();renderDashboard();renderLearningProfile()}$('#flashStudy').innerHTML='<div class="empty-state card"><span class="empty-icon">?</span><h2>Deck complete</h2><p>Your card progress has been saved. Review weak topics in Progress.</p><button class="btn btn-primary" onclick="location.reload()">Study another deck</button></div>';return}const c=currentCards[cardIndex];$('#flashcard').classList.remove('flipped');$('#flashQuestion').textContent=c.question;$('#flashAnswer').textContent=c.answer;$('#cardCounter').textContent=`Card ${cardIndex+1} of ${currentCards.length}`;$('#cardProgress').style.width=(cardIndex/currentCards.length*100)+'%';$('#knownCount').textContent=user().progress.cardsKnown}
function markCard(known){const c=currentCards[cardIndex];user().progress.cardsCompleted++;if(known){user().progress.cardsKnown++;currentCardKnown++}else if(!user().progress.weakTopics.includes(c.topic))user().progress.weakTopics.push(c.topic);user().progress.minutes+=2;recordBehaviorEvent(known?'flashcards_used':'mistake_corrected',{course:c.subject,topic:c.topic,durationMinutes:2,result:{known}});saveDB();cardIndex++;showCard()}
