function buildQuiz(subject,focusTopic=''){const notes=subjectNotes(subject),sourceText=notes.map(n=>`${n.title} ${n.text}`).join(' '),sentences=statementsFor(subject),keys=keywords(sourceText),topic=normalizeTopicName(focusTopic||inferTopicFromText(sourceText,subject)),unit=normalizeUnitName(notes.find(n=>(n.title+' '+n.text).toLowerCase().includes(topic.toLowerCase()))?.title||topic);return Array.from({length:5},(_,i)=>{const sentence=(focusTopic?sentences.find(s=>s.toLowerCase().includes(focusTopic.toLowerCase())):null)||sentences[i%sentences.length]||notes[0].text;const answer=keys.find(k=>sentence.toLowerCase().includes(k))||keys[i%keys.length]||subject;const wrong=keys.filter(k=>k!==answer).slice(0,3);while(wrong.length<3)wrong.push(['concept','process','evidence'][wrong.length]);const options=[answer,...wrong].sort(()=>Math.random()-.5);return {id:`question-${Date.now()}-${i+1}`,course:subject,unit,topic,type:'Multiple Choice',difficulty:'Medium',question:`Which term best connects to this idea: "${sentence.slice(0,105)}${sentence.length>105?'...':''}"`,answer,correctAnswer:answer,options,explanation:`The notes connect this idea with ${answer}: ${sentence}`}})}
function buildQuizFromText(text,subject,count=5,type='Multiple Choice',difficulty='Medium'){const sentences=statementsFromText(text),keys=keywords(text),types=type==='Mixed'?['Multiple Choice','True or False','Short Answer']:Array(count).fill(type),topic=inferTopicFromText(text,subject),unit=normalizeUnitName(topic);return Array.from({length:count},(_,i)=>{const qType=types[i%types.length],sentence=sentences[i%Math.max(sentences.length,1)]||text,answer=keys[i%Math.max(keys.length,1)]||subject,base={id:`question-${Date.now()}-${i+1}`,course:subject,unit,topic,type:qType,answer,correctAnswer:answer,explanation:`This question is based on: ${sentence}`,difficulty};if(qType==='True or False')return {...base,question:`True or False: ${sentence.slice(0,130)}${sentence.length>130?'...':''}`,answer:'True',correctAnswer:'True',options:['True','False']};if(qType==='Short Answer')return {...base,question:`In one or two sentences, explain ${answer} in this file.`};const wrong=keys.filter(k=>k!==answer).slice(0,3);while(wrong.length<3)wrong.push(['concept','process','evidence'][wrong.length]);return {...base,question:`Which term best connects to this idea: "${sentence.slice(0,105)}${sentence.length>105?'...':''}"`,options:[answer,...wrong].sort(()=>Math.random()-.5)}})}
