/* Learning Profile */
function formatProfileDate(value){return value?new Date(value).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}):'Unknown'}
function habitMinutes(value,prefix=''){return value?`${prefix}${value} minutes`:'Unknown'}
function profileFact(label,value){return `<div class="profile-fact"><span>${escapeHTML(label)}</span><b>${escapeHTML(value)}</b></div>`}
function styleCard(label,key,description){const style=normalizeStyleEvidence(ensureLearningProfile()?.learningStyles?.[key]),value=learningStyleLabel(style);return `<article class="learning-style-card"><span class="pill blue-pill">${escapeHTML(value)}</span><h3>${escapeHTML(label)}</h3><p>${escapeHTML(description)}</p><small>${escapeHTML(confidenceLabel(style.confidence))} - ${style.evidenceCount} useful action(s)</small></article>`}
function subjectProfileCard(course,subject){return `<article class="learning-subject-card ${subject.active?'':'inactive'}"><div><h3>${escapeHTML(course)}</h3><span>${subject.active?'Active course':'Inactive course'}</span></div><div class="profile-fact-grid">${profileFact('Current level',profileValue(subject.level))}${profileFact('Average quiz score',`${Number(subject.averageQuizScore)||0}%`)}${profileFact('Quizzes taken',String(Number(subject.quizzesTaken)||0))}${profileFact('Strong topics',profileList(subject.strongTopics))}${profileFact('Developing topics',profileList(subject.developingTopics))}${profileFact('Weak topics',profileList(subject.weakTopics))}</div></article>`}
function learningSpeedSupportText(topic){const category=learningSpeedCategory(topic);if(category==='Fast Progress')return 'Use shorter future reviews with occasional maintenance practice.';if(category==='Steady Progress')return 'Continue the current study method.';if(category==='Extra Practice Needed')return 'This topic took more practice. Break it into smaller steps and use worked examples.';if(category==='Needs More Support')return 'Additional support may help. Review prerequisites and use simpler explanations or diagrams.';if(category==='Review Needed')return 'A short review will help maintain earlier mastery.';return 'Complete more topic-based quizzes to measure learning speed.'}
