function renderLearningSpeed(){const topics=learningSpeedTopics().sort((a,b)=>(b.questionsAnswered+b.quizzesTaken)-(a.questionsAnswered+a.quizzesTaken));$('#learningSpeedTrend').textContent=learningSpeedTrend();$('#learningSpeedGrid').innerHTML=topics.length?topics.map(learningSpeedCard).join(''):'<div class="empty-state card"><h2>Complete more topic-based quizzes to measure learning speed.</h2><p>StudySpark will show attempts, study time, mastery status, and supportive recommendations after repeated topic practice.</p></div>'}
function reviewDateLabel(value){if(!value)return 'More review data is needed.';const diff=calendarDaysBetween(new Date(),value),date=new Date(value).toLocaleDateString(undefined,{month:'short',day:'numeric'});if(value<isoDateOnly())return `${date} - overdue`;if(diff===0)return 'Today';if(diff===1)return 'Tomorrow';return `${date} - in ${diff} days`}
