function memorySupportText(record){if(record.predictionConfidence==='Low')return 'More review data is needed before StudySpark estimates this topic confidently.';if(record.memoryStatus==='Overdue')return 'A short review is recommended because this topic is past its review date.';if(record.memoryStatus==='Review Recommended')return 'This topic may need a refresher soon.';if(record.memoryStatus==='Fading')return 'Your recent accuracy has decreased or enough time has passed for a quick check.';if(record.memoryStatus==='Stable')return 'This topic is holding steady with repeated reviews.';return 'This topic is fresh after a recent review.'}
function memoryCard(record){const last=record.lastReviewedAt?new Date(record.lastReviewedAt).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}):'Not reviewed yet',score=record.lastAccuracy===null||record.lastAccuracy===undefined?'Not measured':record.lastAccuracy+'%';return `<article class="memory-topic-card ${record.memoryStatus.toLowerCase().replace(/\s+/g,'-')}"><div class="learning-speed-head"><div><h3>${escapeHTML(record.topic)}</h3><span>${escapeHTML(record.course)}</span></div><b>${escapeHTML(record.memoryStatus)}</b></div><div class="profile-fact-grid">${profileFact('Last score',score)}${profileFact('Last reviewed',last)}${profileFact('Next review',reviewDateLabel(record.predictedReviewDate))}${profileFact('Prediction confidence',record.predictionConfidence)}</div><div class="memory-timeline">${memoryTimeline(record)||'<span>Complete topic-based quizzes or flashcard sessions to begin tracking memory.</span>'}</div><p>${escapeHTML(memorySupportText(record))}</p><button class="btn btn-secondary" type="button" data-review-topic="${escapeHTML(record.topic)}" data-review-course="${escapeHTML(record.course)}">Review Topic</button></article>`}
function renderMemoryReview(){if(!$('#memoryReviewGrid'))return;const rows=memoryRows().sort((a,b)=>String(a.predictedReviewDate||'9999').localeCompare(String(b.predictedReviewDate||'9999'))),summary=memorySummary();$('#memorySummary').innerHTML=profileFact('Topics remembered well',String(summary.well))+profileFact('Reviews due today',String(summary.dueToday))+profileFact('Overdue topics',String(summary.overdue))+profileFact('Average review interval',summary.avgInterval?`${summary.avgInterval} days`:'More review data is needed')+profileFact('Fastest score decline',summary.fastestDecline?`${summary.fastestDecline.topic} may need a refresher.`:'None identified yet');$('#memoryReviewGrid').innerHTML=rows.length?rows.map(memoryCard).join(''):'<div class="empty-state card"><h2>Complete topic-based quizzes or flashcard sessions to begin tracking memory.</h2><p>Review recommendations will appear after meaningful completed practice.</p></div>';$$('[data-review-topic]',$('#memoryReviewGrid')).forEach(btn=>btn.onclick=()=>startReviewChoice(btn.dataset.reviewCourse,btn.dataset.reviewTopic))}
