function renderDashboardReviews(){if(!$('#reviewsDueList'))return;const due=reviewsDue();$('#reviewsDueList').innerHTML=reviewListGroup('Reviews Due Today',due.today)+reviewListGroup('Overdue',due.overdue)+reviewListGroup('Upcoming',due.upcoming);$$('[data-review-topic]',$('#reviewsDueList')).forEach(btn=>btn.onclick=()=>startReviewChoice(btn.dataset.reviewCourse,btn.dataset.reviewTopic))}
function renderDashboardExamReadiness(){const root=$('#dashboardExamReadiness');if(!root)return;const next=nextExamReadiness();if(!next){root.innerHTML='<div class="empty-mini">Create a study plan and complete topic-based quizzes to begin estimating exam readiness.</div>';return}root.innerHTML=`<div class="dashboard-readiness-row"><div><b>${escapeHTML(next.title)}</b><small>${escapeHTML(next.course)} - Test in ${next.daysRemaining} day(s)</small></div><span>${next.overallReadiness}%</span></div><div class="progress-line"><i style="width:${next.overallReadiness}%"></i></div><p>Status: ${escapeHTML(next.status)}. Confidence: ${escapeHTML(next.confidence)}.</p><button class="btn btn-primary btn-full" id="viewExamReadinessBtn" type="button">View Readiness</button>`;$('#viewExamReadinessBtn').onclick=()=>showView('examReadiness')}
function readinessEvidenceText(r){return `${r.evidence.quizzes} quiz(es), ${r.evidence.questions} question(s), ${r.evidence.measuredTopics} of ${r.evidence.totalTopics} topic(s) measured`}
function renderExamSummaryCard(r){return `<article class="card exam-summary-card"><div class="card-head"><div><span class="pill blue-pill">${escapeHTML(r.course)}</span><h3>${escapeHTML(r.title)}</h3><p>Test date: ${escapeHTML(r.testDate)} - ${r.daysRemaining} day(s) remaining</p></div><button class="btn btn-secondary" data-open-plan="${escapeHTML(r.planId)}" type="button">Open Study Plan</button></div><div class="readiness-hero"><div><small>Overall Readiness</small><b>${r.overallReadiness}%</b><span>${escapeHTML(r.status)}</span></div><div><small>Estimated Score</small><b>${r.prediction.available?`${r.prediction.low}%-${r.prediction.high}%`:'--'}</b><span>${r.prediction.available?'Confidence: '+escapeHTML(r.prediction.confidence):escapeHTML(r.prediction.message)}</span></div><div><small>Trend</small><b>${escapeHTML(r.trend)}</b><span>${escapeHTML(readinessEvidenceText(r))}</span></div></div><div class="progress-line"><i style="width:${r.overallReadiness}%"></i></div>${renderPredictionDisclaimer()}</article>`}
function renderTopicReadiness(r){return `<article class="card"><div class="card-head"><div><h3>Topic Readiness</h3><p>Missing topic data is marked as Not Assessed instead of scored as zero.</p></div></div><div class="topic-readiness-list">${r.topicReadiness.length?r.topicReadiness.map(t=>`<div class="topic-readiness-row"><div><b>${escapeHTML(t.topic)}</b><small>${escapeHTML(t.status)} - ${t.accuracy===null?'Accuracy not assessed':t.accuracy+'% accuracy'} - ${escapeHTML(t.memoryStatus)}</small></div><span>${t.readiness===null?'Not Assessed':t.readiness+'%'}</span><button class="btn btn-secondary" data-practice-topic="${escapeHTML(t.topic)}" data-practice-course="${escapeHTML(r.course)}" type="button">Review</button></div>`).join(''):'<div class="empty-mini">No topics were saved for this plan.</div>'}</div></article>`}
