function validateStudyAvailability(availability){const a=normalizeStudyAvailability(availability),errors=[];if(!Number.isFinite(Number(a.totalAvailableMinutes))||Number(a.totalAvailableMinutes)<=0)errors.push('Add your available study time before generating a plan.');if(!a.availableDays.length)errors.push('Choose at least one available study day.');if(!Number.isFinite(Number(a.preferredSessionMinutes))||a.preferredSessionMinutes<15||a.preferredSessionMinutes>120)errors.push('Preferred session length must be between 15 and 120 minutes.');if(!Number.isFinite(Number(a.maximumDailyMinutes))||a.maximumDailyMinutes<15)errors.push('Maximum daily study time must be at least 15 minutes.');a.availableDays.forEach(day=>{const value=Number(a.dailyAvailability?.[day]);if(!Number.isFinite(value)||value<=0)errors.push(`Enter available minutes for ${day}.`)});return {valid:!errors.length,errors,availability:a}}
