function fillPredictionForm(profile){if(!profile)return resetPredictionForm();ensureAssessmentWeightControls();ensureStudyAvailabilityControls();$('#predictionProfileId').value=profile.id;$('#predictionCourse').innerHTML=courseOptionsHTML(availableCourses());$('#predictionCourse').value=profile.course;$('#predictionExamName').value=profile.examName;$('#predictionExamDate').value=profile.examDate;$('#predictionCurrentGrade').value=profile.currentGrade;$('#predictionTargetGrade').value=profile.targetGrade;ASSESSMENT_CATEGORY_KEYS.forEach(key=>{const input=$(`[data-assessment-weight="${key}"]`);if(input)input.value=profile.assessmentCategoryWeights?.[key]??''});if($('#assessmentWeightSource'))$('#assessmentWeightSource').value=profile.assessmentWeightSource||'student-estimate';fillStudyAvailabilityControls(profile.studyAvailability);$('#predictionChapterList').innerHTML=profile.chapters.map(predictionChapterTemplate).join('');bindPredictionChapterActions();clearPredictionErrors();renderAssessmentWeightStatus();renderChapterWeightStatus();updatePredictionGradePreview();$('#savePredictionProfileBtn').textContent='Save Prediction Profile'}
function formatPredictionDate(value){const date=new Date(`${value}T00:00:00`);return Number.isNaN(date.getTime())?'Not set':date.toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'})}
function predictionProfileCard(profile){return '<article class="card prediction-profile-summary"><span class="pill blue-pill">'+escapeHTML(profile.course)+'</span><h3>'+escapeHTML(profile.examName)+'</h3><div class="profile-fact-grid">'+profileFact('Exam Date',formatPredictionDate(profile.examDate))+profileFact('Current Grade',Number(profile.currentGrade).toFixed(profile.currentGrade%1?1:0)+'%')+profileFact('Target Grade',Number(profile.targetGrade).toFixed(profile.targetGrade%1?1:0)+'%')+profileFact('Assessment Weights',profile.assessmentCategoryWeightsValid?'Complete':'Setup Required')+profileFact('Chapters',String(profile.chapters.length))+profileFact('Chapter Weights',profile.chapterWeightsValid?'Complete':'Setup Required')+profileFact('Updated',formatProfileDate(profile.updatedAt))+'</div><div class="file-actions"><button type="button" data-prediction-open="'+escapeHTML(profile.id)+'">Open</button><button type="button" data-prediction-edit="'+escapeHTML(profile.id)+'">Edit</button><button type="button" data-prediction-delete="'+escapeHTML(profile.id)+'">Delete</button></div></article>'}
function renderPredictionProfiles(){const root=$('#predictionProfilesGrid');if(!root)return;const profiles=getCurrentUserPredictionProfiles().sort((a,b)=>new Date(a.examDate)-new Date(b.examDate));root.innerHTML=profiles.length?profiles.map(predictionProfileCard).join(''):'<div class="empty-state card"><h2>No prediction profiles have been created yet.</h2><p>Create your first prediction profile to prepare future exam-success estimates.</p><button class="btn btn-primary" id="emptyCreatePredictionProfile" type="button">Create Prediction Profile</button></div>';$$('[data-prediction-open]',root).forEach(btn=>btn.onclick=()=>openPredictionProfile(btn.dataset.predictionOpen));$$('[data-prediction-edit]',root).forEach(btn=>btn.onclick=()=>editPredictionProfile(btn.dataset.predictionEdit));$$('[data-prediction-delete]',root).forEach(btn=>btn.onclick=()=>confirmDeletePredictionProfile(btn.dataset.predictionDelete));$('#emptyCreatePredictionProfile')?.addEventListener('click',()=>{$('#predictionCourse')?.focus()})}
function renderFutureSuccessPage(){if(!$('#futureSuccessView')||!user())return;ensureAssessmentWeightControls();ensureStudyAvailabilityControls();ensurePerformanceCategoryControl();if(!$('#predictionChapterList')?.children.length)resetPredictionForm();const currentCourse=$('#predictionCourse')?.value||'';$('#predictionCourse').innerHTML=courseOptionsHTML(availableCourses());if(currentCourse&&availableCourses().some(course=>course.toLowerCase()===currentCourse.toLowerCase()))$('#predictionCourse').value=currentCourse;else if(!$('#predictionCourse').value)$('#predictionCourse').value=selectedCourses()[0]||availableCourses()[0]||'';if($('#predictionExamDate'))$('#predictionExamDate').min=today();renderAssessmentWeightStatus();renderPredictionProfiles();renderPredictionPerformancePanel();updatePredictionGradePreview()}
function ensureChapterWeightsInstructions(){const grid=$('#instructionsView .instruction-grid');if(!grid)return;if(!$('#chapterWeightsInstruction'))grid.insertAdjacentHTML('beforeend',"<article class=\"folder-instructions\" id=\"chapterWeightsInstruction\"><span>23</span><div><h3>Setting Chapter Exam Weights</h3><p>Open a Prediction Profile, select Edit Chapter Weights, and enter the percentage of exam content assigned to every chapter. Chapter weights help show which content areas deserve attention, while assessment category weights drive the main weighted prediction.</p></div></article>");if(!$('#assessmentWeightsInstruction'))grid.insertAdjacentHTML('beforeend',"<article class=\"folder-instructions\" id=\"assessmentWeightsInstruction\"><span>24</span><div><h3>Assessment Category Weights</h3><p>Ontario assessments may be divided into Knowledge and Understanding, Thinking, Communication, and Application. Enter the percentage assigned to each category, and make sure the four percentages add up to 100%. Add the assessment category when recording a quiz, assignment, or practice score. The predictor calculates performance by chapter and by assessment category, and higher-weight categories have more influence on the predicted result. Use your teacher's official breakdown when available.</p></div></article>");if(!$('#examReadinessFutureInstruction'))grid.insertAdjacentHTML('beforeend',"<article class=\"folder-instructions\" id=\"examReadinessFutureInstruction\"><span>25</span><div><h3>Understanding Exam Readiness</h3><p>Open a Prediction Profile with enough performance data, then select Calculate Exam Readiness. StudySpark combines chapter performance, recent improvement, completed study tasks, study consistency, and time remaining. Chapter Performance has the largest influence at 50%, Recent Improvement contributes 20%, Completed Study Tasks contributes 15%, Study Consistency contributes 10%, and Time Remaining contributes 5%. Every component must contain enough data before readiness can be calculated. The readiness percentage measures recorded preparation and is not a predicted exam grade. Record accurate activity regularly to make the estimate more useful. This is an estimate based on recorded activity, not a guaranteed exam result.</p></div></article>");if(!$('#likelyExamScoreInstruction'))grid.insertAdjacentHTML('beforeend',"<article class=\"folder-instructions\" id=\"likelyExamScoreInstruction\"><span>26</span><div><h3>Understanding the Likely Exam Score</h3><p>StudySpark uses your recorded scores and official assessment-category weights for Knowledge and Understanding, Thinking, Communication, and Application. Categories worth more marks have more influence on the estimate. Chapter performance explains strong and weak topics, but chapter weights affect the score only when official chapter percentages are available. The central score is rounded as an approximate result, and the estimated range shows that the calculation is not exact. Missing category data prevents a complete likely-score estimate, so recalculate after adding scores or changing exam weights. This is an estimate based on recorded performance, not a guaranteed exam result.</p></div></article>")}
function ensureTargetProbabilityInstructions(){const grid=$('#instructionsView .instruction-grid');if(!grid||$('#targetProbabilityInstruction'))return;grid.insertAdjacentHTML('beforeend',"<article class=\"folder-instructions\" id=\"targetProbabilityInstruction\"><span>27</span><div><h3>Understanding Target Probability</h3><p>StudySpark compares your target grade with the current Likely Exam Score and estimated range. It also considers recent improvement, study consistency, time remaining, weak chapters, and completed practice. The score gap has the largest influence, and a target inside the current estimated range usually produces a higher probability. Strong recent improvement and consistent study may support the estimate, while weak chapters, missing data, and incomplete practice may lower it. Recalculate after adding new scores or changing the target. This is an estimate based on recorded activity and performance. It is not guaranteed.</p></div></article>")}
function ensureChapterImpactInstructions(){const grid=$('#instructionsView .instruction-grid');if(!grid||$('#chapterImpactInstruction'))return;grid.insertAdjacentHTML('beforeend',"<article class=\"folder-instructions\" id=\"chapterImpactInstruction\"><span>28</span><div><h3>Understanding the Highest-Impact Chapter</h3><p>StudySpark compares chapter performance to determine where focused improvement may matter most. Official chapter percentages are used only when they have been entered from a teacher or course outline and total 100%. If chapter percentages are unavailable, StudySpark estimates impact using Knowledge and Understanding, Thinking, Communication, and Application performance. A low score does not automatically make a chapter the highest priority because the app also considers exam weighting, data coverage, and time remaining. Chapters with insufficient data are shown as data gaps. This is a study-priority estimate based on recorded data. It does not guarantee a specific score increase. Record more chapter-specific scores to improve the analysis.</p></div></article>")}
function ensureStudyImpactInstructions(){const grid=$('#instructionsView .instruction-grid');if(!grid||$('#studyImpactInstruction'))return;grid.insertAdjacentHTML('beforeend',"<article class=\"folder-instructions\" id=\"studyImpactInstruction\"><span>29</span><div><h3>Using the Extra Study Time Simulator</h3><p>Open a Prediction Profile with a current Likely Exam Score, then select a chapter or use the Highest-Impact Chapter. Choose the assessment category, study method, focused study time, and completion date. The simulator uses diminishing-return rules, so the first focused hour usually has the largest estimated effect. It may estimate a chapter-score range, exam-score range, and target-probability range. Official chapter weights are used only when provided; otherwise StudySpark uses assessment-category weights and labels the result as estimated. Simulations do not change actual grades or performance records. One focused hour may improve your predicted result. This is a hypothetical estimate. Actual improvement depends on study quality, difficulty, prior knowledge and exam performance.</p></div></article>")}
function ensureStudyScenarioInstructions(){const grid=$('#instructionsView .instruction-grid');if(!grid||$('#studyScenarioInstruction'))return;grid.insertAdjacentHTML('beforeend',"<article class=\"folder-instructions\" id=\"studyScenarioInstruction\"><span>30</span><div><h3>Comparing Study Plans</h3><p>Open a Prediction Profile with a current Likely Exam Score, create at least two study scenarios, then add one or more study actions to each scenario. Choose the chapter, assessment category, study method, focused hours, and planned date. StudySpark uses the same diminishing-return rules as the Extra Study Time Simulator, estimates a score range and target-probability range, and shows a midpoint for comparison. More study time does not always make a plan better, and balanced plans may cover more than one weak chapter. Select Compare Study Plans to view the scenarios together, then choose Use This Plan to create real incomplete Study Planner tasks. Hypothetical scores are not saved as actual results. These study plans are hypothetical estimates and do not guarantee a specific result.</p></div></article>")}
function ensureRecommendedPlanInstructions(){const grid=$('#instructionsView .instruction-grid');if(!grid||$('#recommendedPlanInstruction'))return;grid.insertAdjacentHTML('beforeend',"<article class=\"folder-instructions\" id=\"recommendedPlanInstruction\"><span>31</span><div><h3>Using the Recommended Study Plan</h3><p>Enter the exam date and available study time, then record chapter and assessment-category performance. StudySpark identifies high-priority chapters and weak topics, gives more time to areas that may have a larger effect on the exam, considers current performance, days remaining, and existing planner tasks, and keeps the plan within your availability. The plan prioritizes active practice, mistake review, and progress checks. Students can edit tasks, durations, dates, chapters, and categories before saving. Save the plan to create incomplete Study Planner tasks. Completing tasks does not automatically change a recorded grade; add new scored activities to update future predictions. Regenerate after performance or availability changes. This plan is a recommendation based on recorded data. Students may adjust it to match their needs.</p></div></article>")}
function ensurePredictionConfidenceInstructions(){const grid=$('#instructionsView .instruction-grid');if(!grid||$('#predictionConfidenceInstruction'))return;grid.insertAdjacentHTML('beforeend',"<article class=\"folder-instructions\" id=\"predictionConfidenceInstruction\"><span>32</span><div><h3>Understanding Prediction Confidence</h3><p>Prediction Confidence measures how much recorded evidence supports the prediction. It is based on the number of scored activities, chapter coverage, assessment-category coverage, data recency, and data consistency. More recorded quizzes and assignments generally improve confidence. Prediction Confidence is different from the probability of reaching your target grade, so a prediction can have High Confidence while still showing a low chance of reaching the target. Confidence updates automatically as more performance data is recorded. Prediction confidence reflects the amount and quality of recorded evidence. It does not guarantee prediction accuracy.</p></div></article>")}
function ensurePredictionDashboardInstructions(){const grid=$('#instructionsView .instruction-grid');if(!grid||$('#predictionDashboardInstruction'))return;grid.insertAdjacentHTML('beforeend',"<article class=\"folder-instructions\" id=\"predictionDashboardInstruction\"><span>33</span><div><h3>Using the Prediction Dashboard</h3><p>Select a Prediction Profile at the top of the dashboard. The dashboard summarizes the latest exam predictions, including Likely Exam Score, Target Grade, Chance of Reaching Target, Highest-Impact Chapter, Exam Readiness, Days Remaining, and Prediction Confidence. Likely Exam Score is a range, Target Grade is your selected goal, Chance of Reaching Target is a rule-based estimate, and Prediction Confidence shows how much recorded evidence supports the prediction. Outdated cards should be recalculated after data changes. Best Next Action recommends one specific next step, and you may add that action to the Study Planner. Different cards may update at different times. Dashboard information remains private. These results are estimates based on recorded data and do not guarantee a specific exam result.</p></div></article>")}
function ensurePredictionDashboardShell(){if(!$('#predictionDashboardView')){($('#viewContainer')||$('main'))?.insertAdjacentHTML('beforeend','<section class="app-view" id="predictionDashboardView"><div class="view-intro"><div><span class="kicker">AI STUDY COACH</span><h1>Prediction Dashboard</h1><p>See your current exam prediction, confidence, alerts, and next best action in one place.</p></div><div class="header-actions"><button class="btn btn-secondary" id="printPredictionDashboardBtn" type="button">Print Dashboard</button><button class="btn btn-primary" id="dashboardRecordPerformanceBtn" type="button">Record Performance</button></div></div><div id="predictionDashboardContent" aria-live="polite"><div class="empty-state card"><h2>Loading Prediction Dashboard...</h2></div></div></section>')}const nav=$('#appNav');if(nav&&!nav.querySelector('[data-view="predictionDashboard"]')){const anchor=nav.querySelector('[data-view="futureSuccess"]');anchor?.insertAdjacentHTML('afterend','<button data-view="predictionDashboard" type="button"><span>D</span> Prediction Dashboard</button>');nav.querySelector('[data-view="predictionDashboard"]')?.addEventListener('click',e=>{e.preventDefault();showView('predictionDashboard')})}}
function predictionDashboardSelectedKey(){return isGuestMode()?GUEST_SELECTED_PREDICTION_DASHBOARD_PROFILE_KEY:SELECTED_PREDICTION_DASHBOARD_PROFILE_KEY}
function predictionDashboardDismissedKey(){return isGuestMode()?GUEST_DASHBOARD_DISMISSED_ACTIONS_KEY:DASHBOARD_DISMISSED_ACTIONS_KEY}
function getStoredUserMap(key){try{const data=JSON.parse(localStorage.getItem(key))||{};return data&&typeof data==='object'&&!Array.isArray(data)?data:{}}catch{return{}}}
function getPredictionDashboardSelectedProfileId(){const map=getStoredUserMap(predictionDashboardSelectedKey());return map[predictionUserId()]||sessionStorage.getItem('selectedPredictionProfileId')||''}
function setPredictionDashboardSelectedProfileId(id){const key=predictionDashboardSelectedKey(),map=getStoredUserMap(key);map[predictionUserId()]=id;localStorage.setItem(key,JSON.stringify(map));sessionStorage.setItem('selectedPredictionProfileId',id)}
function getDashboardDismissedActions(){try{const rows=JSON.parse(localStorage.getItem(predictionDashboardDismissedKey()))||[];return Array.isArray(rows)?rows.filter(row=>row.userId===predictionUserId()):[]}catch{return[]}}
function saveDashboardDismissedActions(rows){const key=predictionDashboardDismissedKey();let all=[];try{all=JSON.parse(localStorage.getItem(key))||[]}catch{all=[]}const others=Array.isArray(all)?all.filter(row=>row.userId!==predictionUserId()):[];localStorage.setItem(key,JSON.stringify([...rows,...others]))}
function dashboardDataVersion(profileId){const profile=findPredictionProfile(profileId),latest=latestPerformanceUpdate(getPerformanceEntriesForProfile(profileId));return `${profile?.updatedAt||''}|${latest}`}
function isDashboardActionDismissed(action,profileId){if(!action?.fingerprint)return false;const version=dashboardDataVersion(profileId);return getDashboardDismissedActions().some(row=>row.predictionProfileId===profileId&&row.actionFingerprint===action.fingerprint&&row.basedOnDataVersion===version)}
function dismissDashboardAction(action,profileId){if(!action?.fingerprint)return;const rows=getDashboardDismissedActions().filter(row=>!(row.predictionProfileId===profileId&&row.actionFingerprint===action.fingerprint));rows.unshift({id:'dismissed-action-'+Date.now(),userId:predictionUserId(),predictionProfileId:profileId,actionFingerprint:action.fingerprint,dismissedAt:new Date().toISOString(),basedOnDataVersion:dashboardDataVersion(profileId)});saveDashboardDismissedActions(rows.slice(0,100));renderPredictionDashboardPage();showNotification({type:'information',message:'Best Next Action dismissed.'})}
function getDashboardDaysRemaining(examDate,currentDate=new Date()){if(!examDate)return {status:'missing',days:null,displayValue:'Not Set'};const exam=parseLocalDate(examDate),current=startOfLocalDay(currentDate);if(Number.isNaN(exam.getTime()))return {status:'invalid',days:null,displayValue:'Not Set'};const difference=Math.ceil((exam.getTime()-current.getTime())/86400000);if(difference<0)return {status:'passed',days:0,displayValue:'Exam Passed'};if(difference===0)return {status:'today',days:0,displayValue:'Today'};return {status:'future',days:difference,displayValue:String(difference)}}
function getPredictionRecordStatus(record){if(!record)return 'missing';if(record.status==='outdated')return 'outdated';if(record.status==='not-available'||record.status==='invalid-settings')return 'not-available';if(record.status==='current')return 'current';return record.status||'missing'}
function calculateOverallDashboardStatus(statuses){const values=['examReadiness','likelyScore','targetProbability','chapterImpact'].map(key=>statuses[key]);if(values.some(value=>value==='missing'||value==='not-available'))return 'incomplete';if(values.some(value=>value==='outdated'))return 'needs-update';return 'current'}
function dashboardStatusLabel(status){return {current:'Current','needs-update':'Needs Update',incomplete:'Incomplete',missing:'Not Available','not-available':'Not Available',outdated:'Outdated'}[status]||String(status||'Not Available')}
function evaluatePredictionDashboardStatuses({predictionProfile,likelyScore,targetProbability,examReadiness,chapterImpact,predictionConfidence,recommendedPlan}){return {profile:predictionProfile?'current':'missing',likelyScore:getPredictionRecordStatus(likelyScore),targetProbability:getPredictionRecordStatus(targetProbability),examReadiness:getPredictionRecordStatus(examReadiness),chapterImpact:getPredictionRecordStatus(chapterImpact),predictionConfidence:getPredictionRecordStatus(predictionConfidence),recommendedPlan:getPredictionRecordStatus(recommendedPlan)}}
function getStudyPlannerTasksByProfile(predictionProfileId){return (user()?.plans||[]).flatMap(plan=>(plan.days||[]).map(day=>({...day,planId:plan.id,planTitle:plan.title,plannedDate:day.date||plan.testDate,predictionProfileId:day.predictionProfileId||plan.predictionProfileId,source:day.source||plan.source}))).filter(task=>task.predictionProfileId===predictionProfileId)}
function currentSourceRecord(record,profile,metrics){return record&&record.status==='current'&&record.basedOnProfileUpdatedAt===profile.updatedAt&&record.basedOnLatestPerformanceUpdate===latestPerformanceUpdate(metrics.entries)?record:record}
async function buildPredictionDashboardData({userId,predictionProfileId}){const predictionProfile=findPredictionProfile(predictionProfileId);if(!predictionProfile)return {available:false,reason:'Prediction Profile not found.'};const metrics=predictionMetrics(predictionProfileId),readiness=evaluatePredictionDataReadiness(predictionProfileId),chapterMetrics=calculateChapterPerformance(predictionProfile,metrics.entries),likelyScore=getLatestLikelyExamScore(predictionProfileId),targetProbability=getLatestTargetProbability(predictionProfileId),examReadiness=getLatestExamReadiness(predictionProfileId),chapterImpact=getLatestChapterImpact(predictionProfileId),predictionConfidence=getLatestPredictionConfidence(predictionProfileId)||createPredictionConfidenceRecord(predictionProfile,readiness),recommendedPlan=getLatestRecommendedStudyPlan(predictionProfileId),plannerTasks=getStudyPlannerTasksByProfile(predictionProfileId),daysRemaining=getDashboardDaysRemaining(predictionProfile.examDate),statuses=evaluatePredictionDashboardStatuses({predictionProfile,likelyScore,targetProbability,examReadiness,chapterImpact,predictionConfidence,recommendedPlan}),bestNextAction=determineBestNextAction({predictionProfile,recommendedPlan,savedPlannerTasks:plannerTasks,highestImpactResult:chapterImpact,predictionConfidence,predictionStatuses:statuses,chapterMetrics,currentDate:new Date()}),alerts=buildPredictionDashboardAlerts({predictionProfile,daysRemaining,statuses,predictionConfidence,plannerTasks,readiness});return {available:true,userId,predictionProfile,metrics,readiness,chapterMetrics,likelyScore,targetProbability,examReadiness,chapterImpact,predictionConfidence,recommendedPlan,plannerTasks,daysRemaining,statuses,overallStatus:calculateOverallDashboardStatus(statuses),bestNextAction,alerts,generatedAt:new Date().toISOString()}}
function linkedPlannerTaskForRecommended(task,savedPlannerTasks){return savedPlannerTasks.find(row=>row.recommendedTaskId===task.id&&!row.deleted)}
function findNextRecommendedTask({recommendedPlan,savedPlannerTasks,currentDate=new Date()}){if(!recommendedPlan||recommendedPlan.status==='outdated')return null;const todayKey=formatDateKey(currentDate),rows=(recommendedPlan.tasks||[]).map(task=>{const linked=linkedPlannerTaskForRecommended(task,savedPlannerTasks);return {...task,linkedPlannerTask:linked,completed:linked?!!linked.completed:false,plannedDate:linked?.plannedDate||task.plannedDate}}).filter(task=>!task.completed&&task.chapterId&&Number(task.durationMinutes)>0&&task.plannedDate).sort((a,b)=>String(a.plannedDate).localeCompare(String(b.plannedDate)));const next=rows.find(task=>task.plannedDate<todayKey)||rows.find(task=>task.plannedDate>=todayKey);if(!next)return null;const overdue=next.plannedDate<todayKey;return {...next,type:'recommended-plan-task',title:overdue?`Complete the overdue ${next.chapterName} ${String(next.activityType||'practice').replace(/-/g,' ')} task.`:next.title,source:'recommended-study-plan',status:overdue?'overdue':'ready',fingerprint:`recommended:${recommendedPlan.id}:${next.id}`,why:[`${next.chapterName} is part of your current recommended study plan.`,`${assessmentCategoryLabel(next.assessmentCategory)} practice is the selected focus.`,overdue?'This task is overdue and still incomplete.':'This is the next incomplete task in your recommended plan.']}}
function findNextScenarioPlannerTask({savedPlannerTasks,predictionProfileId,currentDate=new Date()}){const todayKey=formatDateKey(currentDate),rows=(savedPlannerTasks||[]).filter(task=>task.source==='study-scenario'&&!task.completed&&task.predictionProfileId===predictionProfileId).sort((a,b)=>String(a.plannedDate).localeCompare(String(b.plannedDate))),next=rows.find(task=>task.plannedDate<todayKey)||rows.find(task=>task.plannedDate>=todayKey);if(!next)return null;return {type:'scenario-task',title:next.taskType||next.mainTopic||'Complete your saved study scenario task.',chapterName:next.chapterName||next.mainTopic,assessmentCategory:next.assessmentCategory,durationMinutes:next.estimatedMinutes||next.durationMinutes,plannedDate:next.plannedDate,taskId:next.id,planId:next.planId,source:'study-scenario',status:next.plannedDate<todayKey?'overdue':'ready',fingerprint:`scenario:${next.planId}:${next.id}`,why:['This is the next incomplete task from a study scenario saved to your planner.']}}
function createHighestImpactFallbackAction(chapter){const category=chapter.mainWeakCategory||chapter.mainWeakCategoryLabel||'',catValue=String(category.category||category||'').toLowerCase(),chapterName=chapter.chapterName||'the highest-impact chapter';let title=`Complete a 30-minute mixed review of ${chapterName}.`,durationMinutes=30;if(catValue.includes('application')){title=`Complete 15 ${chapterName} application questions.`;durationMinutes=45}else if(catValue.includes('thinking')){title=`Complete 8 multi-step ${chapterName} problems and explain your reasoning.`;durationMinutes=45}else if(catValue.includes('knowledge')){title=`Review ${chapterName} using active recall for 30 minutes.`;durationMinutes=30}else if(catValue.includes('communication')){title=`Write complete solutions for 5 ${chapterName} questions using correct vocabulary.`;durationMinutes=40}return {type:'highest-impact-fallback',title,chapterName,assessmentCategory:chapter.mainWeakCategory?.category||chapter.mainWeakCategory||'',durationMinutes,source:'highest-impact-chapter',status:'ready',fingerprint:`impact:${chapter.chapterId||chapterName}:${catValue||'mixed'}`,why:[`${chapterName} is your highest-impact chapter.`,chapter.mainWeakCategoryLabel?`${chapter.mainWeakCategoryLabel} is your main weak assessment category.`:'A focused mixed review is the best available recommendation.','No incomplete recommended-plan task is available.']}}
function createHighPriorityDataGapAction(chapterMetrics){const gap=(chapterMetrics||[]).filter(row=>row.highPriorityDataGap||row.dataReadiness?.ready===false||row.scoredEntryCount<2).sort((a,b)=>(Number(b.examWeightPercent)||0)-(Number(a.examWeightPercent)||0))[0];if(!gap)return null;return {type:'data-gap',title:`Complete and record one ${gap.chapterName} scored activity.`,chapterName:gap.chapterName,assessmentCategory:'',durationMinutes:30,source:'data-gap',status:'ready',fingerprint:`data-gap:${gap.chapterId||gap.chapterName}`,why:['More scored data is needed before this chapter impact can be measured.','Recording one quiz, assignment, practice-question set, or practice exam will improve the evidence.']}}
function createPredictionRecalculationAction(statuses){const steps=[['examReadiness','Recalculate your Exam Readiness.','exam-readiness'],['likelyScore','Recalculate your Likely Exam Score.','likely-score'],['targetProbability','Recalculate your Target Probability.','target-probability'],['chapterImpact','Recalculate your Highest-Impact Chapter.','chapter-impact'],['recommendedPlan','Generate an updated Recommended Study Plan.','recommended-plan']];const row=steps.find(([key])=>statuses[key]==='outdated');return row?{type:'recalculate',title:row[1],source:row[2],status:'ready',fingerprint:`recalculate:${row[0]}`,why:['New performance data was added after the previous calculation.','Predictions should be updated in dependency order before choosing a new plan.']}:null}
function createMissingDataAction({predictionProfile,predictionConfidence,chapterMetrics}){if(!predictionProfile?.examDate)return {type:'missing-data',title:'Add the exam date.',source:'prediction-profile',status:'action-required',fingerprint:'missing:exam-date',why:['Days remaining cannot be calculated without an exam date.']};if(!Number.isFinite(Number(predictionProfile.targetGrade)))return {type:'missing-data',title:'Set a target grade for this exam.',source:'prediction-profile',status:'action-required',fingerprint:'missing:target-grade',why:['Target probability needs a target grade.']};if((predictionConfidence?.activityCount||0)<=0)return {type:'missing-data',title:'Record your first scored quiz or assignment.',source:'performance-data',status:'action-required',fingerprint:'missing:first-score',why:['No recorded performance is available.']};if((predictionConfidence?.confidenceLabel||'Low')==='Low')return {type:'missing-data',title:'Record another scored activity to improve prediction confidence.',source:'prediction-confidence',status:'ready',fingerprint:'missing:confidence',why:['Prediction Confidence is Low because recorded evidence is limited.']};const gap=createHighPriorityDataGapAction(chapterMetrics);return gap||{type:'missing-data',title:'Record more performance data or generate a study plan.',source:'dashboard',status:'needs-more-data',fingerprint:'missing:general',why:['No current recommended action is available yet.']}}
function determineBestNextAction({predictionProfile,recommendedPlan,savedPlannerTasks,highestImpactResult,predictionConfidence,predictionStatuses,chapterMetrics,currentDate=new Date()}){const candidates=[];const recommendedTask=findNextRecommendedTask({recommendedPlan,savedPlannerTasks,currentDate});if(recommendedTask)candidates.push(recommendedTask);const scenarioTask=findNextScenarioPlannerTask({savedPlannerTasks,predictionProfileId:predictionProfile.id,currentDate});if(scenarioTask)candidates.push(scenarioTask);if(highestImpactResult?.highestImpactChapter)candidates.push(createHighestImpactFallbackAction(highestImpactResult.highestImpactChapter));const dataGapAction=createHighPriorityDataGapAction(chapterMetrics);if(dataGapAction)candidates.push(dataGapAction);const recalc=createPredictionRecalculationAction(predictionStatuses);if(recalc)candidates.push(recalc);candidates.push(createMissingDataAction({predictionProfile,predictionConfidence,chapterMetrics}));return candidates.find(action=>action&&!isDashboardActionDismissed(action,predictionProfile.id))||null}
function buildPredictionDashboardAlerts({predictionProfile,daysRemaining,statuses,predictionConfidence,plannerTasks,readiness}){const alerts=[];if(daysRemaining.status==='passed')alerts.push({level:'Action Required',text:'This exam date has passed. Prediction actions are unavailable.'});else if(daysRemaining.status==='today')alerts.push({level:'Action Required',text:'Your exam is today.'});else if(daysRemaining.days>=1&&daysRemaining.days<=3)alerts.push({level:'Warning',text:'Your exam is very soon. Focus on priority review and avoid unrealistic study plans.'});else if(daysRemaining.days>=4&&daysRemaining.days<=7)alerts.push({level:'Information',text:'One week or less remains before the exam.'});if(statuses.likelyScore==='outdated')alerts.push({level:'Warning',text:'Your Likely Exam Score is based on older performance data.'});if(statuses.targetProbability==='outdated')alerts.push({level:'Warning',text:'Target Probability is outdated.'});if(statuses.recommendedPlan==='outdated')alerts.push({level:'Warning',text:'Recommended Study Plan is outdated.'});if((predictionConfidence?.confidenceLabel||'').toLowerCase()==='low')alerts.push({level:'Information',text:'Prediction Confidence is Low. More scored activities may improve it.'});if((plannerTasks||[]).some(task=>!task.completed&&task.plannedDate<today()))alerts.push({level:'Warning',text:'A planned task is overdue.'});if(readiness?.missingRequirements?.some(item=>/assessment category/i.test(item)))alerts.push({level:'Action Required',text:'Assessment-category data or weights need attention.'});if(predictionProfile&&!predictionProfile.chapterWeightsValid)alerts.push({level:'Action Required',text:'Chapter weights do not total 100%.'});const order={'Action Required':0,Warning:1,Information:2};return alerts.sort((a,b)=>(order[a.level]??9)-(order[b.level]??9)).slice(0,8)}
function dashboardValueStatus(record){const status=getPredictionRecordStatus(record);if(status==='current')return 'Current';if(status==='outdated')return 'Outdated';if(status==='not-available')return 'Needs More Data';return 'Not Available'}
function likelyDashboardValue(record){if(!record)return {main:'Not Available',support:'Calculate Score',midpoint:'Not Available'};const range=record.estimatedRange?`${record.estimatedRange.displayLower}% to ${record.estimatedRange.displayUpper}%`:(record.displayEstimate===null?'Not Available':formatApproximateExamScore(record.centralEstimate));return {main:range,support:record.status==='outdated'?'This estimate should be recalculated.':'Estimated range based on recorded performance.',midpoint:record.displayEstimate===null?'Not Available':record.displayEstimate+'%'}}
function dashboardCard({key,title,value,support,status,updated,details='',actions=''}){return `<article class="prediction-dashboard-card" data-dashboard-card="${escapeHTML(key)}"><div><span class="status-badge ${status==='Current'?'status-active':status==='Outdated'||status==='Exam Passed'?'status-pending':'status-idle'}">${escapeHTML(status)}</span><h3>${escapeHTML(title)}</h3><b>${escapeHTML(value)}</b><p>${escapeHTML(support)}</p><small>Last updated: ${escapeHTML(updated||'Not Available')}</small></div>${details?`<details><summary>Accessible explanation</summary>${details}</details>`:''}${actions?`<div class="prediction-actions">${actions}</div>`:''}</article>`}
function predictionDashboardCards(data){const likely=likelyDashboardValue(data.likelyScore),target=Number.isFinite(Number(data.predictionProfile.targetGrade))?data.predictionProfile.targetGrade+'%':'Not Set',targetAction=Number.isFinite(Number(data.predictionProfile.targetGrade))?'Edit Target':'Set Target',prob=data.targetProbability?.displayProbability===null||!data.targetProbability?'Not Available':data.targetProbability.displayProbability+'%',impact=data.chapterImpact?.highestImpactChapter,readiness=data.examReadiness?.displayScore===null||!data.examReadiness?'Not Available':data.examReadiness.displayScore+'%',confidence=data.predictionConfidence?.confidenceLabel||'Not Available',confidenceScore=data.predictionConfidence?.confidenceScore===null||!data.predictionConfidence?'Not Available':data.predictionConfidence.confidenceScore+' / 100';return dashboardCard({key:'likely',title:'Likely Exam Score',value:likely.main,support:likely.support,status:dashboardValueStatus(data.likelyScore),updated:formatProfileDate(data.likelyScore?.calculatedAt),details:`<p>Approximate midpoint: ${escapeHTML(likely.midpoint)}. This is an estimated range, not a guaranteed mark.</p>`,actions:`<button class="btn btn-secondary" data-dashboard-jump="likely" type="button">View Calculation</button><button class="btn btn-primary" data-dashboard-calc="likely" type="button">${data.likelyScore?'Recalculate':'Calculate Score'}</button>`})+dashboardCard({key:'target',title:'Target Grade',value:target,support:'Your selected exam target.',status:target==='Not Set'?'Not Available':'Current',updated:formatProfileDate(data.predictionProfile.updatedAt),actions:`<button class="btn btn-secondary" data-dashboard-edit-profile type="button">${targetAction}</button>`})+dashboardCard({key:'probability',title:'Chance of Reaching Target',value:prob,support:'Rule-based estimate using your current prediction and recorded study data.',status:dashboardValueStatus(data.targetProbability),updated:formatProfileDate(data.targetProbability?.calculatedAt),actions:`<button class="btn btn-secondary" data-dashboard-jump="probability" type="button">View Breakdown</button><button class="btn btn-primary" data-dashboard-calc="probability" type="button">${data.targetProbability?'Recalculate':'Calculate Probability'}</button>`})+dashboardCard({key:'impact',title:'Highest-Impact Chapter',value:impact?.chapterName||'Not Available',support:impact?`Current Average: ${formatScorePercentage(impact.averageScore)}. ${impact.examWeightPercent===null||impact.examWeightPercent===undefined?'Estimated Category-Based Impact':`Official Exam Weight: ${impact.examWeightPercent}%`}`:'Record more chapter data to identify the highest-impact chapter.',status:dashboardValueStatus(data.chapterImpact),updated:formatProfileDate(data.chapterImpact?.calculatedAt),details:impact?`<ul><li>Impact label: ${escapeHTML(impact.impactLabel||'Not Available')}</li><li>Main weak category: ${escapeHTML(impact.mainWeakCategoryLabel||'Not Available')}</li></ul>`:'',actions:'<button class="btn btn-secondary" data-dashboard-jump="chapterImpact" type="button">View Chapter Analysis</button>'})+dashboardCard({key:'readiness',title:'Exam Readiness',value:readiness,support:'Based on performance, improvement, completed tasks, consistency and time remaining.',status:dashboardValueStatus(data.examReadiness),updated:formatProfileDate(data.examReadiness?.calculatedAt),actions:`<button class="btn btn-secondary" data-dashboard-jump="readiness" type="button">View Breakdown</button><button class="btn btn-primary" data-dashboard-calc="readiness" type="button">${data.examReadiness?'Recalculate':'Calculate Readiness'}</button>`})+dashboardCard({key:'days',title:'Days Remaining',value:data.daysRemaining.displayValue,support:`Exam Date: ${data.predictionProfile.examDate?formatProfileDate(data.predictionProfile.examDate):'Not Set'}`,status:data.daysRemaining.status==='passed'?'Exam Passed':data.daysRemaining.status==='missing'||data.daysRemaining.status==='invalid'?'Not Available':'Current',updated:formatProfileDate(data.predictionProfile.updatedAt)})+dashboardCard({key:'confidence',title:'Prediction Confidence',value:confidence,support:`Confidence Score: ${confidenceScore}. Based on ${data.predictionConfidence?.activityCount||0} scored activities across ${data.predictionConfidence?.chapterCoverage||0} chapters.`,status:dashboardValueStatus(data.predictionConfidence),updated:formatProfileDate(data.predictionConfidence?.calculatedAt),actions:'<button class="btn btn-secondary" data-dashboard-jump="confidence" type="button">View Evidence</button>'})}
function renderBestNextAction(action){if(!action)return '<article class="prediction-next-action card"><h2>Best Next Action</h2><p>No action is available yet. Add more performance data or generate a study plan.</p></article>';const canAdd=!action.linkedPlannerTask&&!action.planId&&action.source!=='study-scenario';return `<article class="prediction-next-action card"><div><span class="status-badge status-active">${escapeHTML(action.status||'Ready')}</span><h2>Best Next Action</h2><h3>${escapeHTML(action.title)}</h3></div><div class="profile-fact-grid">${profileFact('Chapter',action.chapterName||'Not Available')}${profileFact('Focus',action.assessmentCategory?assessmentCategoryLabel(action.assessmentCategory):'General')}${profileFact('Estimated Time',action.durationMinutes?formatStudyMinutes(action.durationMinutes):'Not Available')}${profileFact('Source',String(action.source||'Dashboard').replace(/-/g,' '))}</div><section><h4>Why</h4><ul>${(action.why||[]).map(item=>`<li>${escapeHTML(item)}</li>`).join('')}</ul></section><div class="prediction-actions"><button class="btn btn-primary" data-dashboard-start-action="${escapeHTML(action.fingerprint)}" type="button">Start Task</button>${canAdd?`<button class="btn btn-secondary" data-dashboard-add-action="${escapeHTML(action.fingerprint)}" type="button">Add to Study Planner</button>`:''}<button class="btn btn-secondary" data-dashboard-full-plan type="button">View Full Plan</button><button class="btn btn-ghost" data-dashboard-dismiss-action="${escapeHTML(action.fingerprint)}" type="button">Dismiss</button></div></article>`}
function predictionDashboardHistory(data){const rows=[...(getLikelyExamScoreHistory().filter(r=>r.predictionProfileId===data.predictionProfile.id).map(r=>({date:r.calculatedAt,title:'Likely Exam Score updated',value:formatEstimatedRange(r.estimatedRange),status:r.status}))),...(getTargetProbabilityHistory().filter(r=>r.predictionProfileId===data.predictionProfile.id).map(r=>({date:r.calculatedAt,title:'Target Probability updated',value:r.displayProbability===null?'Not Available':r.displayProbability+'%',status:r.status}))),...(getExamReadinessHistory().filter(r=>r.predictionProfileId===data.predictionProfile.id).map(r=>({date:r.calculatedAt,title:'Exam Readiness updated',value:r.displayScore===null?'Not Available':r.displayScore+'%',status:r.status}))),...(getChapterImpactHistory().filter(r=>r.predictionProfileId===data.predictionProfile.id).map(r=>({date:r.calculatedAt,title:'Highest-Impact Chapter changed',value:r.highestImpactChapter?.chapterName||'Not Available',status:r.status}))),...(getPredictionConfidenceHistory().filter(r=>r.predictionProfileId===data.predictionProfile.id).map(r=>({date:r.calculatedAt,title:'Prediction Confidence updated',value:r.confidenceLabel||'Not Available',status:r.status}))),...(getRecommendedStudyPlans().filter(r=>r.predictionProfileId===data.predictionProfile.id).map(r=>({date:r.updatedAt||r.createdAt,title:'Recommended Study Plan updated',value:r.mainPriority?.chapterName||'Plan generated',status:r.status})))].filter(r=>r.date).sort((a,b)=>new Date(b.date)-new Date(a.date)).slice(0,5);return `<article class="prediction-dashboard-history card"><h2>Recent Prediction History</h2><div class="readiness-history">${rows.length?rows.map(row=>`<div><span>${escapeHTML(formatProfileDate(row.date))}</span><b>${escapeHTML(row.title)}</b><small>${escapeHTML(row.value)} - ${escapeHTML(dashboardStatusLabel(row.status))}</small></div>`).join(''):'<div class="empty-mini">Recent prediction history appears after calculations are saved.</div>'}</div><button class="btn btn-secondary" data-dashboard-jump="history" type="button">View Full History</button></article>`}
function renderPredictionDashboardAlerts(alerts=[]){return `<article class="prediction-dashboard-alerts card" role="region" aria-label="Important Alerts"><h2>Important Alerts</h2>${alerts.length?`<ul>${alerts.map(alert=>`<li><b>${escapeHTML(alert.level)}:</b> ${escapeHTML(alert.text)}</li>`).join('')}</ul>`:'<p>No important alerts right now.</p>'}</article>`}
function profileOptionLabel(profile){return `${profile.course} - ${profile.examName}`}
function renderPredictionDashboardHeader(data,profiles){const updateState=getCurrentPredictionUpdateStatus(data.predictionProfile.id),updateLabel=updateState==='queued'?'Updating predictions...':updateState==='calculating'?'Updating predictions...':dashboardStatusLabel(data.overallStatus),sources=predictionDataSourceList({predictionProfile:data.predictionProfile,chapterMetrics:data.chapterMetrics,performanceEntries:data.metrics.entries,dependencies:{likelyExamScore:data.likelyScore,examReadiness:data.examReadiness}}),support=buildSupportivePredictionMessage({likelyExamScore:data.likelyScore,targetGrade:data.predictionProfile.targetGrade,highestImpactChapter:data.chapterImpact?.highestImpactChapter,predictionConfidence:data.predictionConfidence});return `<article class="prediction-dashboard-header card"><div class="dashboard-profile-select"><label>Prediction Profile<select id="predictionDashboardProfileSelect">${profiles.map(profile=>`<option value="${escapeHTML(profile.id)}" ${profile.id===data.predictionProfile.id?'selected':''}>${escapeHTML(profileOptionLabel(profile))}</option>`).join('')}</select></label><label>View<select id="predictionDashboardViewMode"><option value="full">Full View</option><option value="compact">Compact View</option></select></label></div><div class="profile-fact-grid">${profileFact('Exam Name',data.predictionProfile.examName)}${profileFact('Course',data.predictionProfile.course)}${profileFact('Exam Date',formatProfileDate(data.predictionProfile.examDate))}${profileFact('Dashboard Status',updateLabel)}${profileFact('Last Updated',formatProfileDate(data.generatedAt))}${profileFact('Prediction Status',dashboardStatusLabel(data.overallStatus))}</div><p class="readiness-note" aria-live="polite">${escapeHTML(updateLabel)}</p>${renderPredictionDisclaimer()}<p class="readiness-note">${escapeHTML(support)}</p>${renderPredictionEvidence({items:sources})}</article>`}
function renderPredictionDashboardPage(){ensurePredictionDashboardShell();const root=$('#predictionDashboardContent');if(!root||!user())return;const profiles=getCurrentUserPredictionProfiles();if(!profiles.length){root.innerHTML='<div class="empty-state card"><h2>Create a Prediction Profile to use the Prediction Dashboard.</h2><button class="btn btn-primary" data-view="futureSuccess" type="button">Create Prediction Profile</button></div>';return bindPredictionDashboardControls(null)}let selectedId=getPredictionDashboardSelectedProfileId();if(!profiles.some(profile=>profile.id===selectedId))selectedId=profiles[0].id;setPredictionDashboardSelectedProfileId(selectedId);root.innerHTML='<div class="empty-state card"><h2>Loading Prediction Dashboard...</h2><p>Loading score prediction, chapter analysis, and recommended action...</p></div>';buildPredictionDashboardData({userId:predictionUserId(),predictionProfileId:selectedId}).then(data=>{if(!data.available){root.innerHTML=`<div class="empty-state card"><h2>${escapeHTML(data.reason||'Select a Prediction Profile.')}</h2></div>`;return}const mode=localStorage.getItem(`predictionDashboardViewMode:${predictionUserId()}`)||'full';root.classList.toggle('compact-dashboard',mode==='compact');root.innerHTML=renderPredictionDashboardHeader(data,profiles)+`<section class="prediction-dashboard-grid">${predictionDashboardCards(data)}</section>`+renderBestNextAction(data.bestNextAction)+renderPredictionDashboardAlerts(data.alerts)+renderPredictionDashboardQuickActions(data)+predictionDashboardHistory(data);const modeEl=$('#predictionDashboardViewMode');if(modeEl)modeEl.value=mode;bindPredictionDashboardControls(data);showNotification({type:data.overallStatus==='incomplete'?'warning':'information',message:data.overallStatus==='incomplete'?'Some dashboard results need more information.':'Prediction Dashboard updated.'})}).catch(error=>{console.error(error?.message||error);root.innerHTML='<div class="empty-state card"><h2>The Prediction Dashboard could not be fully loaded.</h2><p>One or more cards could not load. Try refreshing the dashboard.</p></div>';showNotification({type:'error',message:'The Prediction Dashboard could not be fully loaded.',persistent:true})})}
function renderPredictionDashboardQuickActions(data){const noLikely=!data.likelyScore||data.statuses.likelyScore!=='current';return `<article class="prediction-dashboard-actions card"><h2>Quick Actions</h2><div class="prediction-actions"><button class="btn btn-primary" data-dashboard-record-performance type="button">Record Performance</button><button class="btn btn-secondary" data-dashboard-recalculate-all type="button">${noLikely?'Calculate Likely Exam Score':'Recalculate Predictions'}</button><button class="btn btn-secondary" data-dashboard-generate-plan type="button">Generate Study Plan</button><button class="btn btn-secondary" data-dashboard-compare-plans type="button">Compare Study Plans</button><button class="btn btn-secondary" data-dashboard-edit-profile type="button">Edit Profile</button><button class="btn btn-secondary" data-dashboard-jump="history" type="button">View History</button></div></article>`}
async function recalculateDashboardPredictions(profileId){const profile=findPredictionProfile(profileId);if(!profile)return;await predictionUpdateManager.requestUpdate({userId:predictionUserId(),predictionProfileId:profileId,triggerType:PREDICTION_UPDATE_TRIGGERS.MANUAL_RECALCULATION,force:true});if(getLatestRecommendedStudyPlan(profileId)?.status==='outdated'){const ok=await confirmDialog({title:'Generate Updated Study Plan?',message:'Do you want to generate an updated recommended study plan now?',okText:'Generate Updated Plan',cancelText:'Not Now'});if(ok)await runRecommendedStudyPlanGeneration({confirmReplace:true})}}
function dashboardActionByFingerprint(data,fingerprint){return data?.bestNextAction?.fingerprint===fingerprint?data.bestNextAction:null}
function addDashboardActionToPlanner(data,action){if(!data||!action)return;const existing=getStudyPlannerTasksByProfile(data.predictionProfile.id).some(task=>task.source==='prediction-dashboard'&&task.dashboardActionFingerprint===action.fingerprint);if(existing)return showNotification({type:'information',message:'This action is already in your Study Planner.'});const plan={id:'p'+Date.now(),title:`${data.predictionProfile.examName} Dashboard Action`,course:data.predictionProfile.course,folderId:SYSTEM_FOLDER_ID,testDate:data.predictionProfile.examDate,minutesPerDay:action.durationMinutes||30,topics:[action.chapterName||data.predictionProfile.examName],createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),source:'prediction-dashboard',predictionProfileId:data.predictionProfile.id,dashboardActionFingerprint:action.fingerprint,days:[{dayNumber:1,date:today(),mainTopic:action.chapterName||data.predictionProfile.examName,subtopics:[action.assessmentCategory?assessmentCategoryLabel(action.assessmentCategory):'General review',action.title],taskType:action.title,practiceType:String(action.type||'dashboard action').replace(/-/g,' '),whatToStudy:action.title,stepByStepTask:`1. Prepare the notes or examples you need.\n2. ${action.title}\n3. Record any score or mistakes after you finish.`,practiceQuestions:action.title,mistakeCheck:'Review any incorrect answers and write what to fix next time.',miniReview:'Summarize the most important idea from this task.',estimatedMinutes:action.durationMinutes||30,completed:false,source:'prediction-dashboard',predictionProfileId:data.predictionProfile.id,chapterName:action.chapterName||'',assessmentCategory:action.assessmentCategory||'',activityType:action.type||'study-task',status:'incomplete',dashboardActionFingerprint:action.fingerprint}]};user().plans.unshift(qualityCheckStudyPlan(plan));markStudyWellBeingRecordOutdated();saveDB();renderPlannerPage();renderDashboard();renderPredictionDashboardPage();showNotification({type:'success',message:'Best Next Action added to your Study Planner.'})}
function startDashboardAction(data,action){const linked=action?.linkedPlannerTask;if(linked?.planId)return openPlanDetail(linked.planId);if(action?.planId)return openPlanDetail(action.planId);showNotification({type:'information',message:'Add this action to your Study Planner to open task details.'})}
function jumpPredictionDashboardDetail(target){showView('futureSuccess');setTimeout(()=>{const selector={likely:'.likely-score-card',probability:'.target-probability-card',chapterImpact:'.chapter-impact-card',readiness:'.current-readiness-card',confidence:'.prediction-confidence-card',history:'.performance-history-section'}[target]||'#predictionPerformancePanel';$(selector)?.scrollIntoView({behavior:'smooth',block:'start'})},0)}
function bindPredictionDashboardControls(data){const root=$('#predictionDashboardContent');$$('[data-view]',root).forEach(btn=>btn.onclick=()=>showView(btn.dataset.view));$('#predictionDashboardProfileSelect')?.addEventListener('change',e=>{setPredictionDashboardSelectedProfileId(e.target.value);renderPredictionDashboardPage();showNotification({type:'information',message:'Prediction Dashboard profile changed.'})});$('#predictionDashboardViewMode')?.addEventListener('change',e=>{localStorage.setItem(`predictionDashboardViewMode:${predictionUserId()}`,e.target.value);renderPredictionDashboardPage()});$('#dashboardRecordPerformanceBtn')?.addEventListener('click',()=>{showView('futureSuccess');setTimeout(()=>openPerformanceForm(),0)});$('#printPredictionDashboardBtn')?.addEventListener('click',()=>window.print());$$('[data-dashboard-record-performance]',root).forEach(btn=>btn.onclick=()=>{showView('futureSuccess');setTimeout(()=>openPerformanceForm(),0)});$$('[data-dashboard-calc]',root).forEach(btn=>btn.onclick=()=>{const id=data?.predictionProfile?.id;if(!id)return;predictionUpdateManager.requestUpdate({userId:predictionUserId(),predictionProfileId:id,triggerType:PREDICTION_UPDATE_TRIGGERS.MANUAL_RECALCULATION,force:true})});$$('[data-dashboard-jump]',root).forEach(btn=>btn.onclick=()=>jumpPredictionDashboardDetail(btn.dataset.dashboardJump));$$('[data-dashboard-edit-profile]',root).forEach(btn=>{btn.onclick=()=>{openPredictionProfile(data?.predictionProfile?.id);showView('futureSuccess')}});$$('[data-dashboard-recalculate-all]',root).forEach(btn=>btn.onclick=()=>recalculateDashboardPredictions(data.predictionProfile.id));$$('[data-dashboard-generate-plan]',root).forEach(btn=>btn.onclick=()=>{showView('futureSuccess');setTimeout(()=>runRecommendedStudyPlanGeneration({confirmReplace:true}),0)});$$('[data-dashboard-compare-plans]',root).forEach(btn=>btn.onclick=()=>jumpPredictionDashboardDetail('chapterImpact'));$$('[data-dashboard-full-plan]',root).forEach(btn=>btn.onclick=()=>{if(data?.recommendedPlan?.savedToPlannerPlanId)openPlanDetail(data.recommendedPlan.savedToPlannerPlanId);else showView('futureSuccess')});$$('[data-dashboard-add-action]',root).forEach(btn=>btn.onclick=()=>addDashboardActionToPlanner(data,dashboardActionByFingerprint(data,btn.dataset.dashboardAddAction)));$$('[data-dashboard-start-action]',root).forEach(btn=>btn.onclick=()=>startDashboardAction(data,dashboardActionByFingerprint(data,btn.dataset.dashboardStartAction)));$$('[data-dashboard-dismiss-action]',root).forEach(btn=>btn.onclick=()=>dismissDashboardAction(dashboardActionByFingerprint(data,btn.dataset.dashboardDismissAction),data.predictionProfile.id))}
const PREDICTION_UPDATE_TRIGGERS={QUIZ_COMPLETED:'quiz-completed',SCORE_ADDED:'score-added',SCORE_UPDATED:'score-updated',SCORE_DELETED:'score-deleted',STUDY_SESSION_COMPLETED:'study-session-completed',STUDY_SESSION_UPDATED:'study-session-updated',STUDY_TASK_COMPLETED:'study-task-completed',STUDY_TASK_REOPENED:'study-task-reopened',TARGET_GRADE_CHANGED:'target-grade-changed',CHAPTER_WEIGHT_CHANGED:'chapter-weight-changed',CATEGORY_WEIGHT_CHANGED:'category-weight-changed',EXAM_DATE_CHANGED:'exam-date-changed',CHAPTER_STRUCTURE_CHANGED:'chapter-structure-changed',WEAK_TOPIC_CHANGED:'weak-topic-changed',DAILY_TIME_UPDATE:'daily-time-update',MANUAL_RECALCULATION:'manual-recalculation'};
const PREDICTION_UPDATE_RULES={'quiz-completed':{startAt:'chapter-performance',includeConfidence:true,markPlanOutdated:true},'score-added':{startAt:'chapter-performance',includeConfidence:true,markPlanOutdated:true},'score-updated':{startAt:'chapter-performance',includeConfidence:true,markPlanOutdated:true},'score-deleted':{startAt:'chapter-performance',includeConfidence:true,markPlanOutdated:true},'study-session-completed':{startAt:'exam-readiness',includeConfidence:false,markPlanOutdated:false},'study-session-updated':{startAt:'exam-readiness',includeConfidence:false,markPlanOutdated:false},'study-task-completed':{startAt:'exam-readiness',includeConfidence:false,markPlanOutdated:false},'study-task-reopened':{startAt:'exam-readiness',includeConfidence:false,markPlanOutdated:false},'target-grade-changed':{startAt:'target-probability',includeConfidence:false,markPlanOutdated:true},'chapter-weight-changed':{startAt:'likely-exam-score',includeConfidence:false,markPlanOutdated:true},'category-weight-changed':{startAt:'exam-readiness',includeConfidence:false,markPlanOutdated:true},'exam-date-changed':{startAt:'exam-readiness',includeConfidence:false,markPlanOutdated:true},'chapter-structure-changed':{startAt:'chapter-performance',includeConfidence:true,markPlanOutdated:true},'weak-topic-changed':{startAt:'highest-impact-chapter',includeConfidence:false,markPlanOutdated:true},'daily-time-update':{startAt:'exam-readiness',includeConfidence:false,markPlanOutdated:true},'manual-recalculation':{startAt:'chapter-performance',includeConfidence:true,markPlanOutdated:false}};
const PREDICTION_PIPELINE_STEPS=[{key:'chapter-performance',order:1},{key:'exam-readiness',order:2},{key:'likely-exam-score',order:3},{key:'target-probability',order:4},{key:'highest-impact-chapter',order:5},{key:'prediction-confidence',order:6},{key:'dashboard-refresh',order:7}];
function predictionUpdateHistoryStorageKey(){return isGuestMode()?GUEST_PREDICTION_UPDATE_HISTORY_KEY:PREDICTION_UPDATE_HISTORY_KEY}
function predictionDailyUpdateStorageKey(){return isGuestMode()?GUEST_PREDICTION_DAILY_UPDATE_STATE_KEY:PREDICTION_DAILY_UPDATE_STATE_KEY}
function predictionAutoUpdateSettingsStorageKey(){return isGuestMode()?GUEST_PREDICTION_AUTO_UPDATE_SETTINGS_KEY:PREDICTION_AUTO_UPDATE_SETTINGS_KEY}
function getPredictionUpdateHistory(){try{const rows=JSON.parse(localStorage.getItem(predictionUpdateHistoryStorageKey()))||[];return Array.isArray(rows)?rows.filter(row=>row.userId===predictionUserId()):[]}catch{return[]}}
function savePredictionUpdateHistory(rows){const key=predictionUpdateHistoryStorageKey(),userId=predictionUserId();let all=[];try{all=JSON.parse(localStorage.getItem(key))||[]}catch{all=[]}const mine=(Array.isArray(rows)?rows:[]).filter(row=>row.userId===userId).slice(0,50),others=Array.isArray(all)?all.filter(row=>row.userId!==userId):[];localStorage.setItem(key,JSON.stringify([...mine,...others]))}
function deleteOldPredictionUpdateRecords(){savePredictionUpdateHistory(getPredictionUpdateHistory().sort((a,b)=>new Date(b.startedAt)-new Date(a.startedAt)).slice(0,50))}
function getLatestPredictionUpdate(profileId){return getPredictionUpdateHistory().filter(row=>row.predictionProfileId===profileId).sort((a,b)=>new Date(b.completedAt||b.startedAt)-new Date(a.completedAt||a.startedAt))[0]||null}
function createPredictionUpdateRecord(result,fingerprint){return {id:result.updateId||'prediction-update-'+Date.now(),userId:predictionUserId(),predictionProfileId:result.predictionProfileId,triggerTypes:result.triggerTypes||[result.triggerType].filter(Boolean),sourceRecordIds:result.sourceRecordIds||[result.sourceRecordId].filter(Boolean),pipelineStart:result.pipelineStart||'',updatedSteps:result.updatedSteps||[],skippedSteps:result.skippedSteps||[],failedStep:result.failedStep||null,status:result.status||'completed',dataFingerprint:fingerprint||result.dataFingerprint||'',calculationSource:result.triggerTypes?.includes(PREDICTION_UPDATE_TRIGGERS.MANUAL_RECALCULATION)?'manual-update':'automatic-update',safetyRulesVersion:PREDICTION_SAFETY_RULES_VERSION,startedAt:result.startedAt||new Date().toISOString(),completedAt:result.completedAt||new Date().toISOString(),prototypeOnly:true}}
function stableHash(text){let hash=2166136261;for(let i=0;i<String(text).length;i++){hash^=String(text).charCodeAt(i);hash+=(hash<<1)+(hash<<4)+(hash<<7)+(hash<<8)+(hash<<24)}return (hash>>>0).toString(16)}
function createPredictionDataFingerprint({predictionProfile,performanceEntries,studyTasks,rulesVersions={},localDate=today()}){const source={predictionProfileId:predictionProfile?.id,targetGrade:predictionProfile?.targetGrade,examDate:predictionProfile?.examDate,chapterWeights:(predictionProfile?.chapters||[]).map(ch=>({id:ch.id,name:ch.name,examWeightPercent:ch.examWeightPercent,importance:ch.importance,weakTopics:ch.weakTopics})),assessmentCategoryWeights:predictionProfile?.assessmentCategoryWeights,studyAvailability:predictionProfile?.studyAvailability,performance:(performanceEntries||[]).map(entry=>({id:entry.id,score:entry.score,questionsCorrect:entry.questionsCorrect,totalQuestions:entry.totalQuestions,chapterId:entry.chapterId,assessmentCategory:entry.assessmentCategory,activityType:entry.activityType,date:entry.date,completed:entry.completed,timeSpentMinutes:entry.timeSpentMinutes,updatedAt:entry.updatedAt})).sort((a,b)=>String(a.id).localeCompare(String(b.id))),taskCompletion:(studyTasks||[]).map(task=>({id:task.id||`${task.planId}:${task.dayNumber}`,status:task.status||'',completed:!!task.completed,actualMinutes:task.actualMinutes||task.estimatedMinutes||0,completedAt:task.completedAt||'',updatedAt:task.updatedAt||''})).sort((a,b)=>String(a.id).localeCompare(String(b.id))),rulesVersions,localDate};return stableHash(JSON.stringify(source))}
function predictionRulesVersions(){return {predictionData:appData.predictionDataRules?.rulesVersion||1,readiness:appData.examReadinessRules?.rulesVersion||1,target:appData.targetProbabilityRules?.rulesVersion||1,confidence:appData.predictionConfidenceRules?.rulesVersion||1,impact:appData.studyImpactRules?.rulesVersion||1,recommendedPlan:appData.recommendedStudyPlanRules?.rulesVersion||1}}
function getPredictionStepIndex(key){const index=PREDICTION_PIPELINE_STEPS.findIndex(step=>step.key===key);return index<0?0:index}
function selectEarliestPipelineStart(triggerTypes){const starts=(triggerTypes||[]).map(trigger=>PREDICTION_UPDATE_RULES[trigger]?.startAt).filter(Boolean);return starts.sort((a,b)=>getPredictionStepIndex(a)-getPredictionStepIndex(b))[0]||null}
function getPredictionUpdateQueueKey({userId,predictionProfileId}){return [userId,predictionProfileId].join(':')}
function predictionAutoSettings(){const defaults={userId:predictionUserId(),enabled:true,showNotifications:true,updatedAt:new Date().toISOString()};try{const stored=JSON.parse(localStorage.getItem(predictionAutoUpdateSettingsStorageKey()));if(Array.isArray(stored))return {...defaults,...(stored.find(row=>row.userId===predictionUserId())||{})};if(stored&&stored.userId===predictionUserId())return {...defaults,...stored};return defaults}catch{return defaults}}
function savePredictionAutoSettings(settings){const key=predictionAutoUpdateSettingsStorageKey(),userId=predictionUserId(),next={userId,enabled:settings.enabled!==false,showNotifications:settings.showNotifications!==false,updatedAt:new Date().toISOString()};let rows=[];try{const stored=JSON.parse(localStorage.getItem(key));rows=Array.isArray(stored)?stored:(stored?[stored]:[])}catch{rows=[]}rows=[next,...rows.filter(row=>row.userId!==userId)];localStorage.setItem(key,JSON.stringify(rows));return next}
function getPredictionDailyUpdateState(userId=predictionUserId()){try{const stored=JSON.parse(localStorage.getItem(predictionDailyUpdateStorageKey()))||{};return stored.userId===userId?stored:{userId,lastCheckedDate:null,profileUpdates:{}}}catch{return {userId,lastCheckedDate:null,profileUpdates:{}}}}
function savePredictionDailyUpdateState(state){localStorage.setItem(predictionDailyUpdateStorageKey(),JSON.stringify({...state,userId:predictionUserId()}))}
function getActivePredictionProfiles(){return getCurrentUserPredictionProfiles().filter(profile=>['future','today'].includes(getDashboardDaysRemaining(profile.examDate).status))}
function getCurrentPredictionUpdateStatus(profileId){const key=getPredictionUpdateQueueKey({userId:predictionUserId(),predictionProfileId:profileId});if(predictionUpdateManager?.activeUpdates?.has(key))return 'calculating';if(predictionUpdateManager?.pendingUpdates?.has(key))return 'queued';const latest=getLatestPredictionUpdate(profileId);return latest?.status||''}
function didPredictionRelevantScoreDataChange(previousEntry,updatedEntry){const fields=['score','questionsCorrect','correctAnswers','totalQuestions','chapterId','chapter','assessmentCategory','activityType','date','completed','timeSpentMinutes'];return fields.some(field=>previousEntry?.[field]!==updatedEntry?.[field])}
function profileUpdateTriggers(previous,next){if(!previous||!next)return [PREDICTION_UPDATE_TRIGGERS.CHAPTER_STRUCTURE_CHANGED];const triggers=[];if(Number(previous.targetGrade)!==Number(next.targetGrade))triggers.push(PREDICTION_UPDATE_TRIGGERS.TARGET_GRADE_CHANGED);if(previous.examDate!==next.examDate)triggers.push(PREDICTION_UPDATE_TRIGGERS.EXAM_DATE_CHANGED);if(JSON.stringify((previous.chapters||[]).map(ch=>({id:ch.id,name:ch.name,weight:ch.examWeightPercent,importance:ch.importance})))!==JSON.stringify((next.chapters||[]).map(ch=>({id:ch.id,name:ch.name,weight:ch.examWeightPercent,importance:ch.importance}))))triggers.push(PREDICTION_UPDATE_TRIGGERS.CHAPTER_WEIGHT_CHANGED);if((previous.chapters||[]).length!==(next.chapters||[]).length)triggers.push(PREDICTION_UPDATE_TRIGGERS.CHAPTER_STRUCTURE_CHANGED);if(JSON.stringify((previous.chapters||[]).map(ch=>ch.weakTopics||[]))!==JSON.stringify((next.chapters||[]).map(ch=>ch.weakTopics||[])))triggers.push(PREDICTION_UPDATE_TRIGGERS.WEAK_TOPIC_CHANGED);if(JSON.stringify(previous.assessmentCategoryWeights)!==JSON.stringify(next.assessmentCategoryWeights))triggers.push(PREDICTION_UPDATE_TRIGGERS.CATEGORY_WEIGHT_CHANGED);if(JSON.stringify(previous.studyAvailability)!==JSON.stringify(next.studyAvailability))triggers.push(PREDICTION_UPDATE_TRIGGERS.EXAM_DATE_CHANGED);return [...new Set(triggers)]}
function metadataForPredictionUpdate(updateId,triggerTypes){return {calculationSource:triggerTypes?.includes(PREDICTION_UPDATE_TRIGGERS.MANUAL_RECALCULATION)?'manual-update':'automatic-update',updateTriggerTypes:triggerTypes||[],predictionUpdateId:updateId,safetyRulesVersion:PREDICTION_SAFETY_RULES_VERSION}}
function updateLatestPredictionRecordMetadata(profileId,stepKey,meta){const update=(getter,saver)=>{const rows=getter(),row=rows.filter(item=>item.predictionProfileId===profileId).sort((a,b)=>new Date(b.calculatedAt)-new Date(a.calculatedAt))[0];if(row){Object.assign(row,meta);saver(rows)}};if(stepKey==='exam-readiness')update(getExamReadinessHistory,saveExamReadinessHistory);if(stepKey==='likely-exam-score')update(getLikelyExamScoreHistory,saveLikelyExamScoreHistory);if(stepKey==='target-probability')update(getTargetProbabilityHistory,saveTargetProbabilityHistory);if(stepKey==='highest-impact-chapter')update(getChapterImpactHistory,saveChapterImpactHistory);if(stepKey==='prediction-confidence')update(getPredictionConfidenceHistory,savePredictionConfidenceHistory)}
function markDependentStepsUnavailable({stepKey,predictionProfileId,reason}){if(['exam-readiness','likely-exam-score'].includes(stepKey))markLikelyExamScoreOutdated(predictionProfileId);if(['target-probability'].includes(stepKey))markTargetProbabilityOutdated(predictionProfileId);if(['highest-impact-chapter'].includes(stepKey))markChapterImpactOutdated(predictionProfileId);return reason}
function markPredictionArtifactsOutdated(profileId,{markPlanOutdated=false}={}){markStudyImpactSimulationsOutdated(profileId);markStudyScenarioComparisonOutdated(profileId);if(markPlanOutdated)markRecommendedStudyPlanOutdated(profileId)}
function refreshPredictionDashboard({predictionProfileId}={}){renderFutureSuccessPage();if($('#predictionDashboardView')?.classList.contains('active'))renderPredictionDashboardPage();renderDashboard();renderProgress();return {success:true,predictionProfileId}}
const predictionCalculationService={async runStep({stepKey,predictionProfileId,triggerTypes,updateId}){if(stepKey==='chapter-performance'){const profile=findPredictionProfile(predictionProfileId),metrics=predictionMetrics(predictionProfileId);return {success:!!profile,record:profile?calculateChapterPerformance(profile,metrics.entries):null,reason:profile?'':'Prediction Profile not found.'}}let record=null;if(stepKey==='exam-readiness')record=calculateAndSaveExamReadiness(predictionProfileId,{updated:!!getLatestExamReadiness(predictionProfileId)});if(stepKey==='likely-exam-score')record=calculateAndSaveLikelyExamScore(predictionProfileId,{updated:!!getLatestLikelyExamScore(predictionProfileId)});if(stepKey==='target-probability')record=calculateAndSaveTargetProbability(predictionProfileId,{updated:!!getLatestTargetProbability(predictionProfileId)});if(stepKey==='highest-impact-chapter')record=calculateAndSaveChapterImpact(predictionProfileId,{updated:!!getLatestChapterImpact(predictionProfileId)});if(stepKey==='prediction-confidence')record=calculateAndSavePredictionConfidence(predictionProfileId,{updated:!!getLatestPredictionConfidence(predictionProfileId)});if(stepKey==='dashboard-refresh')return refreshPredictionDashboard({predictionProfileId});if(!record)return {success:true,dependencyMissing:true,reason:'More information is needed for this prediction step.'};updateLatestPredictionRecordMetadata(predictionProfileId,stepKey,metadataForPredictionUpdate(updateId,triggerTypes));return {success:true,record}}};
async function runPredictionUpdatePipeline({userId,predictionProfileId,triggerType,triggerTypes=[triggerType],sourceRecordId,sourceRecordIds=[sourceRecordId].filter(Boolean),calculationService=predictionCalculationService,force=false}){const start=selectEarliestPipelineStart(triggerTypes)||PREDICTION_UPDATE_RULES[triggerType]?.startAt;if(!start)return {success:false,reason:'Unsupported prediction update trigger.'};const profile=findPredictionProfile(predictionProfileId);if(!profile)return {success:false,reason:'Prediction Profile not found.'};const rule={startAt:start,includeConfidence:triggerTypes.some(t=>PREDICTION_UPDATE_RULES[t]?.includeConfidence),markPlanOutdated:triggerTypes.some(t=>PREDICTION_UPDATE_RULES[t]?.markPlanOutdated)},fingerprint=createPredictionDataFingerprint({predictionProfile:profile,performanceEntries:getPerformanceEntriesForProfile(predictionProfileId),studyTasks:getStudyPlannerTasksByProfile(predictionProfileId),rulesVersions:predictionRulesVersions(),localDate:today()}),latest=getLatestPredictionUpdate(predictionProfileId),updateId='prediction-update-'+Date.now(),result={success:true,updateId,triggerType,triggerTypes,sourceRecordId,sourceRecordIds,predictionProfileId,pipelineStart:start,updatedSteps:[],skippedSteps:[],failedStep:null,startedAt:new Date().toISOString(),dataFingerprint:fingerprint};if(!force&&latest?.dataFingerprint===fingerprint&&latest.status==='completed'){refreshPredictionDashboard({predictionProfileId});return {...result,status:'skipped-duplicate',success:true,completedAt:new Date().toISOString()}}try{const startIndex=getPredictionStepIndex(start);predictionUpdateNotificationsMuted=true;for(let index=startIndex;index<PREDICTION_PIPELINE_STEPS.length;index+=1){const step=PREDICTION_PIPELINE_STEPS[index];if(step.key==='prediction-confidence'&&rule.includeConfidence===false){result.skippedSteps.push(step.key);continue}const stepResult=await calculationService.runStep({stepKey:step.key,userId,predictionProfileId,triggerType,triggerTypes,updateId});if(stepResult?.dependencyMissing){result.skippedSteps.push(step.key);markDependentStepsUnavailable({stepKey:step.key,predictionProfileId,reason:stepResult.reason});continue}if(stepResult?.success===false){result.failedStep=step.key;result.success=false;break}result.updatedSteps.push(step.key)}predictionUpdateNotificationsMuted=false;if(rule.markPlanOutdated){markRecommendedStudyPlanOutdated(predictionProfileId);markPredictionArtifactsOutdated(predictionProfileId,{markPlanOutdated:true})}await refreshPredictionDashboard({userId,predictionProfileId});result.completedAt=new Date().toISOString();result.status=result.success?(result.skippedSteps.length?'partially-completed':'completed'):'failed';const history=[createPredictionUpdateRecord(result,fingerprint),...getPredictionUpdateHistory()];savePredictionUpdateHistory(history);deleteOldPredictionUpdateRecords();return result}catch(error){predictionUpdateNotificationsMuted=false;return {...result,success:false,status:'failed',failedStep:result.failedStep||'unknown',errorMessage:error instanceof Error?error.message:'Prediction update failed.',completedAt:new Date().toISOString()}}finally{predictionUpdateNotificationsMuted=false}}
const basePredictionUpdatePipeline=runPredictionUpdatePipeline;runPredictionUpdatePipeline=async function(args){const result=await basePredictionUpdatePipeline(args);if(result&&!result.success&&result.predictionProfileId){const latest=getLatestPredictionUpdate(result.predictionProfileId);if(latest?.id!==result.updateId){savePredictionUpdateHistory([createPredictionUpdateRecord(result,result.dataFingerprint),...getPredictionUpdateHistory()]);deleteOldPredictionUpdateRecords()}}return result};
class PredictionUpdateManager{constructor({storage=null,calculationService=predictionCalculationService,notificationService=showNotification}={}){this.storage=storage;this.calculationService=calculationService;this.notificationService=notificationService;this.pendingUpdates=new Map();this.activeUpdates=new Map()}async requestUpdate({userId=predictionUserId(),predictionProfileId,triggerType,sourceRecordId=null,force=false}={}){if(!userId||!predictionProfileId||!triggerType)return {success:false,reason:'Invalid prediction update request.'};const rule=PREDICTION_UPDATE_RULES[triggerType];if(!rule)return {success:false,reason:'Unsupported prediction update trigger.'};const settings=predictionAutoSettings();if(settings.enabled===false&&!force&&triggerType!==PREDICTION_UPDATE_TRIGGERS.MANUAL_RECALCULATION){markPredictionArtifactsOutdated(predictionProfileId,{markPlanOutdated:rule.markPlanOutdated});refreshPredictionDashboard({predictionProfileId});this.notificationService({type:'information',message:'Prediction data changed. Recalculate when ready.',actionLabel:'Recalculate Predictions',onAction:()=>this.requestUpdate({userId,predictionProfileId,triggerType:PREDICTION_UPDATE_TRIGGERS.MANUAL_RECALCULATION,force:true})});return {success:true,status:'queued',reason:'Automatic updates are off.'}}const key=getPredictionUpdateQueueKey({userId,predictionProfileId});return new Promise(resolve=>{const existing=this.pendingUpdates.get(key)||{userId,predictionProfileId,triggerTypes:new Set(),sourceRecordIds:new Set(),force:false,resolvers:[],timer:null};existing.triggerTypes.add(triggerType);if(sourceRecordId)existing.sourceRecordIds.add(sourceRecordId);existing.force=existing.force||force;existing.resolvers.push(resolve);clearTimeout(existing.timer);existing.timer=setTimeout(()=>this.flushUpdate(key),700);this.pendingUpdates.set(key,existing);refreshPredictionDashboard({predictionProfileId})})}async flushUpdate(key){const queued=this.pendingUpdates.get(key);if(!queued)return;if(this.activeUpdates.has(key)){queued.timer=setTimeout(()=>this.flushUpdate(key),700);return}this.pendingUpdates.delete(key);this.activeUpdates.set(key,queued);refreshPredictionDashboard({predictionProfileId:queued.predictionProfileId});let result;try{result=await runPredictionUpdatePipeline({userId:queued.userId,predictionProfileId:queued.predictionProfileId,triggerType:[...queued.triggerTypes][0],triggerTypes:[...queued.triggerTypes],sourceRecordIds:[...queued.sourceRecordIds],calculationService:this.calculationService,force:queued.force});this.notifyResult(result)}catch(error){result={success:false,status:'failed',errorMessage:error?.message||'Prediction update failed.'};this.notificationService({type:'error',message:'Your exam prediction could not be updated. Your saved performance data was not lost.',persistent:true,actionLabel:'Try Again',onAction:()=>this.requestUpdate({userId:queued.userId,predictionProfileId:queued.predictionProfileId,triggerType:PREDICTION_UPDATE_TRIGGERS.MANUAL_RECALCULATION,force:true})})}finally{this.activeUpdates.delete(key);queued.resolvers.forEach(resolve=>resolve(result));if(this.pendingUpdates.has(key))this.flushUpdate(key)}}notifyResult(result){const settings=predictionAutoSettings();if(result?.status==='skipped-duplicate')return;if(result?.success&&result.status==='completed'){if(settings.showNotifications!==false)this.notificationService({type:'success',message:'Your exam prediction has been updated.'});return}if(result?.success&&result.status==='partially-completed'){this.notificationService({type:'warning',message:'Your exam prediction was partially updated. More information is needed for some results.',persistent:true});return}if(result?.success&&result.updatedSteps?.length===0){this.notificationService({type:'information',message:'Your records were saved, but more data is needed to calculate every prediction.'});return}if(!result?.success)this.notificationService({type:'error',message:'Your exam prediction could not be updated. Your saved performance data was not lost.',persistent:true})}}
const predictionUpdateManager=new PredictionUpdateManager({calculationService:predictionCalculationService,notificationService:showNotification});
async function runDailyPredictionUpdates({userId=predictionUserId(),currentDate=new Date()}={}){if(!userId)return {updated:false,reason:'No active user.'};const todayKey=formatDateKey(currentDate),state=getPredictionDailyUpdateState(userId);if(state?.lastCheckedDate===todayKey)return {updated:false,reason:'Daily update already completed.'};const profiles=getActivePredictionProfiles(userId),results=[];for(const profile of profiles){const days=getDashboardDaysRemaining(profile.examDate,currentDate);if(days.status==='future'||days.status==='today')results.push(await predictionUpdateManager.requestUpdate({userId,predictionProfileId:profile.id,triggerType:PREDICTION_UPDATE_TRIGGERS.DAILY_TIME_UPDATE}))}savePredictionDailyUpdateState({userId,lastCheckedDate:todayKey,profileUpdates:Object.fromEntries(profiles.map(profile=>[profile.id,todayKey]))});return {updated:results.length>0,results}}
function ensurePredictionAutoSettingsPanel(){const layout=$('#settingsView .settings-layout');if(!layout||$('#predictionAutoUpdateSettingsCard'))return;layout.insertAdjacentHTML('beforeend','<form id="predictionAutoUpdateSettingsCard" class="card settings-card"><div class="card-head"><div><h3>Prediction Updates</h3><p>Control when StudySpark updates exam predictions after saved changes.</p></div></div><label>Automatically Update Predictions<select id="predictionAutoUpdateToggle"><option value="on">On</option><option value="off">Off</option></select></label><label>Show Automatic Update Notifications<select id="predictionAutoNotifyToggle"><option value="on">On</option><option value="off">Off</option></select></label><p class="readiness-note">Predictions are estimates based on recorded data and may change as new information is added.</p><button class="btn btn-primary" id="savePredictionAutoSettingsBtn" type="submit">Save Prediction Update Settings</button></form>');$('#predictionAutoUpdateSettingsCard')?.addEventListener('submit',e=>{e.preventDefault();savePredictionAutoSettings({enabled:$('#predictionAutoUpdateToggle')?.value!=='off',showNotifications:$('#predictionAutoNotifyToggle')?.value!=='off'});showNotification({type:'success',message:'Prediction update settings saved.'})})}
function renderPredictionAutoSettingsPanel(){ensurePredictionAutoSettingsPanel();const settings=predictionAutoSettings();if($('#predictionAutoUpdateToggle'))$('#predictionAutoUpdateToggle').value=settings.enabled===false?'off':'on';if($('#predictionAutoNotifyToggle'))$('#predictionAutoNotifyToggle').value=settings.showNotifications===false?'off':'on'}
function ensureAutomaticPredictionUpdateInstructions(){const grid=$('#instructionsView .instruction-grid');if(!grid||$('#automaticPredictionUpdatesInstruction'))return;grid.insertAdjacentHTML('beforeend','<article class="folder-instructions" id="automaticPredictionUpdatesInstruction"><span>34</span><div><h3>Automatic Prediction Updates</h3><p>Predictions update after meaningful saved changes. Completing a quiz or adding a score updates performance-based predictions. Completing a study session or task updates preparation-based predictions. Changing the target grade updates target probability, and changing weights updates weighted score calculations. Days Remaining updates once per calendar day. Calculations run in dependency order and never use unsaved form changes. Automatic recalculation does not replace saved Study Plans or Study Scenarios, although older plans may be marked Outdated. Students may turn automatic updates off in settings, and the Recalculate Predictions button remains available. Saved performance data remains safe if a calculation fails. Your exam prediction has been updated. Predictions are estimates based on recorded data and may change as new information is added.</p></div></article>')}
function ensurePredictionSafetyInstructions(){const grid=$('#instructionsView .instruction-grid');if(!grid||$('#predictionSafetyInstruction'))return;grid.insertAdjacentHTML('beforeend',`<article class="folder-instructions" id="predictionSafetyInstruction"><span>35</span><div><h3>Prediction Safety and Accuracy</h3><p>All predictions are estimates based on recorded information. The app never guarantees an exam result, only uses the student's recorded data, and shows unavailable states when missing information would make a prediction unsupported. Students can edit incorrect scores, chapters, assessment categories, target grade, weights, study availability, and weak topics, then recalculate. Prediction Confidence measures available evidence, not proof. Recommended Study Plans and Study Scenarios are suggestions, not guarantees. Automatic updates occur after important saved changes. Student prediction data remains private and is not used in public profiles, Study Match, shared groups, partner searches, or public dashboards. ${PREDICTION_DISCLAIMER} ${predictionMessage('belowTarget','Your current prediction is below your target, but improving your highest-impact chapter could make the biggest difference.')}</p></div></article>`)}
function mutedPredictionMutation(action){const previous=predictionUpdateNotificationsMuted;predictionUpdateNotificationsMuted=true;try{return action()}finally{predictionUpdateNotificationsMuted=previous}}
function savePredictionProfileRecord(data){return data.id?mutedPredictionMutation(()=>updatePredictionProfile(data.id,data)):createPredictionProfile(data)}
function savePerformanceRecord(activeId,data,profile,options){return mutedPredictionMutation(()=>activeId?updatePerformanceEntry(activeId,data,profile,options):createPerformanceEntry(data,profile,options))}
function deletePerformanceEntryMuted(id){return mutedPredictionMutation(()=>deletePerformanceEntry(id))}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&user()){runDailyPredictionUpdates({userId:predictionUserId()});refreshStudyTaskCompletionIfDueDatesChanged();refreshStudyTimePatternsIfChanged();refreshSessionLengthPatternsIfChanged()}});
document.addEventListener('click',event=>{const btn=event.target.closest?.('[data-recalculate-readiness],[data-recalculate-likely-score],[data-recalculate-target-probability],[data-recalculate-chapter-impact],[data-recalculate-prediction-confidence]');if(!btn||btn.disabled)return;const profile=selectedPredictionProfile();if(!profile)return;event.preventDefault();event.stopImmediatePropagation();predictionUpdateManager.requestUpdate({userId:predictionUserId(),predictionProfileId:profile.id,triggerType:PREDICTION_UPDATE_TRIGGERS.MANUAL_RECALCULATION,force:true})},true);
function savePredictionProfileFromForm(){const data=collectPredictionProfileForm(),validation=validatePredictionProfile(data),weightStatus=getChapterWeightStatus(data.chapters),categoryStatus=getAssessmentCategoryWeightStatus(data.assessmentCategoryWeights);showPredictionErrors(validation.errors);if(!validation.valid){if(validation.errors.assessmentWeightTotal)showNotification({type:'warning',message:'Assessment category weights must add up to 100%.'});else if(validation.errors.chapterWeightTotal||validation.errors.predictionChapters)showNotification({type:'warning',message:weightStatus.total<100?`${weightStatus.difference}% of the exam weight still needs to be assigned.`:weightStatus.total>100?`Chapter weights are ${weightStatus.difference}% over the limit.`:validation.errors.predictionChapters||'Chapter exam weights must add up to 100%.'});else if(!categoryStatus.valid)showNotification({type:'warning',message:'Assessment category weights must add up to 100%.'});return false}try{const previous=data.id?findPredictionProfile(data.id):null,saved=savePredictionProfileRecord(data);if(!saved)throw new Error('Save failed');sessionStorage.setItem('selectedPredictionProfileId',saved.id);renderPredictionProfiles();fillPredictionForm(saved);showNotification({type:'success',message:'Prediction profile saved successfully.',important:true});const triggers=profileUpdateTriggers(previous,saved);triggers.forEach(triggerType=>predictionUpdateManager.requestUpdate({userId:predictionUserId(),predictionProfileId:saved.id,triggerType,sourceRecordId:saved.id}));if(saved.assessmentWeightSource==='student-estimate')showNotification({type:'warning',message:'These category weights are student estimates.'});if(saved.chapters.some(ch=>ch.weightSource==='student-estimate'))showNotification({type:'warning',message:'These exam weights are student estimates.'});if(Number(data.targetGrade)<Number(data.currentGrade))showNotification({type:'information',message:'Your target grade is below your current grade.'});return true}catch(error){console.error(error?.message||error);showNotification({type:'error',message:'Prediction profile could not be saved.'});return false}}
function openPredictionProfile(id){const profile=findPredictionProfile(id);if(!profile)return showNotification({type:'error',message:'Prediction profile could not be loaded.'});sessionStorage.setItem('selectedPredictionProfileId',id);fillPredictionForm(profile);renderPredictionPerformancePanel();showNotification({type:'information',message:'Prediction profile loaded.'});$('#predictionPerformancePanel')?.scrollIntoView({behavior:'smooth',block:'start'})}
function editPredictionProfile(id){openPredictionProfile(id);setTimeout(()=>$('#predictionExamName')?.focus(),0)}
