function targetProbabilityImprovements(record){const items=[];if(Number(record.completedPracticeCount)<Number(record.practiceTargetCount))items.push(`Complete ${Math.min(5,record.practiceTargetCount-record.completedPracticeCount)} more practice activities.`);if(Number(record.factors?.studyConsistency?.score)<70)items.push('Improve study consistency before the exam.');if((record.weakChapters||[]).length)items.push(`Record more ${record.weakChapters[0]} practice.`);if(record.rangePosition&&record.rangePosition.includes('above-range'))items.push('Review high-weight questions tied to your weakest assessment category.');if(Number(record.factors?.recentImprovement?.score)<70)items.push('Add more recent scored activities.');if(record.highPriorityDataGapCount>0)items.push('Update missing chapter data.');return items.length?items:['Keep recording scores, completed practice, and study activity to refine this estimate.']}
function calculateHypotheticalTargetProbability(targetGrade,record){const gap=calculateScoreGapFactor({targetGrade,centralEstimate:record.estimatedExamScore,estimatedRange:record.estimatedRange}),result=calculateTargetProbability({scoreGapFactor:gap.score,recentImprovementFactor:record.factors?.recentImprovement?.score,studyConsistencyFactor:record.factors?.studyConsistency?.score,timeRemainingFactor:calculateTargetTimeFactor(record.daysRemaining,gap.scoreGap),weakChapterFactor:record.factors?.weakChapters?.score,completedPracticeFactor:record.factors?.completedPractice?.score,factorWeights:targetProbabilityRules().factorWeights});return result.available?Math.round(result.probability):null}
function targetScenarioSection(record){const current=Number(record.targetGrade);if(!Number.isFinite(current)||record.status!=='current')return'';const targets=[Math.max(0,current-5),current,Math.min(100,current+5)],rows=targets.map(target=>{const probability=calculateHypotheticalTargetProbability(target,record);return profileFact(`Target ${target}%`,probability===null?'Not Available':probability+'% probability')}).join('');return `<section class="chapter-insights target-scenarios"><h4>Hypothetical Comparison</h4><div class="profile-fact-grid">${rows}</div><p>These comparisons are previews only and are not saved as official predictions.</p></section>`}
function renderTargetProbability(profile,readiness){const metrics=readiness.metrics,likely=getLatestLikelyExamScore(profile.id),readinessRecord=currentExamReadinessForLikely(profile,readiness),latest=getLatestTargetProbability(profile.id),current=targetProbabilityRecordIsCurrent(latest,profile,metrics,likely,readinessRecord)?latest:null,preview=createTargetProbabilityRecord(profile,readiness,likely,readinessRecord);if(preview.status!=='current')return `<article class="current-readiness-card target-probability-card not-ready"><div class="card-head"><div><span class="status-badge status-pending">Not Available</span><h3>Probability of Reaching Target</h3><p>More recorded data is needed before the probability of reaching the target can be estimated.</p></div><button class="btn btn-primary" data-recalculate-target-probability type="button" disabled>Recalculate Probability</button></div><div class="readiness-main-score"><b>Not Available</b><span>Current Probability</span></div><ul class="missing-readiness">${preview.missingRequirements.map(item=>`<li>${escapeHTML(item)}</li>`).join('')}</ul><p class="readiness-note">This is an estimate based on recorded activity and performance. It is not guaranteed.</p><p class="readiness-note">This probability is produced by a rule-based planning model. It is not a scientifically validated prediction.</p>${latest?`<section class="readiness-breakdown"><h4>Target Probability History</h4><div class="readiness-history">${targetProbabilityHistoryList(profile.id)}</div></section>`:''}</article>`;if(!current)return `<article class="current-readiness-card target-probability-card ready"><div class="card-head"><div><span class="status-badge status-active">Ready</span><h3>Probability of Reaching Target</h3><p>${latest?'Your target probability needs to be recalculated.':'Enough data is available. Select Calculate Probability to create the first estimate.'}</p></div><button class="btn btn-primary" data-recalculate-target-probability type="button">${latest?'Recalculate Probability':'Calculate Probability'}</button></div><div class="readiness-main-score"><b>Not Available</b><span>Current Probability</span></div><p class="readiness-note">This is an estimate based on recorded activity and performance. It is not guaranteed.</p><p class="readiness-note">This probability is produced by a rule-based planning model. It is not a scientifically validated prediction.</p>${latest?`<section class="readiness-breakdown"><h4>Target Probability History</h4><div class="readiness-history">${targetProbabilityHistoryList(profile.id)}</div></section>`:''}</article>`;const supporting=targetProbabilitySupportingFactors(current),challenges=targetProbabilityChallenges(current,profile),improvements=targetProbabilityImprovements(current);return `<article class="current-readiness-card target-probability-card target-probability-${escapeHTML(current.labelKey)}"><div class="card-head"><div><span class="status-badge status-active">${escapeHTML(current.label)}</span><h3>Probability of Reaching Target</h3><p>Last calculated ${escapeHTML(formatProfileDate(current.calculatedAt))}.</p></div><button class="btn btn-primary" data-recalculate-target-probability type="button">Recalculate Probability</button></div><div class="readiness-main-score"><b>${current.displayProbability}%</b><span>${escapeHTML(current.label)}</span></div><div class="readiness-progress" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${current.displayProbability}" aria-label="Estimated probability of reaching target"><i style="width:${current.displayProbability}%"></i></div><div class="profile-fact-grid">${profileFact('Target Grade',current.targetGrade+'%')}${profileFact('Estimated Score',formatApproximateExamScore(current.estimatedExamScore))}${profileFact('Estimated Range',formatEstimatedRange(current.estimatedRange))}${profileFact('Score Gap',current.scoreGap+' percentage points')}${profileFact('Days Remaining',daysRemainingLabel(profile.examDate))}${profileFact('Completed Practice',`${current.completedPracticeCount} of ${current.practiceTargetCount}`)}</div><p class="readiness-note">This is an estimate based on recorded activity and performance. It is not guaranteed.</p><p class="readiness-note">The probability may change when new scores, completed practice, study activity or exam details are added.</p><p class="readiness-note">This probability is produced by a rule-based planning model. It is not a scientifically validated prediction.</p><section class="readiness-breakdown"><h4>Probability Calculation</h4><div class="responsive-table"><table><thead><tr><th>Factor</th><th>Score</th><th>Weight</th><th>Contribution</th></tr></thead><tbody>${targetProbabilityFactorRows(current)}</tbody></table></div><ul><li>Current Probability: ${escapeHTML(String(current.probability))}%</li><li>Rounded: ${current.displayProbability}%</li></ul></section><section class="chapter-insights"><h4>Supporting Factors</h4>${supporting.length?supporting.map(item=>`<p>${escapeHTML(item)}</p>`).join(''):'<p>More recorded data will reveal supporting factors.</p>'}</section><section class="chapter-insights"><h4>Main Challenges</h4>${challenges.length?challenges.map(item=>`<p>${escapeHTML(item)}</p>`).join(''):'<p>No major challenge is currently identified from the recorded data.</p>'}</section><section class="chapter-insights"><h4>What Could Improve This Estimate?</h4>${improvements.map(item=>`<p>${escapeHTML(item)}</p>`).join('')}</section>${targetScenarioSection(current)}<section class="readiness-breakdown"><h4>Target Probability History</h4><div class="readiness-history">${targetProbabilityHistoryList(profile.id)}</div></section></article>`}
function calculateAndSaveTargetProbability(profileId,{updated=false}={}){const profile=findPredictionProfile(profileId),readiness=evaluatePredictionDataReadiness(profileId);if(!profile)return null;const likely=getLatestLikelyExamScore(profile.id),readinessRecord=currentExamReadinessForLikely(profile,readiness),chapterMetrics=calculateChapterPerformance(profile,readiness.metrics.entries),validation=validatePredictionRequirements({predictionType:'targetProbability',predictionProfile:profile,chapterMetrics,performanceEntries:readiness.metrics.entries,dependencies:{likelyExamScore:likely,examReadiness:readinessRecord,readiness}});if(!validation.available){renderPredictionPerformancePanel();showNotification({type:'warning',message:'More recorded information is needed before this prediction can be calculated.',persistent:true});return null}const record=createTargetProbabilityRecord(profile,readiness,likely,readinessRecord);if(record.status!=='current'||record.probability===null){renderPredictionPerformancePanel();showNotification({type:'warning',message:'More recorded data is needed before the probability can be estimated.',persistent:true});return null}const saved=saveTargetProbabilityRecord(record);refreshPredictionConfidenceSnapshot(profileId);renderPredictionPerformancePanel();showNotification({type:'success',message:updated?'Target probability updated.':'Target probability calculated successfully.'});return saved}
function calculateChapterPerformanceGap(averageScore){const score=Number(averageScore);if(!Number.isFinite(score)||score<0||score>100)return null;return Number((100-score).toFixed(1))}
function getImprovementTimeMultiplier(daysRemaining){const days=Number(daysRemaining);if(!Number.isFinite(days)||days<0)return null;if(days>=21)return 1;if(days>=14)return .95;if(days>=7)return .85;if(days>=3)return .65;if(days>=1)return .40;return .20}
function calculateOfficialChapterImpact({averageScore,examWeightPercent,scoredEntryCount,daysRemaining}){const average=Number(averageScore),weight=Number(examWeightPercent),entries=Number(scoredEntryCount);if(entries<2||!Number.isFinite(average)||!Number.isFinite(weight)||weight<=0||weight>100)return {impactScore:null,enoughData:false};const performanceGap=calculateChapterPerformanceGap(average),timeMultiplier=getImprovementTimeMultiplier(daysRemaining);if(!Number.isFinite(performanceGap)||!Number.isFinite(timeMultiplier))return {impactScore:null,enoughData:false};const baseImpact=performanceGap*weight/100,impactScore=baseImpact*timeMultiplier;return {impactScore:Number(impactScore.toFixed(2)),baseImpact:Number(baseImpact.toFixed(2)),performanceGap,timeMultiplier,enoughData:true,method:'official-chapter-weight'}}
function calculateChapterCategoryPerformance(chapterEntries,categoryWeights){const categoryMap={'knowledge-understanding':Number(categoryWeights?.knowledgeUnderstanding),thinking:Number(categoryWeights?.thinking),communication:Number(categoryWeights?.communication),application:Number(categoryWeights?.application)},breakdown=[];let totalContribution=0,coveredWeight=0;for(const [category,weight] of Object.entries(categoryMap)){const entries=(chapterEntries||[]).filter(entry=>entry.assessmentCategory===category&&Number.isFinite(Number(entry.score))),average=entries.length>0?calculateAverageScore(entries.map(entry=>Number(entry.score))):null,enoughData=entries.length>=2,contribution=enoughData&&Number.isFinite(average)&&Number.isFinite(weight)?Number((average*weight/100).toFixed(2)):null;if(Number.isFinite(contribution)){totalContribution+=contribution;coveredWeight+=weight}breakdown.push({category,label:assessmentCategoryLabel(category),weight,averageScore:average,scoredEntryCount:entries.length,enoughData,contribution})}const normalizedScore=coveredWeight>0?Number((totalContribution/coveredWeight*100).toFixed(1)):null;return {normalizedScore,coveredWeight:Number(coveredWeight.toFixed(1)),completeCoverage:Math.abs(coveredWeight-100)<=.01,breakdown}}
