function identifyHighestImpactChapter(chapterImpactMetrics){const eligible=(chapterImpactMetrics||[]).filter(chapter=>Number.isFinite(Number(chapter.impactScore))&&chapter.enoughData===true);if(!eligible.length)return null;return [...eligible].sort((a,b)=>{const impactDifference=Number(b.impactScore)-Number(a.impactScore);if(Math.abs(impactDifference)>.001)return impactDifference;const scoreDifference=Number(a.averageScore)-Number(b.averageScore);if(Math.abs(scoreDifference)>.001)return scoreDifference;const entryDifference=Number(b.scoredEntryCount)-Number(a.scoredEntryCount);if(entryDifference)return entryDifference;return String(a.chapterName||'').localeCompare(String(b.chapterName||''))})[0]}
function assignRelativeChapterImpactLabels(chapterImpactMetrics){const eligible=(chapterImpactMetrics||[]).filter(chapter=>Number.isFinite(Number(chapter.impactScore))).sort((a,b)=>b.impactScore-a.impactScore||String(a.chapterName||'').localeCompare(String(b.chapterName||'')));return eligible.map((chapter,index)=>{let impactLabel;if(index===0)impactLabel='Highest Impact';else if(index<Math.ceil(eligible.length*.35))impactLabel='High Impact';else if(index<Math.ceil(eligible.length*.70))impactLabel='Moderate Impact';else impactLabel='Lower Impact';return {...chapter,impactLabel}})}
function identifyMainWeakCategory(categoryBreakdown){const eligible=(categoryBreakdown||[]).filter(category=>category.scoredEntryCount>=2&&Number.isFinite(Number(category.averageScore))&&Number(category.weight)>0).map(category=>({...category,weaknessImpact:Number(((100-Number(category.averageScore))*Number(category.weight)/100).toFixed(2))})).sort((a,b)=>b.weaknessImpact-a.weaknessImpact);return eligible[0]||null}
