function chapterImpactHistoryStorageKey(){return isGuestMode()?GUEST_CHAPTER_IMPACT_HISTORY_KEY:CHAPTER_IMPACT_HISTORY_KEY}
function getAllChapterImpactHistory(){try{const parsed=JSON.parse(localStorage.getItem(chapterImpactHistoryStorageKey()))||[];return Array.isArray(parsed)?parsed.filter(Boolean):[]}catch{return[]}}
function getChapterImpactHistory(){return getAllChapterImpactHistory().filter(row=>row&&row.userId===predictionUserId())}
function saveChapterImpactHistory(rows){const userId=predictionUserId(),others=getAllChapterImpactHistory().filter(row=>row.userId!==userId),mine=(Array.isArray(rows)?rows:[]).filter(row=>row&&row.userId===userId);localStorage.setItem(chapterImpactHistoryStorageKey(),JSON.stringify([...mine,...others]))}
