function markChapterImpactOutdated(profileId){const rows=getChapterImpactHistory(),latest=rows.filter(row=>row.predictionProfileId===profileId).sort((a,b)=>new Date(b.calculatedAt)-new Date(a.calculatedAt))[0];if(!latest||latest.status==='outdated')return;latest.status='outdated';latest.updatedAt=new Date().toISOString();saveChapterImpactHistory(rows);showNotification({type:'warning',message:'Your chapter-impact analysis needs to be recalculated.',persistent:true})}
function profileUsesOfficialChapterImpact(profile){const chapters=(profile?.chapters||[]).filter(ch=>Number(ch.examWeightPercent)>0),total=calculateChapterWeightTotal(chapters);return !!chapters.length&&Math.abs(total-100)<=.01&&chapters.every(ch=>['teacher-provided','course-outline'].includes(ch.weightSource))}
function chapterDataCoverageLabel(chapter,categoryPerformance=null,method='official-chapter-weight'){if(method==='estimated-category-impact'){const coverage=Number(categoryPerformance?.coveredWeight)||0;if(coverage>=99.99)return 'Strong Data Coverage';if(coverage>=75)return 'Moderate Data Coverage';if(coverage>=50)return 'Minimum Data Coverage';return 'Not Enough Data'}if(chapter.scoredEntryCount>=5)return 'Strong Data Coverage';if(chapter.scoredEntryCount>=3)return 'Moderate Data Coverage';if(chapter.scoredEntryCount>=2)return 'Minimum Data Coverage';return 'Not Enough Data'}
function buildChapterImpactMetrics(profile,metrics){const daysRemaining=calculateDaysRemaining(profile?.examDate),official=profileUsesOfficialChapterImpact(profile),chapterMetrics=calculateChapterPerformance(profile,metrics.entries),rows=chapterMetrics.map(chapter=>{const categoryPerformance=calculateChapterCategoryPerformance(chapter.scoredEntries||[],profile.assessmentCategoryWeights),mainWeakCategory=identifyMainWeakCategory(categoryPerformance.breakdown),impact=official?calculateOfficialChapterImpact({averageScore:chapter.averageScore,examWeightPercent:chapter.examWeightPercent,scoredEntryCount:chapter.scoredEntryCount,daysRemaining}):calculateEstimatedChapterImpact({chapterCategoryPerformance:categoryPerformance,daysRemaining}),dataCoverage=chapterDataCoverageLabel(chapter,categoryPerformance,official?'official-chapter-weight':'estimated-category-impact'),highPriorityDataGap=chapter.scoredEntryCount>0&&chapter.scoredEntryCount<2;return {...chapter,...impact,method:official?'official-chapter-weight':'estimated-category-impact',mainWeakCategory,categoryBreakdown:categoryPerformance.breakdown,chapterCategoryPerformance:categoryPerformance,dataCoverage,highPriorityDataGap,suggestedFocus:chapterImpactSuggestedFocus(chapter,mainWeakCategory,impact.enoughData)}});const labeled=assignRelativeChapterImpactLabels(rows),labelMap=Object.fromEntries(labeled.map(row=>[row.chapterId,row.impactLabel]));return rows.map(row=>({...row,impactLabel:labelMap[row.chapterId]||'Not Enough Data'}))}
function chapterImpactSuggestedFocus(chapter,mainWeakCategory,eligible=true){if(!eligible)return `Record another scored activity for ${chapter.chapterName}.`;if(mainWeakCategory?.label)return `Practise ${mainWeakCategory.label} questions in ${chapter.chapterName}.`;if(chapter.statusKey==='needs-improvement')return `Review mistakes and complete targeted practice in ${chapter.chapterName}.`;if(chapter.trend==='Declining')return `Redo recent missed questions from ${chapter.chapterName}.`;return `Maintain performance with a short mixed review for ${chapter.chapterName}.`}
