function createChapterImpactRecord(profile,readiness){const metrics=readiness.metrics,daysRemaining=calculateDaysRemaining(profile.examDate),method=profileUsesOfficialChapterImpact(profile)?'official-chapter-weight':'estimated-category-impact',impactMetrics=buildChapterImpactMetrics(profile,metrics),highest=identifyHighestImpactChapter(impactMetrics),missing=[];if(!(profile.chapters||[]).length)missing.push('Add chapters before identifying a study priority.');if(daysRemaining===null)missing.push('Enter a valid exam date.');if(daysRemaining!==null&&daysRemaining<0)missing.push('This exam date has passed.');if(!highest&&!missing.length)missing.push('Record at least two scored activities for a chapter before its impact can be measured.');const gaps=impactMetrics.filter(row=>row.highPriorityDataGap||(!row.enoughData&&row.totalEntryCount>0));const record={id:'chapter-impact-'+Date.now(),userId:predictionUserId(),predictionProfileId:profile.id,method,highestImpactChapter:highest?chapterImpactSnapshot(highest):null,chapterImpactMetrics:impactMetrics.map(chapterImpactSnapshot),highPriorityDataGaps:gaps.map(row=>({chapterId:row.chapterId,chapterName:row.chapterName,reason:row.reason||'More scored activity is needed before its impact can be measured.',scoredEntryCount:row.scoredEntryCount,dataCoverage:row.dataCoverage})),daysRemaining,basedOnProfileUpdatedAt:profile.updatedAt,basedOnLatestPerformanceUpdate:latestPerformanceUpdate(metrics.entries),calculatedAt:new Date().toISOString(),status:highest?'current':'not-available',missingRequirements:missing,prototypeOnly:true};return record}
