function calculateAndSaveChapterImpact(profileId,{updated=false}={}){const profile=findPredictionProfile(profileId),readiness=evaluatePredictionDataReadiness(profileId);if(!profile)return null;const record=createChapterImpactRecord(profile,readiness);if(record.status!=='current'||!record.highestImpactChapter){renderPredictionPerformancePanel();showNotification({type:'warning',message:record.daysRemaining<0?'This exam date has passed.':'More chapter performance data is needed.',persistent:true});return null}const saved=saveChapterImpactRecord(record);renderPredictionPerformancePanel();showNotification({type:'success',message:updated?'Chapter-impact analysis updated.':'Highest-impact chapter identified.'});return saved}
function bindChapterImpactControls(root=document){const sort=$('#chapterImpactSort',root),filter=$('#chapterImpactFilter',root);if(sort){sort.value=sessionStorage.getItem('chapterImpactSort')||'impact';sort.onchange=()=>{sessionStorage.setItem('chapterImpactSort',sort.value);renderPredictionPerformancePanel()}}if(filter){filter.value=sessionStorage.getItem('chapterImpactFilter')||'all';filter.onchange=()=>{sessionStorage.setItem('chapterImpactFilter',filter.value);renderPredictionPerformancePanel()}}$$('[data-recalculate-chapter-impact]',root).forEach(btn=>btn.onclick=()=>{const profile=selectedPredictionProfile();if(profile)calculateAndSaveChapterImpact(profile.id,{updated:!!getLatestChapterImpact(profile.id)})});$$('[data-edit-chapter-impact-recommendation]',root).forEach(btn=>btn.onclick=()=>{const profile=selectedPredictionProfile(),latest=profile?getLatestChapterImpact(profile.id):null,current=latest?.highestImpactChapter?.suggestedFocus||'';if(!profile)return;const text=prompt('Edit the suggested focus:',current);if(text!==null)updateChapterImpactRecommendation(profile.id,{text})});$$('[data-dismiss-chapter-impact-recommendation]',root).forEach(btn=>btn.onclick=()=>{const profile=selectedPredictionProfile();if(profile)updateChapterImpactRecommendation(profile.id,{dismissed:true})});$$('[data-restore-chapter-impact-recommendation]',root).forEach(btn=>btn.onclick=()=>{const profile=selectedPredictionProfile();if(profile)updateChapterImpactRecommendation(profile.id,{restore:true})})}
function studyImpactRules(){return appData.studyImpactRules||FALLBACK_STUDY_IMPACT_RULES}
function validateStudyImpactRules(rules){const hourRules=rules?.hourImprovementRanges;if(!Array.isArray(hourRules)||hourRules.length===0)return {valid:false,reason:'Missing hour improvement rules'};const validHours=hourRules.every(rule=>Number.isInteger(Number(rule.hour))&&Number(rule.hour)>=1&&Number.isFinite(Number(rule.minimum))&&Number.isFinite(Number(rule.maximum))&&Number(rule.minimum)>=0&&Number(rule.maximum)>=Number(rule.minimum));return {valid:validHours,reason:validHours?null:'Invalid study-impact rules'}}
function studyMethodOptions(){return [['practice-questions','Practice Questions'],['review-mistakes','Review Mistakes'],['flashcards','Flashcards'],['read-notes','Read Notes'],['timed-practice','Timed Practice'],['ask-for-help','Ask for Help'],['mixed-practice','Mixed Practice']]}
function studyImpactMethodLabel(value){return studyMethodOptions().find(([key])=>key===value)?.[1]||'Mixed Practice'}
function studyMethodGuidance(value){return {'practice-questions':'Complete focused questions and review every incorrect answer.','review-mistakes':'Identify why each mistake happened and solve a similar question again.','flashcards':'Use active recall instead of only reading the answers.','read-notes':'Pause regularly and explain the ideas without looking.','timed-practice':'Complete questions under exam-like time limits, then review errors.','ask-for-help':'Prepare specific questions before asking a teacher, tutor or study partner.','mixed-practice':'Combine active review, practice questions and mistake correction.'}[value]||'Combine active review, practice questions and mistake correction.'}
function calculateBaseStudyGainRange({focusedHours,hourImprovementRanges}){const hours=Number(focusedHours);if(!Number.isInteger(hours)||hours<1||hours>5)return null;let minimumGain=0,maximumGain=0;const hourlyBreakdown=[];for(let hour=1;hour<=hours;hour+=1){const rule=(hourImprovementRanges||[]).find(item=>Number(item.hour)===hour);if(!rule)return null;const minimum=Number(rule.minimum),maximum=Number(rule.maximum);minimumGain+=minimum;maximumGain+=maximum;hourlyBreakdown.push({hour,minimumGain:minimum,maximumGain:maximum})}return {minimumGain:Number(minimumGain.toFixed(1)),maximumGain:Number(maximumGain.toFixed(1)),hourlyBreakdown}}
function getStudyMethodMultiplier(studyMethod,methodMultipliers){const multiplier=Number(methodMultipliers?.[studyMethod]);if(!Number.isFinite(multiplier)||multiplier<=0)return null;return multiplier}
function getStudyImpactCoverageMultiplier(coverageLabel,multipliers){switch(coverageLabel){case 'Strong Data Coverage':return Number(multipliers.strong);case 'Moderate Data':case 'Moderate Data Coverage':return Number(multipliers.moderate);case 'Minimum Data':case 'Minimum Data Coverage':return Number(multipliers.minimum);default:return null}}
function calculateAdjustedStudyGainRange({baseRange,methodMultiplier,coverageMultiplier}){if(!baseRange||!Number.isFinite(Number(methodMultiplier))||!Number.isFinite(Number(coverageMultiplier)))return null;const combinedMultiplier=Number(methodMultiplier)*Number(coverageMultiplier);return {minimumGain:Number((baseRange.minimumGain*combinedMultiplier).toFixed(1)),maximumGain:Number((baseRange.maximumGain*combinedMultiplier).toFixed(1)),combinedMultiplier}}
function calculateSimulatedChapterScoreRange({currentChapterScore,minimumGain,maximumGain}){const current=Number(currentChapterScore),minimum=Number(minimumGain),maximum=Number(maximumGain);if(!Number.isFinite(current)||!Number.isFinite(minimum)||!Number.isFinite(maximum))return null;return {lower:Number(clampNumber(current+minimum,0,100).toFixed(1)),upper:Number(clampNumber(current+maximum,0,100).toFixed(1))}}
function calculateOfficialStudyExamEffect({minimumChapterGain,maximumChapterGain,examWeightPercent}){const minimum=Number(minimumChapterGain),maximum=Number(maximumChapterGain),weight=Number(examWeightPercent);if(!Number.isFinite(minimum)||!Number.isFinite(maximum)||!Number.isFinite(weight)||weight<=0||weight>100)return null;return {minimumExamGain:Number((minimum*weight/100).toFixed(2)),maximumExamGain:Number((maximum*weight/100).toFixed(2))}}
function calculateCategoryBasedStudyExamEffect({minimumChapterGain,maximumChapterGain,assessmentCategoryWeight,chapterShareMultiplier=.5}){const minimum=Number(minimumChapterGain),maximum=Number(maximumChapterGain),categoryWeight=Number(assessmentCategoryWeight),share=Number(chapterShareMultiplier);if(!Number.isFinite(minimum)||!Number.isFinite(maximum)||!Number.isFinite(categoryWeight)||!Number.isFinite(share)||categoryWeight<=0||categoryWeight>100||share<=0||share>1)return null;return {minimumExamGain:Number((minimum*categoryWeight/100*share).toFixed(2)),maximumExamGain:Number((maximum*categoryWeight/100*share).toFixed(2)),chapterShareMultiplier:share}}
function calculateSimulatedExamScoreRange({currentEstimatedScore,minimumExamGain,maximumExamGain}){const current=Number(currentEstimatedScore),minimum=Number(minimumExamGain),maximum=Number(maximumExamGain);if(!Number.isFinite(current)||!Number.isFinite(minimum)||!Number.isFinite(maximum))return null;return {lower:Number(clampNumber(current+minimum,0,100).toFixed(1)),upper:Number(clampNumber(current+maximum,0,100).toFixed(1))}}
