function getAllStudyImpactSimulationHistory(){try{const parsed=JSON.parse(localStorage.getItem(studyImpactSimulationHistoryStorageKey()))||[];return Array.isArray(parsed)?parsed.filter(Boolean):[]}catch{return[]}}
function getStudyImpactSimulationHistory(){return getAllStudyImpactSimulationHistory().filter(row=>row&&row.userId===predictionUserId())}
