function renderStudyImpactResult(record,profile){if(!record)return'';if(record.status!=='current')return `<section class="chapter-insights study-impact-result"><h4>Extra Study Time Estimate</h4><p>${escapeHTML(record.missingRequirements?.[0]||'The extra study-time estimate could not be calculated.')}</p><p class="readiness-note">This is a hypothetical estimate. Actual improvement depends on study quality, difficulty, prior knowledge and exam performance.</p></section>`;const prob=record.simulatedProbabilityRange?formatRange(record.simulatedProbabilityRange):'The exam-score effect can be estimated, but the target probability cannot be updated yet.';return `<section class="study-impact-result"><div class="card-head"><div><h4>Extra Study Time Estimate</h4><p>One focused hour may improve your predicted result.</p></div></div><div class="profile-fact-grid">${profileFact('Selected Chapter',record.chapterName)}${profileFact('Focus',record.assessmentCategory==='general'?'General Chapter Review':assessmentCategoryLabel(record.assessmentCategory))}${profileFact('Study Method',studyImpactMethodLabel(record.studyMethod))}${profileFact('Focused Study Time',`${record.focusedHours} hour${record.focusedHours===1?'':'s'}`)}${profileFact('Current Chapter Score',formatScorePercentage(record.currentChapterScore))}${profileFact('Possible Chapter Score After Study',formatRange(record.simulatedChapterScoreRange))}${profileFact('Current Estimated Exam Score',formatApproximateExamScore(record.currentEstimatedExamScore))}${profileFact('Possible Estimated Score After Study',formatRange(record.simulatedExamScoreRange))}${profileFact(`Current Probability of Reaching ${profile.targetGrade}%`,record.currentProbability===null?'Not Available':record.currentProbability+'%')}${profileFact('Possible Probability After Study',prob)}</div><div class="study-impact-comparison"><section><h5>Before Study</h5>${profileFact('Chapter Score',formatScorePercentage(record.currentChapterScore))}${profileFact('Estimated Exam Score',formatApproximateExamScore(record.currentEstimatedExamScore))}${profileFact('Probability',record.currentProbability===null?'Not Available':record.currentProbability+'%')}</section><section><h5>Hypothetical Result</h5>${profileFact('Chapter Score',formatRange(record.simulatedChapterScoreRange))}${profileFact('Estimated Exam Score',formatRange(record.simulatedExamScoreRange))}${profileFact('Probability',prob)}</section></div><section class="chapter-insights"><h4>Estimated Effect by Hour</h4>${record.hourlyBreakdown.map((hour,index)=>`<p><b>Hour ${hour.hour}:</b> ${index?'Additional ':''}+${hour.minimumGain} to +${hour.maximumGain} chapter points</p>`).join('')}</section><section class="chapter-insights"><h4>Focus Quality</h4><p>${escapeHTML(studyMethodGuidance(record.studyMethod))}</p></section><section class="chapter-insights"><h4>Why This Estimate Changed</h4><ul>${studyImpactReasons(record,profile).map(item=>`<li>${escapeHTML(item)}</li>`).join('')}</ul></section>${record.calculationMethod==='category-based-estimate'?'<p class="readiness-note">Official chapter percentages were not provided, so this estimate uses assessment-category performance.</p>':''}<p class="readiness-note">This is a hypothetical estimate. Actual improvement depends on study quality, difficulty, prior knowledge and exam performance.</p><div class="prediction-actions"><button class="btn btn-primary" data-save-study-impact-simulation type="button">Save Simulation</button><button class="btn btn-secondary" data-save-study-impact-plan type="button">Save as Study Plan</button><button class="btn btn-secondary" data-record-study-impact-completed type="button">Record Completed Study Session</button></div></section>`}
