function getStudyScenarios(profileId=''){return getAllStudyScenarios().filter(row=>row.userId===predictionUserId()&&(!profileId||row.predictionProfileId===profileId))}
function saveStudyScenarios(rows){const userId=predictionUserId(),others=getAllStudyScenarios().filter(row=>row.userId!==userId),mine=(Array.isArray(rows)?rows:[]).filter(row=>row.userId===userId);localStorage.setItem(studyScenarioStorageKey(),JSON.stringify([...mine,...others]))}
