function getAllStudyScenarioComparisonHistory(){try{const parsed=JSON.parse(localStorage.getItem(studyScenarioComparisonStorageKey()))||[];return Array.isArray(parsed)?parsed.filter(Boolean):[]}catch{return[]}}
function getStudyScenarioComparisonHistory(){return getAllStudyScenarioComparisonHistory().filter(row=>row.userId===predictionUserId())}
function saveStudyScenarioComparisonHistory(rows){const userId=predictionUserId(),others=getAllStudyScenarioComparisonHistory().filter(row=>row.userId!==userId),mine=(Array.isArray(rows)?rows:[]).filter(row=>row.userId===userId);localStorage.setItem(studyScenarioComparisonStorageKey(),JSON.stringify([...mine,...others]))}
