function collectScenarioDrafts(profile){return $$('.study-scenario-editor').map((editor,index)=>normalizeStudyScenario({id:editor.dataset.scenarioId||'',predictionProfileId:profile.id,name:$('.scenario-name-input',editor)?.value||`Scenario ${String.fromCharCode(65+index)}`,actions:$$('.scenario-action-row',editor).map((row,i)=>{const chapterId=$('[data-scenario-field="chapterId"]',row)?.value||'',chapter=(profile.chapters||[]).find(ch=>ch.id===chapterId);return {id:row.dataset.actionId||`action-${i+1}`,chapterId,chapterName:chapter?.name||'',assessmentCategory:$('[data-scenario-field="assessmentCategory"]',row)?.value||'general',studyMethod:$('[data-scenario-field="studyMethod"]',row)?.value||'practice-questions',focusedHours:Number($('[data-scenario-field="focusedHours"]',row)?.value)||1,plannedDate:$('[data-scenario-field="plannedDate"]',row)?.value||today()}})},profile,index))}
function scenarioOptionsHTML(options,current){return options.map(([value,label])=>`<option value="${escapeHTML(value)}" ${value===current?'selected':''}>${escapeHTML(label)}</option>`).join('')}
