function ensurePerformanceCategoryControl(){const typeSelect=$('#performanceActivityType');if(typeSelect&&!typeSelect.querySelector('option[value="practice-exam"]'))typeSelect.querySelector('option[value="assignment"]')?.insertAdjacentHTML('beforebegin','<option value="practice-exam">Practice Exam</option>');const chapterLabel=$('#performanceChapter')?.closest('label');if(!chapterLabel||$('#performanceAssessmentCategory'))return;chapterLabel.insertAdjacentHTML('afterend',`<label id="performanceAssessmentCategoryWrap">Assessment Category <span class="required-marker">*</span><select id="performanceAssessmentCategory"><option value="">Select category</option>${ASSESSMENT_CATEGORIES.map(([label,,value])=>`<option value="${escapeHTML(value)}">${escapeHTML(label)}</option>`).join('')}</select><small data-error-for="performanceAssessmentCategory"></small></label>`);$('#performanceAssessmentCategory')?.addEventListener('change',clearPerformanceErrors)}
function updatePerformanceFormVisibility(){ensurePerformanceCategoryControl();const type=$('#performanceActivityType')?.value||'quiz',scored=SCORED_ACTIVITY_TYPES.includes(type),questions=type==='quiz'||type==='practice-questions'||type==='practice-exam';$('.performance-score-row')?.classList.toggle('hidden',!scored);$('#performanceAssessmentCategoryWrap')?.classList.toggle('optional-category',!scored);$('#performanceAssessmentCategoryWrap .required-marker')?.classList.toggle('hidden',!scored);$('#performanceQuestionsCorrect')?.closest('label')?.classList.toggle('hidden',!questions);$('#performanceTotalQuestions')?.closest('label')?.classList.toggle('hidden',!questions);if(type==='study-task')$('#performanceCompleted').checked=true;const data=collectPerformanceForm(),calc=getPerformanceScore(data);$('#performanceCalculatedScore').textContent=(questions&&data.questionsCorrect!==''&&data.totalQuestions!==''&&calc!==null)?`Calculated score: ${calc}%`:''}
function openPerformanceForm(entryId=''){const profile=selectedPredictionProfile();if(!profile){showNotification({type:'warning',message:'Open a Prediction Profile before adding performance data.'});return}resetPerformanceForm();activePerformanceEntryId=entryId;updatePerformanceChapterOptions();const entry=entryId?findPerformanceEntry(entryId):null;if(entry){$('#performanceEntryId').value=entry.id;$('#performanceActivityType').value=entry.activityType;$('#performanceChapter').value=entry.chapter;if($('#performanceAssessmentCategory'))$('#performanceAssessmentCategory').value=entry.assessmentCategory||'';$('#performanceScore').value=entry.score??'';$('#performanceQuestionsCorrect').value=entry.questionsCorrect??'';$('#performanceTotalQuestions').value=entry.totalQuestions??'';$('#performanceTimeSpent').value=entry.timeSpentMinutes||'';$('#performanceAttempts').value=entry.attempts||1;$('#performanceCompleted').checked=!!entry.completed;$('#performanceDate').value=entry.date;$('#performanceNotes').value=entry.notes||'';$('#performanceNotesCount').textContent=`${($('#performanceNotes').value||'').length} of 300 characters`;$('#savePerformanceEntryBtn').textContent='Save Changes'}updatePerformanceFormVisibility();$('#performanceEntryForm').classList.remove('hidden');$('#performanceEntryForm').scrollIntoView({behavior:'smooth',block:'start'})}
function closePerformanceForm(){resetPerformanceForm();$('#performanceEntryForm')?.classList.add('hidden')}
async function savePerformanceFromForm({skipDuplicateWarning=false}={}){const profile=selectedPredictionProfile(),data=collectPerformanceForm(),editing=!!activePerformanceEntryId,previous=editing?findPerformanceEntry(activePerformanceEntryId):null;const result=savePerformanceRecord(activePerformanceEntryId,data,profile,{skipDuplicateWarning});if(result.duplicate){const ok=await confirmDialog({title:'Possible Duplicate Entry',message:'This entry may already exist.',okText:'Save Anyway',cancelText:'Cancel'});if(ok)return savePerformanceFromForm({skipDuplicateWarning:true});return false}showPerformanceErrors(result.errors||{});if(!result.success){showNotification({type:'error',message:result.errors?.performanceScore||'Performance data could not be saved.'});return false}closePerformanceForm();renderPredictionPerformancePanel();renderFutureSuccessPage();renderDashboard();renderProgress();showNotification({type:'success',message:editing?'Performance entry updated.':'Performance data saved successfully.'});notifyChapterPerformanceChange(profile.id);if(!editing||didPredictionRelevantScoreDataChange(previous,result.entry)){if(editing)showNotification({type:'information',message:'Predictions based on this score will be updated.'});const scored=SCORED_ACTIVITY_TYPES.includes(result.entry.activityType),triggerType=result.entry.activityType==='study-session'?(editing?PREDICTION_UPDATE_TRIGGERS.STUDY_SESSION_UPDATED:PREDICTION_UPDATE_TRIGGERS.STUDY_SESSION_COMPLETED):result.entry.activityType==='study-task'?(result.entry.completed?PREDICTION_UPDATE_TRIGGERS.STUDY_TASK_COMPLETED:PREDICTION_UPDATE_TRIGGERS.STUDY_TASK_REOPENED):(editing?PREDICTION_UPDATE_TRIGGERS.SCORE_UPDATED:(result.entry.activityType==='quiz'&&scored?PREDICTION_UPDATE_TRIGGERS.QUIZ_COMPLETED:PREDICTION_UPDATE_TRIGGERS.SCORE_ADDED));predictionUpdateManager.requestUpdate({userId:predictionUserId(),predictionProfileId:profile.id,triggerType,sourceRecordId:result.entry.id})}return true}
function notifyChapterPerformanceChange(profileId){const metrics=predictionMetrics(profileId);showNotification({type:'information',message:metrics.scored.length?'Chapter performance updated.':'Add scored activities to calculate chapter performance.'})}
async function confirmDeletePerformanceEntry(id){const entry=findPerformanceEntry(id),profileId=entry?.predictionProfileId;const ok=await confirmDialog({title:'Delete Performance Entry',message:'Delete this performance entry?',okText:'Delete',cancelText:'Cancel',danger:true});if(!ok)return;if(deletePerformanceEntryMuted(id)){renderPredictionPerformancePanel();renderFutureSuccessPage();renderDashboard();renderProgress();showNotification({type:'information',message:'Performance entry deleted.'});if(profileId){notifyChapterPerformanceChange(profileId);predictionUpdateManager.requestUpdate({userId:predictionUserId(),predictionProfileId:profileId,triggerType:PREDICTION_UPDATE_TRIGGERS.SCORE_DELETED,sourceRecordId:id})}}}
function performanceRequirementRow(label,req,suffix=''){const current=String(req.current),required=String(req.required),detail=typeof req.current==='string'||typeof req.required==='string'?`${current} required: ${required}`:`${current} of ${required}${suffix}`;return `<div class="readiness-requirement ${req.met?'met':''}"><span>${req.met?'Met':'Needed'}</span><b>${escapeHTML(label)}</b><small>${escapeHTML(detail)}</small></div>`}
function renderDataReadiness(readiness){const req=readiness.requirements;return `<article class="data-readiness-card ${readiness.ready?'ready':'not-ready'}"><div><span class="status-badge ${readiness.ready?'status-active':'status-pending'}">${readiness.ready?'Ready for Readiness Estimate':'Not Ready'}</span><h3>Prediction Data Readiness</h3><p>${readiness.ready?'Enough performance data has been collected to calculate current exam readiness. This is still an estimate, not a guaranteed result.':'More performance data is needed before exam readiness can be estimated.'}</p></div><div class="readiness-requirement-grid">${performanceRequirementRow('Assessment category weights',req.assessmentCategoryWeights,'%')}${performanceRequirementRow('Categories with data',req.categoriesWithData)}${performanceRequirementRow('High-weight categories covered',req.highWeightCategoriesCovered)}${performanceRequirementRow('Chapter weights',req.chapterWeights,'%')}${performanceRequirementRow('Performance entries',req.totalEntries)}${performanceRequirementRow('Scored activities',req.scoredEntries)}${performanceRequirementRow('Study dates',req.differentDates)}${performanceRequirementRow('Chapters with data',req.chaptersWithData)}${performanceRequirementRow('Study time',req.studyMinutes,' minutes')}${performanceRequirementRow('Completed study task',req.completedTasks)}${performanceRequirementRow('Exam timing',req.examDate,' days')}</div>${readiness.missingRequirements.length?`<ul class="missing-readiness">${readiness.missingRequirements.map(item=>`<li>${escapeHTML(item)}</li>`).join('')}</ul>`:''}<div class="prediction-actions"><button class="btn btn-primary" data-recalculate-readiness type="button" ${readiness.ready?'':'disabled'}>Calculate Exam Readiness</button>${readiness.ready?'':'<small>Collect more data to unlock exam readiness.</small>'}</div></article>`}
function chapterPerformanceViewKey(){return isGuestMode()?'guestChapterPerformanceView':'chapterPerformanceView'}
function getChapterPerformanceView(){return localStorage.getItem(chapterPerformanceViewKey())||'cards'}
function setChapterPerformanceView(value){localStorage.setItem(chapterPerformanceViewKey(),value==='table'?'table':'cards')}
function calculateWeightedChapterContribution(averageScore,examWeightPercent,scoredEntryCount=2){const score=Number(averageScore),weight=Number(examWeightPercent);if(scoredEntryCount<2||!Number.isFinite(score)||!Number.isFinite(weight)||weight<0||weight>100)return null;return Number((score*weight/100).toFixed(2))}
function calculateWeightedRecordedPerformance(chapterMetrics){const eligible=chapterMetrics.filter(chapter=>chapter.scoredEntryCount>=2&&Number.isFinite(Number(chapter.averageScore))&&Number.isFinite(Number(chapter.examWeightPercent))&&Number(chapter.examWeightPercent)>0),coveredWeight=eligible.reduce((sum,chapter)=>sum+Number(chapter.examWeightPercent),0);if(!eligible.length||coveredWeight===0)return {score:null,coveredWeight:0,completeCoverage:false};const weightedTotal=eligible.reduce((sum,chapter)=>sum+(Number(chapter.averageScore)*Number(chapter.examWeightPercent)),0),normalizedScore=weightedTotal/coveredWeight;return {score:Number(normalizedScore.toFixed(1)),coveredWeight:Number(coveredWeight.toFixed(1)),completeCoverage:Math.abs(coveredWeight-100)<=0.01}}
function getExamImpactLabel(examWeightPercent){const weight=Number(examWeightPercent);if(!Number.isFinite(weight))return 'Unknown Impact';if(weight>=30)return 'Very High Impact';if(weight>=20)return 'High Impact';if(weight>=10)return 'Moderate Impact';if(weight>0)return 'Low Impact';return 'No Exam Impact'}
function calculateChapterPriorityScore(chapter){if(chapter.scoredEntryCount<2)return null;const average=Number(chapter.averageScore),weight=Number(chapter.examWeightPercent);if(!Number.isFinite(average)||!Number.isFinite(weight))return null;return Number(((100-average)*(weight/100)).toFixed(2))}
function applyChapterPriorityLabels(metrics){const scored=metrics.filter(ch=>Number.isFinite(ch.priorityScore)).sort((a,b)=>b.priorityScore-a.priorityScore);return metrics.map(ch=>{if(Number(ch.examWeightPercent)>=20&&ch.scoredEntryCount<2)return {...ch,priorityLabel:'High-Priority Data Gap',priorityMessage:'More performance data is needed for this important chapter.'};const rank=scored.findIndex(row=>row.chapterId===ch.chapterId);if(rank<0)return {...ch,priorityLabel:'Data Needed',priorityMessage:'Add scored activities before StudySpark ranks this chapter.'};const label=rank===0?'Highest Priority':rank===1?'High Priority':rank<=Math.ceil(scored.length/2)?'Medium Priority':'Lower Priority';return {...ch,priorityLabel:label,priorityMessage:`Priority score: ${ch.priorityScore}. Higher scores combine lower performance with higher exam weight.`}})}
function sortedChapterMetrics(metrics,sort='exam-order'){const rows=[...metrics],scoreValue=row=>Number.isFinite(row.averageScore)?row.averageScore:null,priorityValue=row=>Number.isFinite(row.priorityScore)?row.priorityScore:null;if(sort==='lowest-score')return rows.sort((a,b)=>(scoreValue(a)===null)-(scoreValue(b)===null)||(a.averageScore??999)-(b.averageScore??999));if(sort==='highest-score')return rows.sort((a,b)=>(scoreValue(a)===null)-(scoreValue(b)===null)||(b.averageScore??-1)-(a.averageScore??-1));if(sort==='highest-exam-weight'||sort==='highest-importance')return rows.sort((a,b)=>(Number(b.examWeightPercent)||0)-(Number(a.examWeightPercent)||0));if(sort==='highest-priority')return rows.sort((a,b)=>(priorityValue(b)===null)-(priorityValue(a)===null)||(b.priorityScore??-1)-(a.priorityScore??-1)||(Number(b.examWeightPercent)||0)-(Number(a.examWeightPercent)||0));if(sort==='lowest-priority')return rows.sort((a,b)=>(priorityValue(a)===null)-(priorityValue(b)===null)||(a.priorityScore??999)-(b.priorityScore??999));if(sort==='most-study-time')return rows.sort((a,b)=>b.totalStudyMinutes-a.totalStudyMinutes);if(sort==='status')return rows.sort((a,b)=>a.statusLabel.localeCompare(b.statusLabel));return rows}
function chapterStatusIcon(key){return {'strong':'OK','developing':'Progress','needs-improvement':'Attention','not-enough-data':'Info'}[key]||'Info'}
function chapterActivityDate(value){return value?formatPredictionDate(value):'No activity yet'}
function chapterTaskText(chapter){return chapter.totalTasks?`${chapter.completedTasks} of ${chapter.totalTasks}`:'No study tasks recorded'}
function chapterPerformanceMessage(chapter){if(chapter.scoredEntryCount===0)return 'Add at least two scored activities for this chapter to receive a performance label.';if(chapter.scoredEntryCount===1)return 'Add one more scored activity to receive a chapter rating.';return `Trend: ${chapter.trend}. Score change: ${scoreChangeText(chapter.scoreChange.scoreChange)}.`}
function chapterPerformanceCard(chapter){const contribution=chapter.weightedContribution===null?'Not calculated - more chapter data needed.':chapter.weightedContribution+' points';return `<article class="chapter-performance-item chapter-performance-item--${escapeHTML(chapter.statusKey)}" aria-labelledby="chapter-${escapeHTML(chapter.chapterId)}"><div class="chapter-performance-head"><div><h4 id="chapter-${escapeHTML(chapter.chapterId)}">${escapeHTML(chapter.chapterName)}</h4><small>Exam Weight: ${escapeHTML(chapter.examWeightPercent===null?'Setup required':chapter.examWeightPercent+'%')} - ${escapeHTML(chapter.weightSourceLabel)}</small></div><span class="chapter-status chapter-status--${escapeHTML(chapter.statusKey)}"><b aria-hidden="true">${escapeHTML(chapterStatusIcon(chapter.statusKey))}</b><span class="sr-only">${escapeHTML(chapterStatusIcon(chapter.statusKey))}: </span>${escapeHTML(chapter.statusLabel)}</span></div><div class="profile-fact-grid">${profileFact('Exam Weight',chapter.examWeightPercent===null?'Setup required':chapter.examWeightPercent+'%')}${profileFact('Weighted Impact',chapter.examImpactLabel)}${profileFact('Weighted Contribution',contribution)}${profileFact('Study Priority',chapter.priorityLabel)}${profileFact('Average Score',formatScorePercentage(chapter.averageScore))}${profileFact('Scored Activities',String(chapter.scoredEntryCount))}${profileFact('Latest Score',formatScorePercentage(chapter.latestScore))}${profileFact('Study Time',formatStudyMinutes(chapter.totalStudyMinutes))}${profileFact('Last Activity',chapterActivityDate(chapter.latestActivityDate))}${profileFact('Prediction Data',chapter.dataReadiness.ready?'Ready':'More Data Needed')}</div><p>${escapeHTML(chapter.examWeightPercent===0?'Not included in weighted prediction.':chapter.priorityMessage||chapterPerformanceMessage(chapter))}</p><button class="btn btn-secondary" type="button" data-chapter-detail="${escapeHTML(chapter.chapterId)}">View Details</button></article>`}
function chapterPerformanceTable(metrics){return `<div class="responsive-table chapter-performance-table"><table><thead><tr><th>Chapter</th><th>Exam Weight</th><th>Weighted Impact</th><th>Average</th><th>Status</th><th>Study Priority</th><th>Scored Activities</th><th>Latest Score</th><th>Study Time</th><th>Trend</th></tr></thead><tbody>${metrics.map(chapter=>`<tr><td>${escapeHTML(chapter.chapterName)}</td><td>${escapeHTML(chapter.examWeightPercent===null?'Setup required':chapter.examWeightPercent+'%')}</td><td>${escapeHTML(chapter.examImpactLabel)}</td><td>${escapeHTML(formatScorePercentage(chapter.averageScore))}</td><td><span class="chapter-status chapter-status--${escapeHTML(chapter.statusKey)}">${escapeHTML(chapter.statusLabel)}</span></td><td>${escapeHTML(chapter.priorityLabel)}</td><td>${chapter.scoredEntryCount}</td><td>${escapeHTML(formatScorePercentage(chapter.latestScore))}</td><td>${escapeHTML(formatStudyMinutes(chapter.totalStudyMinutes))}</td><td>${escapeHTML(chapter.trend)}</td></tr>`).join('')}</tbody></table></div>`}
function chapterInsights(metrics){const high=findHighestPerformingChapter(metrics),low=findLowestPerformingChapter(metrics),needsOne=metrics.find(ch=>ch.scoredEntryCount===1),missing=metrics.filter(ch=>ch.totalEntryCount===0),important=metrics.find(ch=>Number(ch.examWeightPercent)>=20&&ch.statusKey==='needs-improvement'),dataGap=metrics.find(ch=>ch.priorityLabel==='High-Priority Data Gap'),estimated=metrics.some(ch=>ch.weightSource==='student-estimate'),items=[];if(high)items.push(`${high.chapterName} currently has your highest recorded average at ${formatScorePercentage(high.averageScore)}.`);if(low)items.push(`${low.chapterName} currently has your lowest recorded average at ${formatScorePercentage(low.averageScore)}.`);if(needsOne)items.push(`${needsOne.chapterName} needs one more scored activity before it can be classified.`);if(missing.length)items.push(`You have not recorded performance data for ${missing.length} exam chapter${missing.length===1?'':'s'}.`);if(important)items.push(`${important.chapterName} is a high-weight exam chapter with a recorded average below 70%.`);if(dataGap)items.push(`${dataGap.chapterName} is a high-priority data gap. More performance data is needed for this important chapter.`);if(estimated)items.push('These chapter weights are estimates. Your prediction may change if the official exam breakdown is different.');return items.length?`<article class="chapter-insights"><h4>Performance Insights</h4>${items.map(item=>`<p>${escapeHTML(item)}</p>`).join('')}<button class="btn btn-secondary" type="button" data-add-performance-from-warning>Add Performance Data</button></article>`:''}
function weightedPerformanceSummary(metrics){const weighted=calculateWeightedRecordedPerformance(metrics),status=weighted.completeCoverage?'Full Chapter Coverage':'Partial Chapter Coverage',score=weighted.score===null?'Not enough data':weighted.score+'%',message=weighted.score===null?'Record at least two scored activities in weighted chapters before this can be calculated.':weighted.completeCoverage?'Every non-zero-weight chapter has enough data for weighted performance.':'This score is based only on chapters with enough recorded data.';return `<section class="weighted-performance-summary"><div>${profileFact('Weighted Recorded Performance',score)}${profileFact('Exam Weight Covered',weighted.coveredWeight+'%')}${profileFact('Coverage Status',status)}</div><p>${escapeHTML(message)}</p></section>`}
function assessmentCategoryCard(row){const contribution=row.weightedContribution===null?'Not Enough Data':row.weightedContribution+' percentage points';return `<article class="chapter-performance-item assessment-category-item" aria-labelledby="category-${escapeHTML(row.category)}"><div class="chapter-performance-head"><div><h4 id="category-${escapeHTML(row.category)}">${escapeHTML(row.label)}</h4><small>Exam Weight: ${escapeHTML(row.examWeightPercent===null?'Setup required':row.examWeightPercent+'%')}</small></div><span class="chapter-status chapter-status--${escapeHTML(row.status.toLowerCase().replace(/\s+/g,'-'))}">${escapeHTML(row.status)}</span></div><div class="profile-fact-grid">${profileFact('Exam Weight',row.examWeightPercent===null?'Setup required':row.examWeightPercent+'%')}${profileFact('Average Score',formatScorePercentage(row.averageScore))}${profileFact('Status',row.status)}${profileFact('Scored Activities',String(row.scoredEntryCount))}${profileFact('Weighted Contribution',contribution)}${profileFact('Data Readiness',row.dataReadiness)}</div>${row.scoredEntryCount<2?`<p>More performance data is needed for ${escapeHTML(row.label)}.</p>`:''}</article>`}
function categoryFocusSuggestion(chapters,categories){const weakChapter=chapters.find(ch=>ch.scoredEntryCount>=2&&ch.statusKey==='needs-improvement'),weakCategory=categories.find(row=>row.scoredEntryCount>=2&&row.status==='Needs Improvement'&&Number(row.examWeightPercent)>0);return weakChapter&&weakCategory?`Practise ${weakCategory.label.toLowerCase()} questions in ${weakChapter.chapterName}.`:''}
function assessmentCategoryPerformanceSection(profile,entries,chapterMetrics){const rows=calculateAssessmentCategoryPerformance(entries,profile.assessmentCategoryWeights),weighted=calculateWeightedCategoryRecordedPerformance(rows),status=weighted.completeCoverage?'Full Category Coverage':'Partial Category Coverage',score=weighted.score===null?'Not enough data':weighted.score+'%',message=weighted.score===null?'Record at least two scored activities in an assessment category before calculating weighted category performance.':weighted.completeCoverage?'All assessment categories have enough scored data for a complete weighted view.':'This recorded performance is normalized across only the covered category weight.',estimateNotice=profile.assessmentWeightSource==='student-estimate'?'<p class="chapter-weight-note">These category weights are estimates and may not match the official exam breakdown.</p>':'',suggestion=categoryFocusSuggestion(chapterMetrics,rows);return `<article class="chapter-performance-card assessment-category-performance" id="assessmentCategoryPerformanceSection"><div class="card-head"><div><h3>Assessment Category Performance</h3><p>Track Knowledge and Understanding, Thinking, Communication, and Application separately from chapter content.</p></div><button class="btn btn-secondary" data-open-assessment-weights type="button">Edit Assessment Weights</button></div><section class="weighted-performance-summary"><div>${profileFact('Weighted Category Performance',score)}${profileFact('Assessment Weight Covered',weighted.coveredWeight+'%')}${profileFact('Coverage Status',status)}</div><p>${escapeHTML(message)}</p></section>${estimateNotice}${suggestion?`<article class="chapter-insights"><h4>Suggested Focus</h4><p>${escapeHTML(suggestion)}</p></article>`:''}<div class="chapter-performance-grid">${rows.map(assessmentCategoryCard).join('')}</div>${assessmentWeightEditor(profile)}</article>`}
function assessmentWeightEditor(profile){const open=sessionStorage.getItem('assessmentWeightEditorOpen')==='true'||!profile.assessmentCategoryWeightsValid;if(!open)return'';const status=getAssessmentCategoryWeightStatus(profile.assessmentCategoryWeights),rows=ASSESSMENT_CATEGORIES.map(([label,key])=>`<label>${escapeHTML(label)}<span class="weight-input-wrap"><input data-assessment-editor-weight="${escapeHTML(key)}" type="number" min="0" max="100" step="0.1" value="${escapeHTML(profile.assessmentCategoryWeights?.[key]??'')}"><span>%</span></span></label>`).join('');return `<section class="chapter-weight-editor assessment-weight-editor" id="assessmentWeightEditor"><div class="chapter-detail-top"><div><span class="kicker">EDIT ASSESSMENT CATEGORY WEIGHTS</span><h3>Edit Assessment Category Weights</h3><p>Enter the percentage assigned to each assessment category. The total must be exactly 100%.</p></div></div><div class="assessment-weight-grid">${rows}<label>Weight Source<select id="assessmentEditorSource">${CHAPTER_WEIGHT_SOURCE_OPTIONS.map(([label,value])=>`<option value="${escapeHTML(value)}" ${profile.assessmentWeightSource===value?'selected':''}>${escapeHTML(label)}</option>`).join('')}</select></label></div><div class="chapter-weight-status ${status.valid?'valid':status.total>100?'over':'incomplete'}" id="assessmentEditorStatus" aria-live="polite"><b>Total: ${escapeHTML(String(status.total))}%</b><span>${escapeHTML(status.message)}</span></div><div class="prediction-actions"><button class="btn btn-primary" data-save-assessment-weights type="button">Save Weights</button><button class="btn btn-secondary" data-cancel-assessment-weights type="button">Cancel</button></div></section>`}
function chapterWeightEditor(profile){const open=sessionStorage.getItem('chapterWeightEditorOpen')==='true'||!profile.chapterWeightsValid;if(!open)return'';const status=getChapterWeightStatus(profile.chapters),rows=profile.chapters.map((chapter,index)=>`<div class="chapter-weight-editor-row" data-weight-editor-row="${index}" data-chapter-id="${escapeHTML(chapter.id)}"><b>${escapeHTML(chapter.name)}</b><label>Exam Weight<span class="weight-input-wrap"><input data-weight-editor-input type="number" min="0" max="100" step="0.1" value="${escapeHTML(chapter.examWeightPercent===null?'':chapter.examWeightPercent)}"><span>%</span></span></label><label>Weight Source<select data-weight-editor-source>${CHAPTER_WEIGHT_SOURCE_OPTIONS.map(([label,value])=>`<option value="${escapeHTML(value)}" ${chapter.weightSource===value?'selected':''}>${escapeHTML(label)}</option>`).join('')}</select></label></div>`).join('');return `<section class="chapter-weight-editor" id="chapterWeightEditor"><div class="chapter-detail-top"><div><span class="kicker">EDIT CHAPTER WEIGHTS</span><h3>Edit Chapter Weights</h3><p>Enter the percentage of the exam assigned to each chapter. The total must be exactly 100%.</p></div></div><div class="chapter-weight-editor-list">${rows}</div><div class="chapter-weight-status ${status.valid?'valid':status.total>100?'over':'incomplete'}" id="chapterWeightEditorStatus" aria-live="polite"><b>Current total: ${escapeHTML(String(status.total))}%</b><span>${escapeHTML(status.message)}</span></div><div class="prediction-actions"><button class="btn btn-secondary" data-editor-distribute type="button">Distribute Equally</button><button class="btn btn-primary" data-save-chapter-weights type="button">Save Weights</button><button class="btn btn-secondary" data-cancel-chapter-weights type="button">Cancel</button></div></section>`}
