function readinessHistoryList(profileId){const rows=getExamReadinessHistory().filter(row=>row.predictionProfileId===profileId).sort((a,b)=>new Date(b.calculatedAt)-new Date(a.calculatedAt)).slice(0,8);return rows.length?rows.map(row=>`<div><span>${escapeHTML(formatProfileDate(row.calculatedAt))}</span><b>${row.displayScore===null?'Not Available':row.displayScore+'%'}</b><small>${escapeHTML(row.label)}${row.status==='outdated'?' - Outdated':''}</small></div>`).join(''):'<div class="empty-mini">Readiness history appears after the first calculation.</div>'}
function currentExamReadinessForLikely(profile,readiness,{persist=false}={}){const metrics=readiness.metrics,latest=getLatestExamReadiness(profile.id),current=examReadinessRecordIsCurrent(latest,profile,metrics)?latest:null;if(current)return current;const candidate=createExamReadinessRecord(profile,readiness);if(candidate.status==='current'&&candidate.score!==null)return persist?saveExamReadinessRecord(candidate):candidate;return candidate}
function likelyScoreHistoryList(profileId){const rows=getLikelyExamScoreHistory().filter(row=>row.predictionProfileId===profileId).sort((a,b)=>new Date(b.calculatedAt)-new Date(a.calculatedAt)).slice(0,8);return rows.length?rows.map(row=>`<div><span>${escapeHTML(formatProfileDate(row.calculatedAt))}</span><b>${row.displayEstimate===null?'Not Available':formatApproximateExamScore(row.centralEstimate)}</b><small>${escapeHTML(row.status==='outdated'?'Outdated':formatEstimatedRange(row.estimatedRange))}</small></div>`).join(''):'<div class="empty-mini">Likely score history appears after the first calculation.</div>'}
function likelyScoreCategoryRows(record){return (record.categoryBreakdown||[]).map(row=>`<tr><td>${escapeHTML(row.label||assessmentCategoryLabel(row.category))}</td><td>${escapeHTML(row.averageScore===null||row.averageScore===undefined?'Not enough data':row.averageScore+'%')}</td><td>${escapeHTML(row.weight===null||row.weight===undefined?'Invalid':row.weight+'%')}</td><td>${escapeHTML(row.contribution===null||row.contribution===undefined?row.missingReason||'Not available':row.contribution+' points')}</td></tr>`).join('')}
function likelyScoreCategoryInsights(record){const rows=(record.categoryBreakdown||[]).filter(row=>Number(row.weight)>0&&Number.isFinite(Number(row.averageScore))),items=[];const heavy=rows.sort((a,b)=>Number(b.weight)-Number(a.weight))[0],high=rows.sort((a,b)=>Number(b.averageScore)-Number(a.averageScore))[0],low=rows.sort((a,b)=>Number(a.averageScore)-Number(b.averageScore))[0];if(heavy)items.push(`${heavy.label} has a large effect on this estimate because it is worth ${heavy.weight}% of the exam.`);if(high)items.push(`${high.label} currently has the highest recorded category average at ${formatScorePercentage(high.averageScore)}.`);if(low)items.push(`${low.label} currently needs the most attention with a recorded average of ${formatScorePercentage(low.averageScore)}.`);return items}
function likelyScoreChapterEvidence(profile,readiness){const chapters=calculateChapterPerformance(profile,readiness.metrics.entries),high=findHighestPerformingChapter(chapters),low=findLowestPerformingChapter(chapters),missing=chapters.filter(chapter=>chapter.scoredEntryCount<2).map(chapter=>chapter.chapterName);return `<section class="chapter-insights"><h4>Chapter Evidence</h4><div class="profile-fact-grid">${profileFact('Strongest recorded chapter',high?`${high.chapterName} - ${formatScorePercentage(high.averageScore)}`:'Not enough data')}${profileFact('Lowest recorded chapter',low?`${low.chapterName} - ${formatScorePercentage(low.averageScore)}`:'Not enough data')}${profileFact('Chapters needing more data',missing.length?missing.slice(0,4).join(', '):'All active chapters have data')}${profileFact('Official chapter weighting','Used only when official chapter weights total 100%.')}</div></section>`}
function targetComparisonCard(profile,record){const comparison=compareTargetGradeToRange(profile.targetGrade,record.estimatedRange);return `<section class="chapter-insights target-comparison target-${escapeHTML(comparison.status)}"><h4>Target Grade Comparison</h4><div class="profile-fact-grid">${profileFact('Target Grade',Number.isFinite(Number(profile.targetGrade))?Number(profile.targetGrade)+'%':'Not set')}${profileFact('Estimated Range',formatEstimatedRange(record.estimatedRange))}</div><p>${escapeHTML(comparison.message)} This is not a guarantee.</p></section>`}
function renderLikelyExamScore(profile,readiness){const metrics=readiness.metrics,latest=getLatestLikelyExamScore(profile.id),readinessRecord=currentExamReadinessForLikely(profile,readiness),current=likelyExamScoreRecordIsCurrent(latest,profile,metrics,readinessRecord)?latest:null,preview=createLikelyExamScoreRecord(profile,readiness,readinessRecord);if(calculateDaysRemaining(profile.examDate)<0||!readiness.ready||preview.status!=='current'){const missing=preview.missingRequirements?.length?preview.missingRequirements:readiness.missingRequirements;return `<article class="current-readiness-card likely-score-card not-ready"><div class="card-head"><div><span class="status-badge status-pending">Not Available</span><h3>Likely Exam Score</h3><p>More recorded performance data is needed before a likely exam score can be estimated.</p></div><button class="btn btn-primary" data-recalculate-likely-score type="button" disabled>Recalculate Likely Score</button></div><div class="readiness-main-score"><b>Not Available</b><span>Likely Exam Score</span></div>${preview.partialRecordedEstimate!==null?`<section class="weighted-performance-summary"><div>${profileFact('Partial Recorded Estimate',preview.partialRecordedEstimate+'%')}${profileFact('Exam Weight Covered',preview.examWeightCovered+'%')}${profileFact('Coverage Status','Partial only')}</div><p>This partial estimate does not cover the full exam.</p></section>`:''}<ul class="missing-readiness">${missing.map(item=>`<li>${escapeHTML(item)}</li>`).join('')}</ul>${likelyScoreChapterEvidence(profile,readiness)}<p class="readiness-note">This is an estimate based on recorded performance, not a guaranteed exam result.</p>${latest?`<section class="readiness-breakdown"><h4>Likely Score History</h4><div class="readiness-history">${likelyScoreHistoryList(profile.id)}</div></section>`:''}</article>`}if(!current){return `<article class="current-readiness-card likely-score-card ready"><div class="card-head"><div><span class="status-badge status-active">Ready</span><h3>Likely Exam Score</h3><p>${latest?'Your likely exam score needs to be recalculated.':'Enough data is available. Select Calculate Likely Score to create the first estimate.'}</p></div><button class="btn btn-primary" data-recalculate-likely-score type="button">${latest?'Recalculate Likely Score':'Calculate Likely Score'}</button></div><div class="readiness-main-score"><b>Not Available</b><span>Likely Exam Score</span></div><p class="readiness-note">This is an estimate based on recorded performance, not a guaranteed exam result.</p>${latest?`<section class="readiness-breakdown"><h4>Likely Score History</h4><div class="readiness-history">${likelyScoreHistoryList(profile.id)}</div></section>`:''}</article>`}const adjustment=Number.isFinite(Number(current.examReadinessScore))?Number((current.centralEstimate-current.categoryWeightedScore-(Number.isFinite(Number(current.officialChapterWeightedScore))?(current.officialChapterWeightedScore-current.categoryWeightedScore)*.25:0)).toFixed(1)):null,insights=likelyScoreCategoryInsights(current);return `<article class="current-readiness-card likely-score-card ready"><div class="card-head"><div><span class="status-badge status-active">${escapeHTML(current.dataCoverageLabel)}</span><h3>Likely Exam Score</h3><p>Based on activity recorded through ${escapeHTML(formatProfileDate(current.basedOnLatestPerformanceUpdate||current.calculatedAt))}.</p></div><button class="btn btn-primary" data-recalculate-likely-score type="button">Recalculate</button></div><div class="readiness-main-score"><b>${escapeHTML(formatApproximateExamScore(current.centralEstimate))}</b><span>Estimated Range: ${escapeHTML(formatEstimatedRange(current.estimatedRange))}</span></div><div class="profile-fact-grid">${profileFact('Calculation detail',current.centralEstimate+'%')}${profileFact('Recorded weighted score',current.categoryWeightedScore+'%')}${profileFact('Official chapter-weighted estimate',current.officialChapterWeightedScore===null?'Not available':current.officialChapterWeightedScore+'%')}${profileFact('Exam readiness score',current.examReadinessScore+'%')}${profileFact('Score variation',current.standardDeviation===null?'Not enough data':current.standardDeviation+' points')}${profileFact('Last calculated',formatProfileDate(current.calculatedAt))}</div><p class="readiness-note">This is an estimate based on recorded performance, not a guaranteed exam result.</p><p class="readiness-note">Actual results may be affected by exam difficulty, question selection, marking and performance on the exam day.</p>${targetComparisonCard(profile,current)}<section class="readiness-breakdown"><h4>Assessment Category Breakdown</h4><div class="responsive-table"><table><thead><tr><th>Category</th><th>Average</th><th>Weight</th><th>Contribution</th></tr></thead><tbody>${likelyScoreCategoryRows(current)}</tbody></table></div><ul>${Number.isFinite(adjustment)?`<li>Readiness Adjustment: ${adjustment>=0?'+':''}${adjustment} points</li>`:''}<li>Likely Exam Score: ${escapeHTML(String(current.centralEstimate))}%</li><li>Rounded: ${escapeHTML(formatApproximateExamScore(current.centralEstimate))}</li></ul></section>${insights.length?`<section class="chapter-insights"><h4>Category Influence</h4>${insights.map(item=>`<p>${escapeHTML(item)}</p>`).join('')}</section>`:''}${likelyScoreChapterEvidence(profile,readiness)}<section class="readiness-breakdown"><h4>Data Coverage</h4><div class="profile-fact-grid">${profileFact('Coverage label',current.dataCoverageLabel)}${profileFact('Range margin',current.estimatedRange.margin+' points')}${profileFact('Variation adjustment',current.estimatedRange.variationAdjustment+' points')}${profileFact('Estimate date',formatProfileDate(current.calculatedAt))}</div></section><section class="readiness-breakdown"><h4>Likely Score History</h4><div class="readiness-history">${likelyScoreHistoryList(profile.id)}</div></section></article>`}
function calculateAndSaveLikelyExamScore(profileId,{updated=false}={}){const profile=findPredictionProfile(profileId),readiness=evaluatePredictionDataReadiness(profileId);if(!profile)return null;const readinessRecord=currentExamReadinessForLikely(profile,readiness,{persist:true}),chapterMetrics=calculateChapterPerformance(profile,readiness.metrics.entries),validation=validatePredictionRequirements({predictionType:'likelyExamScore',predictionProfile:profile,chapterMetrics,performanceEntries:readiness.metrics.entries,dependencies:{readiness,examReadiness:readinessRecord}});if(!validation.available){renderPredictionPerformancePanel();showNotification({type:'warning',message:'More recorded information is needed before this prediction can be calculated.',persistent:true});return null}const record=createLikelyExamScoreRecord(profile,readiness,readinessRecord);if(record.status!=='current'||record.centralEstimate===null){renderPredictionPerformancePanel();showNotification({type:'warning',message:'More recorded performance data is needed before a likely score can be estimated.',persistent:true});return null}const saved=saveLikelyExamScoreRecord(record);renderPredictionPerformancePanel();showNotification({type:'success',message:updated?'Likely exam score updated.':'Likely exam score calculated successfully.'});return saved}
function renderCurrentExamReadiness(profile,readiness){const rules=futureExamReadinessRules(),weightValidation=validateReadinessWeights(rules.componentWeights),latest=getLatestExamReadiness(profile.id),daysRemaining=calculateDaysRemaining(profile.examDate);if(!weightValidation.valid)return `<article class="current-readiness-card not-ready"><div><span class="status-badge status-declined">Configuration Error</span><h3>Current Exam Readiness</h3><p>Exam readiness weights are invalid.</p></div></article>`;if(daysRemaining!==null&&daysRemaining<0)return `<article class="current-readiness-card not-ready"><div><span class="status-badge status-pending">Not Available</span><h3>Current Exam Readiness</h3><p>This exam date has passed.</p></div><div class="prediction-actions"><button class="btn btn-secondary" type="button" onclick="document.getElementById('predictionExamDate')?.focus()">Update Exam Date</button></div></article>`;if(!readiness.ready)return `<article class="current-readiness-card not-ready"><div><span class="status-badge status-pending">Not Available</span><h3>Current Exam Readiness</h3><p>More performance data is needed before exam readiness can be estimated.</p></div><div class="readiness-main-score"><b>Not Available</b><span>Exam Readiness</span></div><ul class="missing-readiness">${readiness.missingRequirements.map(item=>`<li>${escapeHTML(item)}</li>`).join('')}</ul><p class="readiness-note">This is an estimate based on recorded activity, not a guaranteed exam result.</p></article>`;const record=examReadinessRecordIsCurrent(latest,profile,readiness.metrics)?latest:null,preview=record?null:createExamReadinessRecord(profile,readiness);if(!record&&preview?.missingComponents?.length)return `<article class="current-readiness-card not-ready"><div><span class="status-badge status-pending">Not Available</span><h3>Current Exam Readiness</h3><p>More component data is needed before exam readiness can be estimated.</p></div><div class="readiness-main-score"><b>Not Available</b><span>Exam Readiness</span></div><ul class="missing-readiness">${preview.missingComponents.map(key=>`<li>${escapeHTML(missingComponentMessage(key))}</li>`).join('')}</ul><div class="prediction-actions"><button class="btn btn-primary" data-recalculate-readiness type="button">Recalculate Readiness</button></div><p class="readiness-note">This is an estimate based on recorded activity, not a guaranteed exam result.</p></article>`;if(!record)return `<article class="current-readiness-card ready"><div><span class="status-badge status-active">Ready</span><h3>Current Exam Readiness</h3><p>${latest?'Your readiness estimate needs to be recalculated.':'Enough data is available. Select Calculate Exam Readiness to create the first estimate.'}</p></div><div class="readiness-main-score"><b>Not Available</b><span>Exam Readiness</span></div><div class="prediction-actions"><button class="btn btn-primary" data-recalculate-readiness type="button">${latest?'Recalculate Readiness':'Calculate Exam Readiness'}</button></div><p class="readiness-note">This is an estimate based on recorded activity, not a guaranteed exam result.</p>${latest?`<section class="readiness-breakdown"><h4>Readiness History</h4><div class="readiness-history">${readinessHistoryList(profile.id)}</div></section>`:''}</article>`;const components=record.components||{},score=record.displayScore??Math.round(record.score),bar=clampNumber(score,0,100);return `<article class="current-readiness-card readiness-${escapeHTML(record.labelKey)}"><div class="card-head"><div><span class="status-badge status-active">${escapeHTML(record.dataCoverage.label)}</span><h3>Current Exam Readiness</h3><p>Based on activity recorded through ${escapeHTML(formatProfileDate(record.basedOnLatestPerformanceUpdate||record.calculatedAt))}.</p></div><button class="btn btn-primary" data-recalculate-readiness type="button">Recalculate Readiness</button></div><div class="readiness-main-score"><b>${score}%</b><span>${escapeHTML(record.label)}</span></div><div class="readiness-progress" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${bar}" aria-label="Estimated Exam Readiness"><i style="width:${bar}%"></i></div><p class="readiness-note">This is an estimate based on recorded activity, not a guaranteed exam result.</p><p class="readiness-note">The estimate becomes more useful when you regularly record accurate scores, study time and completed tasks.</p><div class="readiness-component-grid">${Object.entries(components).map(([key,component])=>componentCard(key,component)).join('')}</div><section class="readiness-breakdown"><h4>Exam Readiness Calculation</h4><ul>${calculationLine('Chapter Performance',components.chapterPerformance)}${calculationLine('Recent Improvement',components.recentImprovement)}${calculationLine('Completed Study Tasks',components.taskCompletion)}${calculationLine('Study Consistency',components.studyConsistency)}${calculationLine('Time Remaining',components.timeRemaining)}<li>Total: ${escapeHTML(String(record.score))}%</li><li>Rounded Display: ${score}%</li></ul></section><section class="chapter-insights"><h4>Readiness Insights</h4><ul>${readinessInsights(record).map(item=>`<li>${escapeHTML(item)}</li>`).join('')}</ul></section><section class="readiness-breakdown"><h4>Data Coverage</h4><div class="profile-fact-grid">${profileFact('Performance entries',String(record.dataCoverage.performanceEntries))}${profileFact('Scored entries',String(record.dataCoverage.scoredEntries))}${profileFact('Study dates',String(record.dataCoverage.differentDates))}${profileFact('Chapters with data',String(record.dataCoverage.chaptersWithData))}${profileFact('Assessment categories',String(record.dataCoverage.assessmentCategoriesWithData))}${profileFact('Last updated',formatProfileDate(record.calculatedAt))}</div></section><section class="readiness-breakdown"><h4>Readiness History</h4><div class="readiness-history">${readinessHistoryList(profile.id)}</div></section></article>`}
function renderPredictionPerformancePanelStep5(){const root=$('#predictionPerformanceContent'),panel=$('#predictionPerformancePanel');if(!root||!panel)return;const profile=selectedPredictionProfile();if(!profile){root.innerHTML='<div class="empty-state"><h2>Open a Prediction Profile before adding performance data.</h2><p>Add quiz results, practice scores, assignments and completed study sessions to build your progress history.</p><button class="btn btn-primary" id="openPredictionProfilesBtn" type="button">Open Prediction Profiles</button></div>';$('#openPredictionProfilesBtn')?.addEventListener('click',()=>$('#predictionProfilesGrid')?.scrollIntoView({behavior:'smooth'}));return}const metrics=predictionMetrics(profile.id),readiness=evaluatePredictionDataReadiness(profile.id),chapterMetrics=calculateChapterPerformance(profile,metrics.entries),taskText=metrics.tasks.totalTasks?`${metrics.tasks.completedTasks} of ${metrics.tasks.totalTasks}`:'0 of 0';root.innerHTML=`<article class="performance-overview-card"><div class="card-head"><div><h3>${escapeHTML(profile.examName)}</h3><p>${escapeHTML(profile.course)} - ${escapeHTML(daysRemainingLabel(profile.examDate))}</p></div><span class="pill blue-pill">${metrics.entries.length} recorded activities</span></div><div class="profile-fact-grid">${profileFact('Recorded Activities',String(metrics.entries.length))}${profileFact('Average Score',metrics.averageScore===null?'Not enough data':metrics.averageScore+'%')}${profileFact('Total Study Time',formatStudyMinutes(metrics.study.totalMinutes))}${profileFact('Tasks Completed',taskText)}${profileFact('Average Attempts',metrics.attempts.averageAttempts||'Not enough data')}${profileFact('Days Remaining',daysRemainingLabel(profile.examDate))}</div></article>${renderDataReadiness(readiness)}${renderCurrentExamReadiness(profile,readiness)}${renderLikelyExamScore(profile,readiness)}${assessmentCategoryPerformanceSection(profile,metrics.entries,chapterMetrics)}${renderChapterPerformanceSection(profile,metrics)}${orphanedPerformanceSection(profile)}<article class="performance-history-section"><h3>Performance History</h3>${metrics.entries.length?metrics.entries.slice().sort((a,b)=>parseLocalDate(b.date)-parseLocalDate(a.date)||new Date(b.createdAt)-new Date(a.createdAt)).map(performanceHistoryCard).join(''):'<div class="empty-state"><h2>No performance data has been recorded yet.</h2><p>Add quiz results, practice scores, assignments and completed study sessions to build your progress history.</p><button class="btn btn-primary" id="addFirstPerformanceEntryBtn" type="button">Add Your First Entry</button></div>'}</article>`;$('#addFirstPerformanceEntryBtn')?.addEventListener('click',()=>openPerformanceForm());$$('[data-performance-edit]',root).forEach(btn=>btn.onclick=()=>openPerformanceForm(btn.dataset.performanceEdit));$$('[data-performance-delete]',root).forEach(btn=>btn.onclick=()=>confirmDeletePerformanceEntry(btn.dataset.performanceDelete));$$('[data-recalculate-readiness]',root).forEach(btn=>btn.onclick=()=>calculateAndSaveExamReadiness(profile.id,{updated:!!getLatestExamReadiness(profile.id)}));$$('[data-recalculate-likely-score]',root).forEach(btn=>btn.onclick=()=>calculateAndSaveLikelyExamScore(profile.id,{updated:!!getLatestLikelyExamScore(profile.id)}));bindAssessmentCategoryControls();bindChapterPerformanceControls();bindOrphanedPerformanceControls()}
async function offerQuizToPredictor({subject,score,correct,total,durationMinutes=10}={}){const profiles=getCurrentUserPredictionProfiles().filter(profile=>profile.course.toLowerCase()===String(subject||'').toLowerCase());if(!profiles.length)return;showNotification({type:'information',message:'Add this quiz result to a Prediction Profile?',actionLabel:'Add to Predictor',onAction:async()=>{const profile=profiles.length===1?profiles[0]:profiles[Number(prompt('Choose a Prediction Profile number:\n'+profiles.map((p,i)=>`${i+1}. ${p.examName}`).join('\n')))-1];if(!profile)return;const chapter=profile.chapters.length===1?profile.chapters[0].name:profile.chapters[Number(prompt('Choose a chapter number:\n'+profile.chapters.map((ch,i)=>`${i+1}. ${ch.name}`).join('\n')))-1]?.name;if(!chapter)return;const category=ASSESSMENT_CATEGORIES[Number(prompt('Choose an assessment category number:\n'+ASSESSMENT_CATEGORIES.map(([label],i)=>`${i+1}. ${label}`).join('\n')))-1]?.[2];if(!category)return;const payload={activityType:'quiz',chapter,assessmentCategory:category,score,questionsCorrect:correct,totalQuestions:total,timeSpentMinutes:durationMinutes,attempts:1,completed:true,date:today(),notes:'Saved from completed quiz.'};let result=savePerformanceRecord('',payload,profile,{skipDuplicateWarning:false});if(result.duplicate){const ok=await confirmDialog({title:'Possible Duplicate Entry',message:'This entry may already exist.',okText:'Save Anyway',cancelText:'Cancel'});if(ok)result=savePerformanceRecord('',payload,profile,{skipDuplicateWarning:true})}if(result?.success){renderPredictionPerformancePanel();showNotification({type:'success',message:'Performance data saved successfully.'});predictionUpdateManager.requestUpdate({userId:predictionUserId(),predictionProfileId:profile.id,triggerType:PREDICTION_UPDATE_TRIGGERS.QUIZ_COMPLETED,sourceRecordId:result.entry.id})}}})}
function renderPredictionPerformancePanelStep7(){const root=$('#predictionPerformanceContent'),panel=$('#predictionPerformancePanel');if(!root||!panel)return;const profile=selectedPredictionProfile();if(!profile){root.innerHTML='<div class="empty-state"><h2>Open a Prediction Profile before adding performance data.</h2><p>Add quiz results, practice scores, assignments and completed study sessions to build your progress history.</p><button class="btn btn-primary" id="openPredictionProfilesBtn" type="button">Open Prediction Profiles</button></div>';$('#openPredictionProfilesBtn')?.addEventListener('click',()=>$('#predictionProfilesGrid')?.scrollIntoView({behavior:'smooth'}));return}const metrics=predictionMetrics(profile.id),readiness=evaluatePredictionDataReadiness(profile.id),chapterMetrics=calculateChapterPerformance(profile,metrics.entries),taskText=metrics.tasks.totalTasks?`${metrics.tasks.completedTasks} of ${metrics.tasks.totalTasks}`:'0 of 0';root.innerHTML=`<article class="performance-overview-card"><div class="card-head"><div><h3>${escapeHTML(profile.examName)}</h3><p>${escapeHTML(profile.course)} - ${escapeHTML(daysRemainingLabel(profile.examDate))}</p></div><span class="pill blue-pill">${metrics.entries.length} recorded activities</span></div><div class="profile-fact-grid">${profileFact('Recorded Activities',String(metrics.entries.length))}${profileFact('Average Score',metrics.averageScore===null?'Not enough data':metrics.averageScore+'%')}${profileFact('Total Study Time',formatStudyMinutes(metrics.study.totalMinutes))}${profileFact('Tasks Completed',taskText)}${profileFact('Average Attempts',metrics.attempts.averageAttempts||'Not enough data')}${profileFact('Days Remaining',daysRemainingLabel(profile.examDate))}</div></article>${renderDataReadiness(readiness)}${renderCurrentExamReadiness(profile,readiness)}${renderLikelyExamScore(profile,readiness)}${renderTargetProbability(profile,readiness)}${assessmentCategoryPerformanceSection(profile,metrics.entries,chapterMetrics)}${renderChapterPerformanceSection(profile,metrics)}${orphanedPerformanceSection(profile)}<article class="performance-history-section"><h3>Performance History</h3>${metrics.entries.length?metrics.entries.slice().sort((a,b)=>parseLocalDate(b.date)-parseLocalDate(a.date)||new Date(b.createdAt)-new Date(a.createdAt)).map(performanceHistoryCard).join(''):'<div class="empty-state"><h2>No performance data has been recorded yet.</h2><p>Add quiz results, practice scores, assignments and completed study sessions to build your progress history.</p><button class="btn btn-primary" id="addFirstPerformanceEntryBtn" type="button">Add Your First Entry</button></div>'}</article>`;$('#addFirstPerformanceEntryBtn')?.addEventListener('click',()=>openPerformanceForm());$$('[data-performance-edit]',root).forEach(btn=>btn.onclick=()=>openPerformanceForm(btn.dataset.performanceEdit));$$('[data-performance-delete]',root).forEach(btn=>btn.onclick=()=>confirmDeletePerformanceEntry(btn.dataset.performanceDelete));$$('[data-recalculate-readiness]',root).forEach(btn=>btn.onclick=()=>calculateAndSaveExamReadiness(profile.id,{updated:!!getLatestExamReadiness(profile.id)}));$$('[data-recalculate-likely-score]',root).forEach(btn=>btn.onclick=()=>calculateAndSaveLikelyExamScore(profile.id,{updated:!!getLatestLikelyExamScore(profile.id)}));$$('[data-recalculate-target-probability]',root).forEach(btn=>btn.onclick=()=>calculateAndSaveTargetProbability(profile.id,{updated:!!getLatestTargetProbability(profile.id)}));bindAssessmentCategoryControls();bindChapterPerformanceControls();bindOrphanedPerformanceControls()}
