const renderPredictionPerformancePanelBase=renderPredictionPerformancePanel;
renderPredictionPerformancePanel=function(){renderPredictionPerformancePanelBase();const root=$('#predictionPerformanceContent'),profile=selectedPredictionProfile();if(!root||!profile||root.querySelector('.prediction-safety-overview'))return;const readiness=evaluatePredictionDataReadiness(profile.id),chapterMetrics=calculateChapterPerformance(profile,readiness.metrics.entries),overview=root.querySelector('.performance-overview-card');overview?.insertAdjacentHTML('afterend',renderPredictionSafetyOverview(profile,readiness,chapterMetrics));repairRenderedEncoding(root)}
function startReviewChoice(course,topic){showView('quiz');if($('#quizSubject'))$('#quizSubject').value=course;renderQuiz(buildTopicPracticeQuiz(course,topic),course);toast(`${topic} is ready for review.`)}
function methodConfidenceWithFeedback(row){const fb=ensureLearningProfile()?.methodPerformance?.feedback?.[row.method]?.mode;if(fb==='accurate'&&row.confidence==='Medium')return 'High';if(fb==='accurate'&&row.confidence==='Low')return 'Medium';if(fb==='disagree'&&row.confidence==='High')return 'Medium';if(fb==='disagree'&&row.confidence==='Medium')return 'Low';return row.confidence}
function methodWhy(row){if(row.confidence==='Not Enough Data')return `StudySpark needs at least ${methodRules().confidence?.lowMin||3} linked quizzes before ranking ${row.method}.`;return `You completed ${row.assessments} linked quiz${row.assessments===1?'':'zes'} after using ${row.method} and averaged ${row.averageScore}% with ${methodConfidenceWithFeedback(row).toLowerCase()} confidence.`}
function methodCard(row,index){const avg=row.averageScore===null?'Not enough data':`${row.averageScore}%`,recent=row.recentAverage===null?'Not enough data':`${row.recentAverage}%`,confidence=methodConfidenceWithFeedback(row);return `<article class="method-card ${row.status.toLowerCase().replace(/\s+/g,'-')}"><div class="learning-speed-head"><div><h3>${escapeHTML(row.method)}</h3><span>${index===0&&row.status!=='Not Enough Data'?'Current strongest method':'Study method'}</span></div><b>${escapeHTML(row.status)}</b></div><div class="profile-fact-grid">${profileFact('Average score',avg)}${profileFact('Recent average',recent)}${profileFact('Sessions',String(row.sessions||0))}${profileFact('Linked quizzes',String(row.assessments||0))}${profileFact('Confidence',confidence)}${profileFact('Trend',row.trend||'Stable')}</div><p class="method-why hidden">${escapeHTML(methodWhy(row))}</p><div class="method-actions"><button type="button" class="btn btn-secondary" data-method-why="${escapeHTML(row.method)}">Why?</button><button type="button" class="btn btn-ghost" data-method-feedback="${escapeHTML(row.method)}" data-mode="accurate">This seems accurate</button><button type="button" class="btn btn-ghost" data-method-feedback="${escapeHTML(row.method)}" data-mode="disagree">This does not seem accurate</button><button type="button" class="btn btn-ghost" data-method-feedback="${escapeHTML(row.method)}" data-mode="try_more">Try this method more often</button><button type="button" class="btn btn-danger" data-method-feedback="${escapeHTML(row.method)}" data-mode="reset">Reset method data</button></div></article>`}
function renderEffectiveMethods(){if(!$('#effectiveMethodsGrid'))return;const rows=methodRows(),ranked=rows.sort((a,b)=>(b.averageScore??-1)-(a.averageScore??-1)),used=mostUsedMethod(),effective=bestMethod();$('#methodSummary').innerHTML=`<div class="method-summary-card">${profileFact('Most used method',used&&used.sessions?used.method:'Not enough data')}${profileFact('Most effective method',effective?effective.method:'Not enough data')}${profileFact('Evidence note','Results are estimates based on linked quizzes.')}</div>`;$('#effectiveMethodsGrid').innerHTML=ranked.some(r=>r.sessions||r.assessments)?ranked.map(methodCard).join(''):'<div class="empty-state card"><h2>Use different study tools and complete topic-based quizzes to discover which methods work best for you.</h2><p>StudySpark will compare methods after enough linked quiz results.</p></div>';$$('[data-method-why]').forEach(btn=>btn.onclick=()=>btn.closest('.method-card')?.querySelector('.method-why')?.classList.toggle('hidden'));$$('[data-method-feedback]').forEach(btn=>btn.onclick=()=>setMethodFeedback(btn.dataset.methodFeedback,btn.dataset.mode))}
function courseTopicSummary(course){const rows=Object.values(ensureLearningProfile()?.topicPerformance||{}).filter(r=>r.course===course),total=rows.reduce((sum,r)=>sum+r.totalAnswers,0),correct=rows.reduce((sum,r)=>sum+r.correctAnswers,0),strong=rows.filter(r=>r.status==='Strong').length,developing=rows.filter(r=>r.status==='Developing').length,needs=rows.filter(r=>r.status==='Needs Practice').length,improved=rows.filter(r=>topicTrend(r)==='Improving').sort((a,b)=>(topicRecentAccuracy(b)||0)-(topicRecentAccuracy(a)||0))[0],weakest=rows.filter(r=>r.totalAnswers>=topicRules().minimumQuestions).sort((a,b)=>(a.accuracy??100)-(b.accuracy??100))[0];return {course,accuracy:total?Math.round(correct/total*100):null,tracked:rows.length,strong,developing,needs,improved:improved?.topic||'Not enough data',weakest:weakest?.topic||'Not enough data'}}
function renderCoursePerformanceSummary(courseFilter=''){const courses=uniqueCourses([...(courseFilter?[courseFilter]:selectedCourses()),...Object.values(ensureLearningProfile()?.topicPerformance||{}).map(r=>r.course)]).filter(c=>!courseFilter||c===courseFilter),cards=courses.map(course=>{const s=courseTopicSummary(course);return `<article class="course-summary-card"><h3>${escapeHTML(course)}</h3><div class="profile-fact-grid">${profileFact('Overall accuracy',s.accuracy===null?'Not enough data':`${s.accuracy}%`)}${profileFact('Topics tracked',String(s.tracked))}${profileFact('Strong topics',String(s.strong))}${profileFact('Developing topics',String(s.developing))}${profileFact('Needs practice',String(s.needs))}${profileFact('Most improved',s.improved)}${profileFact('Current focus',s.weakest)}</div></article>`}).join('');$('#coursePerformanceSummary').innerHTML=cards||'<div class="empty-mini">Course summaries appear after topic quizzes.</div>'}
function topicPerformanceCard(row){const recent=topicRecentAccuracy(row),trend=topicTrend(row),accuracy=row.totalAnswers?`${row.accuracy}%`:'Not enough data',date=row.lastPracticed?new Date(row.lastPracticed).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}):'Not yet';return `<article class="topic-performance-row ${row.status.toLowerCase().replace(/\s+/g,'-')}"><div><h3>${escapeHTML(row.topic)}</h3><p>${escapeHTML(row.course)} - ${escapeHTML(row.unit)}</p></div><div class="topic-metrics"><span><b>${escapeHTML(accuracy)}</b><small>Lifetime accuracy</small></span><span><b>${row.totalAnswers}</b><small>Questions answered</small></span><span><b>${recent===null?'Not enough data':recent+'%'}</b><small>Recent accuracy</small></span><span><b>${escapeHTML(trend)}</b><small>Trend</small></span></div><div class="topic-status"><b>${escapeHTML(row.status)}</b><small>${row.totalAnswers?`${accuracy} across ${row.totalAnswers} question${row.totalAnswers===1?'':'s'}`:'Not enough data'}</small><small>Last practised: ${escapeHTML(date)}</small></div><button class="btn btn-secondary" type="button" data-practice-topic="${escapeHTML(row.topic)}" data-practice-course="${escapeHTML(row.course)}">Practice Topic</button></article>`}
function renderTopicPerformance(){if(!$('#topicPerformanceList'))return;const profile=ensureLearningProfile(),allRows=Object.values(profile.topicPerformance||{}),courseEl=$('#topicPerfCourse'),unitEl=$('#topicPerfUnit'),sortEl=$('#topicPerfSort'),searchEl=$('#topicPerfSearch'),prevCourse=courseEl.value,prevUnit=unitEl.value,courses=uniqueCourses([...selectedCourses(),...allRows.map(r=>r.course)]);courseEl.innerHTML='<option value="">All courses</option>'+courses.map(c=>`<option value="${escapeHTML(c)}">${escapeHTML(c)}</option>`).join('');courseEl.value=courses.includes(prevCourse)?prevCourse:'';const units=uniqueCourses(allRows.filter(r=>!courseEl.value||r.course===courseEl.value).map(r=>r.unit));unitEl.innerHTML='<option value="">All units</option>'+units.map(u=>`<option value="${escapeHTML(u)}">${escapeHTML(u)}</option>`).join('');unitEl.value=units.includes(prevUnit)?prevUnit:'';let rows=topicPerformanceRows(courseEl.value,unitEl.value,searchEl.value);if(sortEl.value==='strongest')rows.sort((a,b)=>(b.accuracy??-1)-(a.accuracy??-1));else if(sortEl.value==='recent')rows.sort((a,b)=>new Date(b.lastPracticed||0)-new Date(a.lastPracticed||0));else rows.sort((a,b)=>(a.accuracy??101)-(b.accuracy??101));renderCoursePerformanceSummary(courseEl.value);$('#topicPerformanceList').innerHTML=rows.length?rows.map(topicPerformanceCard).join(''):'<div class="empty-state card"><h2>No topic performance yet.</h2><p>Complete quizzes to help StudySpark understand your strengths and areas for improvement.</p></div>';$$('[data-practice-topic]').forEach(btn=>btn.onclick=()=>practiceTopic(btn.dataset.practiceCourse,btn.dataset.practiceTopic));[courseEl,unitEl,sortEl].forEach(el=>el.onchange=renderTopicPerformance);searchEl.oninput=renderTopicPerformance}
function buildTopicPracticeQuiz(course,topic){if(subjectNotes(course).length)return buildQuiz(course,topic);const clean=normalizeTopicName(topic),unit=normalizeUnitName(clean);return Array.from({length:5},(_,i)=>({id:`question-${Date.now()}-${i+1}`,course,unit,topic:clean,type:'Short Answer',difficulty:i<2?'Easy':i<4?'Medium':'Hard',question:`Explain one important idea about ${clean}.`,answer:clean,correctAnswer:clean,options:[],explanation:`A strong answer should use accurate details about ${clean}.`}))}
function practiceTopic(course,topic){showView('quiz');if($('#quizSubject'))$('#quizSubject').value=course;renderQuiz(buildTopicPracticeQuiz(course,topic),course);toast(`Practice quiz ready for ${topic}.`)}
function insightRow({id,title,value,evidence}){return `<article class="learning-insight-row" data-insight="${escapeHTML(id)}"><div><h3>${escapeHTML(title)}</h3><p><b>${escapeHTML(value)}</b> ${escapeHTML(evidence)}</p><small class="insight-why hidden">${escapeHTML(learningInsightReason(id))}</small></div><div class="insight-actions"><button type="button" data-insight-why="${escapeHTML(id)}">Why?</button><button type="button" data-insight-accurate="${escapeHTML(id)}">This seems accurate</button><button type="button" data-insight-disagree="${escapeHTML(id)}">This does not seem accurate</button><button type="button" data-insight-reset="${escapeHTML(id)}">Reset this insight</button></div></article>`}
function buildLearningInsights(profile){const styles=profile.learningStyles||{},habits=profile.studyHabits||{},insights=[];[['visual','Visual Learning'],['reading','Reading and Writing'],['practice','Practice-Based Learning'],['audio','Audio Learning']].forEach(([key,title])=>{const style=normalizeStyleEvidence(styles[key]),label=learningStyleLabel(style);if(label!=='Unknown')insights.push({id:`style:${key}`,title,value:label,evidence:`${confidenceLabel(style.confidence)} based on ${style.evidenceCount} useful action(s).`})});if(habits.preferredStudyTime)insights.push({id:'habit:preferredStudyTime',title:'Preferred Study Time',value:habits.preferredStudyTime,evidence:`${confidenceLabel(habits.preferredStudyTimeConfidence)} from recent sessions.`});if(habits.averageSessionMinutes)insights.push({id:'habit:averageSessionMinutes',title:'Typical Session Length',value:`About ${habits.averageSessionMinutes} minutes`,evidence:`${confidenceLabel(habits.averageSessionConfidence)} from timed activity.`});Object.values(profile.topicPerformance||{}).forEach(row=>{if(row.status!=='Not Enough Data')insights.push({id:`topic:${row.topic}`,title:row.topic,value:row.status,evidence:`Quiz accuracy: ${row.accuracy}% across ${row.totalAnswers} questions. Trend: ${topicTrend(row)}.`})});return insights}
function bindLearningInsightActions(){$$('[data-insight-why]').forEach(b=>b.onclick=()=>b.closest('.learning-insight-row').querySelector('.insight-why')?.classList.toggle('hidden'));$$('[data-insight-accurate]').forEach(b=>b.onclick=()=>setInsightFeedback(b.dataset.insightAccurate,'accurate'));$$('[data-insight-disagree]').forEach(b=>b.onclick=()=>setInsightFeedback(b.dataset.insightDisagree,'disagree'));$$('[data-insight-reset]').forEach(b=>b.onclick=()=>setInsightFeedback(b.dataset.insightReset,'reset'))}
function continuousProfileRefresh({force=false}={}){const profile=ensureLearningProfile();if(!profile||profile.profileSettings?.autoUpdate===false)return profile;const todayKey=isoDateOnly(new Date());if(!force&&profile.profileSettings.lastDailyRefresh===todayKey)return profile;recalculateBehaviorProfile(profile);memoryRows();learningSpeedTopics().forEach(updateLearningSpeedStatus);rebuildMethodPerformance(profile);calculateAllExamReadiness({store:true});profile.profileSettings.lastDailyRefresh=todayKey;profile.lastUpdated=new Date().toISOString();saveDB();return profile}
function profileHistoryRows(filter='all'){const rows=(ensureLearningProfile()?.profileHistory||[]);return filter==='all'?rows:rows.filter(r=>r.category===filter)}
function renderProfileTimeline(){const root=$('#profileTimelineList');if(!root)return;const filter=$('#profileTimelineFilter')?.value||'all',rows=profileHistoryRows(filter);root.innerHTML=rows.length?rows.slice(0,30).map(r=>`<div class="profile-timeline-row"><span>${escapeHTML(formatProfileDate(r.date))}</span><div><b>${escapeHTML(r.type.replace(/:/g,' - ').replace(/([A-Z])/g,' $1'))}</b><p>${escapeHTML(r.previousValue??'None')} -> ${escapeHTML(r.newValue??'Unknown')}</p><small>${escapeHTML(r.reason||'Profile updated from recent evidence.')} Confidence: ${escapeHTML(r.confidence)}.</small></div></div>`).join(''):'<div class="empty-mini">Profile changes will appear here after StudySpark has enough evidence.</div>';$('#profileTimelineFilter')?.addEventListener('change',renderProfileTimeline)}
function renderPendingProfileUpdates(){const root=$('#pendingProfileUpdates');if(!root)return;const profile=ensureLearningProfile(),rows=(profile.pendingProfileUpdates||[]).filter(r=>r.status!=='dismissed').slice(0,3);root.innerHTML=rows.length?rows.map(r=>`<div class="pending-profile-update"><div><b>Your learning profile has been updated.</b><p>${escapeHTML(r.type.replace(/([A-Z])/g,' $1'))} changed from ${escapeHTML(r.previousValue??'Unknown')} to ${escapeHTML(r.newValue??'Unknown')}.</p></div><div><button class="btn btn-secondary" data-view-change="${escapeHTML(r.id)}" type="button">View Change</button><button class="btn btn-secondary" data-keep-profile="${escapeHTML(r.id)}" type="button">Keep Previous Preference</button><button class="btn btn-ghost" data-dismiss-profile="${escapeHTML(r.id)}" type="button">Dismiss</button></div></div>`).join(''):'';$$('[data-view-change]',root).forEach(b=>b.onclick=()=>{$('#profileTimelineFilter').value='all';renderProfileTimeline();$('#profileTimelineList')?.scrollIntoView({behavior:'smooth'})});$$('[data-keep-profile]',root).forEach(b=>b.onclick=()=>keepPreviousProfileValue(b.dataset.keepProfile));$$('[data-dismiss-profile]',root).forEach(b=>b.onclick=()=>dismissProfileUpdate(b.dataset.dismissProfile))}
function renderLearningProfile(){const u=user();if(!u||!$('#learningProfileView'))return;const profile=continuousProfileRefresh(),perf=profile.performance||{},subjects=profile.subjects||{},courses=selectedCourses(),habits=profile.studyHabits||{},insights=buildLearningInsights(profile);$('#learningProfileSummary').innerHTML=profileFact('Student name',u.name||'Student')+profileFact('Grade',u.grade||'Unknown')+profileFact('Courses',courses.length?courses.join(', '):'None selected')+profileFact('Profile version',String(profile.learningProfileVersion||1))+profileFact('Last updated',formatProfileDate(profile.lastUpdated));$('#learningPreferenceCards').innerHTML=styleCard('Visual Learning','visual','Diagrams, graphs, timelines, charts, and concept maps.')+styleCard('Reading and Writing','reading','Summaries, written explanations, rewritten notes, and text review.')+styleCard('Practice-Based Learning','practice','Practice questions, quizzes, correction tasks, and examples.')+styleCard('Audio Learning','audio','Explaining concepts aloud or listening to explanations.');$('#learningInsights').innerHTML=insights.length?insights.map(insightRow).join(''):'<div class="empty-mini">Keep studying. Insights appear after repeated activity and enough confidence.</div>';bindLearningInsightActions();renderEffectiveMethods();renderLearningSpeed();renderMemoryReview();renderPendingProfileUpdates();renderProfileTimeline();$('#learningSubjectGrid').innerHTML=Object.keys(subjects).length?Object.entries(subjects).map(([course,subject])=>subjectProfileCard(course,subject)).join(''):'<div class="empty-state card"><h2>No subject profiles yet</h2><p>Choose courses in Account Settings to start building subject profiles.</p></div>';$('#learningHabits').innerHTML=profileFact('Preferred study time',`${profileValue(habits.preferredStudyTime)} (${habits.preferredStudyTimeSource||'automatic'})`)+profileFact('Average session',`${habitMinutes(habits.averageSessionMinutes)} (${habits.averageSessionSource||'automatic'})`)+profileFact('Break frequency',`${habitMinutes(habits.breakFrequencyMinutes,'Every ')} (${habits.breakFrequencySource||'automatic'})`);$('#learningPerformance').innerHTML=profileFact('Overall quiz accuracy',`${Number(perf.quizAccuracy)||0}%`)+profileFact('Quizzes completed',String(Number(perf.quizzesCompleted)||0))+profileFact('Strongest course',profileValue(perf.strongestCourse))+profileFact('Course needing practice',profileValue(perf.courseNeedingPractice))+profileFact('Strong topics',profileList(perf.strongTopics))+profileFact('Developing topics',profileList(perf.developingTopics))+profileFact('Weak topics',profileList(perf.weakTopics))+profileFact('Most improved topic',profileValue(perf.mostImprovedTopic));$('#learningSuggestions').innerHTML=(perf.quizzesCompleted?learningPreferenceSuggestions():['Complete a quiz to begin building your performance profile.',...learningPreferenceSuggestions()]).slice(0,6).map(text=>`<div class="weak-item"><b>${escapeHTML(text)}</b><span>Suggestion</span></div>`).join('');$('#behaviorTrackingToggle').value=profile.behavior.enabled===false?'off':'on';if($('#methodTrackingToggle'))$('#methodTrackingToggle').value=profile.methodPerformance?.enabled===false?'off':'on';if($('#autoProfileUpdateToggle'))$('#autoProfileUpdateToggle').value=profile.profileSettings?.autoUpdate===false?'off':'on'}
function openLearningProfileModal(){const profile=ensureLearningProfile(),styles=profile.learningStyles,habits=profile.studyHabits;$('#prefVisual').value=normalizeStyleEvidence(styles.visual).manual||'';$('#prefReading').value=normalizeStyleEvidence(styles.reading).manual||'';$('#prefPractice').value=normalizeStyleEvidence(styles.practice).manual||'';$('#prefAudio').value=normalizeStyleEvidence(styles.audio).manual||'';$('#habitPreferredTime').value=habits.preferredStudyTime||'';$('#habitAverageSession').value=[15,25,45,60].includes(Number(habits.averageSessionMinutes))?String(habits.averageSessionMinutes):(habits.averageSessionMinutes?'custom':'');$('#habitAverageCustom').value=$('#habitAverageSession').value==='custom'?habits.averageSessionMinutes:'';$('#habitBreakFrequency').value=[20,25,45,60].includes(Number(habits.breakFrequencyMinutes))?String(habits.breakFrequencyMinutes):(habits.breakFrequencyMinutes?'custom':'');$('#habitBreakCustom').value=$('#habitBreakFrequency').value==='custom'?habits.breakFrequencyMinutes:'';$('#learningProfileModal').classList.add('open');$('#learningProfileModal').setAttribute('aria-hidden','false')}
function closeLearningProfileModal(){$('#learningProfileModal').classList.remove('open');$('#learningProfileModal').setAttribute('aria-hidden','true')}
function habitSelectValue(selectId,customId){const value=$(selectId).value;if(value==='custom')return Number($(customId).value)||null;return value?Number(value):null}
function dismissProfileUpdate(id){const profile=ensureLearningProfile(),entry=(profile.pendingProfileUpdates||[]).find(e=>e.id===id);if(entry)entry.status='dismissed';saveDB();renderPendingProfileUpdates();toast('Profile update dismissed.')}
function keepPreviousProfileValue(id){const profile=ensureLearningProfile(),entry=(profile.pendingProfileUpdates||[]).find(e=>e.id===id);if(!entry)return;entry.status='kept_previous';if(entry.type==='preferredStudyTime'){profile.studyHabits.preferredStudyTime=entry.previousValue||null;profile.studyHabits.preferredStudyTimeSource='user-selected'}if(entry.type==='averageSessionMinutes'){profile.studyHabits.averageSessionMinutes=Number(entry.previousValue)||null;profile.studyHabits.averageSessionSource='user-selected'}if(entry.type==='breakFrequencyMinutes'){profile.studyHabits.breakFrequencyMinutes=Number(entry.previousValue)||null;profile.studyHabits.breakFrequencySource='user-selected'}profile.profileInsights[entry.type]={...(profile.profileInsights[entry.type]||{}),value:entry.previousValue,source:'user-selected',lastUpdated:new Date().toISOString(),reason:'Student kept the previous preference.'};recordProfileHistory(profile,{type:entry.type,previousValue:entry.newValue,newValue:entry.previousValue,confidence:'High',reason:'Student chose to keep the previous value.',source:'user-selected'});saveDB();renderLearningProfile();toast('Previous preference kept.')}
function setInsightFeedback(id,mode){const profile=ensureLearningProfile();profile.behavior.insightFeedback[id]={accurate:mode==='accurate',disagree:mode==='disagree',reset:mode==='reset',updatedAt:new Date().toISOString()};if(mode==='reset'&&id.startsWith('style:'))profile.learningStyles[id.split(':')[1]]={...blankStyleEvidence(),resetAt:new Date().toISOString()};recalculateBehaviorProfile(profile);profile.lastUpdated=new Date().toISOString();saveDB();renderLearningProfile();toast(mode==='accurate'?'Thanks. This insight was reinforced.':mode==='disagree'?'Thanks. Confidence was reduced.':'Insight reset.')}
