$('#learningProfileForm')?.addEventListener('submit',e=>{e.preventDefault();const profile=ensureLearningProfile(),styleInputs={visual:'#prefVisual',reading:'#prefReading',practice:'#prefPractice',audio:'#prefAudio'};Object.entries(styleInputs).forEach(([key,id])=>{const value=$(id).value||null;profile.learningStyles[key]={...normalizeStyleEvidence(profile.learningStyles[key]),manual:value,source:value?'user-selected':'automatic'};if(value)recordProfileHistory(profile,{type:`style:${key}`,previousValue:profile.profileInsights?.[`style:${key}`]?.value||null,newValue:value,confidence:'High',reason:'Student set this learning preference manually.',source:'user-selected'})});const oldTime=profile.studyHabits.preferredStudyTime,oldAvg=profile.studyHabits.averageSessionMinutes,oldBreak=profile.studyHabits.breakFrequencyMinutes;profile.studyHabits.preferredStudyTime=$('#habitPreferredTime').value||null;profile.studyHabits.preferredStudyTimeSource=profile.studyHabits.preferredStudyTime?'user-selected':'automatic';profile.studyHabits.averageSessionMinutes=habitSelectValue('#habitAverageSession','#habitAverageCustom');profile.studyHabits.averageSessionSource=profile.studyHabits.averageSessionMinutes?'user-selected':'automatic';profile.studyHabits.breakFrequencyMinutes=habitSelectValue('#habitBreakFrequency','#habitBreakCustom');profile.studyHabits.breakFrequencySource=profile.studyHabits.breakFrequencyMinutes?'user-selected':'automatic';if(oldTime!==profile.studyHabits.preferredStudyTime)recordProfileHistory(profile,{type:'preferredStudyTime',previousValue:oldTime,newValue:profile.studyHabits.preferredStudyTime,confidence:'High',reason:'Student set this study habit manually.',source:'user-selected'});if(oldAvg!==profile.studyHabits.averageSessionMinutes)recordProfileHistory(profile,{type:'averageSessionMinutes',previousValue:oldAvg,newValue:profile.studyHabits.averageSessionMinutes,confidence:'High',reason:'Student set this study habit manually.',source:'user-selected'});if(oldBreak!==profile.studyHabits.breakFrequencyMinutes)recordProfileHistory(profile,{type:'breakFrequencyMinutes',previousValue:oldBreak,newValue:profile.studyHabits.breakFrequencyMinutes,confidence:'High',reason:'Student set this study habit manually.',source:'user-selected'});profile.lastUpdated=new Date().toISOString();saveDB();closeLearningProfileModal();renderLearningProfile();toast('Learning preferences saved.')});
