/* Planner */
function setMinDate(){const d=new Date(),iso=d.toISOString().slice(0,10);if($('#testDate')){$('#testDate').min=iso;if(!$('#testDate').value){const next=new Date(Date.now()+6*86400000);$('#testDate').value=next.toISOString().slice(0,10)}}if($('#studyMatchExamDate'))$('#studyMatchExamDate').min=iso;if($('#predictionExamDate'))$('#predictionExamDate').min=iso;if($('#performanceDate')){$('#performanceDate').max=iso;if(!$('#performanceDate').value)$('#performanceDate').value=iso}}
function localDate(value){const d=value?new Date(value+'T12:00:00'):new Date();return new Date(d.getFullYear(),d.getMonth(),d.getDate(),12)}
function addDays(date,days){const d=new Date(date);d.setDate(d.getDate()+days);return d}
function formatPlanDate(date){return date.toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'})}
function daysUntilTest(testDate){const start=localDate(today()),test=localDate(testDate);return Math.ceil((test-start)/86400000)}
function splitTopics(value=''){return uniqueCourses(value.split(/[,;\n]+/).flatMap(t=>expandTopicParts(t.trim())).filter(Boolean)).slice(0,36)}
function expandTopicParts(topic){if(!topic)return[];const lower=topic.toLowerCase(),extras=[];if(lower.includes('polynomial'))extras.push('polynomial vocabulary','degree and leading coefficient','polynomial rules');if(lower.includes('factor'))extras.push('greatest common factor','factoring by grouping','difference of squares');if(lower.includes('zero')||lower.includes('root'))extras.push('zeros and x-intercepts','multiplicity','solving from factored form');if(lower.includes('graph'))extras.push('graph shape','x-intercepts and y-intercepts','turning points');if(lower.includes('transform'))extras.push('vertical shifts','stretches and compressions','reflections');if(lower.includes('word'))extras.push('word problem setup','choosing variables','checking reasonableness');return uniqueCourses([topic,...extras])}
function plannerTemplateFor(course){const templates=appData.plannerTemplates||FALLBACK_PLANNER_TEMPLATES,key=Object.keys(templates).find(k=>k!=='fallback'&&(templates[k].keywords||[]).some(w=>course.toLowerCase().includes(w)));return templates[key]||templates.fallback}
function noteKeywordsForPlan(course,folderId){const same=x=>x.subject&&x.subject.toLowerCase()===course.toLowerCase(),folder=normalizeFolderId(folderId);const notes=user().notes.filter(n=>same(n)&&(!folderId||n.folderId===folder));return uniqueCourses(keywords(notes.map(n=>`${n.title} ${n.text}`).join(' ')).slice(0,10))}
function profileTopicsForPlan(course){const profile=ensureLearningProfile(),subject=profile?.subjects?.[course]||{},rows=Object.values(profile.topicPerformance||{}).filter(r=>!course||r.course.toLowerCase()===course.toLowerCase()),needsPractice=rows.filter(r=>r.status==='Needs Practice'&&r.totalAnswers>=topicRules().planningMinimumQuestions).map(r=>r.topic),developing=rows.filter(r=>r.status==='Developing').map(r=>r.topic),strongPerf=rows.filter(r=>r.status==='Strong').map(r=>r.topic),speed=learningSpeedTopics().filter(t=>!course||t.course.toLowerCase()===course.toLowerCase()),slow=speed.filter(t=>['Needs More Support','Extra Practice Needed','Review Needed'].includes(learningSpeedCategory(t))).map(t=>t.topic),fast=speed.filter(t=>learningSpeedCategory(t)==='Fast Progress').map(t=>t.topic),weak=uniqueCourses([...needsPractice,...slow,...(subject.weakTopics||[]),...(profile?.performance?.weakTopics||[])]),strong=uniqueCourses([...fast,...strongPerf,...(subject.strongTopics||[]),...(profile?.performance?.strongTopics||[])]);return {weak,strong,slow,fast,developing,needsPractice}}
function personalizePlanDay(day,course,index){const tips=learningPreferenceSuggestions(course).filter(t=>!t.includes('Complete a quiz')).slice(0,2),topics=profileTopicsForPlan(course),memoryDue=memoryTopicsForPlan(course,index+1);if(index<topics.weak.length){const weak=topics.weak[index];day.mainTopic=day.mainTopic.toLowerCase().includes(weak.toLowerCase())?day.mainTopic:`${day.mainTopic} and ${weak}`;day.whatToStudy=completeSentence(`${day.whatToStudy} Give extra attention to ${weak} because previous topic performance shows it needs more practice.`,day.whatToStudy)}const due=memoryDue.find(r=>day.mainTopic.toLowerCase().includes(r.topic.toLowerCase()));if(due){day.mainTopic=`Quick spaced review - ${due.topic}`;day.estimatedMinutes=Math.min(day.estimatedMinutes||30,25);day.whatToStudy=completeSentence(`Review the key ideas for ${due.topic}. Focus on the parts that felt difficult last time.`,day.whatToStudy);day.stepByStepTask=completeSentence(`Complete a short refresher, work through one example, and explain the main idea without looking at your notes.`,day.stepByStepTask);day.practiceQuestions=completeSentence(`Complete 5 mixed questions for ${due.topic} and check every answer.`,day.practiceQuestions);day.mistakeCheck=completeSentence(`Correct any mistakes and write one sentence explaining how to avoid them next time.`,day.mistakeCheck);day.miniReview=completeSentence(`End with a brief recall check so the review stays short and focused.`,day.miniReview)}if(topics.developing.some(t=>day.mainTopic.toLowerCase().includes(t.toLowerCase())))day.practiceQuestions=completeSentence(`${day.practiceQuestions} Use a medium practice set and check each step because this topic is still developing.`,day.practiceQuestions);if([...topics.slow,...topics.needsPractice].some(t=>day.mainTopic.toLowerCase().includes(t.toLowerCase()))){day.stepByStepTask=completeSentence(`${day.stepByStepTask} Break ${day.mainTopic} into smaller subtopics before moving to mixed practice.`,day.stepByStepTask);day.practiceQuestions=completeSentence(`${day.practiceQuestions} Include one easier warm-up set, one guided example, and one independent practice set.`,day.practiceQuestions)}if(topics.strong.some(t=>day.mainTopic.toLowerCase().includes(t.toLowerCase())))day.miniReview=completeSentence(`${day.miniReview} Keep this strong or fast-progress topic fresh with a shorter review.`,day.miniReview);if(tips.length)day.miniReview=completeSentence(`${day.miniReview} ${tips.join(' ')}`,day.miniReview);const method=bestMethod({course,topic:day.mainTopic})||bestMethod({course})||bestMethod();if(method){if(method.method==='Practice Questions')day.practiceQuestions=completeSentence(day.practiceQuestions+' Add an extra focused practice set because practice questions currently lead to strong results for you.',day.practiceQuestions);else if(method.method==='Flashcards')day.miniReview=completeSentence(day.miniReview+' Include a quick recall or flashcard check because flashcards currently appear helpful.',day.miniReview);else if(method.method==='Video or Visual Explanation'||method.method==='Diagram or Mind Map')day.whatToStudy=completeSentence(day.whatToStudy+' Use a diagram, chart, timeline, or visual example before practicing.',day.whatToStudy);else if(method.method==='Reading Notes')day.stepByStepTask=completeSentence(day.stepByStepTask+' Rewrite the main ideas in your own words before practicing.',day.stepByStepTask);else if(method.method==='Audio Explanation'||method.method==='Teaching or Explaining Aloud')day.miniReview=completeSentence(day.miniReview+' Explain the topic aloud as if teaching it to someone else.',day.miniReview)}return day}
function reviewDayType(index,total){const day=index+1;if(total<=1)return 'emergency';if(total<=3&&day===total)return 'final';if(total<=7&&day===total)return 'final';if(total<=14&&(day===Math.ceil(total/2)||day===total))return day===total?'final':'mid';if(total>14&&(day%7===0||day===total))return day===total?'final':'weekly';return ''}
function pickFrom(list,index,fallback='Review {topic}.'){return (list&&list.length?list:[fallback])[index%(list&&list.length?list.length:1)]}
function fillTemplate(text,topic,minutes){return (text||'Review {topic}.').replaceAll('{topic}',topic).replaceAll('{practiceCount}',String(Math.max(5,Math.round(minutes/5))))}
function countValue(list,value,key){return list.filter(item=>item[key]===value).length}
const PLAN_VERBS=['Identify','Solve','Explain','Complete','Review','Compare','Practice','Analyze','Create','Write','Build','List','Read','Update','Redo','Rank','Skim','Make','Study','Correct','Choose','Sort','Define','Label','Draft','Revise','Connect','Answer','Apply','Find','Factor','Verify','Plot','Check','Determine','Match','Describe','Work','Rewrite','Group'];
function cleanPlanText(text=''){return repairEncoding(text).replace(/\s+/g,' ').replace(/\s+([,.!?;:])/g,'$1').replace(/\bteh\b/gi,'the').replace(/\badn\b/gi,'and').replace(/\byour your\b/gi,'your').trim()}
function sentenceCase(text){return text?text.charAt(0).toUpperCase()+text.slice(1):text}
function completeSentence(text,fallback){let value=cleanPlanText(text||fallback);if(!value)return fallback;if(!/[.!?]$/.test(value))value+='.';return value}
function startsWithPlanVerb(text){return PLAN_VERBS.some(verb=>new RegExp(`^${verb}\\b`,'i').test(text))}
function actionSentence(text,fallback='Review the study task.'){let value=completeSentence(text,fallback);if(!startsWithPlanVerb(value))value=`Review ${value.charAt(0).toLowerCase()+value.slice(1)}`;return sentenceCase(completeSentence(value,fallback))}
function repairBrokenPlannerFragments(text=''){return cleanPlanText(text).replace(/\bappl\.?\b|\bapplic\.?\b/gi,'applications').replace(/\bques\.?\b/gi,'questions').replace(/\bfunc\.?\b/gi,'function').replace(/\bpoly\.?\b/gi,'polynomial').replace(/\bdef\.?\b/gi,'definition').replace(/\bcalc\.?\b/gi,'calculation').replace(/\b(\w+)\s+\1\b/gi,'$1').replace(/\b(practice|questions|function|polynomial|application|applications)\s+\1\b/gi,'$1')}
function shortTopicName(topic=''){const value=repairBrokenPlannerFragments(topic),lower=value.toLowerCase();if(lower.includes('rational')&&lower.includes('word'))return 'rational function word problems';if(lower.includes('rational')&&lower.includes('applic'))return 'rational function applications';if(lower.includes('rational'))return 'rational functions';if(lower.includes('factoring by grouping'))return 'factoring by grouping';if(lower.includes('greatest common factor'))return 'GCF factoring';if(lower.includes('difference of squares'))return 'difference of squares';if(lower.includes('zeros')||lower.includes('x-intercepts'))return 'zeros and intercepts';if(lower.includes('transformation'))return 'transformations';if(lower.includes('word problem'))return 'word problems';return value.length>54?'the main topic':value}
function hasBrokenPlannerText(text){const value=repairBrokenPlannerFragments(text),lower=value.toLowerCase();return !value||/\b(appl|applic|ques|func|poly|def|calc)\.?($|\s)/i.test(value)||/\b(or|and|from|with|for|to|apply|review|choose)\.$/i.test(value)||/\bfrom\s+[a-z]+\.?$/i.test(value)||/(\b\w+\b)(\s+\1\b)+/i.test(lower)||value.length>170}
const PLAN_PURPOSES=['Learn key concepts','Work through examples','Build core skills','Solve application questions','Correct mistakes','Use flashcards and recall','Complete mixed review','Run a final test simulation','Create a final summary','Teach back the topic'];
function planPurpose(index,total,reviewType){if(reviewType==='emergency')return 'Emergency same-day review';if(reviewType==='final')return total<=3?'Final mixed review':'Run a final test simulation';if(reviewType==='mid')return 'Complete mixed review';if(reviewType==='weekly')return 'Weekly mixed review';const day=index+1;if(total===1)return 'Emergency same-day review';if(day===total)return 'Run a final test simulation';const ratio=day/total;if(ratio<.22)return PLAN_PURPOSES[index%2];if(ratio<.48)return ['Build core skills','Solve application questions','Use flashcards and recall'][index%3];if(ratio<.76)return ['Correct mistakes','Complete mixed review','Solve application questions'][index%3];return ['Complete mixed review','Create a final summary','Teach back the topic'][index%3]}
function purposeInstructions(purpose,topic,minutes){const count=Math.max(6,Math.round((minutes||45)/5)),challenge=Math.max(2,Math.round(count/4));const sets={whatToStudy:{'Learn key concepts':`Study the definitions, rules, and teacher-highlighted examples for ${topic}. Build a one-page summary sheet that explains the main ideas in your own words before doing any practice.`,'Work through examples':`Choose two or three worked examples about ${topic}. Read each line slowly, label why each step works, and copy one example with short notes in the margin.`,'Build core skills':`Focus on the exact skills needed for ${topic}. List the steps, formulas, or decision rules, then mark the parts that still feel slow or confusing.`,'Solve application questions':`Look for ways ${topic} appears in word problems, graphs, diagrams, or real situations. Write down the clues that tell you which method to use.`,'Correct mistakes':`Open your notes, quizzes, and practice work for ${topic}. Find the mistakes, group them by type, and choose the errors that would cost the most marks on a test.`,'Use flashcards and recall':`Turn the key vocabulary, formulas, rules, and examples for ${topic} into quick recall prompts. Focus on facts you should know without checking your notes.`,'Complete mixed review':`Review ${topic} together with related topics from this unit. Look for similarities, differences, and question types that could be mixed on the test.`,'Run a final test simulation':`Prepare for ${topic} like a test session. Gather only the tools your teacher allows, clear distractions, and decide how much time you will spend on each question type.`,'Create a final summary':`Condense ${topic} into a final study sheet. Include key rules, common question types, one model example, and the mistakes you need to avoid.`,'Teach back the topic':`Review ${topic} by preparing to teach it. Decide what a classmate would need to know first, then organize the explanation from easiest to hardest.`,'Emergency same-day review':`Review the highest-priority ideas for ${topic}. Focus on the rules, examples, and mistakes that are most likely to appear on the test today.`,'Final mixed review':`Revisit ${topic} and the connected unit topics. Focus on test-style questions, common traps, and the ideas your teacher emphasized most.`,'Weekly mixed review':`Revisit ${topic} with the other topics studied this week. Mark what is secure, what needs more practice, and what should appear in next week's review.`},stepByStepTask:{'Learn key concepts':`1. Read your notes on ${topic}.\n2. Highlight the main rules and vocabulary.\n3. Rewrite each rule in student-friendly language.\n4. Add one example beside each rule.\n5. Circle anything that still needs a question for your teacher.`,'Work through examples':`1. Select two worked examples for ${topic}.\n2. Cover the solution and predict the first step.\n3. Reveal one line at a time and explain the reason for it.\n4. Redo one example without looking.\n5. Compare your redo with the original solution.`,'Build core skills':`1. List the main steps for ${topic}.\n2. Complete three easy questions slowly and accurately.\n3. Complete five medium questions without notes.\n4. Check each answer and mark slow steps.\n5. Repeat the weakest step until it feels smoother.`,'Solve application questions':`1. Read each application problem twice.\n2. Underline the given information and the question being asked.\n3. Choose the method that fits ${topic}.\n4. Solve and label each step.\n5. Check whether the answer makes sense in the situation.`,'Correct mistakes':`1. Choose three missed questions about ${topic}.\n2. Identify the exact line where each mistake started.\n3. Write why the correct method works.\n4. Redo each question without notes.\n5. Add one warning sentence for future practice.`,'Use flashcards and recall':`1. Make quick prompts for vocabulary, formulas, and examples from ${topic}.\n2. Answer each prompt without notes.\n3. Sort prompts into easy and hard piles.\n4. Restudy the hard pile.\n5. Test yourself again after a short break.`,'Complete mixed review':`1. Mix ${topic} with two related topics.\n2. Sort questions by type before solving.\n3. Complete one question from each type.\n4. Explain why each method fits.\n5. Redo the question type that took the longest.`,'Run a final test simulation':`1. Set a timer for a short test block.\n2. Complete questions about ${topic} without notes.\n3. Skip and return to questions that get stuck.\n4. Check answers only after the timer ends.\n5. Record the mistakes to review before the test.`,'Create a final summary':`1. Write the most important rules for ${topic}.\n2. Add one solved example.\n3. Add common mistakes and how to avoid them.\n4. Add a short practice question.\n5. Use the page to teach the topic from memory.`,'Teach back the topic':`1. Explain ${topic} aloud from the beginning.\n2. Use one example while you explain.\n3. Pause when the explanation becomes unclear.\n4. Check notes only for the unclear part.\n5. Explain it again more clearly.`},practiceQuestions:{default:`Complete ${count} practice questions about ${topic}.\n- Use 5 easier ${topic} questions to warm up.\n- Use 5 medium ${topic} questions to build accuracy.\n- Finish with ${challenge} challenge or test-style ${topic} questions.`},mistakeCheck:{default:`Review every incorrect answer from today's ${topic} work. Write why the ${topic} mistake happened, solve it again correctly, and note the step to remember next time.`},miniReview:{default:`End by writing 5 to 10 bullet points about ${topic}, or explain the day's focus aloud as if teaching it to a classmate.`}};return {whatToStudy:sets.whatToStudy[purpose]||sets.whatToStudy['Learn key concepts'],stepByStepTask:sets.stepByStepTask[purpose]||sets.stepByStepTask['Build core skills'],practiceQuestions:sets.practiceQuestions.default,mistakeCheck:sets.mistakeCheck.default,miniReview:sets.miniReview.default}}
function plannerTaskFallback(key,day){const topic=shortTopicName(day.mainTopic||'the test topic'),purpose=day.purpose||day.taskType||'Build core skills';return purposeInstructions(purpose,topic,day.estimatedMinutes||45)[key]||`Review the key ideas in ${topic}.`}
function validatedPlanSentence(text,fallback){if(!text)return fallback;let value=repairBrokenPlannerFragments(text);if(hasBrokenPlannerText(value))return fallback;return actionSentence(value,fallback)}
function sentenceParts(text=''){return repairBrokenPlannerFragments(text).split(/(?<=[.!?])\s+|\n+/).map(s=>cleanPlanText(s)).filter(Boolean)}
function repeatedSentence(text,seen){return sentenceParts(text).some(s=>seen.has(s.toLowerCase()))}
function rememberSentences(text,seen){sentenceParts(text).forEach(s=>seen.add(s.toLowerCase()))}
function nextPurpose(current,index,total,used){for(let offset=0;offset<PLAN_PURPOSES.length;offset++){const candidate=planPurpose(index+offset,total,'');if(!used.has(candidate.toLowerCase()))return candidate}return `${current} focus`}
function qualityCheckStudyPlan(plan){if(!plan)return plan;migratePlanDays(plan);const seenTitles=new Set(),seenPurposes=new Set(),seenSentences=new Set();plan.days.forEach((day,index)=>{day.mainTopic=repairBrokenPlannerFragments(day.mainTopic||'Study focus');if(seenTitles.has(day.mainTopic.toLowerCase()))day.mainTopic=`${day.mainTopic} application`;seenTitles.add(day.mainTopic.toLowerCase());day.purpose=day.purpose||day.taskType||planPurpose(index,plan.days.length,'');if(index&&plan.days[index-1].purpose===day.purpose)day.purpose=nextPurpose(day.purpose,index,plan.days.length,seenPurposes);if(seenPurposes.has(day.purpose.toLowerCase()))day.purpose=nextPurpose(day.purpose,index+1,plan.days.length,seenPurposes);seenPurposes.add(day.purpose.toLowerCase());day.taskType=repairBrokenPlannerFragments(day.purpose);day.practiceType=repairBrokenPlannerFragments(day.practiceType||'focused practice');day.subtopics=(day.subtopics||[]).map(repairBrokenPlannerFragments).filter(Boolean);['whatToStudy','stepByStepTask','practiceQuestions','mistakeCheck','miniReview'].forEach(key=>{const fallback=plannerTaskFallback(key,day),raw=day[key]||'',current=repairBrokenPlannerFragments(raw);day[key]=(raw.includes('\n')&&!hasBrokenPlannerText(current)&&!repeatedSentence(raw,seenSentences))?raw:(!current||current.length<95||hasBrokenPlannerText(current)||repeatedSentence(current,seenSentences))?fallback:validatedPlanSentence(current,fallback);rememberSentences(day[key],seenSentences)});delete day.checklist});return plan}
function nextUniqueTopic(pool,index,usedMainTopics,reviewType){if(reviewType==='final')return 'Final mixed review';if(reviewType==='mid')return 'Midpoint mixed review';if(reviewType==='weekly')return 'Weekly cumulative review';if(reviewType==='emergency')return 'Emergency high-priority review';if(!pool.length)return 'Core test material';for(let offset=0;offset<pool.length;offset++){const candidate=pool[(index+offset)%pool.length];if(!usedMainTopics.has(candidate.toLowerCase()))return candidate}return `${pool[index%pool.length]} application review`}
function topicBundle(topics,noteKeys,index,reviewType,usedMainTopics){const pool=uniqueCourses([...topics,...noteKeys]);const main=nextUniqueTopic(pool,index,usedMainTopics,reviewType);if(!reviewType)usedMainTopics.add(main.toLowerCase());const subs=reviewType?pool.slice(0,6):uniqueCourses([main,pool[(index+1)%pool.length],pool[(index+2)%pool.length]].filter(Boolean));return {main,subs:subs.length?subs:['highest-value notes','teacher examples','missed questions']}}
function usageCount(map,value){return map.get(value)||0}
function markUsed(map,value){map.set(value,usageCount(map,value)+1)}
function inferPlanDayDueDate(plan,day){if(day.dueDate)return day.dueDate;if(day.isoDate)return day.isoDate;if(day.date){const parsed=new Date(String(day.date).includes('T')?day.date:`${day.date} ${new Date(plan.createdAt||Date.now()).getFullYear()}`);if(!Number.isNaN(parsed.getTime()))return parsed.toISOString()}const base=plan.createdAt?new Date(plan.createdAt):new Date();if(!Number.isNaN(base.getTime())){const due=new Date(base);due.setDate(base.getDate()+Math.max(0,(Number(day.dayNumber)||1)-1));return due.toISOString()}return null}
function migratePlanDays(plan){if(Array.isArray(plan.courses)){plan.course=plan.courses[0]||plan.course||plan.subject||'';delete plan.courses}plan.course=plan.course||plan.subject||'';delete plan.subject;plan.title=plan.title||`${plan.course||'Study'} Plan`;plan.createdAt=plan.createdAt||new Date().toISOString();plan.updatedAt=plan.updatedAt||plan.createdAt||new Date().toISOString();const days=plan.days||plan.plan||[];days.forEach((day,index)=>{delete day.checklist;day.id=day.id||`task-${plan.id||'plan'}-${day.dayNumber||index+1}`;day.dayNumber=day.dayNumber||index+1;day.dueDate=inferPlanDayDueDate(plan,day);day.status=day.completed?'completed':day.status||'incomplete';day.completed=day.status==='completed'||day.completed===true;day.completedAt=day.completedAt||(day.completed?plan.updatedAt:null);day.skippedAt=day.skippedAt||null;day.previousDueDates=Array.isArray(day.previousDueDates)?day.previousDueDates:[];day.createdAt=day.createdAt||plan.createdAt;day.updatedAt=day.updatedAt||plan.updatedAt;day.prototypeOnly=day.prototypeOnly!==false});plan.days=days;delete plan.plan;return plan}
function taskDetail(template,index,topic,minutes,purpose,usedTaskTypes=new Map(),usedPracticeTypes=new Map()){let taskType=purpose||pickFrom(template.taskTypes,index,'concept review'),practiceType=pickFrom(template.practiceTypes,index,'focused questions');for(let step=1;usageCount(usedPracticeTypes,practiceType)>=2&&step<6;step++)practiceType=pickFrom(template.practiceTypes,index+step,practiceType);return {purpose:taskType,taskType,practiceType,...purposeInstructions(taskType,topic,minutes)}}
function reviewDetail(reviewType,topic,subs,minutes,template){const names={emergency:'Emergency same-day review',mid:'Midpoint mixed review',weekly:'Weekly cumulative review',final:'Final mixed review'},focus=subs.slice(0,6).join(', ')||topic,count=Math.max(6,Math.round(minutes/6));return {taskType:`${reviewType} review`,practiceType:pickFrom(template.practiceTypes||[],subs.length,'mixed practice'),whatToStudy:reviewType==='emergency'?`Review the highest-priority topics: ${focus}. Build a one-page final summary that includes formulas, vocabulary, examples, and the mistakes you most need to avoid.`:`Revisit notes, examples, and teacher-highlighted ideas across ${focus}. Mark the ideas that feel weak, then choose the three most important ones for today's review.`,stepByStepTask:reviewType==='emergency'?`1. Rank the topics by test importance.\n2. Review the three topics that are most likely to appear.\n3. Complete one example from each topic.\n4. Write what you still forget.\n5. Spend the final minutes reviewing those weak points.`:`1. Create a mixed review sheet for ${focus}.\n2. Group the topics by question type.\n3. Complete one worked example from each group.\n4. Redo any example that feels unclear.\n5. Write a short final summary of what connects the topics.`,practiceQuestions:`Complete ${count} mixed practice questions across ${focus}.\n- Use easier questions first to warm up.\n- Use medium questions to check test readiness.\n- Use challenge questions for the topics that still feel weak.`,mistakeCheck:'Update your mistake log, redo missed questions, and write the correct reasoning beside each one.',miniReview:reviewType==='final'?'Do a final closed-notes recall. List formulas, vocabulary, examples, and the three most common mistakes to avoid.':'Make quick recall prompts for weak topics and answer them without notes.',mainTopic:names[reviewType]||topic}}
function ensurePlanQuality(days,template){return days.map((day,index)=>{if(index&&day.mainTopic===days[index-1].mainTopic)day.mainTopic=`${day.mainTopic} application`;if(countValue(days.slice(0,index),day.taskType,'taskType')>=2)day.taskType=pickFrom(template.taskTypes,index+2,day.taskType);if(countValue(days.slice(0,index),day.practiceType,'practiceType')>=2)day.practiceType=pickFrom(template.practiceTypes,index+2,day.practiceType);delete day.checklist;if(!day.practiceQuestions)day.practiceQuestions=plannerTaskFallback('practiceQuestions',day);if(!day.mistakeCheck)day.mistakeCheck=plannerTaskFallback('mistakeCheck',day);if(!day.miniReview)day.miniReview=plannerTaskFallback('miniReview',day);return day})}
function buildPlanDay({course,minutes,index,total,template,bundle,reviewType,usedTaskTypes,usedPracticeTypes}){const due=addDays(localDate(today()),index),date=formatPlanDate(due),purpose=planPurpose(index,total,reviewType);let detail=reviewType?reviewDetail(reviewType,bundle.main,bundle.subs,minutes,template):taskDetail(template,index,bundle.main,minutes,purpose,usedTaskTypes,usedPracticeTypes);detail.purpose=detail.purpose||purpose;markUsed(usedTaskTypes,detail.taskType);markUsed(usedPracticeTypes,detail.practiceType);return {id:`task-${Date.now()}-${index+1}`,dayNumber:index+1,date,dueDate:due.toISOString(),status:'incomplete',mainTopic:detail.mainTopic||bundle.main,subtopics:bundle.subs,purpose:detail.purpose,taskType:detail.taskType,practiceType:detail.practiceType,whatToStudy:detail.whatToStudy,stepByStepTask:detail.stepByStepTask,practiceQuestions:detail.practiceQuestions,mistakeCheck:detail.mistakeCheck,miniReview:detail.miniReview,estimatedMinutes:minutes,completed:false,completedAt:null,skippedAt:null,previousDueDates:[],createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),prototypeOnly:true}}
function buildStudyPlan({title,course,folderId,testDate,minutesPerDay,topics,id,createdAt}){const diff=daysUntilTest(testDate),total=Math.max(1,diff),template=plannerTemplateFor(course),noteKeys=noteKeywordsForPlan(course,folderId),profileTopics=profileTopicsForPlan(course),memoryReviewTopics=memoryTopicsForPlan(course,total).map(r=>r.topic),slowExpansions=profileTopics.slow.flatMap(t=>[`${t} fundamentals`,`${t} guided practice`,`${t} application practice`]),combined=uniqueCourses([...memoryReviewTopics,...profileTopics.weak,...slowExpansions,...profileTopics.developing,...topics,...noteKeys,...profileTopics.strong.slice(0,2).map(t=>`${t} maintenance review`)]),usedMainTopics=new Set(),usedTaskTypes=new Map(),usedPracticeTypes=new Map(),days=[];for(let index=0;index<total;index++){const reviewType=reviewDayType(index,total),bundle=topicBundle(combined,noteKeys,index,reviewType,usedMainTopics);days.push(personalizePlanDay(buildPlanDay({course,minutes:minutesPerDay,index,total,template,bundle,reviewType,usedTaskTypes,usedPracticeTypes}),course,index))}return qualityCheckStudyPlan({id:id||'p'+Date.now(),title:title||`${course} Study Plan`,course,folderId,testDate,minutesPerDay,topics:combined.map(cleanPlanText),createdAt:createdAt||new Date().toISOString(),updatedAt:new Date().toISOString(),days:ensurePlanQuality(days,template)})}
function plannerProgress(plan){migratePlanDays(plan);const total=plan?.days?.length||0,done=plan?.days?.filter(d=>d.completed).length||0;return {total,done,percent:total?Math.round(done/total*100):0}}
function planById(id){return (user().plans||[]).find(p=>p.id===id)}
function formatPlanUpdated(plan){return plan.updatedAt?new Date(plan.updatedAt).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}):'Not saved'}
function daysRemaining(plan){return Math.max(0,daysUntilTest(plan.testDate))}
function planTopicLabel(plan){return (plan.topics||[]).slice(0,3).join(', ')||'Study topics'}
function planDayStatusLabel(day){if(day.status==='skipped')return 'Skipped';if(day.completed||day.status==='completed')return 'Completed';if(day.status==='cancelled')return 'Cancelled';if(day.dueDate&&new Date(day.dueDate)<=new Date())return 'Overdue';return 'Incomplete'}
function planDayActions(plan,day){if(day.status==='skipped')return `<button class="btn btn-secondary" data-plan-reopen="${plan.id}:${day.dayNumber}" type="button">Reopen Task</button><button class="btn btn-secondary" data-plan-reschedule="${plan.id}:${day.dayNumber}" type="button">Reschedule Task</button>`;if(day.completed||day.status==='completed')return `<button class="btn btn-secondary" data-plan-reopen="${plan.id}:${day.dayNumber}" type="button">Reopen Task</button>`;return `<button class="btn btn-primary" data-plan-day="${plan.id}:${day.dayNumber}" type="button">&#10003; Mark Day Complete</button><button class="btn btn-secondary" data-plan-skip="${plan.id}:${day.dayNumber}" type="button">Mark as Skipped</button><button class="btn btn-secondary" data-plan-reschedule="${plan.id}:${day.dayNumber}" type="button">Reschedule Task</button>`}
function renderPlanDays(plan,{interactive=false}={}){qualityCheckStudyPlan(plan);const days=plan.days||[];return days.map(day=>`<article class="plan-day-card ${day.completed?'complete':''} ${day.status==='skipped'?'skipped':''}"><div class="plan-day-head"><span class="schedule-day">DAY ${day.dayNumber}</span><div><b>${escapeHTML(day.mainTopic)}</b><small>${escapeHTML(day.date)} - ${day.estimatedMinutes} min - ${escapeHTML(planDayStatusLabel(day))}</small></div>${interactive?`<div class="plan-day-actions">${planDayActions(plan,day)}</div>`:''}</div><div class="plan-subtopics">${(day.subtopics||[]).map(s=>`<span>${escapeHTML(s)}</span>`).join('')}</div><div class="plan-detail-stack"><section><span>Main Focus</span><p>${escapeHTML(day.taskType||day.mainTopic)}</p></section><section><span>What to Study</span><p>${escapeHTML(day.whatToStudy||day.studyTask||plannerTaskFallback('whatToStudy',day))}</p></section><section><span>Step-by-Step Tasks</span><p>${escapeHTML(day.stepByStepTask||plannerTaskFallback('stepByStepTask',day))}</p></section><section><span>Practice Questions</span><p>${escapeHTML(day.practiceQuestions||day.practiceTask||plannerTaskFallback('practiceQuestions',day))}</p></section><section><span>Estimated Study Time</span><p>${day.estimatedMinutes} minutes of focused study. Use the first part for review, the middle for practice, and the final minutes for correcting mistakes.</p></section><section><span>Mistake Check</span><p>${escapeHTML(day.mistakeCheck||plannerTaskFallback('mistakeCheck',day))}</p></section><section><span>Mini Review</span><p>${escapeHTML(day.miniReview||day.reviewTask||plannerTaskFallback('miniReview',day))}</p></section></div></article>`).join('')}
function previewActionBar(){return pendingPlanSaved?`<div class="plan-save-bar saved"><div><b>&#10003; Study Plan Saved</b><span>Your plan is stored in this browser.</span></div><div class="plan-save-actions"><button class="btn btn-primary" id="openSavedPlansBtn" type="button">Open Saved Plans</button><button class="btn btn-secondary" id="continueEditingPlanBtn" type="button">Continue Editing</button></div></div>`:`<div class="plan-save-bar"><div><b>Study Plan Generated Successfully</b><span>Save now so this plan stays available after refresh or logout.</span></div><div class="plan-save-actions"><button class="btn btn-primary btn-save-plan" id="savePlanBtn" type="button">Save Study Plan</button><button class="btn btn-secondary" id="editPlanBtn" type="button">&#9998; Edit Details</button><button class="btn btn-secondary" id="regeneratePlanBtn" type="button">&#10227; Generate Again</button></div></div>`}
function bindPreviewActions(){$('#savePlanBtn')?.addEventListener('click',savePendingPlan);$('#editPlanBtn')?.addEventListener('click',()=>$('#plannerForm').scrollIntoView({behavior:'smooth'}));$('#regeneratePlanBtn')?.addEventListener('click',()=>$('#plannerForm').requestSubmit());$('#openSavedPlansBtn')?.addEventListener('click',()=>scrollPlannerTarget('saved'));$('#continueEditingPlanBtn')?.addEventListener('click',()=>$('#plannerForm').scrollIntoView({behavior:'smooth'}))}
function renderPlanPreview(){if(!pendingPlan){$('#scheduleTitle').textContent='Generate a plan to preview it';$('#scheduleList').innerHTML='<div class="schedule-placeholder"><span>P</span><p>Your generated plan preview will appear here.</p></div>';return}const p=plannerProgress(pendingPlan);$('#scheduleTitle').textContent=`${pendingPlan.title} - ${p.total} day preview`;$('#scheduleList').innerHTML=`<div class="planner-progress"><div><b>${pendingPlanSaved?'Saved plan preview':'Preview only'}</b><span>${p.total} days</span></div><div class="progress-line"><i style="width:${pendingPlanSaved?p.percent:0}%"></i></div></div>`+previewActionBar()+renderPlanDays(pendingPlan);bindPreviewActions()}
function renderSavedPlans(){const plans=(user().plans||[]).map(migratePlanDays);$('#savedPlansGrid').innerHTML=plans.length?plans.map(plan=>{const p=plannerProgress(plan);return `<article class="card saved-plan-card"><span class="pill blue-pill">${escapeHTML(plan.course||'Course')}</span><h3>${escapeHTML(plan.title||'Study Plan')}</h3><p>${escapeHTML(planTopicLabel(plan))}</p><div class="saved-plan-meta"><span>Test: ${escapeHTML(plan.testDate||'Not set')}</span><span>${p.total} days</span><span>${p.percent}% complete</span><span>Updated ${escapeHTML(formatPlanUpdated(plan))}</span></div><div class="file-actions"><button type="button" data-plan-open="${plan.id}">Open Plan</button><button type="button" data-plan-edit="${plan.id}">Edit Plan</button><button type="button" data-plan-rename="${plan.id}">Rename Plan</button><button type="button" data-plan-delete="${plan.id}">Delete Plan</button></div></article>`}).join(''):'<div class="empty-state card"><h2>No saved study plans yet</h2><p>Generate a plan, preview it, then save it here.</p></div>';bindSavedPlanActions()}
function renderPlannerDailyCheckIn(){let root=$('#plannerDailyCheckIn');if(!root){$('#plannerView .planner-layout')?.insertAdjacentHTML('beforebegin','<div id="plannerDailyCheckIn"></div>');root=$('#plannerDailyCheckIn')}if(root){root.innerHTML=dailyStudyCheckInHTML({context:'study-planner',compact:true});bindDailyStudyCheckInActions(root)}}
function renderPlannerPage(){renderPlannerDailyCheckIn();renderPlanPreview();renderSavedPlans();setMinDate()}
function savePendingPlan(){if(!pendingPlan)return toast('Generate a study plan first.');migratePlanDays(pendingPlan);pendingPlan.updatedAt=new Date().toISOString();const existing=user().plans.findIndex(p=>p.id===pendingPlan.id);if(existing>=0)user().plans[existing]=pendingPlan;else user().plans.unshift(pendingPlan);touchFolder(pendingPlan.folderId);recordActivity('note',`Saved ${pendingPlan.course} study plan`);calculateAllExamReadiness({store:true});markStudyWellBeingRecordOutdated();saveDB();activePlanId=pendingPlan.id;pendingPlanSaved=true;renderPlannerPage();renderOrganization();renderProgress();renderDashboard();renderExamReadinessPage();toast('Study plan saved successfully.')}
function fillPlannerForm(plan){$('#planCourse').value=plan.course||'';$('#planFolder').value=folderById(plan.folderId)&&!folderById(plan.folderId).protected?plan.folderId:'';$('#planTitle').value=plan.title||'';$('#testDate').value=plan.testDate||'';$('#planTopics').value=(plan.topics||[]).join(', ');$('#planMinutes').value=plan.minutesPerDay||45}
function openPlanDetail(id){activePlanId=id;const plan=planById(id);if(plan){recordBehaviorEvent('study_plan_session_started',{course:plan.course,topic:planTopicLabel(plan)});startStudySession(plan.course,planTopicLabel(plan),'study_plan_session_started')}showView('planDetail')}
function editPlanFromCard(id){const plan=planById(id);if(!plan)return;activePlanId=id;showView('planDetail');setTimeout(()=>$('#detailPlanTitle')?.focus(),0)}
async function renamePlan(id){const plan=planById(id);if(!plan)return;const next=prompt('Rename study plan',plan.title||'Study Plan');if(!next?.trim())return;plan.title=next.trim();plan.updatedAt=new Date().toISOString();saveDB();renderPlannerPage();renderPlanDetail();toast('Study plan renamed.')}
async function deletePlan(id=activePlanId){const plan=planById(id);if(!plan)return;const ok=await confirmDialog({title:'Delete Study Plan',message:'Are you sure you want to delete this study plan?',okText:'Delete Study Plan',cancelText:'Cancel',danger:true});if(!ok)return;user().plans=user().plans.filter(p=>p.id!==id);markStudyWellBeingRecordOutdated();saveDB();if(activePlanId===id)activePlanId=null;renderAll();showView('planner');toast('Study plan deleted.')}
function bindSavedPlanActions(){$$('[data-plan-open]').forEach(b=>b.onclick=()=>openPlanDetail(b.dataset.planOpen));$$('[data-plan-edit]').forEach(b=>b.onclick=()=>editPlanFromCard(b.dataset.planEdit));$$('[data-plan-rename]').forEach(b=>b.onclick=()=>renamePlan(b.dataset.planRename));$$('[data-plan-delete]').forEach(b=>b.onclick=()=>deletePlan(b.dataset.planDelete))}
function updatePlanCompletion(plan,day,wasComplete){if(day.completed&&!wasComplete){day.completedAt=day.completedAt||new Date().toISOString();day.status='completed';day.skippedAt=null;user().progress.minutes+=(day.estimatedMinutes||0);recordBehaviorEvent('study_session_ended',{course:plan.course,topic:day.mainTopic,durationMinutes:day.estimatedMinutes});recordStudyMethodSession({course:plan.course,topic:day.mainTopic,method:'Mixed Method',durationMinutes:day.estimatedMinutes,completed:true});recordMemoryReview({course:plan.course,topic:day.mainTopic,activityType:'study_plan',accuracy:null,questionsAnswered:0,durationMinutes:day.estimatedMinutes});touchStudy();recordActivity('note',`Completed day ${day.dayNumber} of ${plan.course} plan`)}day.updatedAt=new Date().toISOString();plan.updatedAt=new Date().toISOString();calculateAllExamReadiness({store:true});saveDB();maybeAutoUpdateStudyWellBeing();renderPlanDetail();renderPlannerPage();renderDashboard();renderProgress();renderOrganization();renderLearningProfile();renderExamReadinessPage();renderStudyWellBeingPage();const predictionProfileId=day.predictionProfileId||plan.predictionProfileId;if(predictionProfileId&&day.completed!==wasComplete)predictionUpdateManager.requestUpdate({userId:predictionUserId(),predictionProfileId,triggerType:day.completed?PREDICTION_UPDATE_TRIGGERS.STUDY_TASK_COMPLETED:PREDICTION_UPDATE_TRIGGERS.STUDY_TASK_REOPENED,sourceRecordId:day.id||`${plan.id}:${day.dayNumber}`})}
function planDayFromValue(value){const [planId,dayNumber]=value.split(':'),plan=planById(planId),day=plan?.days?.find(d=>String(d.dayNumber)===dayNumber);return {plan,day}}
