function renderPlanDetail(){const plan=planById(activePlanId),missing=!plan;$('#planDetailMissing').classList.toggle('hidden',!missing);$('#planDetailForm').classList.toggle('hidden',missing);if(missing)return;migratePlanDays(plan);const p=plannerProgress(plan);$('#detailPlanTitle').value=plan.title||'Study Plan';$('#detailPlanCourse').innerHTML=courseOptionsHTML(selectedCourses());$('#detailPlanCourse').value=plan.course||'';$('#detailTestDate').value=plan.testDate||'';$('#detailPlanMinutes').value=plan.minutesPerDay||45;$('#detailPlanTopics').value=(plan.topics||[]).join(', ');$('#detailPlanMeta').textContent=`${plan.course} - Test ${plan.testDate||'not set'} - ${daysRemaining(plan)} day(s) remaining`;$('#planDetailSummary').innerHTML=`<div><b>${p.done} of ${p.total} days complete</b><span>${p.percent}%</span></div><div class="progress-line"><i style="width:${p.percent}%"></i></div>`;$('#planDetailDays').innerHTML=renderPlanDays(plan,{interactive:true});$$('[data-plan-day]',$('#planDetailDays')).forEach(btn=>btn.onclick=()=>completePlanDay(btn.dataset.planDay));$$('[data-plan-skip]',$('#planDetailDays')).forEach(btn=>btn.onclick=()=>skipPlanDay(btn.dataset.planSkip));$$('[data-plan-reopen]',$('#planDetailDays')).forEach(btn=>btn.onclick=()=>reopenPlanDay(btn.dataset.planReopen));$$('[data-plan-reschedule]',$('#planDetailDays')).forEach(btn=>btn.onclick=()=>reschedulePlanDay(btn.dataset.planReschedule))}
