function isValidQuizScore(score){const value=Number(score);return Number.isFinite(value)&&value>=0&&value<=100}
function calculateQuizCompletionMinutes({startTime,completionTime}){const start=new Date(startTime),completed=new Date(completionTime);if(Number.isNaN(start.getTime())||Number.isNaN(completed.getTime())||completed<=start)return null;return Math.round((completed.getTime()-start.getTime())/60000)}
