function calculateMinutesPerQuestion(quiz){const minutes=Number(quiz.completionMinutes),questions=Number(quiz.totalQuestions);if(!Number.isFinite(minutes)||minutes<=0||!Number.isInteger(questions)||questions<=0)return null;return Number((minutes/questions).toFixed(2))}
function calculateUnansweredRate(quiz){const unanswered=Number(quiz.unansweredQuestions),total=Number(quiz.totalQuestions);if(!Number.isInteger(unanswered)||unanswered<0||!Number.isInteger(total)||total<=0||unanswered>total)return null;return Number((unanswered/total*100).toFixed(1))}
