function quizCourseId(course){return course?normalizeCourseName(course).toLowerCase().replace(/\s+/g,'-'):''}
function normalizeQuizPerformanceRecord(quiz,index=0){if(!quiz||quiz.status==='draft'||quiz.status==='unfinished'||quiz.deleted)return null;const score=Number(quiz.score);if(!isValidQuizScore(score))return null;const totalQuestions=Number.isInteger(Number(quiz.totalQuestions))?Number(quiz.totalQuestions):(Array.isArray(quiz.questionResults)?quiz.questionResults.length:0),answeredQuestions=Number.isInteger(Number(quiz.answeredQuestions))?Number(quiz.answeredQuestions):(Array.isArray(quiz.questionResults)?quiz.questionResults.filter(q=>String(q.userAnswer||q.chosen||'').trim()).length:totalQuestions),directUnanswered=Number(quiz.unansweredQuestions),calculatedUnanswered=calculateUnansweredQuestions({totalQuestions,answeredQuestions}),unansweredQuestions=Number.isInteger(directUnanswered)&&directUnanswered>=0&&directUnanswered<=totalQuestions?directUnanswered:calculatedUnanswered,completionTime=quiz.completionTime||quiz.completedAt||quiz.createdAt||null,startTime=quiz.startTime||quiz.startedAt||null,completionMinutes=Number.isFinite(Number(quiz.completionMinutes))?Number(quiz.completionMinutes):calculateQuizCompletionMinutes({startTime,completionTime}),subject=quiz.subject||quiz.course||'',topic=quiz.topic||quiz.questionResults?.[0]?.topic||inferTopicFromText(JSON.stringify(quiz.questionResults||[]),subject);return {id:`quiz-performance-${quiz.id||index}`,userId:quiz.userId||predictionUserId(),sourceQuizId:quiz.id||`quiz-${index}`,subject,topic:normalizeTopicName(topic||subject||'Quiz'),courseId:quiz.courseId||quizCourseId(quiz.course||subject),predictionProfileId:quiz.predictionProfileId||'',score,startTime,completionTime,completionMinutes,date:wellBeingDateKey(completionTime||quiz.dateISO||quiz.date),totalQuestions,answeredQuestions,unansweredQuestions,status:'completed',minutesPerQuestion:null,unansweredRate:null,prototypeOnly:true}}
function normalizedQuizPerformanceRecords({course='',range=getStudyWellBeingDateRange()}={}){const window=wellBeingDateRangeWindow(range),source=getWellBeingDataSource({userId:predictionUserId(),demoEnabled:isWellBeingDemoActive()}),quizzes=source?(source.quizzes||[]):(user()?.quizzes||[]);return quizzes.map(normalizeQuizPerformanceRecord).filter(Boolean).map(q=>({...q,minutesPerQuestion:calculateMinutesPerQuestion(q),unansweredRate:calculateUnansweredRate(q)})).filter(q=>q.userId===predictionUserId()).filter(q=>inWellBeingRange(q.date,window)).filter(q=>!course||q.subject===course||q.courseId===quizCourseId(course)).sort((a,b)=>quizTimestamp(b)-quizTimestamp(a))}
function calculateQuizAverage(quizRecords){const scores=quizRecords.map(quiz=>Number(quiz.score)).filter(isValidQuizScore);if(!scores.length)return null;return Number((scores.reduce((total,score)=>total+score,0)/scores.length).toFixed(1))}
