function getQuizPerformanceChangeLabel({changePercentagePoints,rules=studyWellBeingRules()}){if(!Number.isFinite(changePercentagePoints))return 'Not Enough Data';const settings=rules.quizPerformance||FALLBACK_STUDY_WELL_BEING_RULES.quizPerformance;if(changePercentagePoints>=settings.improvingThreshold)return 'Improving';if(changePercentagePoints<=settings.noticeableDropThreshold)return 'Noticeable Drop';if(changePercentagePoints<=settings.smallDropThreshold)return 'Small Drop';return 'Stable'}
