function compareQuizUnanswered(recent=[],usual=[]){const recentAvg=averageNumeric(recent.map(q=>q.unansweredQuestions)),usualAvg=averageNumeric(usual.map(q=>q.unansweredQuestions)),recentRate=averageNumeric(recent.map(calculateUnansweredRate)),usualRate=averageNumeric(usual.map(calculateUnansweredRate));if(recentAvg===null||usualAvg===null)return {available:false,message:'Unanswered-question rates cannot be calculated for some quizzes.'};const settings=studyWellBeingRules().quizPerformance||FALLBACK_STUDY_WELL_BEING_RULES.quizPerformance,change=Number((recentAvg-usualAvg).toFixed(1)),rateChange=recentRate!==null&&usualRate!==null?Number((recentRate-usualRate).toFixed(1)):null;return {available:true,recentAverage:recentAvg,usualAverage:usualAvg,recentRate,usualRate,changeUnanswered:change,rateChange,meaningfulIncrease:change>=(settings.unansweredIncrease||1)||(rateChange!==null&&rateChange>=(settings.unansweredRateIncrease||8))}}
