function safeReadLocalStorage(key,fallback){try{const raw=localStorage.getItem(key);return raw?JSON.parse(raw):fallback}catch{return fallback}}
function safeWriteLocalStorage(key,value){localStorage.setItem(key,JSON.stringify(value))}
function questionResponseStorageKey(){return isGuestMode()?GUEST_QUIZ_QUESTION_RESPONSES_KEY:QUIZ_QUESTION_RESPONSES_KEY}
function getQuestionResponses(){return safeReadLocalStorage(questionResponseStorageKey(),{})}
function getQuestionResponsesByUser(userId=predictionUserId()){const demo=getWellBeingDataSource({userId,demoEnabled:isWellBeingDemoActive()});if(demo)return (demo.questionResponses||[]).map(normalizeQuestionResponseRecord).filter(Boolean);const data=getQuestionResponses();return Array.isArray(data[userId])?data[userId].map(normalizeQuestionResponseRecord).filter(Boolean):[]}
function saveQuestionResponsesByUser(userId,rows){const data=getQuestionResponses();data[userId]=(Array.isArray(rows)?rows:[]).map(normalizeQuestionResponseRecord).filter(Boolean);safeWriteLocalStorage(questionResponseStorageKey(),data)}
function getQuestionResponsesByQuiz(quizId){return getQuestionResponsesByUser().filter(row=>row.quizId===quizId)}
function getQuestionResponsesByTopic(topic){return getQuestionResponsesByUser().filter(row=>row.topic===topic)}
function calculateQuestionResponseSeconds({shownAt,firstAnsweredAt}){const shown=new Date(shownAt),answered=new Date(firstAnsweredAt);if(Number.isNaN(shown.getTime())||Number.isNaN(answered.getTime())||answered<=shown)return null;return Number(((answered.getTime()-shown.getTime())/1000).toFixed(1))}
