function renderBreakReminder(reminder){if(!reminder)return '<div class="sr-only" aria-live="polite"></div>';return `<div class="break-reminder ${reminder.tone}" role="status" aria-live="polite"><div><b>Continuous Study Reminder</b><p>${escapeHTML(reminder.message)}</p><small>${escapeHTML(reminder.note||'Break records show study timing only and do not prove study overload.')}</small></div><div class="study-session-actions">${reminder.buttons.map(label=>`<button class="btn ${label==='Start Break'?'btn-primary':'btn-secondary'}" data-break-reminder-action="${label.toLowerCase().replaceAll(' ','-')}" data-break-threshold="${reminder.threshold}" type="button">${escapeHTML(label)}</button>`).join('')}</div></div>`}
function unfinishedBreakNoticeHTML(session,activeBreak){if(!activeBreak)return '';const key=`break-recovery-${session.id}-${activeBreak.id}`;if(sessionStorage.getItem(key)==='dismissed')return '';return `<div class="unfinished-break-notice" role="status"><b>An unfinished break was found.</b><p>The study timer is paused until you choose what happened.</p><div class="study-session-actions"><button class="btn btn-primary" data-break-recovery="continue" data-break-recovery-key="${escapeHTML(key)}" type="button">Continue Break</button><button class="btn btn-secondary" data-break-recovery="end-now" type="button">End Break Now</button><button class="btn btn-secondary" data-break-recovery="correct" type="button">Correct Break Time</button><button class="btn btn-danger" data-break-recovery="cancel" type="button">Cancel Break Record</button></div></div>`}
function renderActiveStudySession(session){const activeBreak=(session.breaks||[]).find(b=>b.status==='active'||(b.startTime&&!b.endTime)),metrics=activeStudyTimerMetrics(session,new Date()),recovery=validateRecoverableActiveSession({session}),status=recovery.status==='recovery-required'?'recovery-required':session.status,controls=status==='paused'?'<button class="btn btn-primary" data-session-action="resume" type="button">Resume Session</button>':activeBreak?'<button class="btn btn-primary" data-session-action="end-break" type="button">End Break</button>':'<button class="btn btn-secondary" data-session-action="start-break" type="button">Start Break</button><button class="btn btn-secondary" data-session-action="pause" type="button">Pause Session</button>';return `<article class="card active-study-session active-study-session-detail ${status==='on-break'?'on-break':''}"><div class="card-head"><div><span class="well-being-status ${status==='on-break'?'some-overload-signals':'balanced-study-pattern'}">${escapeHTML(status.replace(/-/g,' '))}</span><h3>${escapeHTML(session.subject)} - ${escapeHTML(session.topic)}</h3><p>Started ${escapeHTML(formatSessionClock(session.startTime))}</p></div><div class="session-elapsed" aria-label="Active study time"><b>${formatTimerDuration(metrics.activeStudy)}</b><span>active study time</span></div></div>${unfinishedBreakNoticeHTML(session,activeBreak)}<div class="profile-fact-grid">${profileFact('Session Time',formatTimerDuration(metrics.totalElapsed))}${profileFact('Active Study Time',formatTimerDuration(metrics.activeStudy))}${profileFact('Time Since Last Break',formatCompactTimer(metrics.sinceBreak))}${profileFact('Current Active Period',formatTimerDuration(metrics.currentPeriod))}${profileFact('Recorded Break Time',formatCompactTimer(metrics.completedBreaks+metrics.currentBreak))}${profileFact('Break Count',String(metrics.breakCount))}${profileFact('Planned Tasks',session.plannedTasks===null?'Not set':String(session.plannedTasks))}${profileFact('Completed Tasks',String(session.tasksCompleted||0))}</div>${recovery.status==='recovery-required'?'<div class="timer-config-error" role="alert">The active study timer needs to be reviewed.</div>':''}<div class="study-session-actions">${controls}<button class="btn btn-secondary" data-session-action="complete-task" type="button">Complete Task</button><button class="btn btn-secondary" data-session-action="undo-task" type="button">Undo Completed Task</button><button class="btn btn-primary" data-session-action="finish-now" type="button">Finish Session</button><button class="btn btn-danger" data-session-action="cancel" type="button">Cancel Session</button></div><p class="readiness-note">The Active Study Timer records study timing only. It does not provide a medical or mental-health diagnosis.</p></article>`}
function renderStudySessionErrors(errors=[]){const root=$('#studySessionErrors');if(root)root.innerHTML=errors.map(error=>`<p>${escapeHTML(error)}</p>`).join('');else showNotification({type:'warning',message:errors[0]||'Check the study session form.'})}
async function startStudySessionBreak(){const session=getActiveStudySession();if(!session)return;const now=new Date().toISOString();session.breaks=session.breaks||[];if(session.breaks.some(b=>b.status==='active'||(b.startTime&&!b.endTime))){showNotification({type:'warning',message:'A break is already active.'});return}const openPeriod=(session.studyPeriods||[]).find(period=>period.startedAt&&!period.endedAt);if(openPeriod){openPeriod.endedAt=now;openPeriod.durationMinutes=Math.max(0,Number(((new Date(now)-new Date(openPeriod.startedAt))/60000).toFixed(1)));session.completedStudyPeriods=[...(session.completedStudyPeriods||[]),openPeriod]}const breakId=`break-${Date.now()}`;session.breaks.push({id:breakId,userId:session.userId,sessionId:session.id,startTime:now,endTime:null,lengthMinutes:null,durationMinutes:null,status:'active',trackingMethod:'timer',createdAt:now,updatedAt:now,prototypeOnly:true});session.status='on-break';session.activeBreakId=breakId;session.currentStudyPeriodStartedAt=null;session.currentReminderThreshold=null;session.activeReminder=null;session.updatedAt=now;saveActiveStudySession(session);showNotification({type:'information',message:'Break started.'});renderStudyWellBeingPage();updateVisibleStudyTimer()}
