function activeBreakFinishDialog(){return new Promise(resolve=>{const overlay=document.createElement('div');overlay.className='modal-overlay active';overlay.innerHTML=`<div class="modal small-modal" role="dialog" aria-modal="true" aria-labelledby="activeBreakFinishTitle"><h2 id="activeBreakFinishTitle">Active Break</h2><p>A break is currently active. End the break and finish the session?</p><div class="modal-actions"><button class="btn btn-primary" data-choice="end" type="button">End Break and Finish</button><button class="btn btn-secondary" data-choice="return" type="button">Return to Break</button><button class="btn btn-danger" data-choice="cancel" type="button">Cancel Break and Finish</button></div></div>`;document.body.appendChild(overlay);overlay.querySelectorAll('[data-choice]').forEach(btn=>btn.onclick=()=>{const choice=btn.dataset.choice;overlay.remove();resolve(choice)})})}
