async function cancelActiveStudySession({skipConfirm=false}={}){const ok=skipConfirm?true:await confirmDialog({title:'Cancel Study Session',message:'Cancel this study session? The unfinished session will not count toward your Study Well-Being summary.',okText:'Cancel Session',cancelText:'Keep Studying',danger:true});if(!ok)return false;const session=getActiveStudySession();if(session)saveStudySession({...session,status:'cancelled',cancelledAt:new Date().toISOString(),updatedAt:new Date().toISOString()});clearActiveStudySession();sessionStorage.removeItem('studySessionFormMode');renderStudyWellBeingPage();updateVisibleStudyTimer();toast('Study session cancelled.');return true}
function syncStudySessionToPredictionPerformance(session,editing=false){if(!session.predictionProfileId)return;const profile=findPredictionProfile(session.predictionProfileId);if(!profile)return;const chapter=(profile.chapters||[]).find(ch=>normalizeChapterName(ch.name)===normalizeChapterName(session.topic));if(!chapter)return;const payload={activityType:'study-session',chapter:chapter.name,assessmentCategory:'',score:null,timeSpentMinutes:session.durationMinutes,attempts:1,completed:true,date:session.date,notes:session.notes||'Saved from Study Well-Being session tracker.'};let result=session.performanceEntryId?updatePerformanceEntry(session.performanceEntryId,payload,profile,{skipDuplicateWarning:true}):createPerformanceEntry(payload,profile,{skipDuplicateWarning:true});if(result?.success){session.performanceEntryId=result.entry.id;predictionUpdateManager.requestUpdate({userId:predictionUserId(),predictionProfileId:profile.id,triggerType:editing?PREDICTION_UPDATE_TRIGGERS.STUDY_SESSION_UPDATED:PREDICTION_UPDATE_TRIGGERS.STUDY_SESSION_COMPLETED,sourceRecordId:result.entry.id})}}
