function supportiveEvidenceText(evidence=[]){const rows=Array.isArray(evidence)?evidence:[];const first=rows.find(item=>item?.message||item?.evidence);return first?String(first.message||first.evidence):'Recorded study activity was reviewed.'}
function getSupportiveInterpretationForLevel(level,status='current'){if(status==='outdated')return 'Your study records have changed since this dashboard was calculated. Consider refreshing the dashboard before using these results.';if(status==='not-enough-data'||level==='Not Enough Data')return 'There is not enough recorded study activity to summarize your current workload yet.';if(level==='Balanced')return supportiveFallbackMessage('warning','Balanced');if(level==='Mild Overload')return supportiveFallbackMessage('warning','Mild Overload');if(level==='High Workload')return supportiveFallbackMessage('warning','High Workload');if(level==='Strong Overload Pattern')return supportiveFallbackMessage('warning','Strong Overload Pattern');return 'Some study records need to be reviewed before an overall workload warning can be calculated.'}
function buildSupportiveWarning({level='Balanced',evidence=[],recommendation='',rules=studyWellBeingRules(),message=''}={}){if(!supportiveLanguageConfigValid(rules))return supportiveLanguageConfigError();const base=message||getSupportiveInterpretationForLevel(level);const detail=evidence?.length&&!/recorded|recent|study pattern|study activity|study records/i.test(base)?`${supportiveEvidenceText(evidence)} ${base}`:base;const withAction=recommendation&&!/consider|try|choose|take|move|reduce|review|continue|plan|record|start/i.test(detail)?`${detail} ${recommendation}`:detail;return finalizeSupportiveMessage({message:withAction,type:'warning',level,rules})}
function buildSupportiveRecommendation({message='',category='',rules=studyWellBeingRules()}={}){if(!supportiveLanguageConfigValid(rules))return supportiveLanguageConfigError();const text=String(message||supportiveFallbackMessage('recommendation')).trim();const hasAction=/\b(consider|try|choose|take|move|reduce|review|continue|plan|record|start)\b/i.test(text),safe=hasAction?text:`Consider ${text.charAt(0).toLowerCase()+text.slice(1)}`;return finalizeSupportiveMessage({message:safe,type:'recommendation',level:category,rules})}
