function buildSupportiveCheckInMessage(feeling,rec={}){let message='Consider choosing one manageable study task to start.';if(feeling==='Energized')message=rec.positiveOnly?'You reported feeling energized today. Consider continuing the strategies that are working well for you.':'You reported feeling energized today. Consider starting with a challenging topic while you feel ready.';else if(feeling==='Okay')message='You reported feeling okay today. Consider following your plan and adjusting one task if needed.';else if(feeling==='Tired')message='You reported feeling tired today. Consider starting with a shorter review and adding a short break during longer sessions.';else if(feeling==='Overwhelmed')message='You reported feeling overwhelmed today. Consider choosing one priority task and moving one lower-priority task if your schedule allows.';return finalizeSupportiveMessage({message,type:'recommendation',level:feeling,rules:studyWellBeingRules()})}
