function validateRecommendationRules(rules){const settings=rules?.recommendations,errors=[];if(!settings)errors.push('Recommendation rules are missing.');if(Number(settings?.maximumRecommendations)<1)errors.push('At least one recommendation must be allowed.');if(settings&&(!Array.isArray(settings.library)||!settings.library.length))errors.push('Recommendation library is missing.');return {valid:errors.length===0,errors}}
