function recommendationEvidenceText(indicator){if(!indicator)return 'This recommendation is based on current recorded study patterns.';if(typeof indicator.sourceIndicator?.evidence==='string')return indicator.sourceIndicator.evidence;if(typeof indicator.evidence==='string')return indicator.evidence;const evidence=indicator.evidence||{};if(Number.isFinite(Number(evidence.longestStreak)))return `A study streak of ${evidence.longestStreak} day(s) was recorded.`;if(Number.isFinite(Number(evidence.lateNightSessionCount)))return `${evidence.lateNightSessionCount} late-night session(s) were recorded.`;if(Number.isFinite(Number(evidence.skippedOrOverdueTasks)))return `${evidence.skippedOrOverdueTasks} task(s) were skipped or overdue.`;if(Number.isFinite(Number(evidence.changePercentagePoints)))return `Recent quiz average changed by ${evidence.changePercentagePoints} percentage points.`;return indicator.title||'A supported study pattern was found.'}
function getRecommendationForIndicator(indicator,rules=studyWellBeingRules()){const library=mergeRecommendationRules(rules.recommendations).library||[],key=indicator?.key||indicator?.sourceIndicatorKey||'',pointKey=indicator?.pointKey||'',category=indicator?.category||'';const match=library.filter(item=>!item.positiveOnly&&item.supported!==false).find(item=>(item.sourceIndicatorKeys||[]).includes(key)||(item.sourcePointKeys||[]).includes(pointKey)||item.category===category);if(!match)return null;const reminderSettings=loadReminderSettings(),message=match.id==='recommendation-break-before-90'?`Consider taking a short break after about ${reminderSettings.preferredSessionLengthMinutes} minutes.`:match.message;return {...match,message:buildSupportiveRecommendation({message,category,rules}),sourceIndicatorKey:key,reason:buildSupportiveEvidenceSummary({message:match.reason||recommendationEvidenceText(indicator),rules}),supported:true,status:indicator?.status==='outdated'?'outdated':'current',prototypeOnly:true}}
