function recommendationDisplayItems(value){if(Array.isArray(value))return value.map(item=>typeof item==='string'?{id:`legacy-${recommendationKey({message:item})}`,title:'Suggested Next Step',message:item,reason:'This suggestion came from an earlier saved well-being review.',category:'legacy',status:'current',supported:true}:item).filter(Boolean);return Array.isArray(value?.items)?value.items:[]}
function recommendationCardsHTML(value,{status='current'}={}){const errors=value?.errors||[],items=recommendationDisplayItems(value),effectiveStatus=value?.status||status;if(effectiveStatus==='unavailable')return `<section class="recommendation-card-list" role="alert"><p>${escapeHTML('Recommendations could not be generated.')}</p>${wellBeingList(errors)}</section>`;if(effectiveStatus==='outdated')return `<section class="recommendation-card-list" role="alert"><p>${escapeHTML('Recommendations need to be refreshed because your study records changed.')}</p><button class="btn btn-primary" data-refresh-well-being-dashboard type="button">Refresh Recommendations</button><button class="btn btn-secondary" data-view="wellBeingHelpSafety" type="button">Help & Safety</button></section>`;if(!items.length)return `<section class="recommendation-card-list"><p>${escapeHTML('No specific study changes are recommended based on your current recorded study patterns.')}</p><button class="btn btn-secondary" data-view="wellBeingHelpSafety" type="button">Help & Safety</button></section>`;return `<section class="recommendation-card-list">${items.map((rec,index)=>{const id=escapeHTML(rec.id||`recommendation-${index}`),reason=rec.reason||'This recommendation is based on supported recorded study patterns.';return `<article class="recommendation-card"><h4>${escapeHTML(rec.title||'Suggested Next Step')}</h4><p>${escapeHTML(rec.message||'No specific study changes are recommended based on your current recorded study patterns.')}</p><p class="recommendation-why"><b>Why this recommendation?</b> ${escapeHTML(reason)}</p>${rec.personalizedByDailyCheckIn?`<p class="readiness-note">${escapeHTML(rec.personalizedReason||"Personalized because of today's check-in.")}</p>`:''}<div class="study-session-actions"><button class="text-button" type="button" aria-expanded="false" aria-controls="${id}-reason" data-recommendation-details="${id}">View Details</button><button class="text-button" data-view="wellBeingHelpSafety" type="button">Help & Safety</button></div><p class="recommendation-reason hidden" id="${id}-reason"><b>Reason:</b> ${escapeHTML(reason)}</p></article>`}).join('')}<p class="quiz-performance-limitation">${escapeHTML(WELL_BEING_RECOMMENDATION_DISCLAIMER)}</p></section>`}
function formatEvidenceNumber(value,{start=false}={}){const n=Number(value),words=['zero','one','two','three','four','five','six','seven','eight','nine','ten'];if(Number.isInteger(n)&&n>=0&&n<=10){const word=words[n];return start?word.charAt(0).toUpperCase()+word.slice(1):word}return Number.isFinite(n)?String(n):'Not enough'}
function pluralizeWord(count,singular,plural=`${singular}s`){return Number(count)===1?singular:plural}
function formatEvidenceDateRange(range={}){if(!range)return 'Current review period';if(range.mode==='custom'&&(range.start||range.end))return `${formatWellBeingDate(range.start)} to ${formatWellBeingDate(range.end)}`;if(range.start&&range.end)return `${formatWellBeingDate(range.start)} to ${formatWellBeingDate(range.end)}`;const mode=String(range.mode||'14');if(mode==='week')return 'Current week';return `Last ${mode} days`}
function evidenceQualityLabel(data={}){const level=data.studyLoadLevel||{},active=Number(level.activeCategoryCount||level.multiplePatternAssessment?.activeCategoryCount||0);if(data.status==='outdated')return 'Limited';if(level.available&&active>=3)return 'High';if(level.available||data.evidence?.ready)return 'Moderate';return 'Limited'}
function evidenceTitleForCategory(category){return {'quiz-performance':'Recent quiz scores','quiz-response-time':'Quiz response time','study-task-completion':'Skipped or overdue study tasks','late-night-study':'Late-night study sessions','study-session-length':'Study-session length','recorded-break-pattern':'Recorded breaks','recorded-breaks':'Recorded breaks','study-streak':'Study streak'}[category]||dashboardPatternLabel(category||'study-pattern')}
function buildEvidenceExplanation(indicator){const evidence=indicator?.evidence||{},category=indicator?.category||'',title=evidenceTitleForCategory(category),calcParts=[];let message='A supported recorded study pattern was found.';if(category==='quiz-performance'){const change=Math.abs(Number(evidence.changePercentagePoints)||0);message=change?`Your last three quiz scores dropped by ${change} percentage points.`:'Your recent quiz average was lower than your earlier average.';if(Number.isFinite(Number(evidence.recentAverage))&&Number.isFinite(Number(evidence.usualAverage)))calcParts.push(`Recent average: ${evidence.recentAverage}%. Earlier average: ${evidence.usualAverage}%.`)}else if(category==='quiz-response-time'){const recent=Number(evidence.recentMedianSeconds),usual=Number(evidence.usualMedianSeconds),percent=Math.abs(Number(evidence.changePercent)||0);message=Number.isFinite(recent)&&Number.isFinite(usual)?`Recent responses were slower than your usual recorded pace by about ${percent} percent.`:'Recent responses were slower than your usual recorded pace.';if(Number.isFinite(recent)&&Number.isFinite(usual))calcParts.push(`Recent median: ${recent} seconds. Usual median: ${usual} seconds.`)}else if(category==='study-task-completion'){const count=Number(evidence.skippedOrOverdueTasks)||0;message=`${formatEvidenceNumber(count,{start:true})} eligible study ${pluralizeWord(count,'task')} ${count===1?'is':'are'} currently skipped or overdue.`;if(Number.isFinite(Number(evidence.eligibleTasks)))calcParts.push(`${count} of ${evidence.eligibleTasks} eligible due-date tasks were skipped or overdue.`)}else if(category==='late-night-study'){const sessions=Number(evidence.lateNightSessionCount)||0,days=Number(evidence.distinctLateNightDayCount)||0;message=days>=2?`Late-night studying occurred on ${formatEvidenceNumber(days)} separate ${pluralizeWord(days,'day')}.`:`${formatEvidenceNumber(sessions,{start:true})} late-night study ${pluralizeWord(sessions,'session')} ${sessions===1?'was':'were'} recorded this week.`;calcParts.push(`${sessions} late-night ${pluralizeWord(sessions,'session')} across ${days} ${pluralizeWord(days,'day')}.`)}else if(category==='study-session-length'){const veryLong=Number(evidence.veryLongSessions)||0,high=Number(evidence.highWarningSessions)||0,total=veryLong+high;message=total>=2?`${formatEvidenceNumber(total,{start:true})} study sessions exceeded two hours.`:'Several recent study sessions lasted longer than your preferred study-session length.';calcParts.push(`${veryLong} very-long ${pluralizeWord(veryLong,'session')} and ${high} high-length ${pluralizeWord(high,'session')} were recorded.`)}else if(category==='recorded-break-pattern'||category==='recorded-breaks'){const count=Number(evidence.sessionsOver60WithoutMeaningfulBreak)||0,total=Number(evidence.completedSessionCount)||0;message=count?`${formatEvidenceNumber(count,{start:true})} long study ${pluralizeWord(count,'session')} did not include a meaningful recorded break.`:'Several long study sessions did not include a meaningful recorded break.';if(total)calcParts.push(`${count} of ${total} reviewed ${pluralizeWord(total,'session')} lacked a meaningful recorded break.`)}else if(category==='study-streak'){const streak=Number(evidence.longestStreak)||0;message=`Study activity has been recorded on ${formatEvidenceNumber(streak)} consecutive ${pluralizeWord(streak,'day')}.`;calcParts.push(`Longest recorded activity streak in this period: ${streak} ${pluralizeWord(streak,'day')}.`)}else if(indicator?.sourceIndicator?.evidence||indicator?.title){message=indicator.sourceIndicator?.evidence||indicator.title}return {id:indicator?.id||indicator?.key||`evidence-${category}`,category,indicatorKey:indicator?.key||indicator?.sourceIndicatorKey||'',title,message,calculation:calcParts.join(' ')||'Calculated from current StudySpark records for this user.',supported:indicator?.supported===true,usedForCurrentWarning:indicator?.usedForCurrentWarning===true,prototypeOnly:true}}
function buildWarningEvidence({indicators}){return (indicators||[]).filter(indicator=>indicator.supported===true&&indicator.evidenceQuality==="sufficient"&&indicator.usedForCurrentWarning===true).map(buildEvidenceExplanation)}
function dashboardContributingIndicators(data={}){return (data.studyLoadLevel?.scoredIndicators||[]).filter(indicator=>Number(indicator.adjustedPoints??indicator.points??0)>0).map(indicator=>({...indicator,supported:indicator.supported!==false,evidenceQuality:indicator.evidenceQuality||'sufficient',usedForCurrentWarning:true}))}
function positiveEvidenceForDashboard(data={}){return (data.positivePatterns||[]).map((message,index)=>({id:`positive-evidence-${index}`,category:'positive-study-pattern',title:'Positive recorded pattern',message,calculation:'Taken from positive study patterns found in the current review period.',supported:true,prototypeOnly:true}))}
function unusedEvidenceForDashboard(data={}){const rows=[],level=data.studyLoadLevel||{},used=new Set((level.scoredIndicators||[]).filter(i=>Number(i.adjustedPoints??i.points??0)>0).map(i=>i.key||i.id));(level.allIndicators||[]).forEach(indicator=>{if(used.has(indicator.key||indicator.id))return;const category=indicator.category||'',evidence=indicator.evidence||{};let message='Not enough evidence was available for this category.';if(category==='late-night-study'&&Number(evidence.lateNightSessionCount)===1)message='One late-night study session was recorded, so it was not used by itself.';else if(category==='study-session-length'&&(Number(evidence.veryLongSessions)+Number(evidence.highWarningSessions)===1))message='One unusually long session was recorded, so it was not used by itself.';else if(category==='study-task-completion'&&Number(evidence.skippedOrOverdueTasks)===1)message='One skipped or overdue task was found, so it was not used by itself.';else if(category==='quiz-performance')message='One low quiz score by itself was not used to create a workload warning.';rows.push({id:`unused-${indicator.key||indicator.id||category}`,category,title:evidenceTitleForCategory(category),message,calculation:'A single unusual activity does not create a workload warning.',supported:false,prototypeOnly:true})});if(!rows.length)rows.push({id:'unused-default',category:'not-enough-data',title:'Not Used in This Warning',message:'Not enough evidence was available for this category.',calculation:'A single unusual activity does not create a workload warning.',supported:false,prototypeOnly:true});return rows.slice(0,4)}
function buildDashboardEvidence(data={}){const recorded=buildWarningEvidence({indicators:dashboardContributingIndicators(data)}),positive=positiveEvidenceForDashboard(data),unused=unusedEvidenceForDashboard(data);return {recorded,positive,unused,summary:recorded.map(item=>({category:item.category,message:item.message})),quality:evidenceQualityLabel(data),reviewPeriod:formatEvidenceDateRange(data.dateRange)}}
function evidenceListHTML(items=[],empty='Not enough evidence was available for this category.'){return items.length?`<ul class="evidence-list">${items.map(item=>`<li><b>${escapeHTML(item.title||'Evidence')}</b><span>${escapeHTML(item.message)}</span><details><summary>How this was calculated</summary><p>${escapeHTML(item.calculation||'Calculated from recorded study activity.')}</p></details></li>`).join('')}</ul>`:`<p>${escapeHTML(empty)}</p>`}
