function bindRecommendationDetails(root=document){$$('[data-recommendation-details]',root).forEach(btn=>btn.onclick=()=>{const target=document.getElementById(`${btn.dataset.recommendationDetails}-reason`);if(!target)return;const hidden=target.classList.toggle('hidden');btn.setAttribute('aria-expanded',String(!hidden))});$$('[data-view="wellBeingHelpSafety"]',root).forEach(btn=>btn.onclick=e=>{e.preventDefault();showView('wellBeingHelpSafety')})}
function validateStudyWellBeingRules(rules){const errors=[],min=rules?.minimumEvidence||{},t=rules?.thresholds||{},s=rules?.statusThresholds||{},qp=rules?.quizPerformance||{},rt=rules?.responseTime||{},st=rules?.skippedStudyTasks||{},late=validateLateNightRules(rules),sessionLength=validateSessionLengthRules(rules),breakPatterns=validateBreakPatternRules(rules),studyLoadLevel=validateStudyLoadLevelRules(rules),multiplePattern=validateMultiplePatternRules(rules),supportiveLanguage=validateSupportiveLanguageRules(rules),notifications=validateNotificationRules(rules);['completedSessions','completedQuizzes','plannerTaskRecords','activityDays'].forEach(key=>{if(!Number.isFinite(Number(min[key]))||Number(min[key])<0)errors.push(`Invalid minimum evidence for ${key}.`)});['longSessionMinutes','veryLongSessionMinutes','lateNightStartHour','longStreakDays','performanceDropPercent','sharpDailyIncreasePercent','multipleLongDays','highDailyMinutes'].forEach(key=>{if(!Number.isFinite(Number(t[key]))||Number(t[key])<0)errors.push(`Invalid threshold for ${key}.`)});['recentQuizCount','minimumUsualQuizCount','maximumUsualQuizCount','improvingThreshold','smallDropThreshold','noticeableDropThreshold','timingIncreaseMinutes','minutesPerQuestionIncrease','unansweredIncrease','unansweredRateIncrease'].forEach(key=>{if(!Number.isFinite(Number(qp[key])))errors.push(`Invalid quiz-performance setting for ${key}.`)});['minimumValidSeconds','maximumStandardQuestionSeconds','recentQuestionCount','minimumUsualQuestionCount','maximumUsualQuestionCount','smallIncreasePercent','noticeableIncreasePercent','fasterThresholdPercent','slowerShareThreshold'].forEach(key=>{if(!Number.isFinite(Number(rt[key])))errors.push(`Invalid response-time setting for ${key}.`)});['minimumTaskCount','normalMaximumPercent','watchMaximumPercent','possibleOverloadMinimumPercent','minimumSkippedOrOverdueForSignal'].forEach(key=>{if(!Number.isFinite(Number(st[key]))||Number(st[key])<0)errors.push(`Invalid skipped-task setting for ${key}.`)});if(Number(t.lateNightStartHour)>23)errors.push('Invalid late-night hour.');if(Number(rt.maximumStandardQuestionSeconds)<=Number(rt.minimumValidSeconds))errors.push('Response-time maximum must be greater than the minimum.');if(Number(st.watchMaximumPercent)<Number(st.normalMaximumPercent))errors.push('Skipped-task watch threshold must be greater than normal.');if(Number(st.possibleOverloadMinimumPercent)<=Number(st.watchMaximumPercent))errors.push('Skipped-task possible-overload threshold must be greater than watch.');if(!late.valid)errors.push(...late.errors);if(!sessionLength.valid)errors.push(...sessionLength.errors);if(!breakPatterns.valid)errors.push(...breakPatterns.errors);if(!studyLoadLevel.valid)errors.push(...studyLoadLevel.errors);if(!multiplePattern.valid)errors.push(...multiplePattern.errors);if(!supportiveLanguage.valid)errors.push(...supportiveLanguage.errors);if(!notifications.valid)errors.push(...notifications.errors);if(!Number.isFinite(Number(s.someSignals))||!Number.isFinite(Number(s.increasedSignals))||Number(s.increasedSignals)<Number(s.someSignals))errors.push('Invalid well-being status thresholds.');return {valid:errors.length===0,errors}}
