function saveDemoWellBeingStore(store,mode=demoWellBeingMode()){safeWriteLocalStorage(demoWellBeingStorageKey(mode),store)}
function getDemoWellBeingScenario(scenarioId='well-being-full-demo'){const scenarios=appData.studyWellBeingDemoData?.scenarios||[];return scenarios.find(s=>s.id===scenarioId)||scenarios[0]||null}
function demoWellBeingUserId(userId=currentStudySessionUserId()){return userId||predictionUserId()||'demo-user'}
function addLocalDays(baseDate,dayOffset=0){const date=new Date(baseDate);date.setDate(date.getDate()+Number(dayOffset||0));return date}
function combineLocalDateAndTime(date,localTime='12:00'){const [hour='12',minute='00']=String(localTime||'12:00').split(':');const next=new Date(date);next.setHours(Number(hour)||0,Number(minute)||0,0,0);return next}
function resolveDemoDate({baseDate,dayOffset=0,localTime='12:00'}={}){return combineLocalDateAndTime(addLocalDays(baseDate,dayOffset),localTime)}
