async function buildWellBeingDashboardData(args){return buildWellBeingDashboardDataSync(args)}
function dashboardMetricCardHTML(card){const state=String(card.status||'current').replace(/\s+/g,'-').toLowerCase();return `<article class="card well-being-metric-card ${state}" aria-label="${escapeHTML(card.title)}"><div class="card-head"><div><span class="well-being-status ${state}">${escapeHTML(card.status==='current'?'Current':card.status||'Current')}</span><h3>${escapeHTML(card.title)}</h3></div><button class="text-button" data-dashboard-detail="${escapeHTML(card.id)}" type="button">${escapeHTML(card.actionLabel||'View Details')}</button></div><b>${escapeHTML(card.value)}</b><p>${escapeHTML(card.detail||card.emptyMessage||'Not enough data yet.')}</p><details class="quiz-comparison-details"><summary>How This Was Calculated</summary><p>${escapeHTML(card.source||'Calculated from current StudySpark records for this user.')}</p></details></article>`}
function dashboardStudyLoadCardHTML(data,outdated=false){const level=data.studyLoadLevel||{},active=(level.scoredIndicators||[]).filter(i=>Number(i.adjustedPoints??i.points??0)>0),state=outdated?'Outdated':level.level||'Not Enough Data';return `<article class="card well-being-dashboard-hero study-load-card"><div class="card-head"><div><span class="well-being-status ${state.toLowerCase().replace(/\s+/g,'-')}">${escapeHTML(state)}</span><h2>Study Load Summary</h2><p>${escapeHTML(dashboardStatusMessage(level.level,state==='Outdated'?'outdated':data.status))}</p></div><div class="dashboard-points"><b>${level.available?level.totalPoints:'-'}</b><span>points</span></div></div><div class="profile-fact-grid">${profileFact('Study Load Level',level.level||'Not Enough Data')}${profileFact('Level',state)}${profileFact('Points',level.available?`${level.totalPoints} of ${level.maximumPossiblePoints}`:'Not enough data')}${profileFact('Supported Patterns',String(active.length))}${profileFact('Last Updated',formatWellBeingDate(data.generatedAt))}</div><p>${escapeHTML(level.message||dashboardStatusMessage(level.level,data.status))}</p><p class="quiz-performance-limitation">${escapeHTML(STUDY_LOAD_DISCLAIMER)}</p><div class="study-session-actions"><button class="btn btn-secondary" data-dashboard-detail="studyLoad" type="button">View Point Breakdown</button><button class="btn btn-secondary" data-dashboard-detail="multiplePattern" type="button">View Multiple-Pattern Check</button><button class="btn btn-secondary" data-scroll-evidence-panel type="button">Why You Are Seeing This</button><button class="btn btn-primary" data-refresh-well-being-dashboard type="button">Recalculate</button></div></article>`}
function dashboardMainPatternHTML(data){const main=data.mainPattern||buildMainPatternDetected({scoredIndicators:data.studyLoadLevel?.scoredIndicators||[]}),title=main.overallWarning?formatMainPatternTitle(main.indicators):main.title;return `<article class="card well-being-main-pattern"><span class="pill blue-pill">${main.overallWarning?'MAIN WORKLOAD PATTERN':'MAIN STUDY PATTERN'}</span><h3>${escapeHTML(title)}</h3><p>${escapeHTML(main.summary||'No overall workload warning was created because multiple separate patterns were not found.')}</p>${main.indicators?.length?`<div class="well-being-signal-list">${main.indicators.map(indicator=>`<div class="well-being-signal ${escapeHTML(String(indicator.severity||'information').toLowerCase())}"><b>${escapeHTML(dashboardPatternLabel(indicator.category))}</b><small>${escapeHTML(indicator.sourceIndicator?.evidence||indicator.title||'Supported by current recorded study data.')}</small></div>`).join('')}</div>`:''}<button class="btn btn-secondary" data-scroll-evidence-panel type="button">Why You Are Seeing This</button></article>`}
function dashboardHistoryHTML(){const rows=getWellBeingDashboardHistory();return `<article class="card well-being-dashboard-history" id="wellBeingDashboardHistory"><div class="card-head"><div><h3>Dashboard History</h3><p>Saved dashboard snapshots for this user only.</p></div><button class="btn btn-danger" id="clearWellBeingDashboardHistoryBtn" type="button">Clear Dashboard History</button></div><div class="well-being-history-list">${rows.length?rows.slice(0,10).map(row=>`<div><span>${escapeHTML(formatWellBeingDate(row.generatedAt))}</span><b>${escapeHTML(row.studyLoadLevel?.level||row.status||'Dashboard Snapshot')}</b><small>${escapeHTML(row.dateRange?.course||'All courses')} - ${row.studyLoadLevel?.totalPoints??'-'} point(s)</small><button class="btn btn-danger" data-delete-dashboard-snapshot="${escapeHTML(row.id)}" type="button">Delete Snapshot</button></div>`).join(''):'<div class="empty-mini">Dashboard history appears after Refresh Dashboard or Save Snapshot.</div>'}</div></article>`}
function dashboardSettingsHTML(){const prefs=getWellBeingDashboardPreferences(),reminders=loadReminderSettings();return `<details class="card well-being-dashboard-settings" id="wellBeingDashboardSettings"><summary>Dashboard Settings</summary><div class="dashboard-settings-grid"><label><span>Show response-time card</span><input type="checkbox" data-dashboard-pref="showResponseTimeCard" ${prefs.showResponseTimeCard?'checked':''}></label><label><span>Show average-break card</span><input type="checkbox" data-dashboard-pref="showAverageBreakCard" ${prefs.showAverageBreakCard?'checked':''}></label><label><span>Show positive patterns</span><input type="checkbox" data-dashboard-pref="showPositivePatterns" ${prefs.showPositivePatterns?'checked':''}></label><label><span>Compare previous dashboard</span><input type="checkbox" data-dashboard-pref="showPreviousComparison" ${prefs.showPreviousComparison?'checked':''}></label><label><span>Automatic dashboard updates</span><input type="checkbox" data-dashboard-pref="automaticUpdates" ${prefs.automaticUpdates?'checked':''}></label><label><span>Include Daily Check-In in export</span><input type="checkbox" data-dashboard-pref="includeDailyCheckInExport" ${prefs.includeDailyCheckInExport?'checked':''}></label><label><span>Include Evidence in export</span><input type="checkbox" data-dashboard-pref="includeEvidenceExport" ${prefs.includeEvidenceExport?'checked':''}></label><label>Late-night threshold<select id="dashboardLateNightThreshold">${lateNightTimeOptionsHTML(reminders.lateNightStartTime)}</select></label></div><section class="dashboard-reminder-summary"><div><h3>Reminder Settings</h3><p>Reminder settings affect future notifications only.</p></div>${reminderSettingsSummaryHTML(reminders)}<button class="btn btn-secondary" data-open-reminder-settings type="button">Open Reminder Settings</button></section></details>`}
